const ASYNC_RESULT_SCATTER_ENV: &str = "SHEAR_PIPNN_ASYNC_RESULT_SCATTER";
const ASYNC_RESULT_SCATTER_MAX_INFLIGHT: usize = 2;
const PERSISTENT_ASYNC_D2H_ENV: &str = "SHEAR_PIPNN_PERSISTENT_ASYNC_D2H";

#[derive(Clone, Debug, PartialEq, Eq)]
struct AsyncResultScatterConfig {
    requested: String,
    enabled: bool,
}

fn parse_async_result_scatter_env(value: Option<&std::ffi::OsStr>) -> AsyncResultScatterConfig {
    match value {
        None => AsyncResultScatterConfig {
            requested: "<unset>".to_string(),
            enabled: true,
        },
        Some(value) => match value.to_str() {
            Some(value) => AsyncResultScatterConfig {
                requested: value.to_string(),
                enabled: value == "1",
            },
            None => AsyncResultScatterConfig {
                requested: "<non-utf8>".to_string(),
                enabled: false,
            },
        },
    }
}

fn async_result_scatter_config_from_env() -> AsyncResultScatterConfig {
    let value = std::env::var_os(ASYNC_RESULT_SCATTER_ENV);
    parse_async_result_scatter_env(value.as_deref())
}

fn parse_persistent_async_d2h_env(value: Option<&std::ffi::OsStr>) -> bool {
    match value {
        None => true,
        Some(value) => value.to_str() == Some("1"),
    }
}

fn persistent_async_d2h_enabled_from_env() -> bool {
    let value = std::env::var_os(PERSISTENT_ASYNC_D2H_ENV);
    parse_persistent_async_d2h_env(value.as_deref())
}

fn sq_wmma_compute_code_layout(layout: SqWmmaCodeLayout) -> GpuSubtreeQuantizedCodeLayout {
    match layout {
        SqWmmaCodeLayout::DenseI8 => GpuSubtreeQuantizedCodeLayout::DenseI8,
        SqWmmaCodeLayout::PackedS4 => GpuSubtreeQuantizedCodeLayout::PackedS4,
    }
}

