        self.tq_survivor_insert_clock_ticks += other.tq_survivor_insert_clock_ticks;
        self.tq_exact_rerank_clock_ticks += other.tq_exact_rerank_clock_ticks;
        self.tq_output_clock_ticks += other.tq_output_clock_ticks;
        self.tile_started += other.tile_started;
        self.tile_done += other.tile_done;
        self.prefilter_row_started += other.prefilter_row_started;
        self.prefilter_row_done += other.prefilter_row_done;
