fn merge_async_compact_flush_telemetry(
    telemetry: &mut RbcPartitionTelemetry,
    flush: &AsyncCompactFlushTelemetry,
) {
    telemetry.gpu_subtree_d1plus_push_wait_wall += flush.push_wait_wall;
    telemetry.gpu_subtree_d1plus_queue_max_bytes = telemetry
        .gpu_subtree_d1plus_queue_max_bytes
        .max(flush.queue_max_bytes);
    telemetry.gpu_subtree_d1plus_queue_max_batches = telemetry
        .gpu_subtree_d1plus_queue_max_batches
        .max(flush.queue_max_batches);
    telemetry.gpu_subtree_async_flush_wall += flush.flush_wall;
    telemetry.gpu_subtree_async_flush_produce_wall += flush.produce_wall;
    telemetry.gpu_subtree_async_flush_join_wait_wall += flush.join_wait_wall;
    telemetry.gpu_subtree_async_flush_worker_wall_sum += flush.worker_wall_sum;
    telemetry.gpu_subtree_async_flush_worker_count = telemetry
        .gpu_subtree_async_flush_worker_count
        .max(flush.peak_workers);
    if telemetry.gpu_subtree_async_flush_worker_mode.is_empty() {
        telemetry.gpu_subtree_async_flush_worker_mode = flush.worker_mode.to_string();
    }
    telemetry.gpu_subtree_async_flush_initial_workers = telemetry
        .gpu_subtree_async_flush_initial_workers
        .max(flush.initial_workers);
    telemetry.gpu_subtree_async_flush_max_workers = telemetry
        .gpu_subtree_async_flush_max_workers
        .max(flush.max_workers);
    telemetry.gpu_subtree_async_flush_peak_workers = telemetry
        .gpu_subtree_async_flush_peak_workers
        .max(flush.peak_workers);
    telemetry.gpu_subtree_async_flush_scale_up_events += flush.scale_up_events;
    telemetry.gpu_subtree_async_flush_queue_budget_initial_bytes = telemetry
        .gpu_subtree_async_flush_queue_budget_initial_bytes
        .max(flush.queue_budget_initial_bytes);
    telemetry.gpu_subtree_async_flush_queue_budget_peak_bytes = telemetry
        .gpu_subtree_async_flush_queue_budget_peak_bytes
        .max(flush.queue_budget_peak_bytes);
    telemetry.gpu_subtree_async_flush_controller_windows += flush.controller_windows;
    telemetry.gpu_subtree_async_flush_controller_required_workers_peak = telemetry
        .gpu_subtree_async_flush_controller_required_workers_peak
        .max(flush.controller_required_workers_peak);
    telemetry.gpu_subtree_async_flush_chunks += flush.chunks;
    telemetry.gpu_subtree_async_flush_batches += flush.batches;
    telemetry.gpu_subtree_async_flush_rows += flush.rows;
    telemetry.gpu_subtree_async_flush_errors += flush.errors;
    telemetry.gpu_subtree_cpu_compact_flush_wall += flush.flush_wall;
}

struct AsyncCompactFlushRuntime<'a> {
    sink: &'a dyn CompactTopKSink,
    queue_budget_bytes: usize,
    worker_policy: AsyncCompactFlushWorkerPolicy,
}

struct AsyncCompactFlushProducer<'a> {
    shared: &'a AsyncCompactFlushShared,
    scale_tx: std::sync::mpsc::Sender<usize>,
}

struct AsyncCompactFlushShared {
    queue_budget_limit_bytes: usize,
    adaptive: bool,
    state: Mutex<AsyncCompactFlushState>,
    can_push: Condvar,
    can_pop: Condvar,
}

const ASYNC_COMPACT_FLUSH_CHUNK_TARGET_ROWS: usize = 8_192;
const ASYNC_COMPACT_FLUSH_CHUNK_TARGET_BATCHES: usize = 64;
const ASYNC_COMPACT_FLUSH_CHUNK_TARGET_BYTES: usize = 8 * 1024 * 1024;
const ASYNC_COMPACT_FLUSH_CONTROL_WINDOW_CHUNKS: usize = 64;
const ASYNC_COMPACT_FLUSH_MIN_QUEUE_BYTES: usize = 64 * 1024 * 1024;
const ASYNC_COMPACT_FLUSH_QUEUED_CHUNKS_PER_WORKER: usize = 4;

fn async_compact_flush_queue_budget(limit_bytes: usize, active_workers: usize) -> usize {
    let derived = ASYNC_COMPACT_FLUSH_CHUNK_TARGET_BYTES
        .saturating_mul(ASYNC_COMPACT_FLUSH_QUEUED_CHUNKS_PER_WORKER)
        .saturating_mul(active_workers.max(1))
        .max(ASYNC_COMPACT_FLUSH_MIN_QUEUE_BYTES);
    limit_bytes.max(1).min(derived)
}

fn required_async_compact_flush_workers(
    enqueued_rows: usize,
    completed_rows: usize,
    worker_wall: Duration,
    elapsed: Duration,
) -> Option<usize> {
    if enqueued_rows == 0 || completed_rows == 0 || elapsed.is_zero() {
        return None;
    }

    let numerator = (enqueued_rows as u128).saturating_mul(worker_wall.as_nanos());
    let denominator = (completed_rows as u128).saturating_mul(elapsed.as_nanos());
    if denominator == 0 {
        return None;
    }
    let rounded = numerator / denominator + u128::from(numerator % denominator != 0);
    Some(rounded.min(usize::MAX as u128) as usize)
}

struct AsyncCompactFlushController {
    active_workers: usize,
    max_workers: usize,
    window_started_at: Instant,
    window_enqueued_rows: usize,
    window_completed_rows: usize,
    window_worker_wall: Duration,
    window_completed_chunks: usize,
    controller_windows: usize,
    required_workers_peak: usize,
    scale_up_events: usize,
}

impl AsyncCompactFlushController {
    fn new(initial_workers: usize, max_workers: usize, now: Instant) -> Self {
        let max_workers = max_workers.max(1);
        Self {
            active_workers: initial_workers.max(1).min(max_workers),
            max_workers,
            window_started_at: now,
            window_enqueued_rows: 0,
            window_completed_rows: 0,
            window_worker_wall: Duration::ZERO,
            window_completed_chunks: 0,
            controller_windows: 0,
            required_workers_peak: 0,
            scale_up_events: 0,
        }
    }

    fn observe_enqueue(&mut self, rows: usize) {
        self.window_enqueued_rows = self.window_enqueued_rows.saturating_add(rows);
    }

    fn observe_completion(&mut self, rows: usize, worker_wall: Duration) {
        self.window_completed_rows = self.window_completed_rows.saturating_add(rows);
        self.window_worker_wall += worker_wall;
        self.window_completed_chunks = self.window_completed_chunks.saturating_add(1);
    }

    fn maybe_scale(
        &mut self,
        now: Instant,
        queue_nonempty: bool,
        forced_by_backpressure: bool,
    ) -> Option<usize> {
        if !queue_nonempty || self.active_workers >= self.max_workers {
            return None;
        }
        if !forced_by_backpressure
            && self.window_completed_chunks < ASYNC_COMPACT_FLUSH_CONTROL_WINDOW_CHUNKS
        {
            return None;
        }

        let elapsed = now.saturating_duration_since(self.window_started_at);
        let required = required_async_compact_flush_workers(
            self.window_enqueued_rows,
            self.window_completed_rows,
            self.window_worker_wall,
            elapsed,
        );
        self.controller_windows = self.controller_windows.saturating_add(1);
        if let Some(required) = required {
            self.required_workers_peak = self.required_workers_peak.max(required);
        }

        let requested = match required {
            Some(required) => required.saturating_add(1),
            None if forced_by_backpressure => self.active_workers.saturating_add(1),
            None => self.active_workers,
        };
        let target = requested.max(self.active_workers).min(self.max_workers);

        self.window_started_at = now;
        self.window_enqueued_rows = 0;
        self.window_completed_rows = 0;
        self.window_worker_wall = Duration::ZERO;
        self.window_completed_chunks = 0;

        if target > self.active_workers {
            self.active_workers = target;
            self.scale_up_events = self.scale_up_events.saturating_add(1);
            Some(target)
        } else {
            None
        }
    }
}

struct AsyncCompactFlushState {
    queue: VecDeque<QueuedCompactTopKChunk>,
    pending: QueuedCompactTopKChunk,
    used_bytes: usize,
    used_batches: usize,
    closed: bool,
    first_error: Option<String>,
    controller: AsyncCompactFlushController,
    queue_budget_bytes: usize,
    telemetry: AsyncCompactFlushTelemetry,
    leaf_profile: LeafProfile,
}

struct QueuedCompactTopKBatch {
    batch: CompactTopKBatch,
    bytes: usize,
}

#[derive(Default)]
struct QueuedCompactTopKChunk {
    batches: Vec<QueuedCompactTopKBatch>,
    bytes: usize,
    rows: usize,
}

impl QueuedCompactTopKChunk {
    fn is_empty(&self) -> bool {
        self.batches.is_empty()
    }

    fn len(&self) -> usize {
        self.batches.len()
    }

    fn would_exceed_target(&self, batch: &QueuedCompactTopKBatch) -> bool {
        !self.is_empty()
            && (self.len().saturating_add(1) > ASYNC_COMPACT_FLUSH_CHUNK_TARGET_BATCHES
                || self.rows.saturating_add(batch.batch.rows)
                    > ASYNC_COMPACT_FLUSH_CHUNK_TARGET_ROWS
                || self.bytes.saturating_add(batch.bytes) > ASYNC_COMPACT_FLUSH_CHUNK_TARGET_BYTES)
    }

    fn should_flush(&self) -> bool {
        self.len() >= ASYNC_COMPACT_FLUSH_CHUNK_TARGET_BATCHES
            || self.rows >= ASYNC_COMPACT_FLUSH_CHUNK_TARGET_ROWS
            || self.bytes >= ASYNC_COMPACT_FLUSH_CHUNK_TARGET_BYTES
    }

    fn push(&mut self, batch: QueuedCompactTopKBatch) {
        self.bytes = self.bytes.saturating_add(batch.bytes);
        self.rows = self.rows.saturating_add(batch.batch.rows);
        self.batches.push(batch);
    }
}

impl<'a> AsyncCompactFlushRuntime<'a> {
    fn new(
        sink: &'a dyn CompactTopKSink,
        queue_budget_bytes: usize,
        worker_policy: AsyncCompactFlushWorkerPolicy,
    ) -> Self {
        Self {
            sink,
            queue_budget_bytes: queue_budget_bytes.max(1),
            worker_policy,
        }
    }

    fn run(
        &self,
        produce: impl FnOnce(&AsyncCompactFlushProducer<'_>) -> AnnResult<()>,
    ) -> AnnResult<AsyncCompactFlushResult> {
        let initial_workers = self.worker_policy.initial_workers();
        let max_workers = self.worker_policy.max_workers().max(initial_workers);
        let initial_queue_budget =
            async_compact_flush_queue_budget(self.queue_budget_bytes, initial_workers);
        eprintln!(
            "gpu-subtree resident HashPrune workers: mode={} initial={} max={} queue_budget_bytes={}",
            self.worker_policy.mode_label(),
            initial_workers,
            max_workers,
            initial_queue_budget,
        );

        let shared = AsyncCompactFlushShared {
            queue_budget_limit_bytes: self.queue_budget_bytes,
            adaptive: self.worker_policy.is_adaptive(),
            state: Mutex::new(AsyncCompactFlushState {
                queue: VecDeque::new(),
                pending: QueuedCompactTopKChunk::default(),
                used_bytes: 0,
                used_batches: 0,
                closed: false,
                first_error: None,
                controller: AsyncCompactFlushController::new(
                    initial_workers,
                    max_workers,
                    Instant::now(),
                ),
                queue_budget_bytes: initial_queue_budget,
                telemetry: AsyncCompactFlushTelemetry {
                    worker_mode: self.worker_policy.mode_label(),
                    initial_workers,
                    max_workers,
                    peak_workers: initial_workers,
                    queue_budget_initial_bytes: initial_queue_budget,
                    queue_budget_peak_bytes: initial_queue_budget,
                    worker_count: initial_workers,
                    ..AsyncCompactFlushTelemetry::default()
                },
                leaf_profile: LeafProfile::default(),
            }),
            can_push: Condvar::new(),
            can_pop: Condvar::new(),
        };

        let worker_result = std::thread::scope(|scope| {
            let (scale_tx, scale_rx) = std::sync::mpsc::channel();
            let manager = scope.spawn(|| {
                async_compact_flush_worker_manager(
                    scope,
                    self.sink,
                    &shared,
                    initial_workers,
                    scale_rx,
                )
            });
            let producer = AsyncCompactFlushProducer {
                shared: &shared,
                scale_tx,
            };
            let produce_start = Instant::now();
            let producer_result = produce(&producer);
            {
                let mut state = shared.state.lock();
                state.telemetry.produce_wall += produce_start.elapsed();
            }
            shared.close();
            drop(producer);

            let join_start = Instant::now();
            let manager_error = match manager.join() {
                Ok(error) => error,
                Err(_) => Some("gpu-subtree async compact flush manager panicked".to_string()),
            };
            let join_wait_wall = join_start.elapsed();
            if let Some(message) = manager_error.as_ref() {
                shared.record_error(message.clone());
            }

            let mut state = shared.state.lock();
            state.telemetry.join_wait_wall += join_wait_wall;
            sync_async_compact_flush_controller_telemetry(&mut state);
            let worker_error = state.first_error.take();
            let result = AsyncCompactFlushResult {
                leaf: std::mem::take(&mut state.leaf_profile),
                telemetry: state.telemetry,
            };
            drop(state);

            if let Some(message) = manager_error.or(worker_error) {
                return Err(AnnError::log_index_error(message));
            }
            if let Err(err) = producer_result {
                return Err(err);
            }
            Ok(result)
        });

        worker_result
    }
}

impl AsyncCompactFlushProducer<'_> {
    fn enqueue(&self, batch: CompactTopKBatch) -> AnnResult<()> {
        let bytes = estimate_compact_topk_batch_bytes(&batch);
        let queued = QueuedCompactTopKBatch { batch, bytes };
        let wait_start = Instant::now();
        let mut state = self.shared.state.lock();
        state.controller.observe_enqueue(queued.batch.rows);
        refresh_async_compact_flush_queue_budget_locked(self.shared, &mut state);
        if state.pending.would_exceed_target(&queued) {
            flush_pending_compact_chunk_locked(&mut state);
            self.shared.can_pop.notify_one();
        }
        while state.first_error.is_none()
            && !state.closed
            && state.used_bytes > 0
            && state.used_bytes.saturating_add(bytes) > state.queue_budget_bytes.max(bytes)
        {
            if self.shared.adaptive {
                request_async_compact_flush_scale_locked(
                    self.shared,
                    &mut state,
                    &self.scale_tx,
                    true,
                );
                if state.first_error.is_some()
                    || state.closed
                    || state.used_bytes.saturating_add(bytes) <= state.queue_budget_bytes.max(bytes)
                {
                    break;
                }
            }
            if !state.pending.is_empty() {
                flush_pending_compact_chunk_locked(&mut state);
                self.shared.can_pop.notify_one();
            }
            self.shared.can_push.wait(&mut state);
        }
        let waited = wait_start.elapsed();
        state.telemetry.push_wait_wall += waited;
        if let Some(message) = state.first_error.clone() {
            return Err(AnnError::log_index_error(message));
        }
        if state.closed {
            return Err(AnnError::log_index_error(
                "gpu-subtree async compact flush queue is closed".to_string(),
            ));
        }
        state.used_bytes = state.used_bytes.saturating_add(bytes);
        state.used_batches = state.used_batches.saturating_add(1);
        state.telemetry.queue_max_bytes = state.telemetry.queue_max_bytes.max(state.used_bytes);
        state.telemetry.queue_max_batches =
            state.telemetry.queue_max_batches.max(state.used_batches);
        state.pending.push(queued);
        if state.pending.should_flush() || state.used_bytes >= state.queue_budget_bytes.max(bytes) {
            flush_pending_compact_chunk_locked(&mut state);
            self.shared.can_pop.notify_one();
        }
        if self.shared.adaptive {
            request_async_compact_flush_scale_locked(
                self.shared,
                &mut state,
                &self.scale_tx,
                false,
            );
            if let Some(message) = state.first_error.clone() {
                return Err(AnnError::log_index_error(message));
            }
        }
        Ok(())
    }
}

impl AsyncCompactFlushShared {
    fn close(&self) {
        let mut state = self.state.lock();
        flush_pending_compact_chunk_locked(&mut state);
        state.closed = true;
        self.can_pop.notify_all();
        self.can_push.notify_all();
    }

    fn record_error(&self, message: String) {
        let mut state = self.state.lock();
        state.telemetry.errors += 1;
        if state.first_error.is_none() {
            state.first_error = Some(message);
        }
        state.closed = true;
        self.can_pop.notify_all();
        self.can_push.notify_all();
    }
}

fn flush_pending_compact_chunk_locked(state: &mut AsyncCompactFlushState) -> bool {
    if state.pending.is_empty() {
        return false;
    }
    state.queue.push_back(std::mem::take(&mut state.pending));
    true
}

fn refresh_async_compact_flush_queue_budget_locked(
    shared: &AsyncCompactFlushShared,
    state: &mut AsyncCompactFlushState,
) {
    state.queue_budget_bytes = async_compact_flush_queue_budget(
        shared.queue_budget_limit_bytes,
        state.controller.active_workers,
    );
    state.telemetry.queue_budget_peak_bytes = state
        .telemetry
        .queue_budget_peak_bytes
        .max(state.queue_budget_bytes);
    sync_async_compact_flush_controller_telemetry(state);
}

fn sync_async_compact_flush_controller_telemetry(state: &mut AsyncCompactFlushState) {
    state.telemetry.controller_windows = state.controller.controller_windows;
    state.telemetry.controller_required_workers_peak = state.controller.required_workers_peak;
    state.telemetry.scale_up_events = state.controller.scale_up_events;
    state.telemetry.peak_workers = state
        .telemetry
        .peak_workers
        .max(state.controller.active_workers);
    state.telemetry.worker_count = state.telemetry.peak_workers;
}

fn request_async_compact_flush_scale_locked(
    shared: &AsyncCompactFlushShared,
    state: &mut AsyncCompactFlushState,
    scale_tx: &std::sync::mpsc::Sender<usize>,
    forced_by_backpressure: bool,
) {
    let queue_nonempty =
        state.used_bytes > 0 || !state.pending.is_empty() || !state.queue.is_empty();
    let previous_workers = state.controller.active_workers;
    let target =
        state
            .controller
            .maybe_scale(Instant::now(), queue_nonempty, forced_by_backpressure);
    refresh_async_compact_flush_queue_budget_locked(shared, state);
    let Some(target_workers) = target else {
        return;
    };

    eprintln!(
        "gpu-subtree resident HashPrune workers scale: {} -> {} queue_bytes={} budget_bytes={}",
        previous_workers, target_workers, state.used_bytes, state.queue_budget_bytes,
    );
    if scale_tx.send(target_workers).is_err() {
        let message = "gpu-subtree async compact flush manager channel disconnected".to_string();
        state.telemetry.errors = state.telemetry.errors.saturating_add(1);
        if state.first_error.is_none() {
            state.first_error = Some(message);
        }
        state.closed = true;
        shared.can_pop.notify_all();
        shared.can_push.notify_all();
    }
}

fn async_compact_flush_worker_manager<'scope, 'env>(
    scope: &'scope std::thread::Scope<'scope, 'env>,
    sink: &'env dyn CompactTopKSink,
    shared: &'env AsyncCompactFlushShared,
    initial_workers: usize,
    target_rx: std::sync::mpsc::Receiver<usize>,
) -> Option<String> {
    let mut workers = Vec::with_capacity(initial_workers);
    let mut created = 0usize;
    let mut spawn_to = |target: usize| {
        while created < target {
            workers.push(scope.spawn(move || async_compact_flush_worker(sink, shared)));
            created += 1;
        }
    };
    spawn_to(initial_workers.max(1));

    for target in target_rx {
        spawn_to(target);
    }

    let mut first_error = None;
    for worker in workers {
        if worker.join().is_err() && first_error.is_none() {
            first_error = Some("gpu-subtree async compact flush worker panicked".to_string());
        }
    }
    first_error
}

fn async_compact_flush_worker(sink: &dyn CompactTopKSink, shared: &AsyncCompactFlushShared) {
    loop {
        let chunk = {
            let mut state = shared.state.lock();
            loop {
                if let Some(chunk) = state.queue.pop_front() {
                    state.used_bytes = state.used_bytes.saturating_sub(chunk.bytes);
                    state.used_batches = state.used_batches.saturating_sub(chunk.len());
                    shared.can_push.notify_all();
                    break chunk;
                }
                if state.closed {
                    return;
                }
                shared.can_pop.wait(&mut state);
            }
        };

        let chunk_batches = chunk.len();
        let chunk_rows = chunk.rows;
        let batches = chunk
            .batches
            .into_iter()
            .map(|queued| queued.batch)
            .collect::<Vec<_>>();
        let flush_start = Instant::now();
        let chunk_profile = match sink.flush_compact_topk_batches(batches) {
            Ok(profile) => profile,
            Err(err) => {
                shared.record_error(err.to_string());
                return;
            }
        };
        let chunk_flush_wall = flush_start.elapsed();

        if chunk_batches > 0 {
            let mut state = shared.state.lock();
            state.telemetry.flush_wall += chunk_flush_wall;
            state.telemetry.worker_wall_sum += chunk_flush_wall;
            state.telemetry.batches += chunk_batches;
            state.telemetry.rows += chunk_rows;
            state.telemetry.chunks += 1;
            state
                .controller
                .observe_completion(chunk_rows, chunk_flush_wall);
            sync_async_compact_flush_controller_telemetry(&mut state);
            state.leaf_profile.merge(chunk_profile);
        }
    }
}

fn estimate_compact_topk_batch_bytes(batch: &CompactTopKBatch) -> usize {
    batch
        .rows
        .saturating_mul(
            batch
                .k
                .saturating_mul(size_of::<u32>() + size_of::<f32>())
                .saturating_add(size_of::<u32>()),
        )
        .max(batch.estimated_total_dtoh_bytes())
        .max(1)
}

fn compact_topk_coverage_error(message: impl std::fmt::Display) -> AnnError {
    AnnError::log_index_error(format!(
        "gpu-subtree compact top-k output does not cover child run: {message}"
    ))
}

