    telemetry.gpu_subtree_persistent_topk_idle_leaf_resets +=
        profile.persistent_topk_idle_leaf_resets;
    telemetry.gpu_subtree_persistent_topk_idle_large_resets +=
        profile.persistent_topk_idle_large_resets;
    telemetry.gpu_subtree_persistent_leaf_size_min = match (
        telemetry.gpu_subtree_persistent_leaf_size_count,
        profile.persistent_leaf_size_count,
    ) {
        (0, 0) => 0,
        (0, _) => profile.persistent_leaf_size_min,
        (_, 0) => telemetry.gpu_subtree_persistent_leaf_size_min,
        _ => telemetry
            .gpu_subtree_persistent_leaf_size_min
            .min(profile.persistent_leaf_size_min),
    };
    telemetry.gpu_subtree_persistent_leaf_size_max = telemetry
        .gpu_subtree_persistent_leaf_size_max
        .max(profile.persistent_leaf_size_max);
    telemetry.gpu_subtree_persistent_leaf_size_sum += profile.persistent_leaf_size_sum;
    telemetry.gpu_subtree_persistent_leaf_size_count += profile.persistent_leaf_size_count;
