fn persistent_async_d2h_max_rows(
    child_runs: &[GpuSubtreeChildRun],
    post_split_max_rows: Option<usize>,
) -> usize {
    let max_child_rows = child_runs
        .iter()
        .map(|child_run| child_run.len)
        .max()
        .unwrap_or(0);
    post_split_max_rows
        .filter(|max_rows| *max_rows > 0)
        .map_or(max_child_rows, |max_rows| max_child_rows.min(max_rows))
}

