fn percentile_nearest_rank(sorted: &[usize], pct: usize) -> usize {
    if sorted.is_empty() {
        return 0;
    }
    let rank = sorted.len().saturating_mul(pct).div_ceil(100);
    let idx = rank.saturating_sub(1).min(sorted.len() - 1);
    sorted[idx]
}

pub(crate) fn compute_gpu_subtree_child_run_stats(
    runs: &[GpuSubtreeChildRun],
) -> GpuSubtreeChildRunStats {
    if runs.is_empty() {
        return GpuSubtreeChildRunStats::default();
    }

    let mut lens = runs.iter().map(|run| run.len).collect::<Vec<_>>();
    lens.sort_unstable();
    let total_points = lens.iter().copied().sum::<usize>();
    let max_len = *lens.last().unwrap_or(&0);
    let p50_len = percentile_nearest_rank(&lens, 50);
    let p95_len = percentile_nearest_rank(&lens, 95);
    let p99_len = percentile_nearest_rank(&lens, 99);
    let histogram = build_gpu_subtree_child_run_histogram(&lens);

    GpuSubtreeChildRunStats {
        count: runs.len(),
        total_points,
        max_len,
        p50_len,
        p95_len,
        p99_len,
        histogram,
    }
}

fn build_gpu_subtree_child_run_histogram(sorted_lens: &[usize]) -> Vec<GpuSubtreeChildRunHistBin> {
    if sorted_lens.is_empty() {
        return Vec::new();
    }

    let max_len = *sorted_lens.last().unwrap();
    let mut upper = 1usize;
    let mut lower = 0usize;
    let mut bins = Vec::new();
    while lower <= max_len {
        let count = sorted_lens
            .iter()
            .filter(|&&len| len >= lower && len <= upper)
            .count();
        if count > 0 {
            bins.push(GpuSubtreeChildRunHistBin {
                lower_len: lower,
                upper_len: upper,
                count,
            });
        }
        if upper == usize::MAX {
            break;
        }
        lower = upper.saturating_add(1);
        upper = upper.saturating_mul(2).saturating_add(1);
    }
    bins
}

#[derive(Debug)]
struct RbcMemoryGate {
    capacity_bytes: usize,
    used_bytes: AtomicUsize,
}

#[derive(Debug)]
struct ResidentSubtreePermit<'a> {
    gate: &'a RbcMemoryGate,
    bytes: usize,
    active_resident_subtrees: Option<&'a AtomicUsize>,
}

