#[derive(Debug)]
struct RbcMemoryContext {
    total_budget_bytes: usize,
    scratch_budget_bytes: usize,
    resident_gate: RbcMemoryGate,
    single_subtree_cap_bytes: usize,
    active_compute_tasks: AtomicUsize,
    active_resident_subtrees: AtomicUsize,
}

#[derive(Debug)]
struct RbcComputeTaskGuard<'a> {
    memory: &'a RbcMemoryContext,
    budget_bytes: usize,
}

impl RbcMemoryGate {
    fn new(capacity_bytes: usize) -> Self {
        Self {
            capacity_bytes,
            used_bytes: AtomicUsize::new(0),
        }
    }

    #[cfg(test)]
    fn used_bytes(&self) -> usize {
        self.used_bytes.load(Ordering::Relaxed)
    }

    fn try_acquire(&self, bytes: usize) -> Option<ResidentSubtreePermit<'_>> {
        if bytes == 0 {
            return Some(ResidentSubtreePermit {
                gate: self,
                bytes,
                active_resident_subtrees: None,
            });
        }
        if bytes > self.capacity_bytes {
            return None;
        }

        let mut current = self.used_bytes.load(Ordering::Relaxed);
        loop {
            let next = current.checked_add(bytes)?;
            if next > self.capacity_bytes {
                return None;
            }
            match self.used_bytes.compare_exchange_weak(
                current,
                next,
                Ordering::Acquire,
                Ordering::Relaxed,
            ) {
                Ok(_) => {
                    return Some(ResidentSubtreePermit {
                        gate: self,
                        bytes,
                        active_resident_subtrees: None,
                    });
                }
                Err(observed) => current = observed,
            }
        }
    }
}

impl Drop for ResidentSubtreePermit<'_> {
    fn drop(&mut self) {
        if let Some(active_resident_subtrees) = self.active_resident_subtrees {
            active_resident_subtrees.fetch_sub(1, Ordering::AcqRel);
        }
        if self.bytes > 0 {
            self.gate
                .used_bytes
                .fetch_sub(self.bytes, Ordering::Release);
        }
    }
}

impl Drop for RbcComputeTaskGuard<'_> {
    fn drop(&mut self) {
        self.memory
            .active_compute_tasks
            .fetch_sub(1, Ordering::AcqRel);
    }
}

impl RbcComputeTaskGuard<'_> {
    fn budget_bytes(&self) -> usize {
        self.budget_bytes
    }
}

fn estimate_resident_subtree_bytes(points: usize, dim: usize) -> usize {
    let point_bytes = points.saturating_mul(dim).saturating_mul(size_of::<f32>());
    let id_bytes = points.saturating_mul(size_of::<u32>());
    let mapping_bytes = points.saturating_mul(size_of::<(u32, usize)>());
    let base = point_bytes
        .saturating_add(id_bytes)
        .saturating_add(mapping_bytes);
    base.saturating_add(base / 10)
}

fn estimate_recursive_scratch_reserve_bytes(recursion_budget_bytes: Option<usize>) -> usize {
    const MIN_RECURSIVE_SCRATCH_RESERVE: usize = 8 * 1024 * 1024;
    const MAX_RECURSIVE_SCRATCH_RESERVE: usize = 512 * 1024 * 1024;

    recursion_budget_bytes
        .unwrap_or(MIN_RECURSIVE_SCRATCH_RESERVE)
        .saturating_div(32)
        .clamp(MIN_RECURSIVE_SCRATCH_RESERVE, MAX_RECURSIVE_SCRATCH_RESERVE)
}

fn estimate_resident_subtree_permit_bytes(
    points: usize,
    dim: usize,
    recursion_budget_bytes: Option<usize>,
) -> usize {
    estimate_resident_subtree_bytes(points, dim).saturating_add(
        estimate_recursive_scratch_reserve_bytes(recursion_budget_bytes),
    )
}

impl RbcMemoryContext {
    fn for_oom_budget(total_budget_bytes: usize, dim: usize) -> Option<Self> {
        let resident_budget = total_budget_bytes.saturating_mul(35) / 100;
        let scratch_budget_bytes = total_budget_bytes.saturating_mul(15) / 100;
        if resident_budget == 0 || total_budget_bytes == 0 || dim == 0 {
            return None;
        }
        let single_subtree_cap_bytes =
            (resident_budget / 2).max(estimate_resident_subtree_bytes(1, dim));
        Some(Self {
            total_budget_bytes,
            scratch_budget_bytes,
            resident_gate: RbcMemoryGate::new(resident_budget),
            single_subtree_cap_bytes,
            active_compute_tasks: AtomicUsize::new(0),
            active_resident_subtrees: AtomicUsize::new(0),
        })
    }

    fn single_subtree_cap_bytes(&self) -> usize {
        self.single_subtree_cap_bytes
    }

    fn active_compute_budget_slots(&self) -> usize {
        self.active_compute_tasks.load(Ordering::Acquire).max(1)
    }

    fn gemm_task_budget_bytes(&self) -> usize {
        const MIN_GEMM_TASK_BUDGET: usize = 8 * 1024 * 1024;

        let budget = self.scratch_budget_bytes / self.active_compute_budget_slots();
        budget
            .max(MIN_GEMM_TASK_BUDGET)
            .min(self.total_budget_bytes)
    }

    fn enter_compute_task(&self) -> RbcComputeTaskGuard<'_> {
        self.active_compute_tasks.fetch_add(1, Ordering::AcqRel);
        RbcComputeTaskGuard {
            memory: self,
            budget_bytes: self.gemm_task_budget_bytes(),
        }
    }

    fn try_acquire_resident_subtree(
        &self,
        points: usize,
        dim: usize,
    ) -> Option<ResidentSubtreePermit<'_>> {
        let resident_bytes = estimate_resident_subtree_bytes(points, dim);
        if resident_bytes > self.single_subtree_cap_bytes {
            return None;
        }

        self.active_resident_subtrees.fetch_add(1, Ordering::AcqRel);
        let permit_bytes = estimate_resident_subtree_permit_bytes(
            points,
            dim,
            Some(self.gemm_task_budget_bytes()),
        );
        match self.resident_gate.try_acquire(permit_bytes) {
            Some(mut permit) => {
                permit.active_resident_subtrees = Some(&self.active_resident_subtrees);
                Some(permit)
            }
            None => {
                self.active_resident_subtrees.fetch_sub(1, Ordering::AcqRel);
                None
            }
        }
    }
}

impl ResidentSubtreeOptions<'_> {
    fn without_materialization(self) -> Self {
        Self {
            memory: self.memory,
            materialize: false,
        }
    }
}

impl ResidentSubtreeLeafEmitter<'_> {
    fn new(inner: &dyn LeafEmitter) -> ResidentSubtreeLeafEmitter<'_> {
        ResidentSubtreeLeafEmitter {
            inner,
            leaf_count: AtomicUsize::new(0),
            emit_wall_nanos: AtomicUsize::new(0),
        }
    }

    fn leaf_count(&self) -> usize {
        self.leaf_count.load(Ordering::Relaxed)
    }

    fn emit_wall(&self) -> Duration {
        Duration::from_nanos(self.emit_wall_nanos.load(Ordering::Relaxed) as u64)
    }
}

impl LeafEmitter for ResidentSubtreeLeafEmitter<'_> {
    fn emit_leaf(&self, leaf: Vec<u32>) -> AnnResult<()> {
        let emit_start = Instant::now();
        self.inner.emit_leaf(leaf)?;
        self.leaf_count.fetch_add(1, Ordering::Relaxed);
        self.emit_wall_nanos.fetch_add(
            emit_start.elapsed().as_nanos().min(usize::MAX as u128) as usize,
            Ordering::Relaxed,
        );
        Ok(())
    }
}

impl<'a> CompactTopKFallbackLeafEmitter<'a> {
    fn new(dataset: &'a dyn PointStore, params: &'a PiPNNParams) -> Self {
        Self {
            dataset,
            params,
            batches: Mutex::new(Vec::new()),
            profile: Mutex::new(LeafProfile::default()),
        }
    }

    fn finish(self) -> (Vec<CompactTopKBatch>, LeafProfile) {
        (self.batches.into_inner(), self.profile.into_inner())
    }
}

impl LeafEmitter for CompactTopKFallbackLeafEmitter<'_> {
    fn emit_leaf(&self, leaf: Vec<u32>) -> AnnResult<()> {
        let (batch, leaf_profile) = cpu_backend().compute_leaf_topk_l2(
            self.dataset,
            &leaf,
            self.params,
            self.params.kernel_safe_leaf_size(),
        )?;
        self.batches.lock().push(batch);
        self.profile.lock().merge(leaf_profile);
        Ok(())
    }
}

fn rbc_memory_context_for_params(
    params: &PiPNNParams,
    dim: usize,
    _worker_count: usize,
) -> Option<RbcMemoryContext> {
    if !params.oom_enable {
        return None;
    }
    RbcMemoryContext::for_oom_budget(params.effective_oom_memory_budget_bytes(), dim)
}

