#[derive(Debug)]
enum RootFanoutMode {
    Fixed,
    CellRadiusCertified {
        config: RadiusWitnessConfig,
        store: Mutex<RootRadiusWitnessStore>,
    },
    RiskBudgeted {
        config: RootRiskBudgetConfig,
        store: Mutex<RootRiskBudgetStore>,
    },
}

#[derive(Debug)]
struct RootFanoutState {
    mode: RootFanoutMode,
    profile: Mutex<RootFanoutProfile>,
    forced_root_leaders: Option<Vec<u32>>,
}

impl RootFanoutState {
    fn fixed(fanout: usize) -> Self {
        Self {
            mode: RootFanoutMode::Fixed,
            profile: Mutex::new(RootFanoutProfile::fixed(fanout)),
            forced_root_leaders: None,
        }
    }

    fn fixed_with_forced_leaders(fanout: usize, total_points: usize, leaders: &[u32]) -> Self {
        Self {
            mode: RootFanoutMode::Fixed,
            profile: Mutex::new(RootFanoutProfile::fixed_with_forced_leaders(
                fanout,
                total_points,
                leaders,
            )),
            forced_root_leaders: Some(leaders.to_vec()),
        }
    }

    fn radius(
        config: RadiusWitnessConfig,
        store: RootRadiusWitnessStore,
        profile: RootFanoutProfile,
        root_leaders: &[u32],
    ) -> Self {
        Self {
            mode: RootFanoutMode::CellRadiusCertified {
                config,
                store: Mutex::new(store),
            },
            profile: Mutex::new(profile),
            forced_root_leaders: Some(root_leaders.to_vec()),
        }
    }

    fn risk(
        config: RootRiskBudgetConfig,
        store: RootRiskBudgetStore,
        profile: RootFanoutProfile,
        root_leaders: &[u32],
    ) -> Self {
        Self {
            mode: RootFanoutMode::RiskBudgeted {
                config,
                store: Mutex::new(store),
            },
            profile: Mutex::new(profile),
            forced_root_leaders: Some(root_leaders.to_vec()),
        }
    }

    fn radius_config(&self) -> Option<&RadiusWitnessConfig> {
        match &self.mode {
            RootFanoutMode::CellRadiusCertified { config, .. } => Some(config),
            RootFanoutMode::Fixed | RootFanoutMode::RiskBudgeted { .. } => None,
        }
    }

    fn risk_config(&self) -> Option<&RootRiskBudgetConfig> {
        match &self.mode {
            RootFanoutMode::RiskBudgeted { config, .. } => Some(config),
            RootFanoutMode::Fixed | RootFanoutMode::CellRadiusCertified { .. } => None,
        }
    }

    fn variable_fixed_fanout(&self) -> Option<usize> {
        match &self.mode {
            RootFanoutMode::CellRadiusCertified { config, .. } => Some(config.fixed_fanout),
            RootFanoutMode::RiskBudgeted { config, .. } => Some(config.fixed_fanout),
            RootFanoutMode::Fixed => None,
        }
    }

    fn is_variable_root(&self) -> bool {
        self.variable_fixed_fanout().is_some()
    }

    fn radius_snapshot(&self) -> Option<super::root_radius_witness::RadiusWitnessSnapshot> {
        match &self.mode {
            RootFanoutMode::CellRadiusCertified { store, .. } => Some(store.lock().snapshot()),
            RootFanoutMode::Fixed | RootFanoutMode::RiskBudgeted { .. } => None,
        }
    }

    fn risk_snapshot(&self) -> Option<super::root_risk_budget::RootRiskBudgetSnapshot> {
        match &self.mode {
            RootFanoutMode::RiskBudgeted { config, store } => {
                Some(store.lock().snapshot_for_config(config))
            }
            RootFanoutMode::Fixed | RootFanoutMode::CellRadiusCertified { .. } => None,
        }
    }

    fn insert_radius_batch(&self, pending: Vec<(usize, f32, u32)>) {
        if pending.is_empty() {
            return;
        }
        if let RootFanoutMode::CellRadiusCertified { store, .. } = &self.mode {
            let update_start = Instant::now();
            store.lock().insert_batch_sorted(pending);
            let mut profile = self.profile.lock();
            profile.radius_update_ms += update_start.elapsed().as_millis();
        }
    }

    fn insert_risk_batch(&self, pending: Vec<(usize, f32)>) {
        if pending.is_empty() {
            return;
        }
        if let RootFanoutMode::RiskBudgeted { store, .. } = &self.mode {
            let update_start = Instant::now();
            store.lock().insert_batch_sorted(pending);
            let mut profile = self.profile.lock();
            profile.risk_update_ms += update_start.elapsed().as_millis();
        }
    }

    fn record_radius_telemetry(&self, telemetry: RadiusWitnessTelemetry) {
        let RootFanoutMode::CellRadiusCertified { store, .. } = &self.mode else {
            return;
        };
        let mut profile = self.profile.lock();
        profile.warmup_points_seen += telemetry.warmup_points_seen;
        profile.certified_points += telemetry.certified_points;
        profile.fallback_points += telemetry.fallback_points;
        profile.insufficient_radius_points += telemetry.insufficient_radius_points;
        if profile.kept_hist.len() < telemetry.kept_hist.len() {
            profile.kept_hist.resize(telemetry.kept_hist.len(), 0);
        }
        for (kept, count) in telemetry.kept_hist.into_iter().enumerate() {
            profile.kept_hist[kept] += count;
        }
        profile.selector_ms += telemetry.selector_ms;
        update_projected_root_fanout_bytes(&mut profile);
        profile.avg_fanout = root_fanout_avg(&profile.kept_hist);
        profile.ready_cells = store.lock().snapshot().ready_cells();
    }

    fn record_risk_calibration(&self, calibration: RootRiskBudgetCalibration) {
        if !matches!(self.mode, RootFanoutMode::RiskBudgeted { .. }) {
            return;
        };
        let mut profile = self.profile.lock();
        profile.calibrated_budget_lambda = Some(calibration.budget_lambda);
        profile.calibration_points = calibration.points;
        profile.warmup_points_seen = calibration.points;
        profile.calibration_avg_fanout = calibration.avg_fanout;
    }

    fn record_risk_telemetry(&self, telemetry: RootRiskBudgetTelemetry) {
        let RootFanoutMode::RiskBudgeted { store, config } = &self.mode else {
            return;
        };
        let mut profile = self.profile.lock();
        profile.fallback_points += telemetry.fallback_points;
        profile.insufficient_stats_points += telemetry.insufficient_stats_points;
        if profile.kept_hist.len() < telemetry.kept_hist.len() {
            profile.kept_hist.resize(telemetry.kept_hist.len(), 0);
        }
        for (kept, count) in telemetry.kept_hist.iter().copied().enumerate() {
            profile.kept_hist[kept] += count;
        }
        profile.selector_ms += telemetry.selector_ms;
        profile.retained_utility_sum += telemetry.retained_utility_sum;
        profile.omitted_utility_sum += telemetry.omitted_utility_sum;
        let total = profile.kept_hist.iter().sum::<usize>();
        profile.omitted_utility_avg = if total == 0 {
            0.0
        } else {
            profile.omitted_utility_sum / total as f64
        };
        if profile.risk_child_counts.len() < telemetry.child_counts().len() {
            profile
                .risk_child_counts
                .resize(telemetry.child_counts().len(), 0);
        }
        for (idx, count) in telemetry.child_counts().iter().copied().enumerate() {
            profile.risk_child_counts[idx] += count;
        }
        profile.sum_child_size_squared_ratio = child_sum_squared_ratio(&profile.risk_child_counts);
        profile.largest_child_ratio = child_largest_ratio(&profile.risk_child_counts);
        profile.child_size_cv = child_size_cv(&profile.risk_child_counts);
        profile.predicted_work_score =
            profile.sum_child_size_squared_ratio * root_fanout_avg(&profile.kept_hist);
        update_projected_root_fanout_bytes(&mut profile);
        profile.avg_fanout = root_fanout_avg(&profile.kept_hist);
        profile.actual_avg_fanout = profile.avg_fanout;
        profile.ready_cells = store.lock().snapshot_for_config(config).ready_cells();
    }

    fn profile(&self) -> RootFanoutProfile {
        let mut profile = self.profile.lock().clone();
        if let RootFanoutMode::CellRadiusCertified { store, .. } = &self.mode {
            profile.ready_cells = store.lock().snapshot().ready_cells();
            profile.avg_fanout = root_fanout_avg(&profile.kept_hist);
            update_projected_root_fanout_bytes(&mut profile);
        } else if let RootFanoutMode::RiskBudgeted { config, store } = &self.mode {
            profile.ready_cells = store.lock().snapshot_for_config(config).ready_cells();
            profile.avg_fanout = root_fanout_avg(&profile.kept_hist);
            profile.actual_avg_fanout = profile.avg_fanout;
            update_projected_root_fanout_bytes(&mut profile);
        }
        profile
    }
}

fn root_fanout_avg(hist: &[usize]) -> f64 {
    let total: usize = hist.iter().sum();
    if total == 0 {
        return 0.0;
    }
    let weighted: usize = hist
        .iter()
        .enumerate()
        .map(|(fanout, count)| fanout * count)
        .sum();
    weighted as f64 / total as f64
}

fn child_sum_squared_ratio(child_counts: &[usize]) -> f64 {
    let total = child_counts.iter().sum::<usize>();
    if total == 0 {
        return 0.0;
    }
    let sum_sq = child_counts
        .iter()
        .map(|&count| {
            let count = count as f64;
            count * count
        })
        .sum::<f64>();
    sum_sq / (total as f64 * total as f64)
}

fn child_largest_ratio(child_counts: &[usize]) -> f64 {
    let total = child_counts.iter().sum::<usize>();
    if total == 0 {
        return 0.0;
    }
    child_counts.iter().copied().max().unwrap_or(0) as f64 / total as f64
}

fn child_size_cv(child_counts: &[usize]) -> f64 {
    if child_counts.is_empty() {
        return 0.0;
    }
    let total = child_counts.iter().sum::<usize>() as f64;
    if total == 0.0 {
        return 0.0;
    }
    let mean = total / child_counts.len() as f64;
    if mean == 0.0 {
        return 0.0;
    }
    let variance = child_counts
        .iter()
        .map(|&count| {
            let delta = count as f64 - mean;
            delta * delta
        })
        .sum::<f64>()
        / child_counts.len() as f64;
    variance.sqrt() / mean
}

fn update_projected_root_fanout_bytes(profile: &mut RootFanoutProfile) {
    let projected_assignments: usize = profile
        .kept_hist
        .iter()
        .enumerate()
        .map(|(fanout, count)| fanout.saturating_mul(*count))
        .sum();
    profile.projected_assignment_bytes = projected_assignments.saturating_mul(size_of::<u32>());
    profile.projected_partition_d00_bytes_pre_dedup = profile.projected_assignment_bytes;
}

fn initialize_root_fanout_state(
    _dataset: &dyn PointStore,
    indices: &[u32],
    leaders: &[u32],
    params: &PiPNNParams,
    metric: Metric,
    _rng: &mut (impl Rng + Send),
) -> AnnResult<RootFanoutState> {
    let fixed_fanout = params.fanout_top.max(1).min(leaders.len().max(1)).min(32);
    let use_risk_budget = matches!(params.root_fanout_policy, RootFanoutPolicy::RiskBudgeted)
        || params.root_risk_dry_run;
    if use_risk_budget {
        if matches!(params.root_fanout_policy, RootFanoutPolicy::RiskBudgeted)
            && !params.root_risk_dry_run
            && !params.root_stop_after_d00
            && !params.root_risk_allow_full_build
        {
            return Err(AnnError::log_index_config_error(
                "root_fanout_policy".to_string(),
                "risk-budgeted is root-only; use root_risk_dry_run, root_stop_after_d00, or root_risk_allow_full_build"
                    .to_string(),
            ));
        }
        let mut candidate_rs: Vec<_> = params
            .root_risk_candidate_rs
            .iter()
            .copied()
            .filter(|&r| r > 0 && r <= fixed_fanout)
            .collect();
        candidate_rs.push(fixed_fanout);
        candidate_rs.sort_unstable();
        candidate_rs.dedup();
        let min_fanout = candidate_rs.iter().copied().min().unwrap_or(fixed_fanout);
        let config = RootRiskBudgetConfig {
            fixed_fanout,
            min_fanout,
            candidate_rs,
            target_avg_fanout: params.root_risk_target_avg_fanout,
            warmup_points: params.root_risk_warmup_points,
            sigma_lambda: params.root_risk_sigma_lambda,
            budget_lambda_override: params.root_risk_budget_lambda,
            sigma_mode: params.root_risk_sigma_mode,
        };
        let mut profile = RootFanoutProfile {
            policy: "risk-budgeted".to_string(),
            selection_semantics: "budgeted_utility_core_drop_v1".to_string(),
            enabled: true,
            dry_run: params.root_risk_dry_run,
            fixed_fanout,
            candidate_rs: config.candidate_rs.clone(),
            warmup_points: config.warmup_points,
            total_points: indices.len(),
            kept_hist: vec![0; fixed_fanout.max(1) + 1],
            target_avg_fanout: config.target_avg_fanout,
            calibrated_budget_lambda: config.budget_lambda_override,
            sigma_lambda: config.sigma_lambda,
            sigma_mode: config.sigma_mode.to_string(),
            root_leader_hash: root_leader_fingerprint(leaders),
            ..RootFanoutProfile::default()
        };
        if metric != Metric::L2 {
            profile.enabled = false;
            profile.fallback_reason = Some("metric_not_l2".to_string());
            return Ok(RootFanoutState {
                mode: RootFanoutMode::Fixed,
                profile: Mutex::new(profile),
                forced_root_leaders: None,
            });
        }
        let store = RootRiskBudgetStore::new(leaders.len());
        return Ok(RootFanoutState::risk(config, store, profile, leaders));
    }
    if !matches!(
        params.root_fanout_policy,
        RootFanoutPolicy::CellRadiusCertified
    ) && !params.root_radius_dry_run
    {
        if params.gpu_subtree_d0_capacity_enable && !leaders.is_empty() {
            return Ok(RootFanoutState::fixed_with_forced_leaders(
                fixed_fanout,
                indices.len(),
                leaders,
            ));
        }
        return Ok(RootFanoutState::fixed(fixed_fanout));
    }

    let mut candidate_rs: Vec<_> = params
        .root_radius_candidate_rs
        .iter()
        .copied()
        .filter(|&r| r > 0 && r < fixed_fanout)
        .collect();
    candidate_rs.sort_unstable();
    candidate_rs.dedup();
    let config = RadiusWitnessConfig {
        k: params.root_radius_k.max(1),
        fixed_fanout,
        candidate_rs,
        warmup_points: params.root_radius_warmup_points,
        dry_run: params.root_radius_dry_run,
    };
    let mut profile = RootFanoutProfile {
        policy: "cell-radius-certified".to_string(),
        selection_semantics: "cell_radius_certified_root_assignment_v1".to_string(),
        enabled: true,
        dry_run: params.root_radius_dry_run,
        k: config.k,
        fixed_fanout,
        candidate_rs: config.candidate_rs.clone(),
        warmup_points: config.warmup_points,
        total_points: indices.len(),
        kept_hist: vec![0; fixed_fanout.max(1) + 1],
        root_leader_hash: root_leader_fingerprint(leaders),
        ..RootFanoutProfile::default()
    };
    if metric != Metric::L2 {
        profile.enabled = false;
        profile.fallback_reason = Some("metric_not_l2".to_string());
        return Ok(RootFanoutState {
            mode: RootFanoutMode::Fixed,
            profile: Mutex::new(profile),
            forced_root_leaders: None,
        });
    }

    let store = RootRadiusWitnessStore::new(leaders.len(), config.k);
    Ok(RootFanoutState::radius(config, store, profile, leaders))
}

#[derive(Debug)]
struct ExternalRunStore {
    base_dir: PathBuf,
    io_cfg: DirectIoConfig,
    writers: HashMap<usize, RunAppender>,
}

#[derive(Debug)]
enum RunAppender {
    Buffered(BufWriter<File>),
    Direct { file: DirectIoFile, offset: u64 },
}

impl ExternalRunStore {
    fn new(base_dir: &Path, io_cfg: DirectIoConfig) -> Self {
        Self {
            base_dir: base_dir.to_path_buf(),
            io_cfg,
            writers: HashMap::new(),
        }
    }

    fn path_for_depth(&self, depth: usize) -> PathBuf {
        self.base_dir
            .join(format!("partition_d{depth:02}_runs.bin"))
    }

    fn io_config(&self) -> DirectIoConfig {
        self.io_cfg
    }

    fn append_points(&mut self, depth: usize, points: &[u32]) -> AnnResult<RunExtent> {
        let path = self.path_for_depth(depth);
        let io_cfg = self.io_cfg;
        let writer = self.writers.entry(depth).or_insert_with(|| {
            if io_cfg.enabled {
                let offset = std::fs::metadata(&path).map(|meta| meta.len()).unwrap_or(0);
                RunAppender::Direct {
                    file: DirectIoFile::open_rw(&path, io_cfg, false).unwrap(),
                    offset,
                }
            } else {
                let file = OpenOptions::new()
                    .create(true)
                    .append(true)
                    .read(true)
                    .open(&path)
                    .unwrap();
                RunAppender::Buffered(BufWriter::new(file))
            }
        });

        let byte_offset = match writer {
            RunAppender::Buffered(writer) => {
                let byte_offset = writer.seek(SeekFrom::End(0))?;
                writer.write_all(&(points.len() as u64).to_le_bytes())?;
                for &point in points {
                    writer.write_all(&point.to_le_bytes())?;
                }
                writer.flush()?;
                byte_offset
            }
            RunAppender::Direct { file, offset } => {
                let byte_offset = *offset;
                let mut bytes =
                    Vec::with_capacity(RUN_EXTENT_HEADER_BYTES + points.len() * size_of::<u32>());
                bytes.extend_from_slice(&(points.len() as u64).to_le_bytes());
                for &point in points {
                    bytes.extend_from_slice(&point.to_le_bytes());
                }
                file.write_all_at(&bytes, *offset)?;
                *offset += bytes.len() as u64;
                byte_offset
            }
        };
        Ok(RunExtent {
            byte_offset,
            len: points.len(),
        })
    }

    fn read_points(&self, depth: usize, extent: RunExtent) -> AnnResult<Vec<u32>> {
        read_run_points_from_path(&self.path_for_depth(depth), self.io_cfg, extent)
    }

    fn finalize(&mut self) -> AnnResult<()> {
        for writer in self.writers.values_mut() {
            match writer {
                RunAppender::Buffered(writer) => {
                    writer.flush()?;
                }
                RunAppender::Direct { file, offset } => {
                    file.set_len(*offset)?;
                    file.sync_all()?;
                }
            }
        }
        Ok(())
    }
}

impl Drop for ExternalRunStore {
    fn drop(&mut self) {
        let _ = self.finalize();
    }
}

fn write_child_run(
    store: &mut ExternalRunStore,
    depth: usize,
    points: &[u32],
) -> AnnResult<RunExtent> {
    store.append_points(depth, points)
}

fn read_run_points_from_path(
    path: &Path,
    io_cfg: DirectIoConfig,
    extent: RunExtent,
) -> AnnResult<Vec<u32>> {
    if io_cfg.enabled {
        let file = DirectIoFile::open_read(path, io_cfg)?;
        let mut header = [0u8; RUN_EXTENT_HEADER_BYTES];
        file.read_exact_at(&mut header, extent.byte_offset)?;
        let len = u64::from_le_bytes(header) as usize;
        let mut bytes = vec![0u8; len * size_of::<u32>()];
        file.read_exact_at(
            &mut bytes,
            extent.byte_offset + RUN_EXTENT_HEADER_BYTES as u64,
        )?;
        let mut points = vec![0_u32; len];
        for (idx, point) in points.iter_mut().enumerate() {
            let start = idx * size_of::<u32>();
            *point = u32::from_le_bytes(bytes[start..start + size_of::<u32>()].try_into().unwrap());
        }
        return Ok(points);
    }

    let mut reader = BufReader::new(File::open(path)?);
    reader.seek(SeekFrom::Start(extent.byte_offset))?;
    let mut header = [0u8; RUN_EXTENT_HEADER_BYTES];
    reader.read_exact(&mut header)?;
    let len = u64::from_le_bytes(header) as usize;
    let mut points = vec![0_u32; len];
    let mut buf = [0u8; size_of::<u32>()];
    for point in &mut points {
        reader.read_exact(&mut buf)?;
        *point = u32::from_le_bytes(buf);
    }
    Ok(points)
}

fn read_first_run_point_from_path(
    path: &Path,
    io_cfg: DirectIoConfig,
    extent: RunExtent,
) -> AnnResult<Option<u32>> {
    if extent.len == 0 {
        return Ok(None);
    }

    if io_cfg.enabled {
        let file = DirectIoFile::open_read(path, io_cfg)?;
        let mut header = [0u8; RUN_EXTENT_HEADER_BYTES];
        file.read_exact_at(&mut header, extent.byte_offset)?;
        let len = u64::from_le_bytes(header) as usize;
        if len == 0 {
            return Ok(None);
        }
        let mut bytes = [0u8; size_of::<u32>()];
        file.read_exact_at(
            &mut bytes,
            extent.byte_offset + RUN_EXTENT_HEADER_BYTES as u64,
        )?;
        return Ok(Some(u32::from_le_bytes(bytes)));
    }

    let mut reader = BufReader::new(File::open(path)?);
    reader.seek(SeekFrom::Start(extent.byte_offset))?;
    let mut header = [0u8; RUN_EXTENT_HEADER_BYTES];
    reader.read_exact(&mut header)?;
    let len = u64::from_le_bytes(header) as usize;
    if len == 0 {
        return Ok(None);
    }
    let mut bytes = [0u8; size_of::<u32>()];
    reader.read_exact(&mut bytes)?;
    Ok(Some(u32::from_le_bytes(bytes)))
}

fn read_child_run(
    store: &ExternalRunStore,
    depth: usize,
    extent: RunExtent,
) -> AnnResult<Vec<u32>> {
    let points = store.read_points(depth, extent)?;
    debug_assert_eq!(points.len(), extent.len);
    Ok(points)
}

fn read_child_run_chain(
    store: &ExternalRunStore,
    depth: usize,
    extents: &[RunExtent],
) -> AnnResult<Vec<u32>> {
    let total_len = extents.iter().map(|extent| extent.len).sum();
    let mut points = Vec::with_capacity(total_len);
    for &extent in extents {
        let mut chunk = read_child_run(store, depth, extent)?;
        points.append(&mut chunk);
    }
    Ok(points)
}

fn read_child_run_chain_from_path(
    base_dir: &Path,
    io_cfg: DirectIoConfig,
    depth: usize,
    extents: &[RunExtent],
) -> AnnResult<Vec<u32>> {
    let total_len = extents.iter().map(|extent| extent.len).sum();
    let mut points = Vec::with_capacity(total_len);
    let path = base_dir.join(format!("partition_d{depth:02}_runs.bin"));
    for &extent in extents {
        let mut chunk = read_run_points_from_path(&path, io_cfg, extent)?;
        points.append(&mut chunk);
    }
    Ok(points)
}

const GPU_SUBTREE_D0_HASH_VERSION: u64 = 1;
const FNV1A64_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
const FNV1A64_PRIME: u64 = 0x0000_0100_0000_01b3;

struct StableFnv1a64(u64);

impl StableFnv1a64 {
    fn new(domain: &[u8]) -> Self {
        let mut hash = Self(FNV1A64_OFFSET_BASIS);
        hash.write(domain);
        hash
    }

    fn write(&mut self, bytes: &[u8]) {
        for &byte in bytes {
            self.0 ^= u64::from(byte);
            self.0 = self.0.wrapping_mul(FNV1A64_PRIME);
        }
    }

    fn write_u64(&mut self, value: u64) {
        self.write(&value.to_le_bytes());
    }

    fn finish(self) -> u64 {
        if self.0 == 0 { 1 } else { self.0 }
    }
}

fn canonical_gpu_subtree_d0_hashes(children: &[(usize, usize, u64, Vec<Vec<u32>>)]) -> (u64, u64) {
    let mut membership = children
        .iter()
        .flat_map(|(child_index, _, _, extents)| {
            extents
                .iter()
                .flatten()
                .map(|&point_id| (*child_index, point_id))
        })
        .collect::<Vec<_>>();
    membership.sort_unstable();

    let mut partition_hash = StableFnv1a64::new(b"SHEAR-D0-PARTITION\0");
    partition_hash.write_u64(GPU_SUBTREE_D0_HASH_VERSION);
    partition_hash.write_u64(children.len() as u64);
    partition_hash.write_u64(membership.len() as u64);
    for (child_index, point_id) in membership {
        partition_hash.write_u64(child_index as u64);
        partition_hash.write_u64(u64::from(point_id));
    }

    let mut task_list_hash = StableFnv1a64::new(b"SHEAR-D0-TASK-LIST\0");
    task_list_hash.write_u64(GPU_SUBTREE_D0_HASH_VERSION);
    task_list_hash.write_u64(children.len() as u64);
    for (child_index, len, seed, _) in children {
        task_list_hash.write_u64(*child_index as u64);
        task_list_hash.write_u64(*len as u64);
        task_list_hash.write_u64(*seed);
    }

    (partition_hash.finish(), task_list_hash.finish())
}

fn gpu_subtree_d0_hash_inputs(
    d0_plan: &GpuSubtreeD0Plan,
) -> AnnResult<Vec<(usize, usize, u64, Vec<Vec<u32>>)>> {
    if d0_plan.sq_shard_local_payloads.is_empty() {
        let path = d0_plan.external_child_dir.join("partition_d00_runs.bin");
        return d0_plan
            .child_runs
            .iter()
            .enumerate()
            .map(|(child_index, child_run)| {
                let extents = child_run
                    .extents
                    .iter()
                    .map(|&extent| read_run_points_from_path(&path, d0_plan.io_cfg, extent))
                    .collect::<AnnResult<Vec<_>>>()?;
                let stored_len = extents.iter().map(Vec::len).sum::<usize>();
                if stored_len != child_run.len {
                    return Err(AnnError::log_index_error(format!(
                        "GPU-subtree D0 hash expected child {} length {}, read {}",
                        child_index, child_run.len, stored_len
                    )));
                }
                Ok((child_index, child_run.len, child_run.seed, extents))
            })
            .collect();
    }

    if !d0_plan.sq_cluster_child_indices.is_empty() {
        if d0_plan.sq_cluster_child_indices.len() != d0_plan.child_runs.len() {
            return Err(AnnError::log_index_error(format!(
                "GPU-subtree D0 hash has {} cluster child indices for {} child runs",
                d0_plan.sq_cluster_child_indices.len(),
                d0_plan.child_runs.len()
            )));
        }
        return d0_plan
            .child_runs
            .iter()
            .zip(&d0_plan.sq_cluster_child_indices)
            .enumerate()
            .map(|(task_index, (child_run, &source_child_index))| {
                let mut points = Vec::with_capacity(child_run.len);
                for payload in &d0_plan.sq_shard_local_payloads {
                    let child_rows = payload
                        .child_local_rows
                        .get(source_child_index)
                        .ok_or_else(|| {
                            AnnError::log_index_error(format!(
                                "GPU-subtree D0 hash cluster child {} is outside payload width {}",
                                source_child_index,
                                payload.child_local_rows.len()
                            ))
                        })?;
                    for &local_row in child_rows {
                        points.push(*payload.ids.get(local_row).ok_or_else(|| {
                            AnnError::log_index_error(format!(
                                "GPU-subtree D0 hash local row {} is outside payload rows {}",
                                local_row,
                                payload.ids.len()
                            ))
                        })?);
                    }
                }
                if points.len() != child_run.len {
                    return Err(AnnError::log_index_error(format!(
                        "GPU-subtree D0 hash expected cluster task {} length {}, gathered {}",
                        task_index,
                        child_run.len,
                        points.len()
                    )));
                }
                Ok((
                    source_child_index,
                    child_run.len,
                    child_run.seed,
                    vec![points],
                ))
            })
            .collect();
    }

    let mut inputs = Vec::with_capacity(d0_plan.child_runs.len());
    let mut run_index = 0usize;
    for payload in &d0_plan.sq_shard_local_payloads {
        for child_rows in &payload.child_local_rows {
            if child_rows.is_empty() {
                continue;
            }
            let child_run = d0_plan.child_runs.get(run_index).ok_or_else(|| {
                AnnError::log_index_error(format!(
                    "GPU-subtree D0 hash is missing shard-local child run {}",
                    run_index
                ))
            })?;
            let points = child_rows
                .iter()
                .map(|&local_row| {
                    payload.ids.get(local_row).copied().ok_or_else(|| {
                        AnnError::log_index_error(format!(
                            "GPU-subtree D0 hash local row {} is outside payload rows {}",
                            local_row,
                            payload.ids.len()
                        ))
                    })
                })
                .collect::<AnnResult<Vec<_>>>()?;
            if points.len() != child_run.len {
                return Err(AnnError::log_index_error(format!(
                    "GPU-subtree D0 hash expected shard-local task {} length {}, gathered {}",
                    run_index,
                    child_run.len,
                    points.len()
                )));
            }
            inputs.push((run_index, child_run.len, child_run.seed, vec![points]));
            run_index += 1;
        }
    }
    if run_index != d0_plan.child_runs.len() {
        return Err(AnnError::log_index_error(format!(
            "GPU-subtree D0 hash gathered {} shard-local tasks for {} child runs",
            run_index,
            d0_plan.child_runs.len()
        )));
    }
    Ok(inputs)
}

fn finalize_gpu_subtree_d0_hashes(mut d0_plan: GpuSubtreeD0Plan) -> AnnResult<GpuSubtreeD0Plan> {
    let inputs = gpu_subtree_d0_hash_inputs(&d0_plan)?;
    let (partition_hash, task_list_hash) = canonical_gpu_subtree_d0_hashes(&inputs);
    RbcPartitionTelemetry::merge_observed_d0_hash(
        &mut d0_plan.rbc_telemetry.gpu_subtree_d0_partition_hash,
        partition_hash,
        &mut d0_plan.rbc_telemetry.gpu_subtree_d0_hash_conflict,
    );
    RbcPartitionTelemetry::merge_observed_d0_hash(
        &mut d0_plan.rbc_telemetry.gpu_subtree_d0_task_list_hash,
        task_list_hash,
        &mut d0_plan.rbc_telemetry.gpu_subtree_d0_hash_conflict,
    );
    d0_plan.rbc_telemetry.validate_gpu_subtree_d0_hashes()?;
    Ok(d0_plan)
}

fn first_point_from_child_run_chain_from_path(
    base_dir: &Path,
    io_cfg: DirectIoConfig,
    depth: usize,
    extents: &[RunExtent],
) -> AnnResult<Option<u32>> {
    let path = base_dir.join(format!("partition_d{depth:02}_runs.bin"));
    for &extent in extents {
        if let Some(point) = read_first_run_point_from_path(&path, io_cfg, extent)? {
            return Ok(Some(point));
        }
    }
    Ok(None)
}

fn scan_gpu_subtree_child_unique_sizes(
    base_dir: &Path,
    io_cfg: DirectIoConfig,
    child_runs: &[GpuSubtreeChildRun],
) -> AnnResult<Vec<usize>> {
    let mut sizes = Vec::with_capacity(child_runs.len());
    for child_run in child_runs {
        let mut points = read_child_run_chain_from_path(base_dir, io_cfg, 0, &child_run.extents)?;
        points.sort_unstable();
        points.dedup();
        sizes.push(points.len());
    }
    Ok(sizes)
}

pub(crate) fn gpu_subtree_entry_point_from_d0_plan(
    d0_plan: &GpuSubtreeD0Plan,
) -> AnnResult<Option<u32>> {
    if let Some(point) = gpu_subtree_entry_point_from_sq_payloads(d0_plan) {
        return Ok(Some(point));
    }

    let Some(child_run) = d0_plan
        .child_runs
        .iter()
        .filter(|child_run| child_run.len > 0)
        .max_by_key(|child_run| child_run.len)
    else {
        return Ok(None);
    };

    first_point_from_child_run_chain_from_path(
        &d0_plan.external_child_dir,
        d0_plan.io_cfg,
        0,
        &child_run.extents,
    )
}

fn gpu_subtree_entry_point_from_sq_payloads(d0_plan: &GpuSubtreeD0Plan) -> Option<u32> {
    let mut best: Option<(usize, u32)> = None;
    for payload in &d0_plan.sq_shard_local_payloads {
        for child_rows in &payload.child_local_rows {
            let Some(&local_row) = child_rows.first() else {
                continue;
            };
            let Some(&point_id) = payload.ids.get(local_row) else {
                continue;
            };
            let candidate = (child_rows.len(), point_id);
            best = match best {
                Some(current) if current.0 > candidate.0 => Some(current),
                Some(current) if current.0 == candidate.0 && current.1 <= candidate.1 => {
                    Some(current)
                }
                _ => Some(candidate),
            };
        }
    }
    best.map(|(_, point_id)| point_id)
}

#[cfg(test)]
fn split_points_by_nearest_local_leader_for_test(points: &[u32], leaders: &[u32]) -> Vec<Vec<u32>> {
    let mut clusters = vec![Vec::new(); leaders.len()];
    for &point in points {
        let (best_idx, _) = leaders
            .iter()
            .enumerate()
            .map(|(idx, &leader)| (idx, point.abs_diff(leader)))
            .min_by_key(|&(idx, distance)| (distance, idx))
            .unwrap();
        clusters[best_idx].push(point);
    }
    clusters
}

fn merge_cluster_plan(raw_counts: &[usize], c_min: usize, c_max: usize) -> Vec<MergedRawGroup> {
    let mut clusters: Vec<(u16, usize)> = raw_counts
        .iter()
        .copied()
        .enumerate()
        .filter_map(|(raw_child, len)| (len > 0).then_some((raw_child as u16, len)))
        .collect();
    if clusters.is_empty() {
        return Vec::new();
    }

    clusters.sort_by_key(|&(_, len)| len);

    let mut result: Vec<MergedRawGroup> = Vec::new();
    let mut current_small: Option<MergedRawGroup> = None;

    for (raw_child, size) in clusters {
        let cluster = MergedRawGroup {
            raw_children: vec![raw_child],
            raw_len: size,
        };
        if size >= c_min {
            if let Some(small) = current_small.take() {
                if small.raw_len + size <= c_max {
                    let mut merged_children = vec![raw_child];
                    merged_children.extend_from_slice(&small.raw_children);
                    result.push(MergedRawGroup {
                        raw_children: merged_children,
                        raw_len: size + small.raw_len,
                    });
                } else {
                    result.push(small);
                    result.push(cluster);
                }
            } else {
                result.push(cluster);
            }
        } else {
            match current_small.take() {
                Some(small) => {
                    if small.raw_len + size <= c_max {
                        let mut merged_children = small.raw_children;
                        merged_children.push(raw_child);
                        current_small = Some(MergedRawGroup {
                            raw_children: merged_children,
                            raw_len: small.raw_len + size,
                        });
                    } else {
                        result.push(small);
                        current_small = Some(cluster);
                    }
                }
                None => {
                    current_small = Some(cluster);
                }
            }
        }
    }

    if let Some(small) = current_small {
        if let Some(last) = result.last_mut() {
            if last.raw_len + small.raw_len <= c_max {
                last.raw_children.extend_from_slice(&small.raw_children);
                last.raw_len += small.raw_len;
            } else {
                result.push(small);
            }
        } else {
            result.push(small);
        }
    }

    result
}

fn assign_record_fanout(local_fanout: usize) -> usize {
    local_fanout.max(1).min(32)
}

fn assign_record_width(record_cap: usize) -> usize {
    1 + 2 * assign_record_fanout(record_cap)
}

fn write_assign_record(
    writer: &mut BufWriter<File>,
    leaders: &[u16],
    record_cap: usize,
) -> AnnResult<()> {
    let record_cap = assign_record_fanout(record_cap);
    if leaders.len() > record_cap {
        return Err(AnnError::log_index_error(format!(
            "Assignment record contains {} leaders above cap {}",
            leaders.len(),
            record_cap
        )));
    }
    writer.write_all(&[leaders.len() as u8])?;
    for &leader in leaders {
        writer.write_all(&leader.to_le_bytes())?;
    }
    for _ in leaders.len()..record_cap {
        writer.write_all(&0u16.to_le_bytes())?;
    }
    Ok(())
}

fn read_assign_record(reader: &mut BufReader<File>, out: &mut [u16]) -> AnnResult<usize> {
    let mut count_buf = [0u8; 1];
    reader.read_exact(&mut count_buf)?;
    let count = count_buf[0] as usize;
    if count > out.len() {
        return Err(AnnError::log_index_error(format!(
            "Assignment record count {count} exceeds record cap {}",
            out.len()
        )));
    }
    let mut buf = [0u8; size_of::<u16>()];
    for slot in out.iter_mut() {
        reader.read_exact(&mut buf)?;
        *slot = u16::from_le_bytes(buf);
    }
    Ok(count)
}

fn append_assign_record_bytes(
    buf: &mut Vec<u8>,
    leaders: &[u16],
    record_cap: usize,
) -> AnnResult<()> {
    let record_cap = assign_record_fanout(record_cap);
    if leaders.len() > record_cap {
        return Err(AnnError::log_index_error(format!(
            "Assignment record contains {} leaders above cap {}",
            leaders.len(),
            record_cap
        )));
    }
    buf.push(leaders.len() as u8);
    for &leader in leaders {
        buf.extend_from_slice(&leader.to_le_bytes());
    }
    for _ in leaders.len()..record_cap {
        buf.extend_from_slice(&0u16.to_le_bytes());
    }
    Ok(())
}

fn flush_materialized_child_buffer(
    store: &mut ExternalRunStore,
    depth: usize,
    child: &mut BufferedMergedChild,
) -> AnnResult<()> {
    if child.buffer.is_empty() {
        return Ok(());
    }
    let extent = write_child_run(store, depth, &child.buffer)?;
    child.extents.push(extent);
    child.buffer.clear();
    Ok(())
}

fn materialize_merged_children_from_spool(
    cur: &[u32],
    depth: usize,
    fanout: usize,
    merge_groups: &[MergedRawGroup],
    spool: &NamedTempFile,
    store: &mut ExternalRunStore,
) -> AnnResult<Vec<MaterializedMergedChild>> {
    materialize_merged_children_from_spool_with_inline_limit(
        cur,
        depth,
        fanout,
        merge_groups,
        spool,
        store,
        None,
    )
}

fn materialize_merged_children_from_spool_with_inline_limit(
    cur: &[u32],
    depth: usize,
    fanout: usize,
    merge_groups: &[MergedRawGroup],
    spool: &NamedTempFile,
    store: &mut ExternalRunStore,
    inline_limit: Option<usize>,
) -> AnnResult<Vec<MaterializedMergedChild>> {
    let raw_child_count = merge_groups
        .iter()
        .flat_map(|group| group.raw_children.iter())
        .copied()
        .max()
        .map(|idx| idx as usize + 1)
        .unwrap_or(0);
    let mut raw_to_merged = vec![u16::MAX; raw_child_count];
    for (merged_idx, group) in merge_groups.iter().enumerate() {
        for &raw_child in &group.raw_children {
            raw_to_merged[raw_child as usize] = merged_idx as u16;
        }
    }

    let record_cap = assign_record_fanout(fanout);
    let buffer_cap = MATERIALIZE_CHILD_BUFFER_POINTS.max(record_cap);
    let mut children: Vec<BufferedMergedChild> = merge_groups
        .iter()
        .map(|group| {
            let inline = inline_limit.map_or(false, |limit| group.raw_len <= limit);
            BufferedMergedChild {
                extents: Vec::new(),
                buffer: Vec::with_capacity(if inline {
                    group.raw_len.min(buffer_cap)
                } else {
                    buffer_cap
                }),
                inline,
            }
        })
        .collect();
    let mut reader = BufReader::new(spool.reopen()?);
    let batch_points = MATERIALIZE_BATCH_POINTS.max(buffer_cap);
    let mut assignment_batch = vec![0u16; batch_points * record_cap];
    let mut assignment_counts = vec![0usize; batch_points];

    for point_batch in cur.chunks(batch_points) {
        let used = point_batch.len() * record_cap;
        for (row, record) in assignment_batch[..used].chunks_mut(record_cap).enumerate() {
            assignment_counts[row] = read_assign_record(&mut reader, record)?;
        }

        let per_point_merged: Vec<([u16; 32], u8)> = assignment_batch[..used]
            .par_chunks(record_cap)
            .zip(assignment_counts[..point_batch.len()].par_iter())
            .map(|(record, &record_len)| {
                let mut merged_for_point = [u16::MAX; 32];
                let mut unique_count = 0usize;
                for &raw_child in &record[..record_len] {
                    let merged_idx = raw_to_merged[raw_child as usize];
                    if merged_for_point[..unique_count].contains(&merged_idx) {
                        continue;
                    }
                    merged_for_point[unique_count] = merged_idx;
                    unique_count += 1;
                }
                (merged_for_point, unique_count as u8)
            })
            .collect();

        for (point, (merged_children, unique_count)) in
            point_batch.iter().copied().zip(per_point_merged.iter())
        {
            for &merged_idx in &merged_children[..usize::from(*unique_count)] {
                let child = &mut children[merged_idx as usize];
                child.buffer.push(point);
                if !child.inline && child.buffer.len() >= buffer_cap {
                    flush_materialized_child_buffer(store, depth, child)?;
                }
            }
        }
    }

    let mut materialized = Vec::with_capacity(children.len());
    for mut child in children {
        if !child.inline {
            flush_materialized_child_buffer(store, depth, &mut child)?;
        }
        let points = child.inline.then_some(child.buffer);
        materialized.push(MaterializedMergedChild {
            extents: child.extents,
            points,
        });
    }
    Ok(materialized)
}

fn compute_clusters_scalar_to_spool(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
    metric: Metric,
    spool_writer: &mut BufWriter<File>,
    raw_counts: &mut [usize],
) -> AnnResult<()> {
    let fanout = assign_record_fanout(local_fanout.min(leaders.len().max(1)));
    if fanout == 1 {
        for &idx in cur {
            let mut best_lid = 0usize;
            let mut best_dist = f32::INFINITY;
            for (lid, &lid_global) in leaders.iter().enumerate() {
                let d = dataset.get_distance(idx, lid_global, metric)?;
                if d < best_dist {
                    best_dist = d;
                    best_lid = lid;
                }
            }
            raw_counts[best_lid] += 1;
            let leader = [best_lid as u16];
            write_assign_record(spool_writer, &leader, fanout)?;
        }
    } else {
        for &idx in cur {
            let mut top_k = StackTopK::new(fanout);
            for (lid, &lid_global) in leaders.iter().enumerate() {
                let d = dataset.get_distance(idx, lid_global, metric)?;
                top_k.push(d, lid);
            }
            let mut leaders_for_point = [0u16; 32];
            let mut len = 0usize;
            for &(_, lid) in top_k.iter() {
                raw_counts[lid] += 1;
                leaders_for_point[len] = lid as u16;
                len += 1;
            }
            write_assign_record(spool_writer, &leaders_for_point[..len], fanout)?;
        }
    }
    spool_writer.flush()?;
    Ok(())
}

fn root_radius_assignment_from_topk(
    config: &RadiusWitnessConfig,
    snapshot: &super::root_radius_witness::RadiusWitnessSnapshot,
    top_k: &StackTopK,
    points_seen: usize,
    out: &mut [u16; 32],
) -> (usize, usize, f32, RadiusWitnessDecision) {
    let fixed_fanout = config.fixed_fanout.max(1).min(32);
    let mut top_leaders = [usize::MAX; 32];
    let mut top_distances = [0.0f32; 32];
    let mut top_len = 0usize;
    for &(distance, leader) in top_k.iter().take(32) {
        top_leaders[top_len] = leader;
        top_distances[top_len] = distance;
        top_len += 1;
    }
    let owner = top_leaders.first().copied().unwrap_or(0);
    let owner_dist = top_distances
        .first()
        .copied()
        .unwrap_or(0.0)
        .max(0.0)
        .sqrt();
    let decision = select_radius_certified_fanout(
        config,
        snapshot,
        &top_leaders[..top_len],
        &top_distances[..top_len],
        points_seen,
    );
    let emit_len = if config.dry_run {
        fixed_fanout.min(top_len).max(1)
    } else {
        decision.kept.min(top_len).max(1)
    };
    for (slot, &leader) in out.iter_mut().zip(top_leaders[..emit_len].iter()) {
        *slot = leader as u16;
    }
    (emit_len, owner, owner_dist, decision)
}

fn compute_root_radius_clusters_gemm_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    root_fanout_state: &RootFanoutState,
    memory_budget_bytes: Option<usize>,
) -> AnnResult<(Vec<Vec<u32>>, GemmProfile)> {
    let Some(config) = root_fanout_state.radius_config().cloned() else {
        return compute_clusters_gemm_budgeted(dataset, cur, leaders, 1, memory_budget_bytes);
    };
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let query_fanout = (config.fixed_fanout + 1).min(nl.max(1)).min(32);
    let (point_tile_size, leader_tile_size) =
        choose_gemm_tile_sizes_with_override_and_budget(nl, dim, memory_budget_bytes);
    let leader_read_options =
        default_rbc_windowed_options(dataset, nl.min(leader_tile_size.max(1)));
    let point_read_options = default_rbc_windowed_options(dataset, point_tile_size);

    let mut l_data = vec![0f32; nl * dim];
    let mut leader_io_stats = PointBatchStats::default();
    dataset.read_points_windowed_into_batch_stats(
        leaders,
        &mut l_data,
        &leader_read_options,
        &mut leader_io_stats,
    )?;
    let l_norms: Vec<f32> = l_data
        .chunks(dim)
        .map(|r| r.iter().map(|&v| v * v).sum())
        .collect();
    let l_mat = ArrayView2::from_shape((nl, dim), &l_data).unwrap();
    let num_workers = rayon::current_num_threads().max(1);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        num_workers,
        memory_budget_bytes,
    );
    let mut state = GemmFoldState::new(
        point_tile_size,
        leader_tile_size,
        dim,
        nl,
        config.fixed_fanout,
    );
    let mut io_stats = leader_io_stats;
    let mut points_seen = 0usize;

    struct RadiusBatchState {
        fold: GemmFoldState,
        telemetry: RadiusWitnessTelemetry,
        pending: Vec<(usize, f32, u32)>,
    }

    for_each_prefetched_point_batch(
        dataset,
        cur,
        batch_points,
        point_read_options,
        |prefetched| {
            io_stats.merge(&prefetched.io_stats);
            state.profile.build_x += prefetched.load;
            let compute_block_points =
                choose_compute_block_points_for_batch(point_tile_size, prefetched.len, num_workers);
            let batch_points_seen = points_seen;
            let radius_snapshot = root_fanout_state
                .radius_snapshot()
                .expect("radius config and store must be present together");

            let batch_state = (0..prefetched.len)
                .into_par_iter()
                .step_by(compute_block_points)
                .map(|block_start_idx| {
                    let block_end_idx =
                        (block_start_idx + compute_block_points).min(prefetched.len);
                    let block = &prefetched.ids[block_start_idx..block_end_idx];
                    let x_slice = &prefetched.data[block_start_idx * dim..block_end_idx * dim];
                    let block_n = block.len();
                    let mut local = RadiusBatchState {
                        fold: GemmFoldState::new(
                            compute_block_points,
                            leader_tile_size,
                            dim,
                            nl,
                            config.fixed_fanout,
                        ),
                        telemetry: RadiusWitnessTelemetry::new(&config, cur.len()),
                        pending: Vec::with_capacity(block_n),
                    };
                    let mut block_profile = GemmProfile {
                        blocks: 1,
                        ..GemmProfile::default()
                    };
                    let block_start = Instant::now();
                    let scratch = &mut local.fold.scratch;
                    let build_x_start = Instant::now();
                    scratch.x_data.clear();
                    scratch.x_data.extend_from_slice(x_slice);
                    scratch.x_norms.resize(block_n, 0f32);
                    for (i, chunk) in scratch.x_data.chunks(dim).enumerate() {
                        scratch.x_norms[i] = chunk.iter().map(|&v| v * v).sum();
                    }
                    let x_mat =
                        ArrayView2::from_shape((block_n, dim), scratch.x_data.as_slice()).unwrap();
                    block_profile.build_x += build_x_start.elapsed();

                    let topk_start = Instant::now();
                    scratch
                        .topk_rows
                        .resize_with(block_n, || StackTopK::new(query_fanout));
                    for topk in scratch.topk_rows[..block_n].iter_mut() {
                        *topk = StackTopK::new(query_fanout);
                    }
                    block_profile.topk += topk_start.elapsed();

                    for leader_offset in (0..nl).step_by(leader_tile_size) {
                        let leader_end = (leader_offset + leader_tile_size).min(nl);
                        let leader_view = l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                        let tile_cols = leader_end - leader_offset;
                        let mut gram_tile =
                            borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                        let gemm_start = Instant::now();
                        ndarray::linalg::general_mat_mul(
                            1.0,
                            &x_mat,
                            &leader_view.t(),
                            0.0,
                            &mut gram_tile,
                        );
                        block_profile.gemm += gemm_start.elapsed();
                        let topk_update_start = Instant::now();
                        update_block_topk_from_gram_tile(
                            &mut scratch.topk_rows[..block_n],
                            &scratch.x_norms[..block_n],
                            &l_norms,
                            gram_tile.view(),
                            leader_offset,
                        );
                        block_profile.topk += topk_update_start.elapsed();
                    }

                    let merge_start = Instant::now();
                    scratch.local_clusters.resize_with(nl, Vec::new);
                    for cluster in scratch.local_clusters[..nl].iter_mut() {
                        cluster.clear();
                    }
                    let mut assignment = [0u16; 32];
                    for (i, top_k) in scratch.topk_rows[..block_n].iter().enumerate() {
                        let seen = batch_points_seen + block_start_idx + i;
                        let selector_start = Instant::now();
                        let (len, owner, owner_dist, decision) = root_radius_assignment_from_topk(
                            &config,
                            &radius_snapshot,
                            top_k,
                            seen,
                            &mut assignment,
                        );
                        local.telemetry.selector_ms += selector_start.elapsed().as_millis();
                        local.telemetry.record(&decision);
                        local.pending.push((owner, owner_dist, block[i]));
                        for &lid in &assignment[..len] {
                            scratch.local_clusters[lid as usize].push(block[i]);
                        }
                    }
                    merge_cluster_buffers_in_place(
                        &mut local.fold.clusters,
                        &mut scratch.local_clusters,
                    );
                    block_profile.merge += merge_start.elapsed();
                    block_profile.total_wall = block_start.elapsed();
                    local.fold.profile.merge(block_profile);
                    Ok::<RadiusBatchState, crate::common::AnnError>(local)
                })
                .try_reduce(
                    || RadiusBatchState {
                        fold: GemmFoldState::new(
                            compute_block_points,
                            leader_tile_size,
                            dim,
                            nl,
                            config.fixed_fanout,
                        ),
                        telemetry: RadiusWitnessTelemetry::new(&config, cur.len()),
                        pending: Vec::new(),
                    },
                    |mut left, right| -> AnnResult<RadiusBatchState> {
                        merge_cluster_buffers(&mut left.fold.clusters, right.fold.clusters);
                        left.fold.profile.merge(right.fold.profile);
                        left.telemetry.warmup_points_seen += right.telemetry.warmup_points_seen;
                        left.telemetry.certified_points += right.telemetry.certified_points;
                        left.telemetry.fallback_points += right.telemetry.fallback_points;
                        left.telemetry.insufficient_radius_points +=
                            right.telemetry.insufficient_radius_points;
                        if left.telemetry.kept_hist.len() < right.telemetry.kept_hist.len() {
                            left.telemetry
                                .kept_hist
                                .resize(right.telemetry.kept_hist.len(), 0);
                        }
                        for (kept, count) in right.telemetry.kept_hist.into_iter().enumerate() {
                            left.telemetry.kept_hist[kept] += count;
                        }
                        left.telemetry.selector_ms += right.telemetry.selector_ms;
                        left.pending.extend(right.pending);
                        Ok(left)
                    },
                )?;

            merge_cluster_buffers(&mut state.clusters, batch_state.fold.clusters);
            state.profile.merge(batch_state.fold.profile);
            root_fanout_state.record_radius_telemetry(batch_state.telemetry);
            root_fanout_state.insert_radius_batch(batch_state.pending);
            points_seen += prefetched.len;
            Ok(())
        },
    )?;

    let mut profile = state.profile;
    profile.total_wall = total_start.elapsed();
    tracing::info!(
        "[rbc/root-radius-gemm] point_reads={} range_reads={} range_rows={} hit_ratio={:.2}",
        io_stats.point_calls,
        io_stats.range_calls,
        io_stats.range_rows_read,
        io_stats.range_hit_ratio(),
    );
    Ok((state.clusters, profile))
}

#[derive(Clone, Copy, Debug)]
struct RootRiskTopRecord {
    leaders: [usize; 32],
    distances_sq: [f32; 32],
    leader_pair_distances: [f32; 32],
    len: usize,
    owner: usize,
    owner_dist: f32,
}

impl RootRiskTopRecord {
    fn leader_slice(&self) -> &[usize] {
        &self.leaders[..self.len]
    }

    fn distance_slice(&self) -> &[f32] {
        &self.distances_sq[..self.len]
    }

    fn leader_pair_distance_slice(&self) -> &[f32] {
        &self.leader_pair_distances[..self.len]
    }
}

fn leader_pair_distance(l_data: &[f32], dim: usize, left: usize, right: usize) -> f32 {
    if left == right || dim == 0 {
        return 0.0;
    }
    let left_start = left.saturating_mul(dim);
    let right_start = right.saturating_mul(dim);
    let Some(left_row) = l_data.get(left_start..left_start + dim) else {
        return f32::NAN;
    };
    let Some(right_row) = l_data.get(right_start..right_start + dim) else {
        return f32::NAN;
    };
    left_row
        .iter()
        .zip(right_row.iter())
        .map(|(&a, &b)| {
            let delta = a - b;
            delta * delta
        })
        .sum::<f32>()
        .max(0.0)
        .sqrt()
}

fn root_risk_top_record_from_topk(
    top_k: &StackTopK,
    fixed_fanout: usize,
    l_data: &[f32],
    dim: usize,
) -> RootRiskTopRecord {
    let mut record = RootRiskTopRecord {
        leaders: [usize::MAX; 32],
        distances_sq: [0.0; 32],
        leader_pair_distances: [0.0; 32],
        len: 0,
        owner: 0,
        owner_dist: 0.0,
    };
    let limit = fixed_fanout.max(1).min(32);
    for &(distance, leader) in top_k.iter().take(limit) {
        record.leaders[record.len] = leader;
        record.distances_sq[record.len] = distance;
        record.len += 1;
    }
    if record.len == 0 {
        return record;
    }
    record.owner = record.leaders[0];
    record.owner_dist = record.distances_sq[0].max(0.0).sqrt();
    for idx in 1..record.len {
        record.leader_pair_distances[idx] =
            leader_pair_distance(l_data, dim, record.owner, record.leaders[idx]);
    }
    record
}

fn root_risk_utility_records(
    config: &RootRiskBudgetConfig,
    snapshot: &super::root_risk_budget::RootRiskBudgetSnapshot,
    top_records: &[RootRiskTopRecord],
) -> Vec<RootRiskUtilityRecord> {
    top_records
        .iter()
        .filter_map(|record| {
            utility_record_from_top_distances(
                config,
                snapshot,
                record.leader_slice(),
                record.distance_slice(),
                record.leader_pair_distance_slice(),
            )
            .map(|(record, _)| record)
        })
        .collect()
}

fn collect_root_risk_pilot_records_gemm(
    dataset: &dyn PointStore,
    cur: &[u32],
    l_data: &[f32],
    l_norms: &[f32],
    l_mat: ArrayView2<'_, f32>,
    point_tile_size: usize,
    leader_tile_size: usize,
    query_fanout: usize,
    memory_budget_bytes: Option<usize>,
) -> AnnResult<(Vec<RootRiskTopRecord>, Vec<(usize, f32)>, GemmProfile)> {
    if cur.is_empty() {
        return Ok((Vec::new(), Vec::new(), GemmProfile::default()));
    }
    let nl = l_norms.len();
    let dim = dataset.dim();
    let num_workers = rayon::current_num_threads().max(1);
    let point_read_options = default_rbc_windowed_options(dataset, point_tile_size);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        num_workers,
        memory_budget_bytes,
    );
    let mut all_records = Vec::with_capacity(cur.len());
    let mut all_pending = Vec::with_capacity(cur.len());
    let mut profile = GemmProfile::default();

    for_each_prefetched_point_batch(
        dataset,
        cur,
        batch_points,
        point_read_options,
        |prefetched| {
            profile.build_x += prefetched.load;
            let compute_block_points =
                choose_compute_block_points_for_batch(point_tile_size, prefetched.len, num_workers);
            let folds: Vec<(Vec<RootRiskTopRecord>, Vec<(usize, f32)>, GemmProfile)> = (0
                ..prefetched.len)
                .into_par_iter()
                .step_by(compute_block_points)
                .map(|block_start_idx| {
                    let block_end_idx =
                        (block_start_idx + compute_block_points).min(prefetched.len);
                    let x_slice = &prefetched.data[block_start_idx * dim..block_end_idx * dim];
                    let block_n = block_end_idx - block_start_idx;
                    let mut scratch = GemmScratch::new(
                        compute_block_points,
                        leader_tile_size,
                        dim,
                        nl,
                        query_fanout,
                    );
                    let mut block_profile = GemmProfile {
                        blocks: 1,
                        ..GemmProfile::default()
                    };
                    let block_start = Instant::now();
                    let build_x_start = Instant::now();
                    scratch.x_data.clear();
                    scratch.x_data.extend_from_slice(x_slice);
                    scratch.x_norms.resize(block_n, 0f32);
                    for (i, chunk) in scratch.x_data.chunks(dim).enumerate() {
                        scratch.x_norms[i] = chunk.iter().map(|&v| v * v).sum();
                    }
                    let x_mat =
                        ArrayView2::from_shape((block_n, dim), scratch.x_data.as_slice()).unwrap();
                    block_profile.build_x += build_x_start.elapsed();

                    scratch
                        .topk_rows
                        .resize_with(block_n, || StackTopK::new(query_fanout));
                    for topk in scratch.topk_rows[..block_n].iter_mut() {
                        *topk = StackTopK::new(query_fanout);
                    }

                    for leader_offset in (0..nl).step_by(leader_tile_size) {
                        let leader_end = (leader_offset + leader_tile_size).min(nl);
                        let leader_view = l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                        let tile_cols = leader_end - leader_offset;
                        let mut gram_tile =
                            borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                        let gemm_start = Instant::now();
                        ndarray::linalg::general_mat_mul(
                            1.0,
                            &x_mat,
                            &leader_view.t(),
                            0.0,
                            &mut gram_tile,
                        );
                        block_profile.gemm += gemm_start.elapsed();
                        let topk_update_start = Instant::now();
                        update_block_topk_from_gram_tile(
                            &mut scratch.topk_rows[..block_n],
                            &scratch.x_norms[..block_n],
                            l_norms,
                            gram_tile.view(),
                            leader_offset,
                        );
                        block_profile.topk += topk_update_start.elapsed();
                    }

                    let mut records = Vec::with_capacity(block_n);
                    let mut pending = Vec::with_capacity(block_n);
                    for top_k in scratch.topk_rows[..block_n].iter() {
                        let record =
                            root_risk_top_record_from_topk(top_k, query_fanout, l_data, dim);
                        pending.push((record.owner, record.owner_dist));
                        records.push(record);
                    }
                    block_profile.total_wall = block_start.elapsed();
                    Ok::<_, crate::common::AnnError>((records, pending, block_profile))
                })
                .collect::<AnnResult<Vec<_>>>()?;

            for (records, pending, block_profile) in folds {
                profile.merge(block_profile);
                all_records.extend(records);
                all_pending.extend(pending);
            }
            Ok(())
        },
    )?;

    Ok((all_records, all_pending, profile))
}

fn compute_root_risk_clusters_gemm_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    root_fanout_state: &RootFanoutState,
    memory_budget_bytes: Option<usize>,
) -> AnnResult<(Vec<Vec<u32>>, GemmProfile)> {
    let Some(config) = root_fanout_state.risk_config().cloned() else {
        return compute_clusters_gemm_budgeted(dataset, cur, leaders, 1, memory_budget_bytes);
    };
    let dry_run = root_fanout_state.profile.lock().dry_run;
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let query_fanout = config.fixed_fanout.min(nl.max(1)).min(32);
    let (point_tile_size, leader_tile_size) =
        choose_gemm_tile_sizes_with_override_and_budget(nl, dim, memory_budget_bytes);
    let leader_read_options =
        default_rbc_windowed_options(dataset, nl.min(leader_tile_size.max(1)));
    let point_read_options = default_rbc_windowed_options(dataset, point_tile_size);

    let mut l_data = vec![0f32; nl * dim];
    let mut leader_io_stats = PointBatchStats::default();
    dataset.read_points_windowed_into_batch_stats(
        leaders,
        &mut l_data,
        &leader_read_options,
        &mut leader_io_stats,
    )?;
    let l_norms: Vec<f32> = l_data
        .chunks(dim)
        .map(|r| r.iter().map(|&v| v * v).sum())
        .collect();
    let l_mat = ArrayView2::from_shape((nl, dim), &l_data).unwrap();
    let pilot_points = config.warmup_points.min(cur.len());
    let (pilot_records, pilot_pending, pilot_profile) = collect_root_risk_pilot_records_gemm(
        dataset,
        &cur[..pilot_points],
        &l_data,
        &l_norms,
        l_mat,
        point_tile_size,
        leader_tile_size,
        query_fanout,
        memory_budget_bytes,
    )?;
    root_fanout_state.insert_risk_batch(pilot_pending);
    let risk_snapshot = root_fanout_state
        .risk_snapshot()
        .expect("risk config and store must be present together");
    let utility_records = root_risk_utility_records(&config, &risk_snapshot, &pilot_records);
    let calibration = calibrate_budget_lambda(&config, &utility_records);
    root_fanout_state.record_risk_calibration(calibration);
    let budget_lambda = calibration.budget_lambda;

    let num_workers = rayon::current_num_threads().max(1);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        num_workers,
        memory_budget_bytes,
    );
    let mut state = GemmFoldState::new(
        point_tile_size,
        leader_tile_size,
        dim,
        nl,
        config.fixed_fanout,
    );
    state.profile.merge(pilot_profile);
    let mut io_stats = leader_io_stats;

    struct RiskBatchState {
        fold: GemmFoldState,
        telemetry: RootRiskBudgetTelemetry,
    }

    for_each_prefetched_point_batch(
        dataset,
        cur,
        batch_points,
        point_read_options,
        |prefetched| {
            io_stats.merge(&prefetched.io_stats);
            state.profile.build_x += prefetched.load;
            let compute_block_points =
                choose_compute_block_points_for_batch(point_tile_size, prefetched.len, num_workers);

            let batch_state = (0..prefetched.len)
                .into_par_iter()
                .step_by(compute_block_points)
                .map(|block_start_idx| {
                    let block_end_idx =
                        (block_start_idx + compute_block_points).min(prefetched.len);
                    let block = &prefetched.ids[block_start_idx..block_end_idx];
                    let x_slice = &prefetched.data[block_start_idx * dim..block_end_idx * dim];
                    let block_n = block.len();
                    let mut local = RiskBatchState {
                        fold: GemmFoldState::new(
                            compute_block_points,
                            leader_tile_size,
                            dim,
                            nl,
                            config.fixed_fanout,
                        ),
                        telemetry: RootRiskBudgetTelemetry::new(&config, cur.len(), nl),
                    };
                    let mut block_profile = GemmProfile {
                        blocks: 1,
                        ..GemmProfile::default()
                    };
                    let block_start = Instant::now();
                    let scratch = &mut local.fold.scratch;
                    let build_x_start = Instant::now();
                    scratch.x_data.clear();
                    scratch.x_data.extend_from_slice(x_slice);
                    scratch.x_norms.resize(block_n, 0f32);
                    for (i, chunk) in scratch.x_data.chunks(dim).enumerate() {
                        scratch.x_norms[i] = chunk.iter().map(|&v| v * v).sum();
                    }
                    let x_mat =
                        ArrayView2::from_shape((block_n, dim), scratch.x_data.as_slice()).unwrap();
                    block_profile.build_x += build_x_start.elapsed();

                    scratch
                        .topk_rows
                        .resize_with(block_n, || StackTopK::new(query_fanout));
                    for topk in scratch.topk_rows[..block_n].iter_mut() {
                        *topk = StackTopK::new(query_fanout);
                    }

                    for leader_offset in (0..nl).step_by(leader_tile_size) {
                        let leader_end = (leader_offset + leader_tile_size).min(nl);
                        let leader_view = l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                        let tile_cols = leader_end - leader_offset;
                        let mut gram_tile =
                            borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                        let gemm_start = Instant::now();
                        ndarray::linalg::general_mat_mul(
                            1.0,
                            &x_mat,
                            &leader_view.t(),
                            0.0,
                            &mut gram_tile,
                        );
                        block_profile.gemm += gemm_start.elapsed();
                        let topk_update_start = Instant::now();
                        update_block_topk_from_gram_tile(
                            &mut scratch.topk_rows[..block_n],
                            &scratch.x_norms[..block_n],
                            &l_norms,
                            gram_tile.view(),
                            leader_offset,
                        );
                        block_profile.topk += topk_update_start.elapsed();
                    }

                    let merge_start = Instant::now();
                    scratch.local_clusters.resize_with(nl, Vec::new);
                    for cluster in scratch.local_clusters[..nl].iter_mut() {
                        cluster.clear();
                    }
                    let mut assignment = [0u16; 32];
                    for (i, top_k) in scratch.topk_rows[..block_n].iter().enumerate() {
                        let selector_start = Instant::now();
                        let record =
                            root_risk_top_record_from_topk(top_k, query_fanout, &l_data, dim);
                        let decision = select_risk_budgeted_fanout(
                            &config,
                            &risk_snapshot,
                            record.leader_slice(),
                            record.distance_slice(),
                            record.leader_pair_distance_slice(),
                            budget_lambda,
                        );
                        local.telemetry.selector_ms += selector_start.elapsed().as_millis();
                        local.telemetry.record(&decision, record.leader_slice());
                        let emit_len = if dry_run {
                            query_fanout.min(record.len).max(1)
                        } else {
                            decision.kept.min(record.len).max(1)
                        };
                        for (slot, &leader) in assignment
                            .iter_mut()
                            .zip(record.leader_slice()[..emit_len].iter())
                        {
                            *slot = leader as u16;
                        }
                        for &lid in &assignment[..emit_len] {
                            scratch.local_clusters[lid as usize].push(block[i]);
                        }
                    }
                    merge_cluster_buffers_in_place(
                        &mut local.fold.clusters,
                        &mut scratch.local_clusters,
                    );
                    block_profile.merge += merge_start.elapsed();
                    block_profile.total_wall = block_start.elapsed();
                    local.fold.profile.merge(block_profile);
                    Ok::<RiskBatchState, crate::common::AnnError>(local)
                })
                .try_reduce(
                    || RiskBatchState {
                        fold: GemmFoldState::new(
                            compute_block_points,
                            leader_tile_size,
                            dim,
                            nl,
                            config.fixed_fanout,
                        ),
                        telemetry: RootRiskBudgetTelemetry::new(&config, cur.len(), nl),
                    },
                    |mut left, right| -> AnnResult<RiskBatchState> {
                        merge_cluster_buffers(&mut left.fold.clusters, right.fold.clusters);
                        left.fold.profile.merge(right.fold.profile);
                        left.telemetry.merge(right.telemetry);
                        Ok(left)
                    },
                )?;

            merge_cluster_buffers(&mut state.clusters, batch_state.fold.clusters);
            state.profile.merge(batch_state.fold.profile);
            root_fanout_state.record_risk_telemetry(batch_state.telemetry);
            Ok(())
        },
    )?;

    let mut profile = state.profile;
    profile.total_wall = total_start.elapsed();
    tracing::info!(
        "[rbc/root-risk-gemm] point_reads={} range_reads={} range_rows={} hit_ratio={:.2}",
        io_stats.point_calls,
        io_stats.range_calls,
        io_stats.range_rows_read,
        io_stats.range_hit_ratio(),
    );
    Ok((state.clusters, profile))
}

fn compute_root_radius_clusters_gemm_to_spool_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    root_fanout_state: &RootFanoutState,
    memory_budget_bytes: Option<usize>,
    spool_writer: &mut BufWriter<File>,
    raw_counts: &mut [usize],
) -> AnnResult<GemmProfile> {
    let Some(config) = root_fanout_state.radius_config().cloned() else {
        return compute_clusters_gemm_to_spool_budgeted(
            dataset,
            cur,
            leaders,
            1,
            memory_budget_bytes,
            spool_writer,
            raw_counts,
        );
    };
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let fanout = assign_record_fanout(config.fixed_fanout.min(nl.max(1)));
    let query_fanout = (fanout + 1).min(nl.max(1)).min(32);
    let (point_tile_size, leader_tile_size) =
        choose_gemm_tile_sizes_with_override_and_budget(nl, dim, memory_budget_bytes);
    let leader_read_options =
        default_rbc_windowed_options(dataset, nl.min(leader_tile_size.max(1)));
    let point_read_options = default_rbc_windowed_options(dataset, point_tile_size);

    let mut l_data = vec![0f32; nl * dim];
    let mut leader_io_stats = PointBatchStats::default();
    dataset.read_points_windowed_into_batch_stats(
        leaders,
        &mut l_data,
        &leader_read_options,
        &mut leader_io_stats,
    )?;
    let l_norms: Vec<f32> = l_data
        .chunks(dim)
        .map(|r| r.iter().map(|&v| v * v).sum())
        .collect();
    let l_mat = ArrayView2::from_shape((nl, dim), &l_data).unwrap();
    let num_workers = rayon::current_num_threads().max(1);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        choose_spool_prefetch_workers(num_workers, memory_budget_bytes),
        memory_budget_bytes,
    );

    struct RadiusSpoolFold {
        scratch: GemmScratch,
        profile: GemmProfile,
        raw_counts: Vec<usize>,
        assign_chunks: Vec<Vec<u8>>,
        telemetry: RadiusWitnessTelemetry,
        pending: Vec<(usize, f32, u32)>,
    }

    let mut profile = GemmProfile::default();
    let mut io_stats = leader_io_stats;
    let mut merged_raw_counts = vec![0usize; nl];
    let mut points_seen = 0usize;

    for_each_prefetched_point_batch(
        dataset,
        cur,
        batch_points,
        point_read_options,
        |prefetched| {
            io_stats.merge(&prefetched.io_stats);
            profile.build_x += prefetched.load;
            let compute_block_points =
                choose_compute_block_points_for_batch(point_tile_size, prefetched.len, num_workers);
            let batch_points_seen = points_seen;
            let radius_snapshot = root_fanout_state
                .radius_snapshot()
                .expect("radius config and store must be present together");

            let folds: Vec<RadiusSpoolFold> = (0..prefetched.len)
                .into_par_iter()
                .step_by(compute_block_points)
                .map(|block_start_idx| {
                    let block_end_idx =
                        (block_start_idx + compute_block_points).min(prefetched.len);
                    let block = &prefetched.ids[block_start_idx..block_end_idx];
                    let x_slice = &prefetched.data[block_start_idx * dim..block_end_idx * dim];
                    let block_n = block.len();
                    let mut fold = RadiusSpoolFold {
                        scratch: GemmScratch::new(
                            compute_block_points,
                            leader_tile_size,
                            dim,
                            nl,
                            query_fanout,
                        ),
                        profile: GemmProfile::default(),
                        raw_counts: vec![0usize; nl],
                        assign_chunks: Vec::new(),
                        telemetry: RadiusWitnessTelemetry::new(&config, cur.len()),
                        pending: Vec::with_capacity(block_n),
                    };
                    let mut block_profile = GemmProfile {
                        blocks: 1,
                        ..GemmProfile::default()
                    };
                    let block_start = Instant::now();
                    let scratch = &mut fold.scratch;
                    let build_x_start = Instant::now();
                    scratch.x_data.clear();
                    scratch.x_data.extend_from_slice(x_slice);
                    scratch.x_norms.resize(block_n, 0f32);
                    for (i, chunk) in scratch.x_data.chunks(dim).enumerate() {
                        scratch.x_norms[i] = chunk.iter().map(|&v| v * v).sum();
                    }
                    let x_mat =
                        ArrayView2::from_shape((block_n, dim), scratch.x_data.as_slice()).unwrap();
                    block_profile.build_x += build_x_start.elapsed();

                    scratch
                        .topk_rows
                        .resize_with(block_n, || StackTopK::new(query_fanout));
                    for topk in scratch.topk_rows[..block_n].iter_mut() {
                        *topk = StackTopK::new(query_fanout);
                    }

                    for leader_offset in (0..nl).step_by(leader_tile_size) {
                        let leader_end = (leader_offset + leader_tile_size).min(nl);
                        let leader_view = l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                        let tile_cols = leader_end - leader_offset;
                        let mut gram_tile =
                            borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                        let gemm_start = Instant::now();
                        ndarray::linalg::general_mat_mul(
                            1.0,
                            &x_mat,
                            &leader_view.t(),
                            0.0,
                            &mut gram_tile,
                        );
                        block_profile.gemm += gemm_start.elapsed();
                        let topk_update_start = Instant::now();
                        update_block_topk_from_gram_tile(
                            &mut scratch.topk_rows[..block_n],
                            &scratch.x_norms[..block_n],
                            &l_norms,
                            gram_tile.view(),
                            leader_offset,
                        );
                        block_profile.topk += topk_update_start.elapsed();
                    }

                    let mut assign_buf = Vec::with_capacity(block_n * assign_record_width(fanout));
                    let mut assignment = [0u16; 32];
                    for (i, top_k) in scratch.topk_rows[..block_n].iter().enumerate() {
                        let seen = batch_points_seen + block_start_idx + i;
                        let selector_start = Instant::now();
                        let (len, owner, owner_dist, decision) = root_radius_assignment_from_topk(
                            &config,
                            &radius_snapshot,
                            top_k,
                            seen,
                            &mut assignment,
                        );
                        fold.telemetry.selector_ms += selector_start.elapsed().as_millis();
                        fold.telemetry.record(&decision);
                        fold.pending.push((owner, owner_dist, block[i]));
                        for &lid in &assignment[..len] {
                            fold.raw_counts[lid as usize] += 1;
                        }
                        append_assign_record_bytes(&mut assign_buf, &assignment[..len], fanout)?;
                    }

                    block_profile.total_wall = block_start.elapsed();
                    fold.profile.merge(block_profile);
                    fold.assign_chunks.push(assign_buf);
                    Ok::<RadiusSpoolFold, crate::common::AnnError>(fold)
                })
                .collect::<AnnResult<Vec<_>>>()?;

            let mut batch_telemetry = RadiusWitnessTelemetry::new(&config, cur.len());
            let mut batch_pending = Vec::new();
            for fold in folds {
                profile.merge(fold.profile);
                for (lid, count) in fold.raw_counts.into_iter().enumerate() {
                    merged_raw_counts[lid] += count;
                }
                batch_telemetry.warmup_points_seen += fold.telemetry.warmup_points_seen;
                batch_telemetry.certified_points += fold.telemetry.certified_points;
                batch_telemetry.fallback_points += fold.telemetry.fallback_points;
                batch_telemetry.insufficient_radius_points +=
                    fold.telemetry.insufficient_radius_points;
                if batch_telemetry.kept_hist.len() < fold.telemetry.kept_hist.len() {
                    batch_telemetry
                        .kept_hist
                        .resize(fold.telemetry.kept_hist.len(), 0);
                }
                for (kept, count) in fold.telemetry.kept_hist.into_iter().enumerate() {
                    batch_telemetry.kept_hist[kept] += count;
                }
                batch_telemetry.selector_ms += fold.telemetry.selector_ms;
                batch_pending.extend(fold.pending);
                for bytes in fold.assign_chunks {
                    let spool_write_start = Instant::now();
                    spool_writer.write_all(&bytes)?;
                    profile.spool_write += spool_write_start.elapsed();
                }
            }
            root_fanout_state.record_radius_telemetry(batch_telemetry);
            root_fanout_state.insert_radius_batch(batch_pending);
            points_seen += prefetched.len;
            Ok(())
        },
    )?;

    raw_counts.copy_from_slice(&merged_raw_counts);
    let flush_start = Instant::now();
    spool_writer.flush()?;
    profile.flush += flush_start.elapsed();
    profile.total_wall = total_start.elapsed();
    tracing::info!(
        "[rbc/root-radius-gemm-spool] point_reads={} range_reads={} range_rows={} hit_ratio={:.2}",
        io_stats.point_calls,
        io_stats.range_calls,
        io_stats.range_rows_read,
        io_stats.range_hit_ratio(),
    );
    Ok(profile)
}

fn compute_root_risk_clusters_gemm_to_spool_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    root_fanout_state: &RootFanoutState,
    memory_budget_bytes: Option<usize>,
    spool_writer: &mut BufWriter<File>,
    raw_counts: &mut [usize],
) -> AnnResult<GemmProfile> {
    let Some(config) = root_fanout_state.risk_config().cloned() else {
        return compute_clusters_gemm_to_spool_budgeted(
            dataset,
            cur,
            leaders,
            1,
            memory_budget_bytes,
            spool_writer,
            raw_counts,
        );
    };
    let dry_run = root_fanout_state.profile.lock().dry_run;
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let fanout = assign_record_fanout(config.fixed_fanout.min(nl.max(1)));
    let query_fanout = fanout.min(32);
    let (point_tile_size, leader_tile_size) =
        choose_gemm_tile_sizes_with_override_and_budget(nl, dim, memory_budget_bytes);
    let leader_read_options =
        default_rbc_windowed_options(dataset, nl.min(leader_tile_size.max(1)));
    let point_read_options = default_rbc_windowed_options(dataset, point_tile_size);

    let mut l_data = vec![0f32; nl * dim];
    let mut leader_io_stats = PointBatchStats::default();
    dataset.read_points_windowed_into_batch_stats(
        leaders,
        &mut l_data,
        &leader_read_options,
        &mut leader_io_stats,
    )?;
    let l_norms: Vec<f32> = l_data
        .chunks(dim)
        .map(|r| r.iter().map(|&v| v * v).sum())
        .collect();
    let l_mat = ArrayView2::from_shape((nl, dim), &l_data).unwrap();
    let pilot_points = config.warmup_points.min(cur.len());
    let (pilot_records, pilot_pending, pilot_profile) = collect_root_risk_pilot_records_gemm(
        dataset,
        &cur[..pilot_points],
        &l_data,
        &l_norms,
        l_mat,
        point_tile_size,
        leader_tile_size,
        query_fanout,
        memory_budget_bytes,
    )?;
    root_fanout_state.insert_risk_batch(pilot_pending);
    let risk_snapshot = root_fanout_state
        .risk_snapshot()
        .expect("risk config and store must be present together");
    let utility_records = root_risk_utility_records(&config, &risk_snapshot, &pilot_records);
    let calibration = calibrate_budget_lambda(&config, &utility_records);
    root_fanout_state.record_risk_calibration(calibration);
    let budget_lambda = calibration.budget_lambda;

    struct RiskSpoolFold {
        scratch: GemmScratch,
        profile: GemmProfile,
        raw_counts: Vec<usize>,
        assign_chunks: Vec<Vec<u8>>,
        telemetry: RootRiskBudgetTelemetry,
    }

    let num_workers = rayon::current_num_threads().max(1);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        choose_spool_prefetch_workers(num_workers, memory_budget_bytes),
        memory_budget_bytes,
    );
    let mut profile = pilot_profile;
    let mut io_stats = leader_io_stats;
    let mut merged_raw_counts = vec![0usize; nl];

    for_each_prefetched_point_batch(
        dataset,
        cur,
        batch_points,
        point_read_options,
        |prefetched| {
            io_stats.merge(&prefetched.io_stats);
            profile.build_x += prefetched.load;
            let compute_block_points =
                choose_compute_block_points_for_batch(point_tile_size, prefetched.len, num_workers);

            let folds: Vec<RiskSpoolFold> = (0..prefetched.len)
                .into_par_iter()
                .step_by(compute_block_points)
                .map(|block_start_idx| {
                    let block_end_idx =
                        (block_start_idx + compute_block_points).min(prefetched.len);
                    let block_n = block_end_idx - block_start_idx;
                    let x_slice = &prefetched.data[block_start_idx * dim..block_end_idx * dim];
                    let mut fold = RiskSpoolFold {
                        scratch: GemmScratch::new(
                            compute_block_points,
                            leader_tile_size,
                            dim,
                            nl,
                            query_fanout,
                        ),
                        profile: GemmProfile::default(),
                        raw_counts: vec![0usize; nl],
                        assign_chunks: Vec::new(),
                        telemetry: RootRiskBudgetTelemetry::new(&config, cur.len(), nl),
                    };
                    let mut block_profile = GemmProfile {
                        blocks: 1,
                        ..GemmProfile::default()
                    };
                    let block_start = Instant::now();
                    let scratch = &mut fold.scratch;
                    let build_x_start = Instant::now();
                    scratch.x_data.clear();
                    scratch.x_data.extend_from_slice(x_slice);
                    scratch.x_norms.resize(block_n, 0f32);
                    for (i, chunk) in scratch.x_data.chunks(dim).enumerate() {
                        scratch.x_norms[i] = chunk.iter().map(|&v| v * v).sum();
                    }
                    let x_mat =
                        ArrayView2::from_shape((block_n, dim), scratch.x_data.as_slice()).unwrap();
                    block_profile.build_x += build_x_start.elapsed();

                    scratch
                        .topk_rows
                        .resize_with(block_n, || StackTopK::new(query_fanout));
                    for topk in scratch.topk_rows[..block_n].iter_mut() {
                        *topk = StackTopK::new(query_fanout);
                    }

                    for leader_offset in (0..nl).step_by(leader_tile_size) {
                        let leader_end = (leader_offset + leader_tile_size).min(nl);
                        let leader_view = l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                        let tile_cols = leader_end - leader_offset;
                        let mut gram_tile =
                            borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                        let gemm_start = Instant::now();
                        ndarray::linalg::general_mat_mul(
                            1.0,
                            &x_mat,
                            &leader_view.t(),
                            0.0,
                            &mut gram_tile,
                        );
                        block_profile.gemm += gemm_start.elapsed();
                        let topk_update_start = Instant::now();
                        update_block_topk_from_gram_tile(
                            &mut scratch.topk_rows[..block_n],
                            &scratch.x_norms[..block_n],
                            &l_norms,
                            gram_tile.view(),
                            leader_offset,
                        );
                        block_profile.topk += topk_update_start.elapsed();
                    }

                    let mut assign_buf = Vec::with_capacity(block_n * assign_record_width(fanout));
                    let mut assignment = [0u16; 32];
                    for top_k in scratch.topk_rows[..block_n].iter() {
                        let selector_start = Instant::now();
                        let record =
                            root_risk_top_record_from_topk(top_k, query_fanout, &l_data, dim);
                        let decision = select_risk_budgeted_fanout(
                            &config,
                            &risk_snapshot,
                            record.leader_slice(),
                            record.distance_slice(),
                            record.leader_pair_distance_slice(),
                            budget_lambda,
                        );
                        fold.telemetry.selector_ms += selector_start.elapsed().as_millis();
                        fold.telemetry.record(&decision, record.leader_slice());
                        let emit_len = if dry_run {
                            fanout.min(record.len).max(1)
                        } else {
                            decision.kept.min(record.len).max(1)
                        };
                        for (slot, &leader) in assignment
                            .iter_mut()
                            .zip(record.leader_slice()[..emit_len].iter())
                        {
                            *slot = leader as u16;
                        }
                        for &lid in &assignment[..emit_len] {
                            fold.raw_counts[lid as usize] += 1;
                        }
                        append_assign_record_bytes(
                            &mut assign_buf,
                            &assignment[..emit_len],
                            fanout,
                        )?;
                    }

                    block_profile.total_wall = block_start.elapsed();
                    fold.profile.merge(block_profile);
                    fold.assign_chunks.push(assign_buf);
                    Ok::<RiskSpoolFold, crate::common::AnnError>(fold)
                })
                .collect::<AnnResult<Vec<_>>>()?;

            let mut batch_telemetry = RootRiskBudgetTelemetry::new(&config, cur.len(), nl);
            for fold in folds {
                profile.merge(fold.profile);
                for (lid, count) in fold.raw_counts.into_iter().enumerate() {
                    merged_raw_counts[lid] += count;
                }
                batch_telemetry.merge(fold.telemetry);
                for bytes in fold.assign_chunks {
                    let spool_write_start = Instant::now();
                    spool_writer.write_all(&bytes)?;
                    profile.spool_write += spool_write_start.elapsed();
                }
            }
            root_fanout_state.record_risk_telemetry(batch_telemetry);
            Ok(())
        },
    )?;

    raw_counts.copy_from_slice(&merged_raw_counts);
    let flush_start = Instant::now();
    spool_writer.flush()?;
    profile.flush += flush_start.elapsed();
    profile.total_wall = total_start.elapsed();
    tracing::info!(
        "[rbc/root-risk-gemm-spool] point_reads={} range_reads={} range_rows={} hit_ratio={:.2}",
        io_stats.point_calls,
        io_stats.range_calls,
        io_stats.range_rows_read,
        io_stats.range_hit_ratio(),
    );
    Ok(profile)
}

fn partition_external_once(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    cur: &[u32],
    depth: usize,
    metric: Metric,
    params: &PiPNNParams,
    adaptive_c_max: usize,
    leaders: &[u32],
    local_fanout: usize,
    use_root_radius: bool,
    root_fanout_state: &RootFanoutState,
    compute_budget_bytes: Option<usize>,
    external_run_store: &Arc<Mutex<ExternalRunStore>>,
    _runtime_context: GpuSubtreeRuntimeContext<'_>,
    stats: &mut PartitionStats,
) -> AnnResult<ExternalPartitionAttempt> {
    let fanout = assign_record_fanout(
        root_fanout_state
            .variable_fixed_fanout()
            .filter(|_| use_root_radius)
            .unwrap_or(local_fanout)
            .min(leaders.len().max(1)),
    );
    let mut raw_counts = vec![0usize; leaders.len()];
    let base_dir = { external_run_store.lock().base_dir.clone() };
    let assign_spool = NamedTempFile::new_in(base_dir)?;
    let mut writer = BufWriter::new(assign_spool.reopen()?);

    let use_gemm = metric == Metric::L2 && cur.len() >= 256 && !use_root_radius;
    let use_radius_gemm =
        metric == Metric::L2 && use_root_radius && root_fanout_state.radius_config().is_some();
    let use_risk_gemm =
        metric == Metric::L2 && use_root_radius && root_fanout_state.risk_config().is_some();
    if depth == 0 && params.gpu_subtree_d0_dco_mode.is_enabled() && !use_gemm {
        return Err(AnnError::log_index_error(format!(
            "D0 DCO mode {} was explicitly requested but D0 root assignment is not on the fixed-fanout GEMM/spool path: rows={} metric={:?} variable_root_fanout={}",
            params.gpu_subtree_d0_dco_mode.as_str(),
            cur.len(),
            metric,
            use_root_radius,
        )));
    }
    let assign_start = Instant::now();
    if use_gemm {
        let budget = compute_budget_bytes.or_else(|| {
            params
                .oom_enable
                .then(|| params.effective_oom_memory_budget_bytes())
        });
        if depth == 0 && params.gpu_subtree_d0_dco_mode.is_enabled() {
            match params.gpu_subtree_d0_dco_mode {
                PiPNNGpuSubtreeDcoMode::RabitqWmmaFilter
                | PiPNNGpuSubtreeDcoMode::RabitqSplitFilter => {
                    let prefix = params
                        .gpu_subtree_rabitq_plus_sidecar_prefix
                        .as_ref()
                        .ok_or_else(|| {
                            AnnError::log_index_error(
                                "D0 RabitQ-Library split DCO requires a RabitQ-Library split sidecar prefix"
                                    .to_string(),
                            )
                        })?;
                    let sidecar = RabitqSplitSidecar::preload_validated(
                        prefix,
                        dataset.len(),
                        dataset.dim(),
                        params.gpu_subtree_rabitq_plus_bits,
                        params.gpu_subtree_rabitq_plus_rotator,
                        params.gpu_subtree_rabitq_plus_seed,
                    )?;
                    let profile = compute_clusters_rabitq_split_sidecar_dco_to_spool_budgeted(
                        dataset,
                        cur,
                        leaders,
                        fanout,
                        &mut writer,
                        &mut raw_counts,
                        &sidecar,
                        params,
                    )?;
                    stats.record_d0_dco_spool_profile(profile);
                }
                PiPNNGpuSubtreeDcoMode::SqInt8Filter => {
                    let prefix = params
                        .gpu_subtree_sq_wmma_sidecar_prefix
                        .as_ref()
                        .ok_or_else(|| {
                            AnnError::log_index_error(
                                "D0 SQ-int8 DCO requires a SQ+WMMA sidecar prefix".to_string(),
                            )
                        })?;
                    let sidecar = SqWmmaSidecar::open_validated_with_bits(
                        prefix,
                        dataset.len(),
                        dataset.dim(),
                        params.gpu_subtree_sq_bits,
                    )?;
                    let profile = compute_clusters_sq_sidecar_dco_to_spool_budgeted(
                        dataset,
                        cur,
                        leaders,
                        fanout,
                        budget,
                        &mut writer,
                        &mut raw_counts,
                        &sidecar,
                        params,
                    )?;
                    stats.record_d0_dco_spool_profile(profile);
                }
                other => {
                    return Err(AnnError::log_index_error(format!(
                        "Unsupported explicit D0 DCO mode {}; only rabitq-wmma-filter, rabitq-split-filter, and sq-int8-filter are wired",
                        other.as_str()
                    )));
                }
            }
        } else {
            let profile = if matches!(compute_backend.kind(), PiPNNComputeBackendKind::Cpu) {
                compute_clusters_gemm_to_spool_budgeted(
                    dataset,
                    cur,
                    leaders,
                    fanout,
                    budget,
                    &mut writer,
                    &mut raw_counts,
                )?
            } else {
                compute_clusters_with_backend_to_spool_budgeted(
                    compute_backend,
                    dataset,
                    cur,
                    leaders,
                    fanout,
                    budget,
                    &mut writer,
                    &mut raw_counts,
                )?
            };
            stats.record_gemm_profile(profile);
        }
    } else if use_radius_gemm {
        let profile = compute_root_radius_clusters_gemm_to_spool_budgeted(
            dataset,
            cur,
            leaders,
            root_fanout_state,
            compute_budget_bytes.or_else(|| {
                params
                    .oom_enable
                    .then(|| params.effective_oom_memory_budget_bytes())
            }),
            &mut writer,
            &mut raw_counts,
        )?;
        stats.record_gemm_profile(profile);
    } else if use_risk_gemm {
        let profile = compute_root_risk_clusters_gemm_to_spool_budgeted(
            dataset,
            cur,
            leaders,
            root_fanout_state,
            compute_budget_bytes.or_else(|| {
                params
                    .oom_enable
                    .then(|| params.effective_oom_memory_budget_bytes())
            }),
            &mut writer,
            &mut raw_counts,
        )?;
        stats.record_gemm_profile(profile);
    } else {
        compute_clusters_scalar_to_spool(
            dataset,
            cur,
            leaders,
            fanout,
            metric,
            &mut writer,
            &mut raw_counts,
        )?;
    }
    stats.record_assignment_time(depth, assign_start.elapsed());

    let raw_cluster_count = raw_counts.len();
    let empty_clusters = raw_counts.iter().filter(|&&count| count == 0).count();
    let pre_merge_clusters = raw_cluster_count.saturating_sub(empty_clusters);
    let assignments_before_merge = raw_counts.iter().sum::<usize>();

    let merge_start = Instant::now();
    let merge_groups = merge_cluster_plan(&raw_counts, params.c_min, adaptive_c_max);
    stats.record_phase_time(RbcPhase::MergeClusters, merge_start.elapsed());
    stats.record_merge(pre_merge_clusters, merge_groups.len(), empty_clusters);
    stats.record_assignments(assignments_before_merge, assignments_before_merge);

    Ok(ExternalPartitionAttempt {
        assign_spool,
        fanout,
        merge_groups,
    })
}

#[derive(Clone, Debug)]
struct DepthStats {
    clusters_processed: usize,
    leaves_generated: usize,
    total_points: usize,
    min_cluster_size: usize,
    max_cluster_size: usize,
}

impl DepthStats {
    fn new() -> Self {
        Self {
            clusters_processed: 0,
            leaves_generated: 0,
            total_points: 0,
            min_cluster_size: usize::MAX,
            max_cluster_size: 0,
        }
    }

    fn observe_size(&mut self, size: usize) {
        self.min_cluster_size = self.min_cluster_size.min(size);
        self.max_cluster_size = self.max_cluster_size.max(size);
    }

    fn min_cluster_size(&self) -> usize {
        if self.min_cluster_size == usize::MAX {
            0
        } else {
            self.min_cluster_size
        }
    }
}

#[derive(Debug)]
struct PartitionStats {
    depth_stats: Vec<DepthStats>,
    max_depth_seen: usize,

    early_stop_max_depth: usize,
    early_stop_shrink_ratio: usize,
    early_stop_small_deep: usize,
    early_stop_min_recurse: usize,
    natural_leaf_size: usize,
    partition_fallback_leaves: usize,

    partition_attempts: usize,
    partition_success_first: usize,
    partition_success_retry: usize,
    partition_failed_empty: usize,
    partition_failed_nosplit: usize,
    retry_escalations: usize,

    pre_merge_clusters_total: usize,
    post_merge_clusters_total: usize,
    empty_clusters_dropped: usize,
    no_op_merges: usize,

    leader_sum: usize,
    leader_max: usize,
    fanout_sum: usize,
    fanout_max: usize,

    assignments_before_dedup: usize,
    assignments_after_dedup: usize,
    dedup_runs: usize,
    dedup_skipped: usize,
    dedup_assignments_before: usize,
    dedup_assignments_after: usize,
    dedup_assignments_removed: usize,
    cur_dedup_time: Duration,
    cluster_assign_time: Duration,
    merge_time: Duration,
    merged_dedup_time: Duration,
    gemm_profile: GemmProfile,
    telemetry: RbcPartitionTelemetry,

    max_stack_size: usize,
    max_cluster_size_seen: usize,
    oversized_leaf_events: usize,
    oversized_leaf_points: usize,
    forced_leaf_splits: usize,
    largest_oversized_leaf: usize,

    leaf_sizes: Vec<usize>,
    root_stopped_child_runs: Vec<ChildRun>,
    start_time: Instant,
}

impl PartitionStats {
    fn new(max_depth: usize, expected_leaves: usize) -> Self {
        Self {
            depth_stats: (0..=max_depth).map(|_| DepthStats::new()).collect(),
            max_depth_seen: 0,
            early_stop_max_depth: 0,
            early_stop_shrink_ratio: 0,
            early_stop_small_deep: 0,
            early_stop_min_recurse: 0,
            natural_leaf_size: 0,
            partition_fallback_leaves: 0,
            partition_attempts: 0,
            partition_success_first: 0,
            partition_success_retry: 0,
            partition_failed_empty: 0,
            partition_failed_nosplit: 0,
            retry_escalations: 0,
            pre_merge_clusters_total: 0,
            post_merge_clusters_total: 0,
            empty_clusters_dropped: 0,
            no_op_merges: 0,
            leader_sum: 0,
            leader_max: 0,
            fanout_sum: 0,
            fanout_max: 0,
            assignments_before_dedup: 0,
            assignments_after_dedup: 0,
            dedup_runs: 0,
            dedup_skipped: 0,
            dedup_assignments_before: 0,
            dedup_assignments_after: 0,
            dedup_assignments_removed: 0,
            cur_dedup_time: Duration::ZERO,
            cluster_assign_time: Duration::ZERO,
            merge_time: Duration::ZERO,
            merged_dedup_time: Duration::ZERO,
            gemm_profile: GemmProfile::default(),
            telemetry: RbcPartitionTelemetry::default(),
            max_stack_size: 0,
            max_cluster_size_seen: 0,
            oversized_leaf_events: 0,
            oversized_leaf_points: 0,
            forced_leaf_splits: 0,
            largest_oversized_leaf: 0,
            leaf_sizes: Vec::with_capacity(expected_leaves),
            root_stopped_child_runs: Vec::new(),
            start_time: Instant::now(),
        }
    }

    fn ensure_depth(&mut self, depth: usize) {
        if depth >= self.depth_stats.len() {
            self.depth_stats.resize_with(depth + 1, DepthStats::new);
        }
    }

    fn record_leaf(&mut self, depth: usize, size: usize, reason: LeafReason) {
        self.ensure_depth(depth);
        self.max_depth_seen = self.max_depth_seen.max(depth);
        self.max_cluster_size_seen = self.max_cluster_size_seen.max(size);

        let depth_stats = &mut self.depth_stats[depth];
        depth_stats.leaves_generated += 1;
        depth_stats.total_points += size;
        depth_stats.observe_size(size);

        self.leaf_sizes.push(size);

        match reason {
            LeafReason::NaturalSize => self.natural_leaf_size += 1,
            LeafReason::MaxDepth => self.early_stop_max_depth += 1,
            LeafReason::ShrinkRatio => self.early_stop_shrink_ratio += 1,
            LeafReason::SmallDeep => self.early_stop_small_deep += 1,
            LeafReason::MinRecurse => self.early_stop_min_recurse += 1,
            LeafReason::PartitionFallback => self.partition_fallback_leaves += 1,
        }
    }

    fn record_partition_attempt(
        &mut self,
        depth: usize,
        size: usize,
        leaders: usize,
        fanout: usize,
    ) {
        self.ensure_depth(depth);
        self.partition_attempts += 1;
        self.max_depth_seen = self.max_depth_seen.max(depth);
        self.max_cluster_size_seen = self.max_cluster_size_seen.max(size);

        let depth_stats = &mut self.depth_stats[depth];
        depth_stats.clusters_processed += 1;
        depth_stats.observe_size(size);

        self.leader_sum += leaders;
        self.leader_max = self.leader_max.max(leaders);
        self.fanout_sum += fanout;
        self.fanout_max = self.fanout_max.max(fanout);
    }

    fn record_partition_result(&mut self, result: PartitionResult) {
        match result {
            PartitionResult::SuccessFirst => self.partition_success_first += 1,
            PartitionResult::SuccessRetry => self.partition_success_retry += 1,
            PartitionResult::FailedEmpty => self.partition_failed_empty += 1,
            PartitionResult::FailedNoSplit => self.partition_failed_nosplit += 1,
        }
    }

    fn record_merge(&mut self, pre: usize, post: usize, empty: usize) {
        self.pre_merge_clusters_total += pre;
        self.post_merge_clusters_total += post;
        self.empty_clusters_dropped += empty;
        if pre == post {
            self.no_op_merges += 1;
        }
    }

    fn record_retry_escalation(&mut self) {
        self.retry_escalations += 1;
    }

    fn record_assignments(&mut self, before_dedup: usize, after_dedup: usize) {
        self.assignments_before_dedup += before_dedup;
        self.assignments_after_dedup += after_dedup;
    }

    fn record_dedup(&mut self, executed: bool, before_dedup: usize, after_dedup: usize) {
        if executed {
            self.dedup_runs += 1;
            self.dedup_assignments_before += before_dedup;
            self.dedup_assignments_after += after_dedup;
            self.dedup_assignments_removed += before_dedup.saturating_sub(after_dedup);
        } else {
            self.dedup_skipped += 1;
        }
    }

    fn record_phase_time(&mut self, phase: RbcPhase, duration: Duration) {
        match phase {
            RbcPhase::CurDedup => self.cur_dedup_time += duration,
            RbcPhase::ClusterAssign => self.cluster_assign_time += duration,
            RbcPhase::MergeClusters => self.merge_time += duration,
            RbcPhase::MergedDedup => self.merged_dedup_time += duration,
            RbcPhase::D1Materialize => self.telemetry.d1_materialize_wall += duration,
            RbcPhase::D2Replay => self.telemetry.d2_replay_wall += duration,
        }
    }

    fn record_assignment_time(&mut self, depth: usize, duration: Duration) {
        self.record_phase_time(RbcPhase::ClusterAssign, duration);
        if depth == 0 {
            self.telemetry.d0_ads_assignment_wall += duration;
        } else if depth == 1 {
            self.telemetry.d1_ads_assignment_wall += duration;
        }
    }

    fn record_gemm_profile(&mut self, profile: GemmProfile) {
        self.gemm_profile.merge(profile);
    }

    fn record_d0_dco_spool_profile(&mut self, profile: D0DcoSpoolProfile) {
        self.gemm_profile.merge(profile.gemm);
        self.telemetry.gpu_subtree_d0_dco.merge(profile.dco);
        self.telemetry.gpu_subtree_d0_dco_sidecar_gather_wall += profile.sidecar_gather_wall;
        self.telemetry.gpu_subtree_d0_dco_approx_wall += profile.approx_wall;
        self.telemetry.gpu_subtree_d0_dco_exact_wall += profile.exact_wall;
    }

    fn record_resident_subtree_hit(
        &mut self,
        points: usize,
        bytes: usize,
        read_wall: Duration,
        compute_wall: Duration,
    ) {
        self.telemetry.resident_subtree_count += 1;
        self.telemetry.resident_subtree_points += points;
        self.telemetry.resident_subtree_bytes += bytes;
        self.telemetry.resident_subtree_read_wall += read_wall;
        self.telemetry.resident_subtree_compute_wall += compute_wall;
        self.telemetry.resident_subtree_max_points =
            self.telemetry.resident_subtree_max_points.max(points);
    }

    fn record_resident_subtree_fallback(&mut self, points: usize, wait_wall: Duration) {
        self.telemetry.resident_subtree_fallback_count += 1;
        self.telemetry.resident_subtree_fallback_points += points;
        self.telemetry.resident_subtree_permit_wait += wait_wall;
    }

    fn record_stack_size(&mut self, stack_size: usize) {
        self.max_stack_size = self.max_stack_size.max(stack_size);
    }

    fn record_oversized_leaf(&mut self, size: usize) {
        self.oversized_leaf_events += 1;
        self.oversized_leaf_points += size;
        self.largest_oversized_leaf = self.largest_oversized_leaf.max(size);
    }

    fn merge_from(&mut self, mut other: PartitionStats) {
        // depth_stats: extend or merge per-depth
        for (depth, ds) in other.depth_stats.into_iter().enumerate() {
            self.ensure_depth(depth);
            let mine = &mut self.depth_stats[depth];
            mine.clusters_processed += ds.clusters_processed;
            mine.leaves_generated += ds.leaves_generated;
            mine.total_points += ds.total_points;
            if ds.min_cluster_size < mine.min_cluster_size {
                mine.min_cluster_size = ds.min_cluster_size;
            }
            if ds.max_cluster_size > mine.max_cluster_size {
                mine.max_cluster_size = ds.max_cluster_size;
            }
        }
        self.max_depth_seen = self.max_depth_seen.max(other.max_depth_seen);
        self.early_stop_max_depth += other.early_stop_max_depth;
        self.early_stop_shrink_ratio += other.early_stop_shrink_ratio;
        self.early_stop_small_deep += other.early_stop_small_deep;
        self.early_stop_min_recurse += other.early_stop_min_recurse;
        self.natural_leaf_size += other.natural_leaf_size;
        self.partition_fallback_leaves += other.partition_fallback_leaves;
        self.partition_attempts += other.partition_attempts;
        self.partition_success_first += other.partition_success_first;
        self.partition_success_retry += other.partition_success_retry;
        self.partition_failed_empty += other.partition_failed_empty;
        self.partition_failed_nosplit += other.partition_failed_nosplit;
        self.retry_escalations += other.retry_escalations;
        self.pre_merge_clusters_total += other.pre_merge_clusters_total;
        self.post_merge_clusters_total += other.post_merge_clusters_total;
        self.empty_clusters_dropped += other.empty_clusters_dropped;
        self.no_op_merges += other.no_op_merges;
        self.leader_sum += other.leader_sum;
        self.leader_max = self.leader_max.max(other.leader_max);
        self.fanout_sum += other.fanout_sum;
        self.fanout_max = self.fanout_max.max(other.fanout_max);
        self.assignments_before_dedup += other.assignments_before_dedup;
        self.assignments_after_dedup += other.assignments_after_dedup;
        self.dedup_runs += other.dedup_runs;
        self.dedup_skipped += other.dedup_skipped;
        self.dedup_assignments_before += other.dedup_assignments_before;
        self.dedup_assignments_after += other.dedup_assignments_after;
        self.dedup_assignments_removed += other.dedup_assignments_removed;
        self.cur_dedup_time += other.cur_dedup_time;
        self.cluster_assign_time += other.cluster_assign_time;
        self.merge_time += other.merge_time;
        self.merged_dedup_time += other.merged_dedup_time;
        self.gemm_profile.merge(other.gemm_profile);
        self.telemetry.merge(other.telemetry);
        self.max_stack_size = self.max_stack_size.max(other.max_stack_size);
        self.max_cluster_size_seen = self.max_cluster_size_seen.max(other.max_cluster_size_seen);
        self.oversized_leaf_events += other.oversized_leaf_events;
        self.oversized_leaf_points += other.oversized_leaf_points;
        self.forced_leaf_splits += other.forced_leaf_splits;
        self.largest_oversized_leaf = self
            .largest_oversized_leaf
            .max(other.largest_oversized_leaf);
        self.leaf_sizes.append(&mut other.leaf_sizes);
        self.root_stopped_child_runs
            .append(&mut other.root_stopped_child_runs);
    }

    fn total_leaves(&self) -> usize {
        self.leaf_sizes.len()
    }

    fn elapsed(&self) -> Duration {
        self.start_time.elapsed()
    }

    fn total_points_in_leaves(&self) -> usize {
        self.leaf_sizes.iter().sum()
    }

    fn overlap_ratio(&self) -> f64 {
        percentage(
            self.assignments_before_dedup
                .saturating_sub(self.assignments_after_dedup),
            self.assignments_before_dedup,
        )
    }
}

/// RBC 分区（流式）：在给定点集索引 `indices` 上进行随机球雕，生成的叶子通过 `leaf_emitter` 发射。
///
/// 调用方负责为该 producer 提供 dedicated rayon pool；这里不再嵌套创建线程池，
/// 避免 producer 侧出现双重 pool 导致线程数虚高。
pub fn rbc_partition_streaming(
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    num_threads: u32,
    rng: &mut (impl Rng + Send),
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<()> {
    rbc_partition_streaming_with_backend(
        cpu_backend(),
        dataset,
        indices,
        metric,
        params,
        num_threads,
        rng,
        None,
        leaf_emitter,
    )
    .map(|_| ())
}

pub(crate) fn rbc_partition_streaming_with_backend(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_child_dir: Option<&Path>,
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<RbcPartitionTelemetry> {
    let external_run_store = external_child_dir.map(|dir| {
        let io_cfg = if params.strict_oom_io_enabled() {
            DirectIoConfig::enabled_with_alignment(4096)
        } else {
            DirectIoConfig::disabled()
        };
        Arc::new(Mutex::new(ExternalRunStore::new(dir, io_cfg)))
    });
    rbc_partition_impl_streaming(
        compute_backend,
        dataset,
        indices,
        metric,
        params,
        num_threads,
        rng,
        external_run_store,
        leaf_emitter,
    )
}

pub(crate) fn rbc_partition_gpu_subtree_streaming(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_child_dir: Option<&Path>,
    _leaf_emitter: Option<&dyn LeafEmitter>,
    compact_sink: Option<&dyn CompactTopKSink>,
) -> AnnResult<GpuSubtreeStreamingProfile> {
    let d0_plan = run_gpu_subtree_d0_preflight(
        cpu_backend(),
        dataset,
        indices,
        metric,
        params,
        num_threads,
        rng,
        external_child_dir,
    )?;
    if params.root_stop_after_d00 || d0_plan.child_runs.is_empty() {
        let entry_point = gpu_subtree_entry_point_from_d0_plan(&d0_plan)?;
        return Ok(GpuSubtreeStreamingProfile {
            rbc: d0_plan.rbc_telemetry,
            leaf: LeafProfile::default(),
            entry_point,
        });
    }
    let Some(compact_sink) = compact_sink else {
        return Err(AnnError::log_index_error(
            "gpu-subtree persistent compact output requires a compact top-k sink".to_string(),
        ));
    };
    run_gpu_subtree_from_d0_plan(
        subtree_backend,
        dataset,
        metric,
        params,
        d0_plan,
        compact_sink,
        CompactFlushMode::Sync,
    )
}

fn d0_throughput_error(
    reason: &'static str,
    rows: usize,
    candidates: usize,
    detail: Option<&str>,
) -> AnnError {
    let detail = detail
        .map(|value| format!(", detail={value}"))
        .unwrap_or_default();
    AnnError::log_index_config_error(
        "gpu_subtree_d0_throughput_model".to_string(),
        format!(
            "D0 throughput model failed: reason={reason}, memory_safe_rows={rows}, candidate_count={candidates}{detail}"
        ),
    )
}

fn plan_d0_capacity_with_throughput_model(
    total_points: usize,
    dim: usize,
    params: &PiPNNParams,
    d0_capacity_cfg: super::d0_capacity::D0CapacityConfig,
    workspace_budget: usize,
    sidecar_code_row_bytes: usize,
) -> AnnResult<(usize, Option<D0ThroughputModelDecision>)> {
    let memory_safe_rows = find_max_admissible_rows(
        dim,
        params.leaf_knn,
        gpu_persistent_subtree_max_leaders_for_params(params),
        params.fanout_second.max(1),
        Some(workspace_budget),
        Some(workspace_budget),
        params,
    );
    if params.gpu_subtree_d0_throughput_model == PiPNNGpuSubtreeD0ThroughputModelMode::Off {
        return Ok((memory_safe_rows, None));
    }

    let mut input = D0ThroughputModelInput {
        total_points,
        dim,
        root_fanout: params.fanout_top.max(1),
        fanout_second: params.fanout_second.max(1),
        leaf_target: params.adaptive_c_max(total_points).max(1),
        leaf_tile_rows: params.gpu_subtree_persistent_leaf_tile_rows.max(1),
        min_efficient_rows: d0_capacity_cfg.min_efficient_rows,
        memory_safe_rows,
        sidecar_code_row_bytes: sidecar_code_row_bytes.max(1),
        persistent_growth_limit: params.gpu_subtree_d0_throughput_persistent_growth_limit,
        preload_visible_limit_ms: params.gpu_subtree_d0_throughput_preload_visible_limit_ms,
        min_ratio: params.gpu_subtree_d0_throughput_min_ratio,
        child_p95_guardrail_rows: (params.gpu_subtree_d0_throughput_child_p95_guardrail_rows > 0)
            .then_some(params.gpu_subtree_d0_throughput_child_p95_guardrail_rows),
        calibration: D0ThroughputCalibration::missing(),
    };
    if let Some(path) = params.gpu_subtree_d0_throughput_calibration_path.as_deref() {
        input.calibration =
            calibration_from_json_path(path, &input, d0_capacity_cfg).map_err(|err| {
                d0_throughput_error(
                    err.reason,
                    err.memory_safe_rows,
                    err.candidate_count,
                    err.detail.as_deref(),
                )
            })?;
    }
    let decision = decide_d0_throughput_capacity(
        params.gpu_subtree_d0_throughput_model,
        input,
        d0_capacity_cfg,
    )
    .map_err(|err| {
        d0_throughput_error(
            err.reason,
            err.memory_safe_rows,
            err.candidate_count,
            err.detail.as_deref(),
        )
    })?;
    let selected_rows = if params.gpu_subtree_d0_throughput_model
        == PiPNNGpuSubtreeD0ThroughputModelMode::Enforce
    {
        decision.selected_rows
    } else {
        memory_safe_rows
    };
    Ok((selected_rows, Some(decision)))
}

pub(crate) fn run_gpu_subtree_d0_preflight(
    root_assignment_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    _num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_child_dir: Option<&Path>,
) -> AnnResult<GpuSubtreeD0Plan> {
    run_gpu_subtree_d0_preflight_with_context(
        root_assignment_backend,
        dataset,
        indices,
        metric,
        params,
        _num_threads,
        rng,
        external_child_dir,
        GpuSubtreeRuntimeContext::default(),
    )
}

pub(crate) fn run_gpu_subtree_d0_preflight_with_context(
    root_assignment_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    _num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_child_dir: Option<&Path>,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
) -> AnnResult<GpuSubtreeD0Plan> {
    struct RootStopLeafGuard;

    impl LeafEmitter for RootStopLeafGuard {
        fn emit_leaf(&self, leaf: Vec<u32>) -> AnnResult<()> {
            Err(AnnError::log_index_error(format!(
                "gpu-subtree compact path expected root_stop_after_d00 child runs, got root leaf with {} points",
                leaf.len()
            )))
        }
    }

    if metric != Metric::L2 {
        return Err(AnnError::log_index_error(
            "gpu-subtree partitioner currently supports only L2".to_string(),
        ));
    }
    if !params.oom_enable {
        return Err(AnnError::log_index_error(
            "gpu-subtree partitioner requires OOM mode".to_string(),
        ));
    }
    let Some(external_child_dir) = external_child_dir else {
        return Err(AnnError::log_index_error(
            "gpu-subtree partitioner requires an external child run directory".to_string(),
        ));
    };

    let total_size = indices.len();
    let dim = dataset.dim();
    let adaptive_c_max = params.adaptive_c_max(total_size);
    let min_recurse_size = adaptive_c_max.saturating_mul(2);
    let d0_capacity_cfg = d0_capacity_config_from_params(params);
    let mut d0_capacity_telemetry = D0CapacityTelemetry::default();
    let mut d0_throughput_model = None;
    let c_gpu = if d0_capacity_cfg.enabled {
        let (c_gpu, throughput_decision) = plan_d0_capacity_with_throughput_model(
            total_size,
            dim,
            params,
            d0_capacity_cfg,
            params.effective_gpu_workspace_budget_bytes(),
            dim.max(1),
        )?;
        d0_throughput_model = throughput_decision;
        let thresholds = compute_thresholds(c_gpu, d0_capacity_cfg);
        d0_capacity_telemetry.enabled = true;
        d0_capacity_telemetry.c_gpu = thresholds.c_gpu;
        d0_capacity_telemetry.c_high = thresholds.c_high;
        d0_capacity_telemetry.c_target = thresholds.c_target;
        d0_capacity_telemetry.c_low = thresholds.c_low;
        d0_capacity_telemetry.quality_min_root_leaders = d0_capacity_cfg.quality_min_root_leaders;
        c_gpu
    } else {
        0
    };
    if total_size == 0 {
        let root_fanout_profile = RootFanoutState::fixed(params.fanout_top).profile();
        return finalize_gpu_subtree_d0_hashes(GpuSubtreeD0Plan {
            total_points: 0,
            adaptive_c_max,
            min_recurse_size,
            external_child_dir: external_child_dir.to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: root_fanout_profile.clone(),
            child_runs: Vec::new(),
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats: GpuSubtreeChildRunStats::default(),
            rbc_telemetry: RbcPartitionTelemetry {
                root_fanout: root_fanout_profile,
                d0_throughput_model: d0_throughput_model.clone(),
                ..RbcPartitionTelemetry::default()
            },
            d0_capacity: D0CapacityTelemetry::default(),
        });
    }
    if matches!(
        params.gpu_subtree_d0_partition_mode,
        PiPNNGpuSubtreeD0PartitionMode::TagoreKMeansTopK
    ) {
        return finalize_gpu_subtree_d0_hashes(run_gpu_subtree_d0_tagore_kmeans_topk(
            dataset,
            indices,
            params,
            rng,
            external_child_dir,
            adaptive_c_max,
            min_recurse_size,
            c_gpu,
            d0_capacity_telemetry,
            d0_throughput_model,
        )?);
    }
    let target_root_leaders = if d0_capacity_cfg.enabled {
        let thresholds = compute_thresholds(c_gpu, d0_capacity_cfg);
        let leader_plan =
            plan_root_leaders(total_size, params.fanout_top, thresholds, d0_capacity_cfg);
        d0_capacity_telemetry.k_capacity = leader_plan.k_capacity;
        d0_capacity_telemetry.root_leader_cap = leader_plan.root_leader_cap;
        d0_capacity_telemetry.root_leader_source = leader_plan.root_leader_source;
        d0_capacity_telemetry.root_leaders_initial = leader_plan.k_initial;
        Some(leader_plan.k_initial)
    } else {
        None
    };
    let root_leaders = select_root_leaders_with_target(indices, params, target_root_leaders, rng);
    d0_capacity_telemetry.root_leaders_final = root_leaders.len();
    let root_fanout_state = if root_leaders.is_empty() {
        RootFanoutState::fixed(params.fanout_top)
    } else {
        initialize_root_fanout_state(dataset, indices, &root_leaders, params, metric, rng)?
    };
    let io_cfg = if params.strict_oom_io_enabled() {
        DirectIoConfig::enabled_with_alignment(4096)
    } else {
        DirectIoConfig::disabled()
    };
    let external_run_store = Arc::new(Mutex::new(ExternalRunStore::new(
        external_child_dir,
        io_cfg,
    )));

    let pb = ProgressBar::new_spinner();
    pb.set_style(
        ProgressStyle::default_spinner()
            .template("{spinner:.green} [{elapsed_precise}] {msg}")
            .unwrap(),
    );
    pb.set_message(format!(
        "gpu-subtree root D0: c_max={} min_recurse={}",
        format_count(adaptive_c_max),
        format_count(min_recurse_size),
    ));

    tracing::info!(
        "GPU-subtree partition starting: {} points, adaptive_c_max={}, min_recurse={}",
        format_count(total_size),
        format_count(adaptive_c_max),
        format_count(min_recurse_size),
    );

    let seed: u64 = rng.random();
    let d0_start = Instant::now();
    let resident_context =
        rbc_memory_context_for_params(params, dataset.dim(), rayon::current_num_threads().max(1));
    let resident_options = resident_context
        .as_ref()
        .map(|memory| ResidentSubtreeOptions {
            memory,
            materialize: true,
        });

    let mut root_params = params.clone();
    root_params.root_stop_after_d00 = true;
    let root_stop_leaf_guard = RootStopLeafGuard;
    let mut root_stats = rbc_recurse_parallel(
        root_assignment_backend,
        dataset,
        indices.to_vec(),
        0,
        total_size,
        metric,
        &root_params,
        adaptive_c_max,
        min_recurse_size,
        seed,
        &pb,
        Some(&external_run_store),
        resident_options,
        runtime_context,
        &root_fanout_state,
        &root_stop_leaf_guard,
    )?;
    root_stats.max_cluster_size_seen = root_stats.max_cluster_size_seen.max(total_size);
    root_stats.telemetry.root_fanout = root_fanout_state.profile();
    root_stats.telemetry.gpu_subtree_d0_wall += d0_start.elapsed();
    let child_runs = std::mem::take(&mut root_stats.root_stopped_child_runs)
        .into_iter()
        .map(GpuSubtreeChildRun::from)
        .collect::<Vec<_>>();
    let thresholds = if d0_capacity_telemetry.enabled {
        Some(compute_thresholds(
            d0_capacity_telemetry.c_gpu,
            d0_capacity_config_from_params(params),
        ))
    } else {
        None
    };
    if d0_capacity_telemetry.enabled {
        let mut unique_sizes =
            scan_gpu_subtree_child_unique_sizes(external_child_dir, io_cfg, &child_runs)?;
        super::d0_capacity::observe_child_unique_sizes(
            &mut d0_capacity_telemetry,
            thresholds.unwrap(),
            &mut unique_sizes,
        );
    }
    let child_stats = compute_gpu_subtree_child_run_stats(&child_runs);
    root_stats.telemetry.gpu_subtree_d0_child_run_count = child_stats.count;
    root_stats.telemetry.gpu_subtree_d0_child_points = child_stats.total_points;
    root_stats.telemetry.gpu_subtree_d0_child_max_len = child_stats.max_len;
    root_stats.telemetry.gpu_subtree_d0_child_p50_len = child_stats.p50_len;
    root_stats.telemetry.gpu_subtree_d0_child_p95_len = child_stats.p95_len;
    root_stats.telemetry.gpu_subtree_d0_child_p99_len = child_stats.p99_len;
    root_stats.telemetry.d0_capacity = d0_capacity_telemetry.clone();
    root_stats.telemetry.d0_throughput_model = d0_throughput_model.clone();
    pb.finish_and_clear();

    finalize_gpu_subtree_d0_hashes(GpuSubtreeD0Plan {
        total_points: total_size,
        adaptive_c_max,
        min_recurse_size,
        external_child_dir: external_child_dir.to_path_buf(),
        io_cfg,
        root_fanout_profile: root_fanout_state.profile(),
        child_runs,
        sq_shard_local_payloads: Vec::new(),
        sq_cluster_child_indices: Vec::new(),
        child_stats,
        rbc_telemetry: root_stats.telemetry,
        d0_capacity: d0_capacity_telemetry,
    })
}

pub(crate) fn run_gpu_subtree_qcode_staging_preflight(
    staging_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    _num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_child_dir: Option<&Path>,
) -> AnnResult<(GpuSubtreeD0Plan, RabitqResidualQcodeShardStore)> {
    if metric != Metric::L2 {
        return Err(AnnError::log_index_error(
            "Residual RaBitQ qcode staging currently supports only L2".to_string(),
        ));
    }
    if !params.oom_enable {
        return Err(AnnError::log_index_error(
            "Residual RaBitQ qcode staging requires OOM mode".to_string(),
        ));
    }
    if !matches!(
        params.gpu_subtree_qcode_staging_mode,
        PiPNNGpuSubtreeQcodeStagingMode::RabitqResidual
    ) {
        return Err(AnnError::log_index_error(format!(
            "Unsupported qcode staging mode '{}' in residual RaBitQ preflight",
            params.gpu_subtree_qcode_staging_mode.as_str()
        )));
    }
    let Some(external_child_dir) = external_child_dir else {
        return Err(AnnError::log_index_error(
            "Residual RaBitQ qcode staging requires an external child run directory".to_string(),
        ));
    };
    let total_size = indices.len();
    if total_size == 0 {
        return Err(AnnError::log_index_error(
            "Residual RaBitQ qcode staging requires at least one point".to_string(),
        ));
    }
    for (expected, &point_id) in indices.iter().enumerate() {
        if point_id as usize != expected {
            return Err(AnnError::log_index_error(format!(
                "Residual RaBitQ qcode staging v1 requires dense global ids 0..N, got point_id={} at row={}",
                point_id, expected
            )));
        }
    }

    let total_start = Instant::now();
    let dim = dataset.dim();
    let adaptive_c_max = params.adaptive_c_max(total_size);
    let min_recurse_size = adaptive_c_max.saturating_mul(2);
    let io_cfg = if params.strict_oom_io_enabled() {
        DirectIoConfig::enabled_with_alignment(4096)
    } else {
        DirectIoConfig::disabled()
    };
    let global_d0_leaders = if params.gpu_subtree_qcode_global_d0_leaders > 0 {
        select_root_leaders_with_uncapped_target(
            indices,
            params,
            params.gpu_subtree_qcode_global_d0_leaders,
            rng,
        )
    } else {
        select_root_leaders_with_target(indices, params, None, rng)
    };
    if global_d0_leaders.is_empty() {
        return Err(AnnError::log_index_error(
            "Residual RaBitQ qcode staging selected no global D0 leaders".to_string(),
        ));
    }
    let fanout = params
        .fanout_top
        .max(1)
        .min(global_d0_leaders.len())
        .min(32);
    let leader_vectors = read_point_ids_dense(dataset, &global_d0_leaders)?;

    let centroid_count = params
        .gpu_subtree_rabitq_residual_centroids
        .max(1)
        .min(total_size);
    let centroid_train_start = Instant::now();
    let (centroids, _sample_points) = train_tagore_d0_centers(
        dataset,
        indices,
        centroid_count,
        params.gpu_subtree_d0_tagore_sample_fraction,
        params.kmeans_iterations,
    )?;
    let centroid_train_wall = centroid_train_start.elapsed();
    let center_norms = tagore_d0_center_norms(&centroids, dim);
    let padded_dim = rabitq_padded_dim(dim, RABITQ_DEFAULT_K_ALIGN)?;
    let rotator = params.gpu_subtree_rabitq_plus_rotator;
    let rotator_seed = params.gpu_subtree_rabitq_plus_seed;
    let rotated_centroids =
        prepare_rabitq_residual_centroids(&centroids, dim, rotator, rotator_seed)?;
    let leader_prepare_start = Instant::now();
    let leader_payload = prepare_rabitq_residual_leader_payload(
        &global_d0_leaders,
        &leader_vectors,
        &centroids,
        dim,
        rotator,
        rotator_seed,
    )?;
    let leader_prepare_wall = leader_prepare_start.elapsed();
    let qcode_root = external_child_dir.join("rabitq_residual_qcode");
    let qcode_header = RabitqResidualPayloadHeader {
        rows: total_size,
        dim,
        padded_dim,
        centroid_count,
        code_row_bytes: padded_dim,
    };
    let split_short_ex_child_local = params.gpu_subtree_rabitq_d1_distance_mode
        == PiPNNGpuSubtreeRabitqD1DistanceMode::SplitShortEx
        && params.gpu_subtree_qcode_d1_payload_mode
            == super::params::PiPNNGpuSubtreeQcodeD1PayloadMode::ChildLocal;
    let mut qcode_store = if split_short_ex_child_local {
        RabitqResidualQcodeShardStore::create_split_only(
            &qcode_root,
            qcode_header,
            &rotated_centroids,
        )?
    } else {
        RabitqResidualQcodeShardStore::create(&qcode_root, qcode_header, &rotated_centroids)?
    };

    let mut fragments = Vec::with_capacity(total_size.saturating_mul(fanout));
    let upload_shard_rows = params.gpu_subtree_qcode_staging_upload_shard_rows.max(1);
    let read_options = default_rbc_windowed_options(dataset, upload_shard_rows);
    let mut centroid_assign_wall = Duration::ZERO;
    let mut gpu_quantize_wall = Duration::ZERO;
    let mut gpu_d0_assign_wall = Duration::ZERO;
    let mut leader_payload_h2d_wall = Duration::ZERO;
    let mut qcode_shard_write_wall = Duration::ZERO;
    let mut d0_assign_kernel_mode = "";
    let mut d0_assign_rows = 0usize;
    let mut d0_assign_leaders = 0usize;
    let mut d0_assign_pair_count = 0usize;
    let mut d0_assign_fanout = fanout;
    let mut d0_assign_row_tile = 0usize;
    let mut d0_assign_row_chunk = 0usize;
    let mut d0_assign_leader_tile = 0usize;
    let mut d0_assign_partial_r = 0usize;
    let mut d0_assign_leader_tile_count = 0usize;
    let mut d0_assign_partial_bytes = 0usize;
    let mut d0_assign_distance_kernel_wall = Duration::ZERO;
    let mut d0_assign_merge_kernel_wall = Duration::ZERO;

    for shard_ids in indices.chunks(upload_shard_rows) {
        let shard_start = Instant::now();
        let mut raw_vectors = vec![0.0f32; shard_ids.len().saturating_mul(dim)];
        let mut read_stats = PointBatchStats::default();
        dataset.read_points_windowed_into_batch_stats(
            shard_ids,
            &mut raw_vectors,
            &read_options,
            &mut read_stats,
        )?;
        let assignments = assign_dense_rows_to_precomputed_centers(
            &raw_vectors,
            shard_ids.len(),
            dim,
            &centroids,
            &center_norms,
            1,
        );
        let centroid_ids = (0..shard_ids.len())
            .map(|row| assignments.row(row)[0] as u32)
            .collect::<Vec<_>>();
        centroid_assign_wall += shard_start.elapsed();

        let result = staging_backend.quantize_rabitq_residual_and_assign_global_d0(
            RabitqResidualQuantizeD0Request {
                raw_vectors_row_major: &raw_vectors,
                global_ids: shard_ids,
                centroid_ids: &centroid_ids,
                centroids_row_major: &centroids,
                global_d0_leader_ids: &global_d0_leaders,
                global_d0_leader_vectors_row_major: &leader_vectors,
                leader_payload: Some(&leader_payload),
                dim,
                fanout_top: fanout,
                rotator,
                rotator_seed,
            },
            params,
        )?;
        gpu_quantize_wall += result.profile.gpu_quantize_wall;
        gpu_d0_assign_wall += result.profile.gpu_d0_assign_wall;
        leader_payload_h2d_wall += result.profile.leader_payload_h2d_wall;
        if !result.profile.d0_assign_kernel_mode.is_empty() {
            d0_assign_kernel_mode = result.profile.d0_assign_kernel_mode;
        }
        d0_assign_rows += result.profile.d0_assign_rows;
        d0_assign_leaders = d0_assign_leaders.max(result.profile.d0_assign_leaders);
        d0_assign_pair_count =
            d0_assign_pair_count.saturating_add(result.profile.d0_assign_pair_count);
        d0_assign_fanout = d0_assign_fanout.max(result.profile.d0_assign_fanout);
        d0_assign_row_tile = d0_assign_row_tile.max(result.profile.d0_assign_row_tile);
        d0_assign_row_chunk = d0_assign_row_chunk.max(result.profile.d0_assign_row_chunk);
        d0_assign_leader_tile = d0_assign_leader_tile.max(result.profile.d0_assign_leader_tile);
        d0_assign_partial_r = d0_assign_partial_r.max(result.profile.d0_assign_partial_r);
        d0_assign_leader_tile_count =
            d0_assign_leader_tile_count.max(result.profile.d0_assign_leader_tile_count);
        d0_assign_partial_bytes =
            d0_assign_partial_bytes.max(result.profile.d0_assign_partial_bytes);
        d0_assign_distance_kernel_wall += result.profile.d0_assign_distance_kernel_wall;
        d0_assign_merge_kernel_wall += result.profile.d0_assign_merge_kernel_wall;
        let shard_write_start = Instant::now();
        qcode_store.write_shard(&result.payload)?;
        qcode_shard_write_wall += shard_write_start.elapsed();
        fragments.extend(result.fragments);
    }

    if !qcode_store.is_complete() {
        return Err(AnnError::log_index_error(
            "Residual RaBitQ qcode staging produced an incomplete qcode shard store".to_string(),
        ));
    }

    let mut point_fragment_counts = vec![0usize; total_size];
    for fragment in &fragments {
        if fragment.point_id as usize >= total_size {
            return Err(AnnError::log_index_error(format!(
                "Residual RaBitQ qcode staging fragment point {} is outside payload rows {}",
                fragment.point_id, total_size
            )));
        }
        point_fragment_counts[fragment.point_id as usize] += 1;
    }
    if let Some((point_id, &count)) = point_fragment_counts
        .iter()
        .enumerate()
        .find(|&(_, &count)| count != fanout)
    {
        return Err(AnnError::log_index_error(format!(
            "Residual RaBitQ qcode staging expected fanout {} fragments per point, got {} for point {}",
            fanout, count, point_id
        )));
    }

    let reduce_start = Instant::now();
    let children = reduce_d0_assignment_fragments(global_d0_leaders.len(), total_size, &fragments)?;
    let fragment_reduce_wall = reduce_start.elapsed();
    let mut run_store = ExternalRunStore::new(external_child_dir, io_cfg);
    let seed: u64 = rng.random();
    let mut child_runs = Vec::new();
    let mut child_lens = Vec::with_capacity(children.len());
    for (child_idx, child) in children.into_iter().enumerate() {
        child_lens.push(child.len());
        if child.is_empty() {
            continue;
        }
        let extent = write_child_run(&mut run_store, 0, &child)?;
        child_runs.push(GpuSubtreeChildRun {
            extents: vec![extent],
            len: child.len(),
            seed: seed ^ (child_idx as u64).wrapping_mul(0x9e3779b97f4a7c15),
        });
    }
    run_store.finalize()?;

    let child_stats = compute_gpu_subtree_child_run_stats(&child_runs);
    let root_fanout_profile =
        qcode_global_d0_root_fanout_profile(total_size, fanout, &global_d0_leaders, &child_lens);
    let mut telemetry = RbcPartitionTelemetry {
        root_fanout: root_fanout_profile.clone(),
        gpu_subtree_d0_partition_mode: "qcode-rabitq-residual-global-d0",
        gpu_subtree_d0_wall: total_start.elapsed(),
        gpu_subtree_d0_child_run_count: child_stats.count,
        gpu_subtree_d0_child_points: child_stats.total_points,
        gpu_subtree_d0_child_max_len: child_stats.max_len,
        gpu_subtree_d0_child_p50_len: child_stats.p50_len,
        gpu_subtree_d0_child_p95_len: child_stats.p95_len,
        gpu_subtree_d0_child_p99_len: child_stats.p99_len,
        gpu_subtree_qcode_staging_enabled: true,
        gpu_subtree_qcode_staging_mode: params.gpu_subtree_qcode_staging_mode.as_str(),
        gpu_subtree_qcode_d1_payload_mode: params.gpu_subtree_qcode_d1_payload_mode.as_str(),
        gpu_subtree_qcode_rabitq_residual_centroids: centroid_count,
        gpu_subtree_qcode_staging_upload_shard_rows: upload_shard_rows,
        gpu_subtree_qcode_global_d0_leaders: global_d0_leaders.len(),
        gpu_subtree_rabitq_residual_centroid_train_wall: centroid_train_wall,
        gpu_subtree_rabitq_residual_centroid_assign_wall: centroid_assign_wall,
        gpu_subtree_rabitq_residual_gpu_quantize_wall: gpu_quantize_wall,
        gpu_subtree_rabitq_residual_gpu_d0_assign_wall: gpu_d0_assign_wall,
        gpu_subtree_rabitq_residual_leader_prepare_wall: leader_prepare_wall,
        gpu_subtree_rabitq_residual_leader_payload_h2d_wall: leader_payload_h2d_wall,
        gpu_subtree_rabitq_residual_assignment_fragment_reduce_wall: fragment_reduce_wall,
        gpu_subtree_rabitq_residual_qcode_shard_write_wall: qcode_shard_write_wall,
        gpu_subtree_rabitq_residual_host_lazy_split_count: 0,
        gpu_subtree_rabitq_d0_assign_kernel_mode: d0_assign_kernel_mode,
        gpu_subtree_rabitq_d0_assign_rows: d0_assign_rows,
        gpu_subtree_rabitq_d0_assign_leaders: d0_assign_leaders,
        gpu_subtree_rabitq_d0_assign_pair_count: d0_assign_pair_count,
        gpu_subtree_rabitq_d0_assign_fanout: d0_assign_fanout,
        gpu_subtree_rabitq_d0_assign_row_tile: d0_assign_row_tile,
        gpu_subtree_rabitq_d0_assign_row_chunk: d0_assign_row_chunk,
        gpu_subtree_rabitq_d0_assign_leader_tile: d0_assign_leader_tile,
        gpu_subtree_rabitq_d0_assign_partial_r: d0_assign_partial_r,
        gpu_subtree_rabitq_d0_assign_leader_tile_count: d0_assign_leader_tile_count,
        gpu_subtree_rabitq_d0_assign_partial_bytes: d0_assign_partial_bytes,
        gpu_subtree_rabitq_d0_assign_distance_kernel_wall: d0_assign_distance_kernel_wall,
        gpu_subtree_rabitq_d0_assign_merge_kernel_wall: d0_assign_merge_kernel_wall,
        ..RbcPartitionTelemetry::default()
    };
    telemetry.root_fanout = root_fanout_profile.clone();

    let d0_plan = finalize_gpu_subtree_d0_hashes(GpuSubtreeD0Plan {
        total_points: total_size,
        adaptive_c_max,
        min_recurse_size,
        external_child_dir: external_child_dir.to_path_buf(),
        io_cfg,
        root_fanout_profile,
        child_runs,
        sq_shard_local_payloads: Vec::new(),
        sq_cluster_child_indices: Vec::new(),
        child_stats,
        rbc_telemetry: telemetry,
        d0_capacity: D0CapacityTelemetry::default(),
    })?;
    Ok((d0_plan, qcode_store))
}

struct SqGpuD0RawShard {
    row_start: usize,
    ids: Vec<u32>,
    raw_vectors: Vec<f32>,
    read_stats: PointBatchStats,
    read_wall: Duration,
}

struct SqGpuD0SidecarShard {
    row_start: usize,
    matrix: SqInt8Matrix,
}

struct SqGpuD0SidecarPipelineResult {
    report: SqWmmaSidecarCreateReport,
    runtime_sidecar: Option<SqWmmaSidecar>,
    resident: bool,
}

pub(crate) fn run_gpu_subtree_sq_staging_preflight(
    staging_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_child_dir: Option<&Path>,
) -> AnnResult<GpuSubtreeD0Plan> {
    Ok(run_gpu_subtree_sq_staging_preflight_inner(
        staging_backend,
        dataset,
        indices,
        metric,
        params,
        num_threads,
        rng,
        external_child_dir,
        None,
        None,
    )?
    .d0_plan)
}

pub(crate) fn run_gpu_subtree_sq_staging_preflight_with_sketch(
    staging_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_child_dir: Option<&Path>,
    sketch_path: &Path,
    d0_read_progress: Option<Arc<D0ReadProgress>>,
) -> AnnResult<GpuSubtreeSqStagingPreflightResult> {
    run_gpu_subtree_sq_staging_preflight_inner(
        staging_backend,
        dataset,
        indices,
        metric,
        params,
        num_threads,
        rng,
        external_child_dir,
        Some(sketch_path),
        d0_read_progress,
    )
}

fn validate_sq_staging_raw_d1_diagnostic(params: &PiPNNParams) -> AnnResult<()> {
    if !params.gpu_subtree_sq_staging_raw_d1_diagnostic {
        return Ok(());
    }
    if params.gpu_subtree_sq_staging_mode != PiPNNGpuSubtreeSqStagingMode::GpuD0 {
        return Err(AnnError::log_index_error(
            "raw-D1 diagnostic requires SQ staging mode gpu-d0".to_string(),
        ));
    }
    if params.gpu_subtree_sq_wmma_mode.is_enabled() {
        return Err(AnnError::log_index_error(
            "raw-D1 diagnostic cannot be combined with SQ-WMMA D1+ distance".to_string(),
        ));
    }
    if params.gpu_subtree_turboquant_mode.is_enabled()
        || params.gpu_subtree_turboquant_sidecar_mode.is_enabled()
        || params.gpu_subtree_turboquant_sidecar_prefix.is_some()
    {
        return Err(AnnError::log_index_error(
            "raw-D1 diagnostic cannot be combined with TurboQuant D1+ distance".to_string(),
        ));
    }
    Ok(())
}

fn join_fused_sketch_worker(
    sketch_job: std::thread::ScopedJoinHandle<'_, AnnResult<()>>,
) -> (AnnResult<()>, Duration) {
    let join_start = Instant::now();
    let result = sketch_job
        .join()
        .map_err(|_| {
            AnnError::log_index_error("SQ GPU-D0 staging fused sketch worker panicked".to_string())
        })
        .and_then(|result| result);
    (result, join_start.elapsed())
}

fn run_gpu_subtree_sq_staging_preflight_inner(
    staging_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_child_dir: Option<&Path>,
    fused_sketch_path: Option<&Path>,
    d0_read_progress: Option<Arc<D0ReadProgress>>,
) -> AnnResult<GpuSubtreeSqStagingPreflightResult> {
    validate_sq_staging_raw_d1_diagnostic(params)?;
    if metric != Metric::L2 {
        return Err(AnnError::log_index_error(
            "SQ GPU-D0 staging currently supports only L2".to_string(),
        ));
    }
    if !params.oom_enable {
        return Err(AnnError::log_index_error(
            "SQ GPU-D0 staging requires OOM mode".to_string(),
        ));
    }
    if params.gpu_subtree_qcode_staging_mode.is_enabled() {
        return Err(AnnError::log_index_error(
            "SQ GPU-D0 staging cannot be combined with qcode staging".to_string(),
        ));
    }
    let sq_shard_local_direct = matches!(
        params.gpu_subtree_sq_staging_mode,
        PiPNNGpuSubtreeSqStagingMode::GpuD0ShardLocalD1
    );
    let sq_cluster_batch_direct = matches!(
        params.gpu_subtree_sq_staging_mode,
        PiPNNGpuSubtreeSqStagingMode::GpuD0ClusterBatchD1
    );
    let sq_direct_d1 = sq_shard_local_direct || sq_cluster_batch_direct;
    if !matches!(
        params.gpu_subtree_sq_staging_mode,
        PiPNNGpuSubtreeSqStagingMode::GpuD0
            | PiPNNGpuSubtreeSqStagingMode::GpuD0ShardLocalD1
            | PiPNNGpuSubtreeSqStagingMode::GpuD0ClusterBatchD1
    ) {
        return Err(AnnError::log_index_error(format!(
            "Unsupported SQ staging mode '{}' in SQ GPU-D0 preflight",
            params.gpu_subtree_sq_staging_mode.as_str()
        )));
    }
    if params.gpu_subtree_sq_bits != SQ_INT8_DEFAULT_BITS || params.gpu_subtree_sq_native_int4 {
        return Err(AnnError::log_index_error(
            "SQ GPU-D0 staging supports only dense SQ8 sidecar layout".to_string(),
        ));
    }
    if params.gpu_subtree_sq_wmma_mode != PiPNNGpuSubtreeSqWmmaMode::Build
        && params.gpu_subtree_turboquant_mode != PiPNNGpuSubtreeTurboQuantMode::Build
        && !params.gpu_subtree_sq_staging_raw_d1_diagnostic
    {
        return Err(AnnError::log_index_error(
            "SQ GPU-D0 staging requires SQ+WMMA build mode unless TurboQuant-MSE4 build owns D1+ distance"
                .to_string(),
        ));
    }
    let sidecar_prefix = if sq_direct_d1 {
        if params.gpu_subtree_sq_wmma_sidecar_mode.is_enabled()
            || params.gpu_subtree_sq_wmma_sidecar_prefix.is_some()
        {
            return Err(AnnError::log_index_error(
                "SQ GPU-D0 direct D1 staging runs without a SQ+WMMA sidecar".to_string(),
            ));
        }
        None
    } else {
        if params.gpu_subtree_sq_wmma_sidecar_mode != PiPNNGpuSubtreeSqWmmaSidecarMode::Rebuild {
            return Err(AnnError::log_index_error(
                "SQ GPU-D0 staging requires SQ+WMMA sidecar rebuild".to_string(),
            ));
        }
        Some(
            params
                .gpu_subtree_sq_wmma_sidecar_prefix
                .as_ref()
                .ok_or_else(|| {
                    AnnError::log_index_error(
                        "SQ GPU-D0 staging requires a SQ+WMMA sidecar prefix".to_string(),
                    )
                })?,
        )
    };
    let Some(external_child_dir) = external_child_dir else {
        return Err(AnnError::log_index_error(
            "SQ GPU-D0 staging requires an external child run directory".to_string(),
        ));
    };
    let total_size = indices.len();
    if total_size == 0 {
        return Err(AnnError::log_index_error(
            "SQ GPU-D0 staging requires at least one point".to_string(),
        ));
    }
    for (expected, &point_id) in indices.iter().enumerate() {
        if point_id as usize != expected {
            return Err(AnnError::log_index_error(format!(
                "SQ GPU-D0 staging v1 requires dense global ids 0..N, got point_id={} at row={}",
                point_id, expected
            )));
        }
    }

    let total_start = Instant::now();
    let dim = dataset.dim();
    let adaptive_c_max = params.adaptive_c_max(total_size);
    let min_recurse_size = adaptive_c_max.saturating_mul(2);
    let d0_capacity_cfg = d0_capacity_config_from_params(params);
    let mut d0_capacity_telemetry = D0CapacityTelemetry::default();
    let mut d0_throughput_model = None;
    let target_root_leaders = if d0_capacity_cfg.enabled {
        let sidecar_code_row_bytes =
            if params.gpu_subtree_sq_bits == 4 && params.gpu_subtree_sq_native_int4 {
                dim.max(1).div_ceil(2)
            } else {
                dim.max(1)
            };
        let (c_gpu, throughput_decision) = plan_d0_capacity_with_throughput_model(
            total_size,
            dim,
            params,
            d0_capacity_cfg,
            params.effective_gpu_workspace_budget_bytes(),
            sidecar_code_row_bytes,
        )?;
        d0_throughput_model = throughput_decision;
        let thresholds = compute_thresholds(c_gpu, d0_capacity_cfg);
        let leader_plan =
            plan_root_leaders(total_size, params.fanout_top, thresholds, d0_capacity_cfg);
        d0_capacity_telemetry.enabled = true;
        d0_capacity_telemetry.c_gpu = thresholds.c_gpu;
        d0_capacity_telemetry.c_high = thresholds.c_high;
        d0_capacity_telemetry.c_target = thresholds.c_target;
        d0_capacity_telemetry.c_low = thresholds.c_low;
        d0_capacity_telemetry.k_capacity = leader_plan.k_capacity;
        d0_capacity_telemetry.quality_min_root_leaders = d0_capacity_cfg.quality_min_root_leaders;
        d0_capacity_telemetry.root_leader_cap = leader_plan.root_leader_cap;
        d0_capacity_telemetry.root_leader_source = leader_plan.root_leader_source;
        d0_capacity_telemetry.root_leaders_initial = leader_plan.k_initial;
        Some(leader_plan.k_initial)
    } else {
        None
    };
    let io_cfg = if params.strict_oom_io_enabled() {
        DirectIoConfig::enabled_with_alignment(4096)
    } else {
        DirectIoConfig::disabled()
    };
    let gpu_kmeans_coarse = matches!(
        params.gpu_subtree_d0_partition_mode,
        PiPNNGpuSubtreeD0PartitionMode::GpuKMeansCoarse
    );
    let leader_prepare_start = Instant::now();
    let (
        global_d0_leaders,
        leader_vectors,
        kmeans_sample_points,
        kmeans_train_wall,
        _kmeans_train_assignment_wall,
    ) = if gpu_kmeans_coarse {
        let partition_count = target_root_leaders
            .unwrap_or_else(|| params.max_leaders.max(params.fanout_top).min(total_size))
            .max(1)
            .min(total_size.max(1));
        let sample_count = tagore_d0_sample_count(
            indices.len(),
            partition_count,
            params.gpu_subtree_d0_tagore_sample_fraction,
        );
        let sample_ids = tagore_d0_sample_ids(indices, sample_count);
        let sample_vectors = read_point_ids_dense(dataset, &sample_ids)?;
        let train_result = staging_backend.train_coarse_kmeans_l2(
            GpuCoarseKMeansTrainRequest {
                sample_vectors_row_major: &sample_vectors,
                sample_ids: &sample_ids,
                partitions: partition_count,
                dim,
                iterations: params.kmeans_iterations,
            },
            params,
        )?;
        debug_assert_eq!(train_result.profile.partitions, partition_count);
        debug_assert_eq!(
            train_result.profile.sample_points,
            train_result.sample_points
        );
        debug_assert_eq!(
            train_result.profile.iterations,
            params.kmeans_iterations.max(1)
        );
        let _train_profile_diagnostics = (
            train_result.profile.assignment_backend,
            train_result.profile.center_update_wall,
        );
        let train_wall = train_result.profile.total_wall;
        let train_assignment_wall = train_result.profile.assignment_wall;
        let center_ids = (0..partition_count as u32).collect::<Vec<_>>();
        (
            center_ids,
            train_result.centers,
            train_result.sample_points,
            train_wall,
            train_assignment_wall,
        )
    } else {
        let leaders = select_root_leaders_with_target(indices, params, target_root_leaders, rng);
        let vectors = read_point_ids_dense(dataset, &leaders)?;
        (leaders, vectors, 0, Duration::ZERO, Duration::ZERO)
    };
    d0_capacity_telemetry.root_leaders_final = global_d0_leaders.len();
    if gpu_kmeans_coarse {
        d0_capacity_telemetry.root_leader_source = "gpu-kmeans-coarse";
        if d0_capacity_telemetry.root_leaders_initial == 0 {
            d0_capacity_telemetry.root_leaders_initial = global_d0_leaders.len();
        }
    }
    if global_d0_leaders.is_empty() {
        return Err(AnnError::log_index_error(
            "SQ GPU-D0 staging selected no global D0 leaders".to_string(),
        ));
    }
    let fanout = params
        .fanout_top
        .max(1)
        .min(global_d0_leaders.len())
        .min(32);
    let mut leader_prepare_wall = leader_prepare_start.elapsed();
    let upload_shard_rows = params.gpu_subtree_sq_staging_upload_shard_rows.max(1);
    let read_options = default_rbc_windowed_options(dataset, upload_shard_rows);
    let mut host_io_stats = PointBatchStats::default();
    let mut fragments = Vec::with_capacity(total_size.saturating_mul(fanout));
    let mut sq_shard_local_payloads = Vec::new();
    let mut shard_local_child_lens = Vec::new();
    let mut fragment_reduce_wall = Duration::ZERO;
    let mut sq_staging_padded_dim = 0usize;
    let mut raw_read_wall = Duration::ZERO;
    let mut raw_h2d_wall = Duration::ZERO;
    let mut gpu_quantize_wall = Duration::ZERO;
    let mut qcode_d2h_wall = Duration::ZERO;
    let mut gpu_d0_assign_wall = Duration::ZERO;
    let mut assignment_fragment_d2h_wall = Duration::ZERO;
    let mut leader_h2d_wall = Duration::ZERO;
    let mut leader_quantize_wall = Duration::ZERO;
    let mut leader_code_bytes = 0usize;
    let mut d0_assign_kernel_requested = "";
    let mut d0_assign_kernel_mode = "";
    let mut d0_assign_rows = 0usize;
    let mut d0_assign_leaders = 0usize;
    let mut d0_assign_pair_count = 0usize;
    let mut d0_assign_fanout = fanout;
    let mut d0_assign_row_tile = 0usize;
    let mut d0_assign_row_chunk = 0usize;
    let mut d0_assign_leader_tile = 0usize;
    let mut d0_assign_partial_r = 0usize;
    let mut d0_assign_leader_tile_count = 0usize;
    let mut d0_assign_partial_bytes = 0usize;
    let mut d0_assign_distance_kernel_wall = Duration::ZERO;
    let mut d0_assign_merge_kernel_wall = Duration::ZERO;
    let mut fused_sketch_join_wait_wall = Duration::ZERO;
    let mut shard_count = 0usize;
    let mut fused_sketch_builder = fused_sketch_path.map(|path| {
        ResidentSketchChunkBuilder::new_with_threads(path, total_size, dim, params, num_threads)
    });
    let resident_sidecar_pipeline =
        !params.oom_enable && matches!(params.effective_oom_io_mode(), PiPNNOomIoMode::Buffered);

    let stop_pipeline = Arc::new(AtomicBool::new(false));
    let sidecar_pipeline = std::thread::scope(|scope| -> AnnResult<_> {
        let (raw_tx, raw_rx) = mpsc::sync_channel::<AnnResult<SqGpuD0RawShard>>(1);
        let (write_tx, write_rx) = mpsc::sync_channel::<AnnResult<SqGpuD0SidecarShard>>(1);

        let reader_stop = Arc::clone(&stop_pipeline);
        let reader_progress = d0_read_progress.clone();
        let raw_reader = scope.spawn(move || {
            let mut last_ready_prefix = 0usize;
            for shard_ids in indices.chunks(upload_shard_rows) {
                if reader_stop.load(Ordering::Relaxed) {
                    if let Some(progress) = &reader_progress {
                        progress.cancel(
                            "SQ GPU-D0 raw reader stopped before consuming all dense shards",
                        );
                    }
                    return;
                }
                let row_start = shard_ids.first().copied().unwrap_or(0) as usize;
                let ids = shard_ids.to_vec();
                let read_start = Instant::now();
                let mut raw_vectors = vec![0.0f32; ids.len().saturating_mul(dim)];
                let mut read_stats = PointBatchStats::default();
                let read_result = dataset
                    .read_points_windowed_into_batch_stats(
                        &ids,
                        &mut raw_vectors,
                        &read_options,
                        &mut read_stats,
                    )
                    .map(|()| SqGpuD0RawShard {
                        row_start,
                        ids,
                        raw_vectors,
                        read_stats,
                        read_wall: read_start.elapsed(),
                    });
                let failed = read_result.is_err();
                if let Some(progress) = &reader_progress {
                    match &read_result {
                        Ok(shard) => {
                            if let Err(error) =
                                progress.record_copied_shard(shard.row_start, shard.ids.len())
                            {
                                let message = format!(
                                    "SQ GPU-D0 raw reader produced a noncontiguous shard: {error}"
                                );
                                progress.cancel(message.clone());
                                let _ = raw_tx.send(Err(AnnError::log_index_error(message)));
                                return;
                            }
                            last_ready_prefix = shard.row_start.saturating_add(shard.ids.len());
                        }
                        Err(error) => {
                            progress.cancel(format!(
                                "SQ GPU-D0 raw reader failed at row {row_start}: {error}"
                            ));
                        }
                    }
                } else if let Ok(shard) = &read_result {
                    last_ready_prefix = shard.row_start.saturating_add(shard.ids.len());
                }
                if raw_tx.send(read_result).is_err() {
                    if let Some(progress) = &reader_progress {
                        progress.cancel(
                            "SQ GPU-D0 raw reader receiver closed before accepting a shard",
                        );
                    }
                    return;
                }
                if failed {
                    return;
                }
            }
            if last_ready_prefix == total_size {
                if let Some(progress) = &reader_progress {
                    progress.complete(last_ready_prefix);
                }
            } else if let Some(progress) = &reader_progress {
                progress.cancel(format!(
                    "SQ GPU-D0 raw reader ended at prefix {last_ready_prefix} before {total_size}"
                ));
            }
        });

        let sidecar_writer = scope.spawn(move || -> AnnResult<SqGpuD0SidecarPipelineResult> {
            if sq_direct_d1 {
                while let Ok(shard_result) = write_rx.recv() {
                    let _ = shard_result?;
                }
                let mut report = SqWmmaSidecarCreateReport::default();
                report.header.rows = total_size;
                report.header.dim = dim;
                report.header.bits = SQ_INT8_DEFAULT_BITS;
                return Ok(SqGpuD0SidecarPipelineResult {
                    report,
                    runtime_sidecar: None,
                    resident: false,
                });
            }
            let sidecar_prefix = sidecar_prefix.expect("SQ GPU-D0 sidecar prefix is validated");
            if resident_sidecar_pipeline {
                let mut writer = SqWmmaResidentSidecarBuilder::create(
                    sidecar_prefix,
                    total_size,
                    dim,
                    0,
                    SQ_INT8_DEFAULT_BITS,
                )?;
                while let Ok(shard_result) = write_rx.recv() {
                    let shard = shard_result?;
                    writer.append_dense_i8_matrix(shard.row_start, &shard.matrix)?;
                }
                let artifact = writer.finish()?;
                Ok(SqGpuD0SidecarPipelineResult {
                    report: artifact.report,
                    runtime_sidecar: artifact.runtime_sidecar,
                    resident: true,
                })
            } else {
                let mut writer = SqWmmaSidecarShardWriter::create(
                    sidecar_prefix,
                    total_size,
                    dim,
                    0,
                    SQ_INT8_DEFAULT_BITS,
                )?;
                while let Ok(shard_result) = write_rx.recv() {
                    let shard = shard_result?;
                    writer.append_dense_i8_matrix(shard.row_start, &shard.matrix)?;
                }
                Ok(SqGpuD0SidecarPipelineResult {
                    report: writer.finish()?,
                    runtime_sidecar: None,
                    resident: false,
                })
            }
        });

        let mut process_result: AnnResult<()> = Ok(());
        let mut writer_send_failed = false;
        while let Ok(batch_result) = raw_rx.recv() {
            let batch = match batch_result {
                Ok(batch) => batch,
                Err(err) => {
                    stop_pipeline.store(true, Ordering::Relaxed);
                    process_result = Err(err);
                    break;
                }
            };
            raw_read_wall += batch.read_wall;
            host_io_stats.merge(&batch.read_stats);

            let run_gpu_quantize_assign = || {
                staging_backend.quantize_sq8_and_assign_global_d0(
                    super::dco_sq_int8::SqGpuD0QuantizeAssignRequest {
                        raw_vectors_row_major: &batch.raw_vectors,
                        global_ids: &batch.ids,
                        global_d0_leader_ids: &global_d0_leaders,
                        global_d0_leader_vectors_row_major: &leader_vectors,
                        leader_payload: None,
                        dim,
                        fanout_top: fanout,
                    },
                    params,
                )
            };
            let (gpu_result, sketch_result, sketch_join_wait) = if let Some(builder) =
                fused_sketch_builder.as_mut()
            {
                std::thread::scope(|sketch_scope| {
                    let row_start = batch.row_start;
                    let raw_vectors = batch.raw_vectors.as_slice();
                    let sketch_job =
                        sketch_scope.spawn(move || builder.write_raw_chunk(row_start, raw_vectors));
                    let gpu_result = run_gpu_quantize_assign();
                    let (sketch_result, sketch_join_wait) = join_fused_sketch_worker(sketch_job);
                    (gpu_result, sketch_result, sketch_join_wait)
                })
            } else {
                (run_gpu_quantize_assign(), Ok(()), Duration::ZERO)
            };
            fused_sketch_join_wait_wall += sketch_join_wait;

            if let Err(err) = sketch_result {
                stop_pipeline.store(true, Ordering::Relaxed);
                process_result = Err(err);
                break;
            }

            let result = match gpu_result {
                Ok(result) => result,
                Err(err) => {
                    stop_pipeline.store(true, Ordering::Relaxed);
                    process_result = Err(err);
                    break;
                }
            };

            raw_h2d_wall += result.profile.raw_h2d_wall;
            gpu_quantize_wall += result.profile.gpu_quantize_wall;
            qcode_d2h_wall += result.profile.qcode_d2h_wall;
            gpu_d0_assign_wall += result.profile.gpu_d0_assign_wall;
            assignment_fragment_d2h_wall += result.profile.assignment_fragment_d2h_wall;
            leader_prepare_wall += result.profile.leader_prepare_wall;
            leader_h2d_wall += result.profile.leader_h2d_wall;
            leader_quantize_wall += result.profile.leader_quantize_wall;
            leader_code_bytes = leader_code_bytes.max(result.profile.leader_code_bytes);
            if !result.profile.d0_assign_kernel_requested.is_empty() {
                d0_assign_kernel_requested = result.profile.d0_assign_kernel_requested;
            }
            if !result.profile.d0_assign_kernel_mode.is_empty() {
                d0_assign_kernel_mode = result.profile.d0_assign_kernel_mode;
            }
            d0_assign_rows += result.profile.d0_assign_rows;
            d0_assign_leaders = d0_assign_leaders.max(result.profile.d0_assign_leaders);
            d0_assign_pair_count =
                d0_assign_pair_count.saturating_add(result.profile.d0_assign_pair_count);
            d0_assign_fanout = d0_assign_fanout.max(result.profile.d0_assign_fanout);
            d0_assign_row_tile = d0_assign_row_tile.max(result.profile.d0_assign_row_tile);
            d0_assign_row_chunk = d0_assign_row_chunk.max(result.profile.d0_assign_row_chunk);
            d0_assign_leader_tile = d0_assign_leader_tile.max(result.profile.d0_assign_leader_tile);
            d0_assign_partial_r = d0_assign_partial_r.max(result.profile.d0_assign_partial_r);
            d0_assign_leader_tile_count =
                d0_assign_leader_tile_count.max(result.profile.d0_assign_leader_tile_count);
            d0_assign_partial_bytes =
                d0_assign_partial_bytes.max(result.profile.d0_assign_partial_bytes);
            d0_assign_distance_kernel_wall += result.profile.d0_assign_distance_kernel_wall;
            d0_assign_merge_kernel_wall += result.profile.d0_assign_merge_kernel_wall;

            sq_staging_padded_dim = sq_staging_padded_dim.max(result.matrix.padded_dim);
            if sq_direct_d1 {
                let reduce_start = Instant::now();
                let child_local_rows = match (|| -> AnnResult<Vec<Vec<usize>>> {
                    let mut child_local_rows = vec![Vec::new(); global_d0_leaders.len()];
                    let mut batch_fragment_counts = vec![0usize; batch.ids.len()];
                    for fragment in &result.fragments {
                        if fragment.child_id >= child_local_rows.len() {
                            return Err(AnnError::log_index_error(format!(
                                "SQ GPU-D0 shard-local fragment child {} is outside {} leaders",
                                fragment.child_id,
                                child_local_rows.len()
                            )));
                        }
                        let point = fragment.point_id as usize;
                        if point < batch.row_start || point >= batch.row_start + batch.ids.len() {
                            return Err(AnnError::log_index_error(format!(
                                "SQ GPU-D0 shard-local fragment point {} is outside shard rows [{}..{})",
                                fragment.point_id,
                                batch.row_start,
                                batch.row_start + batch.ids.len()
                            )));
                        }
                        let local_row = point - batch.row_start;
                        if batch.ids.get(local_row).copied() != Some(fragment.point_id) {
                            return Err(AnnError::log_index_error(format!(
                                "SQ GPU-D0 shard-local local row mismatch: point={} local_row={}",
                                fragment.point_id, local_row
                            )));
                        }
                        batch_fragment_counts[local_row] += 1;
                        child_local_rows[fragment.child_id].push(local_row);
                    }
                    if let Some((local_row, &count)) = batch_fragment_counts
                        .iter()
                        .enumerate()
                        .find(|&(_, &count)| count != fanout)
                    {
                        return Err(AnnError::log_index_error(format!(
                            "SQ GPU-D0 shard-local expected fanout {} fragments per point, got {} for point {}",
                            fanout, count, batch.ids[local_row]
                        )));
                    }
                    Ok(child_local_rows)
                })() {
                    Ok(child_local_rows) => child_local_rows,
                    Err(err) => {
                        stop_pipeline.store(true, Ordering::Relaxed);
                        process_result = Err(err);
                        break;
                    }
                };
                fragment_reduce_wall += reduce_start.elapsed();
                if sq_shard_local_direct {
                    shard_local_child_lens.extend(child_local_rows.iter().map(Vec::len));
                }
                sq_shard_local_payloads.push(GpuSubtreeSqShardLocalPayload {
                    row_start: batch.row_start,
                    ids: batch.ids,
                    matrix: result.matrix,
                    child_local_rows,
                });
                shard_count += 1;
                continue;
            }

            fragments.extend(result.fragments);

            if write_tx
                .send(Ok(SqGpuD0SidecarShard {
                    row_start: batch.row_start,
                    matrix: result.matrix,
                }))
                .is_err()
            {
                stop_pipeline.store(true, Ordering::Relaxed);
                writer_send_failed = true;
                process_result = Err(AnnError::log_index_error(
                    "SQ GPU-D0 staging sidecar writer terminated before accepting shard"
                        .to_string(),
                ));
                break;
            }
            shard_count += 1;
        }

        drop(raw_rx);
        drop(write_tx);

        raw_reader.join().map_err(|_| {
            AnnError::log_index_error("SQ GPU-D0 staging raw reader thread panicked".to_string())
        })?;
        let writer_result = sidecar_writer.join().map_err(|_| {
            AnnError::log_index_error(
                "SQ GPU-D0 staging sidecar writer thread panicked".to_string(),
            )
        })?;

        match (process_result, writer_result) {
            (Ok(()), writer_result) => writer_result,
            (Err(_), Err(writer_err)) if writer_send_failed => Err(writer_err),
            (Err(err), writer_result) => {
                let _ = writer_result;
                Err(err)
            }
        }
    })?;
    let SqGpuD0SidecarPipelineResult {
        report: sidecar_report,
        runtime_sidecar,
        resident: sidecar_resident,
    } = sidecar_pipeline;
    if !sq_direct_d1 {
        if let Some(sidecar) = runtime_sidecar {
            cache_sq_wmma_created_sidecar(sidecar);
        } else {
            let _validated_sidecar = SqWmmaSidecar::open_validated_with_bits(
                sidecar_prefix.expect("SQ GPU-D0 sidecar prefix is validated"),
                total_size,
                dim,
                SQ_INT8_DEFAULT_BITS,
            )?;
        }
    }

    if !sq_direct_d1 {
        let mut point_fragment_counts = vec![0usize; total_size];
        for fragment in &fragments {
            if fragment.point_id as usize >= total_size {
                return Err(AnnError::log_index_error(format!(
                    "SQ GPU-D0 staging fragment point {} is outside sidecar rows {}",
                    fragment.point_id, total_size
                )));
            }
            point_fragment_counts[fragment.point_id as usize] += 1;
        }
        if let Some((point_id, &count)) = point_fragment_counts
            .iter()
            .enumerate()
            .find(|&(_, &count)| count != fanout)
        {
            return Err(AnnError::log_index_error(format!(
                "SQ GPU-D0 staging expected fanout {} fragments per point, got {} for point {}",
                fanout, count, point_id
            )));
        }
    }

    let seed: u64 = rng.random();
    let mut child_runs = Vec::new();
    let mut sq_cluster_child_indices = Vec::new();
    let child_lens = if sq_shard_local_direct {
        for (payload_idx, payload) in sq_shard_local_payloads.iter().enumerate() {
            for (child_idx, child_rows) in payload.child_local_rows.iter().enumerate() {
                if child_rows.is_empty() {
                    continue;
                }
                let seed_key = payload_idx
                    .saturating_mul(global_d0_leaders.len())
                    .saturating_add(child_idx);
                child_runs.push(GpuSubtreeChildRun {
                    extents: Vec::new(),
                    len: child_rows.len(),
                    seed: seed ^ (seed_key as u64).wrapping_mul(0x9e3779b97f4a7c15),
                });
            }
        }
        shard_local_child_lens
    } else if sq_cluster_batch_direct {
        let mut child_lens = vec![0usize; global_d0_leaders.len()];
        for payload in &sq_shard_local_payloads {
            if payload.child_local_rows.len() != global_d0_leaders.len() {
                return Err(AnnError::log_index_error(format!(
                    "SQ GPU-D0 cluster-batch payload has {} child buckets for {} leaders",
                    payload.child_local_rows.len(),
                    global_d0_leaders.len()
                )));
            }
            for (child_idx, child_rows) in payload.child_local_rows.iter().enumerate() {
                child_lens[child_idx] = child_lens[child_idx].saturating_add(child_rows.len());
            }
        }
        for (child_idx, &len) in child_lens.iter().enumerate() {
            if len == 0 {
                continue;
            }
            sq_cluster_child_indices.push(child_idx);
            child_runs.push(GpuSubtreeChildRun {
                extents: Vec::new(),
                len,
                seed: seed ^ (child_idx as u64).wrapping_mul(0x9e3779b97f4a7c15),
            });
        }
        child_lens
    } else {
        let reduce_start = Instant::now();
        let children =
            reduce_d0_assignment_fragments(global_d0_leaders.len(), total_size, &fragments)?;
        fragment_reduce_wall += reduce_start.elapsed();
        let mut run_store = ExternalRunStore::new(external_child_dir, io_cfg);
        let mut child_lens = Vec::with_capacity(children.len());
        for (child_idx, child) in children.into_iter().enumerate() {
            child_lens.push(child.len());
            if child.is_empty() {
                continue;
            }
            let extent = write_child_run(&mut run_store, 0, &child)?;
            child_runs.push(GpuSubtreeChildRun {
                extents: vec![extent],
                len: child.len(),
                seed: seed ^ (child_idx as u64).wrapping_mul(0x9e3779b97f4a7c15),
            });
        }
        run_store.finalize()?;
        child_lens
    };

    let child_stats = compute_gpu_subtree_child_run_stats(&child_runs);
    if d0_capacity_telemetry.enabled {
        let thresholds = compute_thresholds(d0_capacity_telemetry.c_gpu, d0_capacity_cfg);
        let mut child_unique_sizes = child_lens.clone();
        super::d0_capacity::observe_child_unique_sizes(
            &mut d0_capacity_telemetry,
            thresholds,
            &mut child_unique_sizes,
        );
    }
    let root_fanout_profile = if gpu_kmeans_coarse {
        gpu_kmeans_coarse_root_fanout_profile(total_size, fanout, &global_d0_leaders, &child_lens)
    } else {
        sq_global_d0_root_fanout_profile(total_size, fanout, &global_d0_leaders, &child_lens)
    };
    let sidecar_write_wall = if sq_direct_d1 {
        Duration::ZERO
    } else {
        sidecar_report.write_wall + sidecar_report.flush_wall + sidecar_report.header_write_wall
    };
    let sidecar_resident_bytes = if !sq_direct_d1 && sidecar_resident {
        sidecar_report
            .header
            .codes_bytes
            .saturating_add(sidecar_report.header.meta_rows_bytes)
    } else {
        0
    };
    let sq_staging_padded_dim = sq_staging_padded_dim.max(sidecar_report.header.padded_dim);
    let mut telemetry = RbcPartitionTelemetry {
        root_fanout: root_fanout_profile.clone(),
        gpu_subtree_d0_partition_mode: if gpu_kmeans_coarse {
            "gpu-kmeans-coarse"
        } else {
            "sq8-gpu-d0-staging-global-d0"
        },
        gpu_subtree_d0_tagore_partitions: if gpu_kmeans_coarse {
            global_d0_leaders.len()
        } else {
            0
        },
        gpu_subtree_d0_tagore_k: if gpu_kmeans_coarse { fanout } else { 0 },
        gpu_subtree_d0_tagore_sample_points: kmeans_sample_points,
        gpu_subtree_d0_tagore_train_wall: if gpu_kmeans_coarse {
            kmeans_train_wall
        } else {
            Duration::ZERO
        },
        gpu_subtree_d0_tagore_assign_wall: if gpu_kmeans_coarse {
            gpu_d0_assign_wall
        } else {
            Duration::ZERO
        },
        gpu_subtree_d0_wall: total_start.elapsed(),
        gpu_subtree_d0_child_run_count: child_stats.count,
        gpu_subtree_d0_child_points: child_stats.total_points,
        gpu_subtree_d0_child_max_len: child_stats.max_len,
        gpu_subtree_d0_child_p50_len: child_stats.p50_len,
        gpu_subtree_d0_child_p95_len: child_stats.p95_len,
        gpu_subtree_d0_child_p99_len: child_stats.p99_len,
        gpu_subtree_host_io_stats: host_io_stats,
        gpu_subtree_sq_staging_enabled: true,
        gpu_subtree_sq_staging_mode: params.gpu_subtree_sq_staging_mode.as_str(),
        gpu_subtree_sq_staging_pipeline_mode: if sq_shard_local_direct {
            "read-compute-direct-d1"
        } else if sq_cluster_batch_direct {
            "read-compute-cluster-d1"
        } else {
            "read-compute-write-overlap"
        },
        gpu_subtree_sq_staging_upload_shard_rows: upload_shard_rows,
        gpu_subtree_sq_staging_rows: total_size,
        gpu_subtree_sq_staging_dim: dim,
        gpu_subtree_sq_staging_padded_dim: sq_staging_padded_dim,
        gpu_subtree_sq_staging_shard_count: shard_count,
        gpu_subtree_sq_staging_global_d0_leaders: global_d0_leaders.len(),
        gpu_subtree_sq_staging_raw_read_wall: raw_read_wall,
        gpu_subtree_sq_staging_raw_h2d_wall: raw_h2d_wall,
        gpu_subtree_sq_staging_gpu_quantize_wall: gpu_quantize_wall,
        gpu_subtree_sq_staging_qcode_d2h_wall: qcode_d2h_wall,
        gpu_subtree_sq_staging_gpu_d0_assign_wall: gpu_d0_assign_wall,
        gpu_subtree_sq_staging_assignment_fragment_d2h_wall: assignment_fragment_d2h_wall,
        gpu_subtree_sq_staging_leader_prepare_wall: leader_prepare_wall,
        gpu_subtree_sq_staging_leader_h2d_wall: leader_h2d_wall,
        gpu_subtree_sq_staging_leader_quantize_wall: leader_quantize_wall,
        gpu_subtree_sq_staging_leader_code_bytes: leader_code_bytes,
        gpu_subtree_sq_staging_assignment_fragment_reduce_wall: fragment_reduce_wall,
        gpu_subtree_sq_staging_sidecar_write_wall: sidecar_write_wall,
        gpu_subtree_sq_staging_sidecar_compatible: !sq_direct_d1,
        gpu_subtree_sq_staging_sidecar_source: if sq_shard_local_direct {
            "gpu-d0-shard-local-d1"
        } else if sq_cluster_batch_direct {
            "gpu-d0-cluster-batch-d1"
        } else if sidecar_resident {
            "gpu-d0-resident"
        } else {
            "gpu-d0"
        },
        gpu_subtree_sq_wmma_sidecar_resident: !sq_direct_d1 && sidecar_resident,
        gpu_subtree_sq_wmma_sidecar_resident_bytes: sidecar_resident_bytes,
        gpu_subtree_sq_wmma_sidecar_resident_rows: if !sq_direct_d1 && sidecar_resident {
            total_size
        } else {
            0
        },
        gpu_subtree_sq_d0_assign_kernel_requested: d0_assign_kernel_requested,
        gpu_subtree_sq_d0_assign_kernel_mode: d0_assign_kernel_mode,
        gpu_subtree_sq_d0_assign_rows: d0_assign_rows,
        gpu_subtree_sq_d0_assign_leaders: d0_assign_leaders,
        gpu_subtree_sq_d0_assign_pair_count: d0_assign_pair_count,
        gpu_subtree_sq_d0_assign_fanout: d0_assign_fanout,
        gpu_subtree_sq_d0_assign_row_tile: d0_assign_row_tile,
        gpu_subtree_sq_d0_assign_row_chunk: d0_assign_row_chunk,
        gpu_subtree_sq_d0_assign_leader_tile: d0_assign_leader_tile,
        gpu_subtree_sq_d0_assign_partial_r: d0_assign_partial_r,
        gpu_subtree_sq_d0_assign_leader_tile_count: d0_assign_leader_tile_count,
        gpu_subtree_sq_d0_assign_partial_bytes: d0_assign_partial_bytes,
        gpu_subtree_sq_d0_assign_distance_kernel_wall: d0_assign_distance_kernel_wall,
        gpu_subtree_sq_d0_assign_merge_kernel_wall: d0_assign_merge_kernel_wall,
        d0_capacity: d0_capacity_telemetry.clone(),
        d0_throughput_model: d0_throughput_model.clone(),
        ..RbcPartitionTelemetry::default()
    };
    telemetry.root_fanout = root_fanout_profile.clone();

    let fused_sketch_compute_wall = fused_sketch_builder
        .as_ref()
        .map(ResidentSketchChunkBuilder::compute_wall)
        .unwrap_or(Duration::ZERO);
    let fused_sketches = fused_sketch_builder
        .map(ResidentSketchChunkBuilder::finish)
        .transpose()?;

    let d0_plan = finalize_gpu_subtree_d0_hashes(GpuSubtreeD0Plan {
        total_points: total_size,
        adaptive_c_max,
        min_recurse_size,
        external_child_dir: external_child_dir.to_path_buf(),
        io_cfg,
        root_fanout_profile,
        child_runs,
        sq_shard_local_payloads,
        sq_cluster_child_indices,
        child_stats,
        rbc_telemetry: telemetry,
        d0_capacity: d0_capacity_telemetry,
    })?;
    Ok(GpuSubtreeSqStagingPreflightResult {
        d0_plan,
        fused_sketches,
        fused_sketch_compute_wall,
        fused_sketch_join_wait_wall,
    })
}

fn qcode_global_d0_root_fanout_profile(
    total_points: usize,
    fanout: usize,
    leaders: &[u32],
    child_lens: &[usize],
) -> RootFanoutProfile {
    let mut profile = RootFanoutProfile::fixed_with_forced_leaders(fanout, total_points, leaders);
    profile.policy = "qcode-rabitq-residual-global-d0".to_string();
    profile.selection_semantics = "residual_rabitq_qcode_global_d0_v1".to_string();
    profile.enabled = true;
    profile.k = leaders.len();
    profile.kept_hist = vec![0; fanout.max(1) + 1];
    profile.kept_hist[fanout] = total_points;
    profile.warmup_points_seen = total_points;
    profile.certified_points = total_points;
    profile.avg_fanout = fanout as f64;
    profile.actual_avg_fanout = fanout as f64;
    profile.sum_child_size_squared_ratio = child_sum_squared_ratio(child_lens);
    profile.largest_child_ratio = child_largest_ratio(child_lens);
    profile.child_size_cv = child_size_cv(child_lens);
    update_projected_root_fanout_bytes(&mut profile);
    profile
}

