const HOST_MATERIALIZATION_REUSE_MAX_CHILDREN: usize = 6;
const HOST_MATERIALIZATION_REUSE_MIN_FACTOR_X1000: usize = 1050;
const HOST_MATERIALIZATION_REUSE_MIN_DUPLICATE_ROWS: usize = 1;
const HOST_MATERIALIZATION_REUSE_MIN_SCRATCH_BYTES: usize = 256 * 1024 * 1024;
const HOST_MATERIALIZATION_REUSE_MAX_SCRATCH_BYTES: usize = 2 * 1024 * 1024 * 1024;

struct MaterializedUnionBatch {
    global_ids: Vec<u32>,
    vectors_row_major: Vec<f32>,
    norms: Vec<f32>,
}

struct ChildMaterializedDense {
    global_ids: Vec<u32>,
    vectors_row_major: Vec<f32>,
    norms: Vec<f32>,
}

fn gpu_subtree_host_materialization_reuse_enabled(
    subtree_backend: &dyn PiPNNComputeBackend,
    params: &PiPNNParams,
) -> bool {
    let _ = (subtree_backend, params);
    false
}

fn host_materialization_reuse_scratch_cap_bytes(params: &PiPNNParams) -> usize {
    let budget_cap = params.effective_oom_memory_budget_bytes() / 16;
    budget_cap.clamp(
        HOST_MATERIALIZATION_REUSE_MIN_SCRATCH_BYTES,
        HOST_MATERIALIZATION_REUSE_MAX_SCRATCH_BYTES,
    )
}

fn host_materialization_point_read_options(
    dataset: &dyn PointStore,
    rows: usize,
) -> WindowedGatherOptions {
    let row_bytes = dataset.dim().saturating_mul(size_of::<f32>());
    WindowedGatherOptions {
        max_gap_rows: if row_bytes <= 4096 { 1 } else { 0 },
        max_window_bytes: row_bytes
            .saturating_mul(rows.max(1))
            .min(4 * 1024 * 1024)
            .max(256 * 1024),
        alignment_bytes: 4096,
        sort_ids: true,
    }
}

fn sort_dedup_points(points: &[u32]) -> Vec<u32> {
    let mut unique = points.to_vec();
    unique.sort_unstable();
    unique.dedup();
    unique
}

fn estimate_host_materialization_group_bytes(
    union_rows: usize,
    max_child_rows: usize,
    dim: usize,
) -> usize {
    let row_values = dim.saturating_mul(size_of::<f32>());
    let union_values = union_rows.saturating_mul(row_values);
    let union_metadata = union_rows.saturating_mul(size_of::<u32>() + size_of::<f32>());
    let child_values = max_child_rows.saturating_mul(row_values);
    let child_metadata = max_child_rows.saturating_mul(size_of::<u32>() + size_of::<f32>());
    union_values
        .saturating_add(union_metadata)
        .saturating_add(child_values)
        .saturating_add(child_metadata)
}

fn child_pair_key(a: usize, b: usize) -> u64 {
    let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
    ((lo as u64) << 32) | hi as u64
}

fn plan_host_materialization_reuse_groups(child_unique_ids: &[Vec<u32>]) -> Vec<Vec<usize>> {
    let child_count = child_unique_ids.len();
    if child_count <= 1 {
        return (0..child_count).map(|idx| vec![idx]).collect();
    }

    let total_rows = child_unique_ids.iter().map(Vec::len).sum::<usize>();
    let mut point_child_entries = Vec::with_capacity(total_rows);
    for (child_idx, ids) in child_unique_ids.iter().enumerate() {
        for &point_id in ids {
            point_child_entries.push((point_id, child_idx as u32));
        }
    }
    point_child_entries.sort_unstable();

    let mut pair_counts: HashMap<u64, u32> = HashMap::new();
    let mut start = 0usize;
    while start < point_child_entries.len() {
        let point_id = point_child_entries[start].0;
        let mut end = start + 1;
        while end < point_child_entries.len() && point_child_entries[end].0 == point_id {
            end += 1;
        }
        for left in start..end {
            let left_child = point_child_entries[left].1 as usize;
            for right in left + 1..end {
                let right_child = point_child_entries[right].1 as usize;
                if left_child == right_child {
                    continue;
                }
                let key = child_pair_key(left_child, right_child);
                *pair_counts.entry(key).or_insert(0) += 1;
            }
        }
        start = end;
    }

    let mut assigned = vec![false; child_count];
    let mut groups = Vec::new();
    for seed in 0..child_count {
        if assigned[seed] {
            continue;
        }
        assigned[seed] = true;
        let mut group = vec![seed];
        while group.len() < HOST_MATERIALIZATION_REUSE_MAX_CHILDREN {
            let mut best_candidate = None::<(usize, u64)>;
            for candidate in 0..child_count {
                if assigned[candidate] {
                    continue;
                }
                let mut score = 0u64;
                for &member in &group {
                    if let Some(&overlap) = pair_counts.get(&child_pair_key(member, candidate)) {
                        score += u64::from(overlap);
                    }
                }
                if score == 0 {
                    continue;
                }
                match best_candidate {
                    None => best_candidate = Some((candidate, score)),
                    Some((best_idx, best_score)) => {
                        if score > best_score || (score == best_score && candidate < best_idx) {
                            best_candidate = Some((candidate, score));
                        }
                    }
                }
            }
            let Some((candidate, _score)) = best_candidate else {
                break;
            };
            assigned[candidate] = true;
            group.push(candidate);
        }
        group.sort_unstable();
        groups.push(group);
    }
    groups
}

fn materialize_union_batch(
    dataset: &dyn PointStore,
    global_ids: Vec<u32>,
) -> AnnResult<(MaterializedUnionBatch, PointBatchStats, Duration, Duration)> {
    let dim = dataset.dim();
    let load_start = Instant::now();
    let mut vectors_row_major = vec![0.0f32; global_ids.len().saturating_mul(dim)];
    let mut io_stats = PointBatchStats::default();
    let read_options = host_materialization_point_read_options(dataset, global_ids.len());
    let read_start = Instant::now();
    dataset.read_points_windowed_into_batch_stats(
        &global_ids,
        &mut vectors_row_major,
        &read_options,
        &mut io_stats,
    )?;
    io_stats.read_wall += read_start.elapsed();
    let load_wall = load_start.elapsed();

    let norms_start = Instant::now();
    let norms = vectors_row_major
        .chunks(dim)
        .map(|row| row.iter().map(|&v| v * v).sum())
        .collect();
    let norms_wall = norms_start.elapsed();

    Ok((
        MaterializedUnionBatch {
            global_ids,
            vectors_row_major,
            norms,
        },
        io_stats,
        load_wall,
        norms_wall,
    ))
}

fn gather_child_from_materialized_union(
    union: &MaterializedUnionBatch,
    child_global_ids: &[u32],
    dim: usize,
) -> AnnResult<ChildMaterializedDense> {
    let mut vectors_row_major = vec![0.0f32; child_global_ids.len().saturating_mul(dim)];
    let mut norms = Vec::with_capacity(child_global_ids.len());
    let mut union_pos = 0usize;
    for (child_row, &point_id) in child_global_ids.iter().enumerate() {
        while union_pos < union.global_ids.len() && union.global_ids[union_pos] < point_id {
            union_pos += 1;
        }
        if union_pos >= union.global_ids.len() || union.global_ids[union_pos] != point_id {
            return Err(AnnError::log_index_error(format!(
                "host materialization union missing child point {point_id}"
            )));
        }
        let src = union_pos.saturating_mul(dim);
        let dst = child_row.saturating_mul(dim);
        vectors_row_major[dst..dst + dim].copy_from_slice(&union.vectors_row_major[src..src + dim]);
        norms.push(union.norms[union_pos]);
    }
    Ok(ChildMaterializedDense {
        global_ids: child_global_ids.to_vec(),
        vectors_row_major,
        norms,
    })
}

fn run_gpu_subtree_d1plus_materialization_reuse(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    mut push_batch: impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    telemetry.gpu_subtree_host_materialization_reuse_enabled = true;
    let diagnostics_enabled = std::env::var_os("SHEAR_PIPNN_D1_CHILD_DIAGNOSTICS").is_some();
    let mut tasks = Vec::with_capacity(d0_plan.child_runs.len());
    for (idx, child_run) in d0_plan.child_runs.iter().cloned().enumerate() {
        let replay_start = Instant::now();
        let points = read_child_run_chain_from_path(
            &d0_plan.external_child_dir,
            d0_plan.io_cfg,
            0,
            &child_run.extents,
        )?;
        tasks.push(Some(GpuSubtreeD1ChildTask {
            child_idx: idx,
            child_run,
            points,
            replay_wall: replay_start.elapsed(),
            split_depth: 0,
        }));
    }

    let plan_start = Instant::now();
    let child_unique_ids = tasks
        .iter()
        .map(|task| {
            task.as_ref()
                .map(|task| sort_dedup_points(&task.points))
                .unwrap_or_default()
        })
        .collect::<Vec<_>>();
    let groups = plan_host_materialization_reuse_groups(&child_unique_ids);
    telemetry.gpu_subtree_host_materialization_plan_wall += plan_start.elapsed();
    let mut child_unique_ids = child_unique_ids
        .into_iter()
        .map(Some)
        .collect::<Vec<Option<Vec<u32>>>>();

    for group_indices in groups {
        let mut group_tasks = Vec::with_capacity(group_indices.len());
        for child_idx in group_indices {
            let Some(task) = tasks.get_mut(child_idx).and_then(Option::take) else {
                return Err(AnnError::log_index_error(format!(
                    "host materialization planner referenced missing D1+ child {child_idx}"
                )));
            };
            let Some(unique_ids) = child_unique_ids.get_mut(child_idx).and_then(Option::take)
            else {
                return Err(AnnError::log_index_error(format!(
                    "host materialization planner missing unique ids for D1+ child {child_idx}"
                )));
            };
            group_tasks.push((task, unique_ids));
        }
        process_gpu_subtree_d1plus_materialization_group(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            group_tasks,
            diagnostics_enabled,
            runtime_context,
            &mut push_batch,
        )?;
    }
    Ok(())
}

fn process_gpu_subtree_d1plus_materialization_group(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    tasks: Vec<(GpuSubtreeD1ChildTask, Vec<u32>)>,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    if tasks.len() < 2 {
        telemetry.gpu_subtree_host_materialization_fallback_groups += 1;
        for (task, _) in tasks {
            process_gpu_subtree_d1plus_child_with_context(
                subtree_backend,
                dataset,
                params,
                d0_plan,
                telemetry,
                task,
                diagnostics_enabled,
                runtime_context,
                push_batch,
            )?;
        }
        return Ok(());
    }

    let normalize_start = Instant::now();
    let sum_child_rows = tasks.iter().map(|(_, ids)| ids.len()).sum::<usize>();
    let mut union_global_ids = Vec::with_capacity(sum_child_rows);
    for (_, ids) in &tasks {
        union_global_ids.extend_from_slice(ids);
    }
    union_global_ids.sort_unstable();
    union_global_ids.dedup();
    let normalize_wall = normalize_start.elapsed();

    let union_rows = union_global_ids.len();
    let duplicate_rows = sum_child_rows.saturating_sub(union_rows);
    let max_child_rows = tasks.iter().map(|(_, ids)| ids.len()).max().unwrap_or(0);
    let estimated_bytes =
        estimate_host_materialization_group_bytes(union_rows, max_child_rows, dataset.dim());
    let reuse_factor_x1000 = if union_rows == 0 {
        0
    } else {
        sum_child_rows.saturating_mul(1000) / union_rows
    };

    let admission_ratio = d1plus_admission_ratio(params);
    let lazy_thresholds = d1plus_lazy_admission_thresholds(params, d0_plan);
    let all_preflight_supported = tasks.iter().all(|(task, ids)| {
        let preflight =
            d1_admission_preflight(task.points.len(), dataset.dim(), params, admission_ratio);
        preflight.supported
            && lazy_thresholds
                .map(|thresholds| ids.len() <= thresholds.c_high)
                .unwrap_or(true)
    });
    let scratch_cap = host_materialization_reuse_scratch_cap_bytes(params);
    if estimated_bytes > scratch_cap && tasks.len() > 2 {
        telemetry.gpu_subtree_host_normalize_wall += normalize_wall;
        let mut left = tasks;
        let right = left.split_off(left.len() / 2);
        process_gpu_subtree_d1plus_materialization_group(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            left,
            diagnostics_enabled,
            runtime_context,
            push_batch,
        )?;
        process_gpu_subtree_d1plus_materialization_group(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            right,
            diagnostics_enabled,
            runtime_context,
            push_batch,
        )?;
        return Ok(());
    }

    telemetry.gpu_subtree_host_normalize_wall += normalize_wall;
    telemetry.gpu_subtree_host_materialization_groups += 1;
    telemetry.gpu_subtree_host_materialization_grouped_children += tasks.len();
    telemetry.gpu_subtree_host_materialization_sum_child_rows += sum_child_rows;
    telemetry.gpu_subtree_host_materialization_union_rows += union_rows;
    telemetry.gpu_subtree_host_materialization_duplicate_rows += duplicate_rows;
    telemetry.gpu_subtree_host_materialization_peak_union_bytes = telemetry
        .gpu_subtree_host_materialization_peak_union_bytes
        .max(estimated_bytes);

    if union_rows == 0
        || duplicate_rows < HOST_MATERIALIZATION_REUSE_MIN_DUPLICATE_ROWS
        || reuse_factor_x1000 < HOST_MATERIALIZATION_REUSE_MIN_FACTOR_X1000
        || estimated_bytes > scratch_cap
        || !all_preflight_supported
    {
        telemetry.gpu_subtree_host_materialization_fallback_groups += 1;
        for (task, _) in tasks {
            process_gpu_subtree_d1plus_child_with_context(
                subtree_backend,
                dataset,
                params,
                d0_plan,
                telemetry,
                task,
                diagnostics_enabled,
                runtime_context,
                push_batch,
            )?;
        }
        return Ok(());
    }

    let (union, io_stats, union_load_wall, union_norms_wall) =
        materialize_union_batch(dataset, union_global_ids)?;
    telemetry.gpu_subtree_host_io_stats.merge(&io_stats);
    telemetry.gpu_subtree_host_point_read_wall += io_stats.read_wall;
    telemetry.gpu_subtree_host_load_vectors_wall += union_load_wall;
    telemetry.gpu_subtree_host_norms_wall += union_norms_wall;
    telemetry.gpu_subtree_host_materialization_union_load_wall += union_load_wall;
    telemetry.gpu_subtree_host_materialization_saved_read_rows_estimate += duplicate_rows;

    for (task, child_ids) in tasks.into_iter() {
        let gather_start = Instant::now();
        let child_dense = gather_child_from_materialized_union(&union, &child_ids, dataset.dim())?;
        let gather_wall = gather_start.elapsed();
        telemetry.gpu_subtree_host_materialization_child_gather_wall += gather_wall;
        process_gpu_subtree_d1plus_materialized_child(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            task,
            child_dense,
            diagnostics_enabled,
            true,
            runtime_context,
            push_batch,
        )?;
    }
    Ok(())
}

fn run_gpu_subtree_d1plus_pipeline(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    mut push_batch: impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    run_gpu_subtree_d1plus_pipeline_with_context(
        subtree_backend,
        dataset,
        params,
        d0_plan,
        telemetry,
        GpuSubtreeRuntimeContext::default(),
        &mut push_batch,
    )
}

fn record_persistent_async_d2h_profile(
    telemetry: &mut RbcPartitionTelemetry,
    profile: PersistentAsyncD2hProfile,
) {
    telemetry.gpu_subtree_persistent_async_d2h_requested |= profile.requested;
    telemetry.gpu_subtree_persistent_async_d2h_enabled |= profile.enabled;
    if telemetry
        .gpu_subtree_persistent_async_d2h_fallback_reason
        .is_empty()
        && !profile.fallback_reason.is_empty()
    {
        telemetry.gpu_subtree_persistent_async_d2h_fallback_reason =
            profile.fallback_reason.clone();
    }
    telemetry.gpu_subtree_persistent_device_output_slots = telemetry
        .gpu_subtree_persistent_device_output_slots
        .max(profile.device_output_slots);
    telemetry.gpu_subtree_persistent_device_output_slot_bytes = telemetry
        .gpu_subtree_persistent_device_output_slot_bytes
        .max(profile.device_output_slot_bytes);
    telemetry.gpu_subtree_persistent_pinned_host_slots = telemetry
        .gpu_subtree_persistent_pinned_host_slots
        .max(profile.pinned_host_slots);
    telemetry.gpu_subtree_persistent_pinned_host_slot_bytes = telemetry
        .gpu_subtree_persistent_pinned_host_slot_bytes
        .max(profile.pinned_host_slot_bytes);
    telemetry.gpu_subtree_persistent_session_init_wall += profile.session_init_wall;
    telemetry.gpu_subtree_persistent_pinned_allocation_wall += profile.pinned_allocation_wall;
    telemetry.gpu_subtree_persistent_d2h_header_copy_wall += profile.header_copy_wall;
    telemetry.gpu_subtree_persistent_d2h_payload_event_wall += profile.payload_event_wall;
    telemetry.gpu_subtree_persistent_d2h_bytes = telemetry
        .gpu_subtree_persistent_d2h_bytes
        .saturating_add(profile.d2h_bytes);
    telemetry.gpu_subtree_persistent_device_slot_wait_wall += profile.device_slot_wait_wall;
    telemetry.gpu_subtree_persistent_host_slot_wait_wall += profile.host_slot_wait_wall;
    telemetry.gpu_subtree_persistent_d2h_final_drain_wall += profile.final_drain_wall;
    telemetry.gpu_subtree_persistent_d2h_hidden_estimate_wall += profile.hidden_estimate_wall();
}

fn run_gpu_subtree_d1plus_pipeline_with_context(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    mut push_batch: impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    telemetry.gpu_subtree_child_schedule_mode = params.gpu_subtree_child_schedule_mode.as_str();
    telemetry.gpu_subtree_d1_root_partition_mode =
        params.gpu_subtree_d1_root_partition_mode.as_str();
    let diagnostics_enabled = std::env::var_os("SHEAR_PIPNN_D1_CHILD_DIAGNOSTICS").is_some();
    let (tx, rx) = mpsc::sync_channel::<SequencedGpuSubtreeD1ChildTask>(1);
    let stop_replay = Arc::new(AtomicBool::new(false));
    let d1_root_kmeans_report = Arc::new(Mutex::new(D1RootKMeansSplitReport::default()));
    let record_repeat_profile = params
        .gpu_subtree_vector_staging_mode
        .records_repeat_profile();
    let mut repeat_estimator = D1PlusRepeatEstimator::new(d0_plan.total_points);
    let async_result_scatter_config = async_result_scatter_config_from_env();
    let use_sq_wmma_sidecar_preload =
        gpu_subtree_sq_wmma_sidecar_preload_enabled(params, d0_plan, dataset.dim());
    let preload_config = use_sq_wmma_sidecar_preload
        .then(|| sq_wmma_sidecar_preload_config(params, d0_plan, dataset.dim(), runtime_context))
        .filter(|config| config.worker_count > 0);
    let mut async_result_scatter = start_async_result_scatter_if_enabled::<PendingSqWmmaChild>(
        &async_result_scatter_config,
        preload_config.is_some(),
        telemetry,
    )?;
    let persistent_async_d2h_requested =
        async_result_scatter_config.enabled && persistent_async_d2h_enabled_from_env();
    let persistent_session_init_start = Instant::now();
    let persistent_async_d2h_admission = subtree_backend.begin_persistent_async_d2h(
        PersistentAsyncD2hAdmission {
            requested: persistent_async_d2h_requested,
            sidecar_preload: preload_config.is_some(),
            ordered_scatter: async_result_scatter.is_some(),
            max_rows: persistent_async_d2h_max_rows(
                &d0_plan.child_runs,
                d1plus_lazy_admission_thresholds(params, d0_plan)
                    .map(|thresholds| thresholds.c_high),
            ),
            dim: dataset.dim(),
        },
        params,
    );
    let mut persistent_async_d2h_profile = match persistent_async_d2h_admission {
        Ok(profile) => profile,
        Err(err) => {
            if let Some(mut scatter_runtime) = async_result_scatter.take()
                && let Err(shutdown_err) = scatter_runtime.shutdown(telemetry)
            {
                tracing::error!(
                    error = %shutdown_err,
                    "gpu-subtree async result scatter shutdown failed after persistent D2H admission error"
                );
            }
            return Err(err);
        }
    };
    persistent_async_d2h_profile.session_init_wall += persistent_session_init_start.elapsed();
    tracing::info!(
        "gpu-subtree D1+ child loop start: mode=async-ordered child_runs={} total_points={} backend={:?} execution_mode={} quantized_sidecar={} persistent_async_d2h={} fallback_reason={}",
        d0_plan.child_runs.len(),
        d0_plan.total_points,
        subtree_backend.kind(),
        params.gpu_subtree_execution_mode.as_str(),
        gpu_subtree_quantized_sidecar_build_enabled(params),
        persistent_async_d2h_profile.enabled,
        persistent_async_d2h_profile.fallback_reason,
    );
    let process_result = std::thread::scope(|scope| {
        let child_runs = &d0_plan.child_runs;
        let external_child_dir = &d0_plan.external_child_dir;
        let io_cfg = d0_plan.io_cfg;
        let stop_for_worker = Arc::clone(&stop_replay);
        let report_for_worker = Arc::clone(&d1_root_kmeans_report);
        let replay_worker = scope.spawn(move || {
            let mut task_seq = 0usize;
            for (child_idx, child_run) in child_runs.iter().cloned().enumerate() {
                if stop_for_worker.load(Ordering::Relaxed) {
                    break;
                }
                let replay_start = Instant::now();
                let task_result = read_child_run_chain_from_path(
                    external_child_dir,
                    io_cfg,
                    0,
                    &child_run.extents,
                )
                .and_then(|points| {
                    let task = GpuSubtreeD1ChildTask {
                        child_idx,
                        child_run,
                        points,
                        replay_wall: replay_start.elapsed(),
                        split_depth: 0,
                    };
                    expand_d1_root_kmeans_task(subtree_backend, dataset, params, task)
                });
                match task_result {
                    Ok((tasks, report)) => {
                        report_for_worker.lock().merge(report);
                        for task in tasks {
                            if stop_for_worker.load(Ordering::Relaxed) {
                                break;
                            }
                            let sequenced = SequencedGpuSubtreeD1ChildTask {
                                seq: task_seq,
                                result: Ok(task),
                            };
                            task_seq = task_seq.saturating_add(1);
                            if tx.send(sequenced).is_err() {
                                return;
                            }
                        }
                    }
                    Err(err) => {
                        let _ = tx.send(SequencedGpuSubtreeD1ChildTask {
                            seq: task_seq,
                            result: Err(err),
                        });
                        break;
                    }
                }
            }
        });

        let mut process_result = Ok(());
        if let Some(preload_config) = preload_config {
            telemetry.gpu_subtree_sidecar_preload_workers = telemetry
                .gpu_subtree_sidecar_preload_workers
                .max(preload_config.worker_count);
            tracing::info!(
                "gpu-subtree D1+ SQ sidecar preload start: workers={} queue_capacity={} budget_bytes={} estimated_child_bytes={}",
                preload_config.worker_count,
                preload_config.queue_capacity,
                preload_config.budget_bytes,
                preload_config.estimated_child_bytes,
            );

            let (preload_tx, preload_rx) =
                mpsc::sync_channel::<SequencedSqWmmaPreloadResult>(preload_config.queue_capacity);
            let rx = Arc::new(Mutex::new(rx));
            let mut preload_workers = Vec::with_capacity(preload_config.worker_count);
            for _ in 0..preload_config.worker_count {
                let preload_tx = preload_tx.clone();
                let rx = Arc::clone(&rx);
                let stop_for_preload = Arc::clone(&stop_replay);
                preload_workers.push(scope.spawn(move || {
                    loop {
                        if stop_for_preload.load(Ordering::Relaxed) {
                            break;
                        }
                        let sequenced = {
                            let rx = rx.lock();
                            rx.recv()
                        };
                        let Ok(sequenced) = sequenced else {
                            break;
                        };
                        let seq = sequenced.seq;
                        let preload_result = match sequenced.result {
                            Ok(task) => preload_gpu_subtree_d1plus_sq_wmma_sidecar_child_batch(
                                dataset,
                                params,
                                d0_plan,
                                runtime_context,
                                task,
                            ),
                            Err(err) => Err(err),
                        };
                        let failed = preload_result.is_err();
                        if preload_tx
                            .send(SequencedSqWmmaPreloadResult {
                                seq,
                                result: preload_result,
                            })
                            .is_err()
                        {
                            break;
                        }
                        if failed {
                            stop_for_preload.store(true, Ordering::Relaxed);
                            break;
                        }
                    }
                }));
            }
            drop(preload_tx);

            let mut next_seq = 0usize;
            let mut pending = BTreeMap::<usize, SequencedSqWmmaPreloadResult>::new();
            let mut pending_bytes = 0usize;
            let mut pending_wait_wall = Duration::ZERO;
            loop {
                if let Some(sequenced) = pending.remove(&next_seq) {
                    pending_bytes = pending_bytes.saturating_sub(preload_result_bytes(&sequenced));
                    process_sq_wmma_preload_result_in_order(
                        sequenced,
                        Duration::ZERO,
                        subtree_backend,
                        dataset,
                        params,
                        d0_plan,
                        telemetry,
                        diagnostics_enabled,
                        runtime_context,
                        &mut push_batch,
                        record_repeat_profile,
                        &mut repeat_estimator,
                        &stop_replay,
                        &mut process_result,
                        &mut async_result_scatter,
                    );
                    next_seq = next_seq.saturating_add(1);
                    continue;
                }

                let wait_start = Instant::now();
                let sequenced = match preload_rx.recv() {
                    Ok(result) => result,
                    Err(_) => break,
                };
                let wait_wall = wait_start.elapsed();
                if sequenced.seq == next_seq {
                    let total_wait_wall = pending_wait_wall + wait_wall;
                    pending_wait_wall = Duration::ZERO;
                    process_sq_wmma_preload_result_in_order(
                        sequenced,
                        total_wait_wall,
                        subtree_backend,
                        dataset,
                        params,
                        d0_plan,
                        telemetry,
                        diagnostics_enabled,
                        runtime_context,
                        &mut push_batch,
                        record_repeat_profile,
                        &mut repeat_estimator,
                        &stop_replay,
                        &mut process_result,
                        &mut async_result_scatter,
                    );
                    next_seq = next_seq.saturating_add(1);
                } else if let Err(err) = sequenced.result {
                    pending_wait_wall += wait_wall;
                    telemetry.gpu_subtree_gpu_wait_for_sidecar_wall += pending_wait_wall;
                    pending_wait_wall = Duration::ZERO;
                    stop_replay.store(true, Ordering::Relaxed);
                    if process_result.is_ok() {
                        process_result = Err(err);
                    }
                } else {
                    pending_wait_wall += wait_wall;
                    pending_bytes = pending_bytes.saturating_add(preload_result_bytes(&sequenced));
                    pending.insert(sequenced.seq, sequenced);
                    telemetry.gpu_subtree_sidecar_queue_max_bytes = telemetry
                        .gpu_subtree_sidecar_queue_max_bytes
                        .max(pending_bytes);
                    telemetry.gpu_subtree_sidecar_queue_max_children = telemetry
                        .gpu_subtree_sidecar_queue_max_children
                        .max(pending.len());
                }
            }
            for preload_worker in preload_workers {
                if preload_worker.join().is_err() && process_result.is_ok() {
                    process_result = Err(AnnError::log_index_error(
                        "gpu-subtree D1+ sidecar preload worker panicked".to_string(),
                    ));
                }
            }
            if let Some(mut scatter_runtime) = async_result_scatter.take() {
                if process_result.is_ok() {
                    match scatter_runtime.finish(telemetry) {
                        Ok(completed) => {
                            for (pending, result) in completed {
                                if let Err(err) = finalize_gpu_subtree_d1plus_sq_wmma_child(
                                    telemetry,
                                    pending,
                                    result,
                                    &mut push_batch,
                                ) {
                                    process_result = Err(err);
                                    break;
                                }
                            }
                        }
                        Err(err) => process_result = Err(err),
                    }
                } else {
                    let producer_error = process_result.unwrap_err();
                    process_result =
                        Err(scatter_runtime
                            .shutdown_after_producer_error(telemetry, producer_error));
                }
            }
        } else {
            while let Ok(sequenced) = rx.recv() {
                match sequenced.result {
                    Ok(task) if process_result.is_ok() => {
                        if record_repeat_profile {
                            repeat_estimator.observe(task.child_idx, &task.points);
                        }
                        if let Err(err) = process_gpu_subtree_d1plus_child_with_context(
                            subtree_backend,
                            dataset,
                            params,
                            d0_plan,
                            telemetry,
                            task,
                            diagnostics_enabled,
                            runtime_context,
                            &mut push_batch,
                        ) {
                            stop_replay.store(true, Ordering::Relaxed);
                            process_result = Err(err);
                        }
                    }
                    Ok(_) => {}
                    Err(err) => {
                        stop_replay.store(true, Ordering::Relaxed);
                        if process_result.is_ok() {
                            process_result = Err(err);
                        }
                    }
                }
            }
        }

        if replay_worker.join().is_err() && process_result.is_ok() {
            process_result = Err(AnnError::log_index_error(
                "gpu-subtree D1+ replay worker panicked".to_string(),
            ));
        }
        d1_root_kmeans_report.lock().clone().record_into(telemetry);
        if record_repeat_profile {
            let repeat_profile = repeat_estimator.finish_profile();
            record_d1plus_natural_repeat_profile(telemetry, &repeat_profile);
        }
        if process_result.is_ok() {
            tracing::info!(
                "gpu-subtree D1+ child loop done: mode=async-ordered child_runs={} total_points={} execution_mode={}",
                d0_plan.child_runs.len(),
                d0_plan.total_points,
                params.gpu_subtree_execution_mode.as_str(),
            );
        }
        process_result
    });
    let persistent_async_d2h_finish = subtree_backend.finish_persistent_async_d2h();
    match persistent_async_d2h_finish {
        Ok(runtime_profile) => {
            persistent_async_d2h_profile.merge_runtime(runtime_profile);
            record_persistent_async_d2h_profile(telemetry, persistent_async_d2h_profile);
            process_result
        }
        Err(finish_err) => {
            record_persistent_async_d2h_profile(telemetry, persistent_async_d2h_profile);
            match process_result {
                Ok(()) => Err(finish_err),
                Err(process_err) => {
                    tracing::error!(
                        error = %finish_err,
                        "persistent async D2H shutdown also failed after D1+ producer error"
                    );
                    Err(process_err)
                }
            }
        }
    }
}

const VECTOR_STAGING_MAX_CHILDREN: usize = 4;
const VECTOR_STAGING_MAX_POINT_MEMBERS: usize = 8;
const VECTOR_STAGING_MAX_OVERLAP_PLAN_BYTES: usize = 2 * 1024 * 1024 * 1024;
const VECTOR_STAGING_MIN_FACTOR_X1000: usize = 1250;
const VECTOR_STAGING_MIN_DUPLICATE_ROWS: usize = 65_536;
const D1_ROOT_KMEANS_MAX_CENTROIDS: usize = 128;
const SQ_WMMA_SIDECAR_PRELOAD_DEFAULT_BUDGET_BYTES: usize = 256 * 1024 * 1024;
const SQ_WMMA_SIDECAR_PRELOAD_MAX_WORKERS: usize = 1;
const SQ_WMMA_SIDECAR_PRELOAD_QUEUE_CAPACITY: usize = 0;

struct GpuSubtreeD1StagingTask {
    task: GpuSubtreeD1ChildTask,
    unique_ids: Vec<u32>,
}

fn read_gpu_subtree_d1plus_staging_tasks(
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    record_repeat_profile: bool,
) -> AnnResult<Vec<GpuSubtreeD1StagingTask>> {
    let mut repeat_estimator =
        record_repeat_profile.then(|| D1PlusRepeatEstimator::new(d0_plan.total_points));
    let mut staging_tasks = Vec::with_capacity(d0_plan.child_runs.len());
    for (child_idx, child_run) in d0_plan.child_runs.iter().cloned().enumerate() {
        let replay_start = Instant::now();
        let points = read_child_run_chain_from_path(
            &d0_plan.external_child_dir,
            d0_plan.io_cfg,
            0,
            &child_run.extents,
        )?;
        let replay_wall = replay_start.elapsed();
        if let Some(estimator) = repeat_estimator.as_mut() {
            estimator.observe(child_idx, &points);
        }

        let dedup_start = Instant::now();
        let unique_ids = sort_dedup_points(&points);
        telemetry.gpu_subtree_host_vector_dedup_wall += dedup_start.elapsed();

        staging_tasks.push(GpuSubtreeD1StagingTask {
            task: GpuSubtreeD1ChildTask {
                child_idx,
                child_run,
                points,
                replay_wall,
                split_depth: 0,
            },
            unique_ids,
        });
    }
    if let Some(estimator) = repeat_estimator {
        let repeat_profile = estimator.finish_profile();
        record_d1plus_natural_repeat_profile(telemetry, &repeat_profile);
    }
    Ok(staging_tasks)
}

fn estimate_d1plus_repeat_profile_for_task_order(
    tasks: &[GpuSubtreeD1StagingTask],
    order: &[usize],
    total_points: usize,
) -> D1PlusRepeatProfile {
    let mut estimator = D1PlusRepeatEstimator::new(total_points);
    for (schedule_pos, &task_idx) in order.iter().enumerate() {
        if let Some(task) = tasks.get(task_idx) {
            estimator.observe(schedule_pos, &task.task.points);
        }
    }
    estimator.finish_profile()
}

fn record_d1plus_scheduled_repeat_profile_for_order(
    telemetry: &mut RbcPartitionTelemetry,
    tasks: &[GpuSubtreeD1StagingTask],
    order: &[usize],
    total_points: usize,
) {
    let start = Instant::now();
    let profile = estimate_d1plus_repeat_profile_for_task_order(tasks, order, total_points);
    telemetry.gpu_subtree_child_schedule_plan_wall += start.elapsed();
    record_d1plus_scheduled_rolling_profile(telemetry, &profile);
}

fn identity_child_order(child_count: usize) -> Vec<usize> {
    (0..child_count).collect()
}

fn is_identity_child_order(order: &[usize]) -> bool {
    order
        .iter()
        .copied()
        .enumerate()
        .all(|(idx, value)| idx == value)
}

fn count_overlap_edges(overlaps: &[u32], child_count: usize) -> usize {
    let mut edges = 0usize;
    for left in 0..child_count {
        for right in left + 1..child_count {
            if overlaps[left * child_count + right] > 0 {
                edges += 1;
            }
        }
    }
    edges
}

fn plan_overlap_greedy_child_order_from_matrix(
    tasks: &[GpuSubtreeD1StagingTask],
    overlaps: &[u32],
    window_children: usize,
) -> Vec<usize> {
    let child_count = tasks.len();
    if child_count <= 1 {
        return identity_child_order(child_count);
    }

    let mut total_overlap = (0..child_count)
        .map(|idx| vector_staging_total_overlap(overlaps, child_count, idx))
        .collect::<Vec<_>>();
    let mut assigned = vec![false; child_count];
    let mut order = Vec::with_capacity(child_count);
    let window = window_children.max(1);

    while order.len() < child_count {
        let recent_start = order.len().saturating_sub(window);
        let recent = &order[recent_start..];
        let mut best = None::<(usize, u64, u64, usize)>;
        for candidate in 0..child_count {
            if assigned[candidate] {
                continue;
            }
            let recent_score = recent
                .iter()
                .map(|&member| u64::from(overlaps[candidate * child_count + member]))
                .sum::<u64>();
            let fallback_score = total_overlap[candidate];
            let rows = tasks[candidate].unique_ids.len();
            match best {
                None => best = Some((candidate, recent_score, fallback_score, rows)),
                Some((best_idx, best_recent, best_total, best_rows)) => {
                    if recent_score > best_recent
                        || (recent_score == best_recent && fallback_score > best_total)
                        || (recent_score == best_recent
                            && fallback_score == best_total
                            && rows > best_rows)
                        || (recent_score == best_recent
                            && fallback_score == best_total
                            && rows == best_rows
                            && candidate < best_idx)
                    {
                        best = Some((candidate, recent_score, fallback_score, rows));
                    }
                }
            }
        }
        let Some((next, _, _, _)) = best else {
            break;
        };
        assigned[next] = true;
        order.push(next);
        total_overlap[next] = 0;
    }
    order
}

fn plan_gpu_subtree_d1plus_child_schedule_order(
    tasks: &[GpuSubtreeD1StagingTask],
    total_points: usize,
    params: &PiPNNParams,
    telemetry: &mut RbcPartitionTelemetry,
) -> Vec<usize> {
    telemetry.gpu_subtree_child_schedule_mode = params.gpu_subtree_child_schedule_mode.as_str();
    let child_count = tasks.len();
    if !matches!(
        params.gpu_subtree_child_schedule_mode,
        PiPNNGpuSubtreeChildScheduleMode::OverlapGreedy
    ) {
        return identity_child_order(child_count);
    }

    let start = Instant::now();
    let plan_bytes = estimate_vector_staging_overlap_plan_bytes(total_points, child_count);
    telemetry.gpu_subtree_child_schedule_plan_bytes = telemetry
        .gpu_subtree_child_schedule_plan_bytes
        .max(plan_bytes);
    if child_count > u16::MAX as usize
        || total_points == 0
        || plan_bytes
            > params
                .effective_gpu_subtree_vector_staging_budget_bytes()
                .max(VECTOR_STAGING_MAX_OVERLAP_PLAN_BYTES)
    {
        telemetry.gpu_subtree_child_schedule_plan_wall += start.elapsed();
        return identity_child_order(child_count);
    }

    let overlaps = build_vector_staging_pair_overlap_matrix(tasks, total_points);
    telemetry.gpu_subtree_child_schedule_overlap_edges +=
        count_overlap_edges(&overlaps, child_count);
    let order = plan_overlap_greedy_child_order_from_matrix(
        tasks,
        &overlaps,
        params.gpu_subtree_vector_staging_window_children,
    );
    if !is_identity_child_order(&order) {
        telemetry.gpu_subtree_child_schedule_reordered_children += child_count;
    }
    telemetry.gpu_subtree_child_schedule_plan_wall += start.elapsed();
    order
}

fn run_gpu_subtree_d1plus_scheduled_producer(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    mut push_batch: impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    let diagnostics_enabled = std::env::var_os("SHEAR_PIPNN_D1_CHILD_DIAGNOSTICS").is_some();
    let record_repeat_profile = params
        .gpu_subtree_vector_staging_mode
        .records_repeat_profile()
        || matches!(
            params.gpu_subtree_child_schedule_mode,
            PiPNNGpuSubtreeChildScheduleMode::OverlapGreedy
        );
    let staging_tasks =
        read_gpu_subtree_d1plus_staging_tasks(d0_plan, telemetry, record_repeat_profile)?;
    let order = plan_gpu_subtree_d1plus_child_schedule_order(
        &staging_tasks,
        d0_plan.total_points,
        params,
        telemetry,
    );
    if matches!(
        params.gpu_subtree_child_schedule_mode,
        PiPNNGpuSubtreeChildScheduleMode::OverlapGreedy
    ) && record_repeat_profile
    {
        record_d1plus_scheduled_repeat_profile_for_order(
            telemetry,
            &staging_tasks,
            &order,
            d0_plan.total_points,
        );
    }

    let mut slots = staging_tasks.into_iter().map(Some).collect::<Vec<_>>();
    for idx in order {
        let Some(staging_task) = slots.get_mut(idx).and_then(Option::take) else {
            continue;
        };
        process_gpu_subtree_d1plus_child(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            staging_task.task,
            diagnostics_enabled,
            &mut push_batch,
        )?;
    }
    Ok(())
}

fn run_gpu_subtree_d1plus_vector_staging_pipeline(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    mut push_batch: impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    telemetry.gpu_subtree_child_schedule_mode = params.gpu_subtree_child_schedule_mode.as_str();
    let diagnostics_enabled = std::env::var_os("SHEAR_PIPNN_D1_CHILD_DIAGNOSTICS").is_some();
    let mut repeat_estimator = D1PlusRepeatEstimator::new(d0_plan.total_points);

    let mut staging_tasks = Vec::with_capacity(d0_plan.child_runs.len());
    for (child_idx, child_run) in d0_plan.child_runs.iter().cloned().enumerate() {
        let replay_start = Instant::now();
        let points = read_child_run_chain_from_path(
            &d0_plan.external_child_dir,
            d0_plan.io_cfg,
            0,
            &child_run.extents,
        )?;
        let replay_wall = replay_start.elapsed();
        repeat_estimator.observe(child_idx, &points);

        let dedup_start = Instant::now();
        let unique_ids = sort_dedup_points(&points);
        telemetry.gpu_subtree_host_vector_dedup_wall += dedup_start.elapsed();

        staging_tasks.push(GpuSubtreeD1StagingTask {
            task: GpuSubtreeD1ChildTask {
                child_idx,
                child_run,
                points,
                replay_wall,
                split_depth: 0,
            },
            unique_ids,
        });
    }
    let repeat_profile = repeat_estimator.finish_profile();
    record_d1plus_natural_repeat_profile(telemetry, &repeat_profile);

    let group_indices = if matches!(
        params.gpu_subtree_child_schedule_mode,
        PiPNNGpuSubtreeChildScheduleMode::OverlapGreedy
    ) {
        plan_gpu_subtree_d1plus_child_schedule_order(
            &staging_tasks,
            d0_plan.total_points,
            params,
            telemetry,
        )
        .chunks(VECTOR_STAGING_MAX_CHILDREN)
        .map(<[usize]>::to_vec)
        .collect::<Vec<_>>()
    } else {
        plan_gpu_subtree_d1plus_vector_staging_groups(
            &staging_tasks,
            d0_plan.total_points,
            params.effective_gpu_subtree_vector_staging_budget_bytes(),
        )
    };
    let scheduled_order = group_indices
        .iter()
        .flat_map(|group| group.iter().copied())
        .collect::<Vec<_>>();
    record_d1plus_scheduled_repeat_profile_for_order(
        telemetry,
        &staging_tasks,
        &scheduled_order,
        d0_plan.total_points,
    );
    let mut staging_slots = staging_tasks.into_iter().map(Some).collect::<Vec<_>>();
    for indices in group_indices {
        let mut group = Vec::with_capacity(indices.len());
        for idx in indices {
            if let Some(task) = staging_slots.get_mut(idx).and_then(Option::take) {
                group.push(task);
            }
        }
        if group.is_empty() {
            continue;
        }
        process_gpu_subtree_d1plus_vector_staging_group(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            group,
            diagnostics_enabled,
            runtime_context,
            &mut push_batch,
        )?;
    }
    Ok(())
}

fn plan_gpu_subtree_d1plus_vector_staging_groups(
    tasks: &[GpuSubtreeD1StagingTask],
    total_points: usize,
    budget_bytes: usize,
) -> Vec<Vec<usize>> {
    if tasks.is_empty() {
        return Vec::new();
    }
    if tasks.len() <= VECTOR_STAGING_MAX_CHILDREN {
        return vec![(0..tasks.len()).collect()];
    }
    let plan_bytes = estimate_vector_staging_overlap_plan_bytes(total_points, tasks.len());
    if tasks.len() > u16::MAX as usize
        || total_points == 0
        || plan_bytes > budget_bytes.max(VECTOR_STAGING_MAX_OVERLAP_PLAN_BYTES)
    {
        return plan_sequential_vector_staging_groups(tasks.len());
    }

    let overlaps = build_vector_staging_pair_overlap_matrix(tasks, total_points);
    if overlaps.iter().all(|&overlap| overlap == 0) {
        return plan_sequential_vector_staging_groups(tasks.len());
    }

    let n = tasks.len();
    let mut assigned = vec![false; n];
    let mut seed_order = (0..n).collect::<Vec<_>>();
    seed_order.sort_unstable_by(|&left, &right| {
        let left_score = vector_staging_total_overlap(&overlaps, n, left);
        let right_score = vector_staging_total_overlap(&overlaps, n, right);
        right_score
            .cmp(&left_score)
            .then_with(|| {
                tasks[right]
                    .unique_ids
                    .len()
                    .cmp(&tasks[left].unique_ids.len())
            })
            .then_with(|| left.cmp(&right))
    });

    let mut groups = Vec::new();
    for seed in seed_order {
        if assigned[seed] {
            continue;
        }
        assigned[seed] = true;
        let mut group = vec![seed];
        while group.len() < VECTOR_STAGING_MAX_CHILDREN {
            let mut best_idx = None;
            let mut best_score = 0_u32;
            let mut best_rows = 0_usize;
            for idx in 0..n {
                if assigned[idx] {
                    continue;
                }
                let score = group
                    .iter()
                    .map(|&member| overlaps[member * n + idx])
                    .sum::<u32>();
                if score > best_score
                    || (score == best_score && score > 0 && tasks[idx].unique_ids.len() > best_rows)
                {
                    best_idx = Some(idx);
                    best_score = score;
                    best_rows = tasks[idx].unique_ids.len();
                }
            }
            let Some(idx) = best_idx else {
                break;
            };
            if best_score == 0 {
                break;
            }
            assigned[idx] = true;
            group.push(idx);
        }
        groups.push(group);
    }
    groups
}

fn plan_sequential_vector_staging_groups(child_count: usize) -> Vec<Vec<usize>> {
    (0..child_count)
        .collect::<Vec<_>>()
        .chunks(VECTOR_STAGING_MAX_CHILDREN)
        .map(<[usize]>::to_vec)
        .collect()
}

fn estimate_vector_staging_overlap_plan_bytes(total_points: usize, child_count: usize) -> usize {
    let membership_bytes = total_points.saturating_mul(
        size_of::<u8>()
            .saturating_add(VECTOR_STAGING_MAX_POINT_MEMBERS.saturating_mul(size_of::<u16>())),
    );
    let overlap_bytes = child_count
        .saturating_mul(child_count)
        .saturating_mul(size_of::<u32>());
    membership_bytes.saturating_add(overlap_bytes)
}

fn build_vector_staging_pair_overlap_matrix(
    tasks: &[GpuSubtreeD1StagingTask],
    total_points: usize,
) -> Vec<u32> {
    let child_count = tasks.len();
    let mut member_counts = vec![0_u8; total_points];
    let mut members = vec![[u16::MAX; VECTOR_STAGING_MAX_POINT_MEMBERS]; total_points];
    for (child_idx, task) in tasks.iter().enumerate() {
        let child_idx_u16 = child_idx as u16;
        for &point_id in &task.unique_ids {
            let point_idx = point_id as usize;
            if point_idx >= total_points {
                continue;
            }
            let count = member_counts[point_idx] as usize;
            if count >= VECTOR_STAGING_MAX_POINT_MEMBERS {
                continue;
            }
            members[point_idx][count] = child_idx_u16;
            member_counts[point_idx] = member_counts[point_idx].saturating_add(1);
        }
    }

    let mut overlaps = vec![0_u32; child_count.saturating_mul(child_count)];
    for (point_idx, &count_u8) in member_counts.iter().enumerate() {
        let count = count_u8 as usize;
        if count < 2 {
            continue;
        }
        for left_pos in 0..count {
            let left = members[point_idx][left_pos] as usize;
            for right_pos in left_pos + 1..count {
                let right = members[point_idx][right_pos] as usize;
                overlaps[left * child_count + right] =
                    overlaps[left * child_count + right].saturating_add(1);
                overlaps[right * child_count + left] =
                    overlaps[right * child_count + left].saturating_add(1);
            }
        }
    }
    overlaps
}

fn vector_staging_total_overlap(overlaps: &[u32], child_count: usize, child_idx: usize) -> u64 {
    overlaps[child_idx * child_count..(child_idx + 1) * child_count]
        .iter()
        .map(|&value| u64::from(value))
        .sum()
}

fn process_gpu_subtree_d1plus_vector_staging_fallback_group(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    tasks: Vec<GpuSubtreeD1StagingTask>,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    telemetry.gpu_subtree_vector_staging_fallback_groups += 1;
    for task in tasks.into_iter().map(|task| task.task) {
        process_gpu_subtree_d1plus_child_with_context(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            task,
            diagnostics_enabled,
            runtime_context,
            push_batch,
        )?;
    }
    Ok(())
}

fn process_gpu_subtree_d1plus_vector_staging_group(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    tasks: Vec<GpuSubtreeD1StagingTask>,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    if tasks.len() < 2 || !subtree_backend.supports_materialized_subtree_l2_compact_topk() {
        return process_gpu_subtree_d1plus_vector_staging_fallback_group(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            tasks,
            diagnostics_enabled,
            runtime_context,
            push_batch,
        );
    }

    let dedup_start = Instant::now();
    let sum_child_rows = tasks
        .iter()
        .map(|task| task.unique_ids.len())
        .sum::<usize>();
    let mut union_global_ids = Vec::with_capacity(sum_child_rows);
    for task in &tasks {
        union_global_ids.extend_from_slice(&task.unique_ids);
    }
    union_global_ids.sort_unstable();
    union_global_ids.dedup();
    telemetry.gpu_subtree_host_vector_dedup_wall += dedup_start.elapsed();

    let union_rows = union_global_ids.len();
    let duplicate_rows = sum_child_rows.saturating_sub(union_rows);
    let max_child_rows = tasks
        .iter()
        .map(|task| task.unique_ids.len())
        .max()
        .unwrap_or(0);
    let estimated_bytes =
        estimate_host_materialization_group_bytes(union_rows, max_child_rows, dataset.dim());
    let reuse_factor_x1000 = if union_rows == 0 {
        0
    } else {
        sum_child_rows.saturating_mul(1000) / union_rows
    };
    telemetry.gpu_subtree_vector_staging_groups += 1;
    telemetry.gpu_subtree_vector_staging_sum_child_rows += sum_child_rows;
    telemetry.gpu_subtree_vector_staging_union_rows += union_rows;
    telemetry.gpu_subtree_vector_staging_duplicate_rows += duplicate_rows;
    telemetry.gpu_subtree_vector_staging_peak_union_bytes = telemetry
        .gpu_subtree_vector_staging_peak_union_bytes
        .max(estimated_bytes);

    let admission_ratio = d1plus_admission_ratio(params);
    let lazy_thresholds = d1plus_lazy_admission_thresholds(params, d0_plan);
    let all_preflight_supported = tasks.iter().all(|task| {
        d1_admission_preflight(
            task.task.points.len(),
            dataset.dim(),
            params,
            admission_ratio,
        )
        .supported
            && lazy_thresholds
                .map(|thresholds| task.unique_ids.len() <= thresholds.c_high)
                .unwrap_or(true)
    });
    let budget_bytes = params.effective_gpu_subtree_vector_staging_budget_bytes();
    if union_rows == 0
        || duplicate_rows < VECTOR_STAGING_MIN_DUPLICATE_ROWS
        || reuse_factor_x1000 < VECTOR_STAGING_MIN_FACTOR_X1000
        || estimated_bytes > budget_bytes
        || !all_preflight_supported
    {
        return process_gpu_subtree_d1plus_vector_staging_fallback_group(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            tasks,
            diagnostics_enabled,
            runtime_context,
            push_batch,
        );
    }

    let (union, io_stats, union_load_wall, union_norms_wall) =
        materialize_union_batch(dataset, union_global_ids)?;
    telemetry.gpu_subtree_host_io_stats.merge(&io_stats);
    telemetry.gpu_subtree_host_point_read_wall += io_stats.read_wall;
    telemetry.gpu_subtree_host_load_vectors_wall += union_load_wall;
    telemetry.gpu_subtree_host_norms_wall += union_norms_wall;
    telemetry.gpu_subtree_vector_staging_saved_read_rows_estimate += duplicate_rows;

    for staging_task in tasks {
        let gather_start = Instant::now();
        let child_ids = staging_task.unique_ids;
        let child_dense = gather_child_from_materialized_union(&union, &child_ids, dataset.dim())?;
        let gather_wall = gather_start.elapsed();
        telemetry.gpu_subtree_host_vector_child_gather_wall += gather_wall;
        telemetry.gpu_subtree_vector_staging_materialized_children += 1;
        process_gpu_subtree_d1plus_materialized_child(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            staging_task.task,
            child_dense,
            diagnostics_enabled,
            false,
            runtime_context,
            push_batch,
        )?;
    }
    Ok(())
}

const D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT: usize = 32;

fn d1plus_admission_ratio(params: &PiPNNParams) -> f64 {
    if params.gpu_subtree_d1plus_lazy_split_mode == PiPNNGpuSubtreeD1PlusLazySplitMode::Off {
        1.0
    } else {
        d0_capacity_config_from_params(params)
            .high_ratio
            .clamp(0.01, 1.0)
    }
}

fn d1plus_lazy_admission_thresholds(
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
) -> Option<super::d0_capacity::D0CapacityThresholds> {
    if params.gpu_subtree_d1plus_lazy_split_mode == PiPNNGpuSubtreeD1PlusLazySplitMode::Off {
        return None;
    }
    if !params.gpu_subtree_d0_capacity_enable || !d0_plan.d0_capacity.enabled {
        return None;
    }
    if d0_plan.d0_capacity.c_high == 0 || d0_plan.d0_capacity.c_target == 0 {
        return None;
    }
    Some(super::d0_capacity::D0CapacityThresholds {
        c_gpu: d0_plan.d0_capacity.c_gpu,
        c_high: d0_plan.d0_capacity.c_high,
        c_target: d0_plan.d0_capacity.c_target,
        c_low: d0_plan.d0_capacity.c_low,
    })
}

fn gpu_subtree_sq_wmma_sidecar_preload_enabled(
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    dim: usize,
) -> bool {
    if !gpu_subtree_sq_wmma_sidecar_build_enabled(params) {
        return false;
    }
    let Some(preload_rows) = sq_wmma_sidecar_preload_estimated_child_rows(params, d0_plan, dim)
    else {
        return false;
    };
    let preflight =
        d1_admission_preflight(preload_rows, dim, params, d1plus_admission_ratio(params));
    preflight.supported
}

fn sq_wmma_sidecar_preload_estimated_child_rows(
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    dim: usize,
) -> Option<usize> {
    let max_len = d0_plan.child_stats.max_len.max(1);
    let Some(thresholds) = d1plus_lazy_admission_thresholds(params, d0_plan) else {
        return Some(max_len);
    };
    if max_len <= thresholds.c_high {
        return Some(max_len);
    }
    let split_limit = d0_capacity_config_from_params(params)
        .split_recursion_limit
        .min(D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT);
    if split_limit == 0 || thresholds.c_high == 0 {
        None
    } else {
        let estimated_rows = thresholds.c_high.min(max_len).max(1);
        let admission_ratio = d1plus_admission_ratio(params);
        if d1_admission_preflight(estimated_rows, dim, params, admission_ratio).supported {
            return Some(estimated_rows);
        }
        let workspace_budget = params.effective_gpu_workspace_budget_bytes();
        let device_budget = ((workspace_budget as f64) * admission_ratio)
            .floor()
            .max(1.0) as usize;
        let max_admissible_rows = find_max_admissible_rows(
            dim,
            params.leaf_knn,
            gpu_persistent_subtree_max_leaders_for_params(params),
            params.fanout_second.max(1),
            Some(workspace_budget),
            Some(device_budget),
            params,
        );
        if max_admissible_rows == 0 {
            None
        } else {
            Some(max_admissible_rows.min(estimated_rows).max(1))
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SqWmmaSidecarPreloadConfig {
    worker_count: usize,
    queue_capacity: usize,
    budget_bytes: usize,
    estimated_child_bytes: usize,
}

fn sq_wmma_sidecar_preload_config(
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    dim: usize,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
) -> SqWmmaSidecarPreloadConfig {
    let code_row_bytes = runtime_context
        .sq_wmma_sidecar
        .map(|sidecar| sidecar.header().code_row_bytes)
        .unwrap_or(dim.max(1));
    let estimated_child_rows = sq_wmma_sidecar_preload_estimated_child_rows(params, d0_plan, dim)
        .unwrap_or_else(|| d0_plan.child_stats.max_len.max(1));
    let estimated_child_bytes =
        estimate_sq_wmma_preloaded_child_bytes(estimated_child_rows, code_row_bytes);
    let budget_bytes = runtime_context
        .transient_pipeline_budget_bytes
        .unwrap_or(SQ_WMMA_SIDECAR_PRELOAD_DEFAULT_BUDGET_BYTES);
    let child_count = d0_plan.child_runs.len();
    let slots_by_budget = budget_bytes
        .checked_div(estimated_child_bytes.max(1))
        .unwrap_or(0)
        .min(child_count);
    let worker_count = slots_by_budget.min(SQ_WMMA_SIDECAR_PRELOAD_MAX_WORKERS);
    let queue_capacity = if worker_count == 0 {
        0
    } else {
        SQ_WMMA_SIDECAR_PRELOAD_QUEUE_CAPACITY
    };
    SqWmmaSidecarPreloadConfig {
        worker_count,
        queue_capacity,
        budget_bytes,
        estimated_child_bytes,
    }
}

fn estimate_sq_wmma_preloaded_child_bytes(rows: usize, code_row_bytes: usize) -> usize {
    rows.max(1)
        .saturating_mul(
            code_row_bytes
                .max(1)
                .saturating_add(3 * size_of::<u32>())
                .saturating_add(3 * size_of::<f32>()),
        )
        .max(1)
}

fn dedup_gpu_subtree_d1plus_task_points(
    task: &mut GpuSubtreeD1ChildTask,
    telemetry: &mut RbcPartitionTelemetry,
) {
    let before = task.points.len();
    let dedup_start = Instant::now();
    task.points.sort_unstable();
    task.points.dedup();
    telemetry.gpu_subtree_host_vector_dedup_wall += dedup_start.elapsed();
    if before != task.points.len() {
        tracing::debug!(
            "gpu-subtree D1+ child dedup: idx={} before={} after={} split_depth={}",
            task.child_idx,
            before,
            task.points.len(),
            task.split_depth,
        );
    }
}

fn split_gpu_subtree_d1plus_task(
    mut task: GpuSubtreeD1ChildTask,
) -> AnnResult<(GpuSubtreeD1ChildTask, GpuSubtreeD1ChildTask)> {
    if task.points.len() <= 1 {
        return Err(AnnError::log_index_error(format!(
            "gpu-subtree D1+ child {} cannot be split further: rows={}",
            task.child_idx,
            task.points.len()
        )));
    }
    let mid = task.points.len() / 2;
    let right_points = task.points.split_off(mid);
    let left_points = task.points;
    let base_seed = task.child_run.seed;
    let split_depth = task.split_depth.saturating_add(1);
    let left_len = left_points.len();
    let right_len = right_points.len();
    let left = GpuSubtreeD1ChildTask {
        child_idx: task.child_idx,
        child_run: GpuSubtreeChildRun {
            extents: Vec::new(),
            len: left_len,
            seed: base_seed ^ 0x9e37_79b9_7f4a_7c15,
        },
        points: left_points,
        replay_wall: Duration::ZERO,
        split_depth,
    };
    let right = GpuSubtreeD1ChildTask {
        child_idx: task.child_idx,
        child_run: GpuSubtreeChildRun {
            extents: Vec::new(),
            len: right_len,
            seed: base_seed ^ 0xbf58_476d_1ce4_e5b9,
        },
        points: right_points,
        replay_wall: Duration::ZERO,
        split_depth,
    };
    Ok((left, right))
}

fn record_d1plus_admission_split(
    telemetry: &mut RbcPartitionTelemetry,
    before_rows: usize,
    left_rows: usize,
    right_rows: usize,
) {
    record_d1plus_admission_split_max_after(telemetry, before_rows, left_rows.max(right_rows));
}

fn record_d1plus_admission_split_max_after(
    telemetry: &mut RbcPartitionTelemetry,
    before_rows: usize,
    max_after_rows: usize,
) {
    telemetry.gpu_subtree_d1plus_admission_split_count += 1;
    telemetry.gpu_subtree_d1plus_admission_split_rows += before_rows;
    telemetry.gpu_subtree_d1plus_admission_split_max_before = telemetry
        .gpu_subtree_d1plus_admission_split_max_before
        .max(before_rows);
    telemetry.gpu_subtree_d1plus_admission_split_max_after = telemetry
        .gpu_subtree_d1plus_admission_split_max_after
        .max(max_after_rows);
}

fn record_d1plus_preflight_split(
    telemetry: &mut RbcPartitionTelemetry,
    before_rows: usize,
    max_after_rows: usize,
) {
    record_d1plus_admission_split_max_after(telemetry, before_rows, max_after_rows);
    telemetry.gpu_subtree_d1plus_preflight_split_count += 1;
    telemetry.gpu_subtree_d1plus_preflight_split_rows += before_rows;
    telemetry.gpu_subtree_d1plus_preflight_split_max_before = telemetry
        .gpu_subtree_d1plus_preflight_split_max_before
        .max(before_rows);
    telemetry.gpu_subtree_d1plus_preflight_split_max_after = telemetry
        .gpu_subtree_d1plus_preflight_split_max_after
        .max(max_after_rows);
}

fn split_gpu_subtree_d1plus_task_by_sampled_leaders_for_admission(
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    child_idx: usize,
    seed: u64,
    mut points: Vec<u32>,
    thresholds: super::d0_capacity::D0CapacityThresholds,
    store: &mut ExternalRunStore,
    telemetry: &mut RbcPartitionTelemetry,
    split_depth: usize,
) -> AnnResult<Vec<GpuSubtreeD1ChildTask>> {
    let split_wall_start = Instant::now();
    points.sort_unstable();
    points.dedup();
    let initial_run = GpuSubtreeChildRun {
        extents: Vec::new(),
        len: points.len(),
        seed,
    };
    let mut queue = VecDeque::from([(points, initial_run, split_depth)]);
    let mut tasks = Vec::new();
    let split_limit = d0_capacity_config_from_params(params).split_recursion_limit;

    while let Some((points, child_run, depth)) = queue.pop_front() {
        if points.len() <= thresholds.c_high {
            tasks.push(GpuSubtreeD1ChildTask {
                child_idx,
                child_run,
                points,
                replay_wall: Duration::ZERO,
                split_depth: depth,
            });
            continue;
        }
        if depth >= split_limit || depth >= D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT {
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ lazy admission split exceeded recursion limit: child={} rows={} depth={} limit={} c_high={}",
                child_idx,
                points.len(),
                depth,
                split_limit.min(D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT),
                thresholds.c_high
            )));
        }
        let split_count = split_leader_count(points.len(), thresholds);
        let split_runs = split_unique_points_once_by_sampled_leaders_with_points(
            dataset,
            &points,
            split_count,
            child_run.seed,
            store,
        )?;
        let max_after = split_runs
            .iter()
            .map(|(_, child_points)| child_points.len())
            .max()
            .unwrap_or(0);
        record_d1plus_preflight_split(telemetry, points.len(), max_after);
        telemetry.gpu_subtree_d1plus_prevented_cpu_fallback_count += 1;
        tracing::warn!(
            "gpu-subtree D1+ child {} lazy split before admission: rows={} split_count={} produced_children={} max_after={} c_high={} c_target={} depth={}",
            child_idx,
            points.len(),
            split_count,
            split_runs.len(),
            max_after,
            thresholds.c_high,
            thresholds.c_target,
            depth,
        );
        for (run, child_points) in split_runs {
            queue.push_back((child_points, run, depth.saturating_add(1)));
        }
    }

    if tasks.len() <= 1 {
        return Err(AnnError::log_index_error(format!(
            "gpu-subtree D1+ lazy admission split made no progress: child={} c_high={}",
            child_idx, thresholds.c_high
        )));
    }

    telemetry.gpu_subtree_d1plus_lazy_split_wall += split_wall_start.elapsed();
    Ok(tasks)
}

fn split_gpu_subtree_d1plus_sq_task_by_sampled_leaders_for_admission(
    sidecar: &SqWmmaSidecar,
    params: &PiPNNParams,
    child_idx: usize,
    seed: u64,
    mut points: Vec<u32>,
    thresholds: super::d0_capacity::D0CapacityThresholds,
    store: &mut ExternalRunStore,
    telemetry: &mut RbcPartitionTelemetry,
    split_depth: usize,
) -> AnnResult<Vec<GpuSubtreeD1ChildTask>> {
    let split_wall_start = Instant::now();
    telemetry.gpu_subtree_d1plus_lazy_split_source = if sidecar.is_fully_resident() {
        "sq-resident"
    } else if sidecar.is_resident() && sidecar.uses_direct_io() {
        "sq-partial-direct"
    } else if sidecar.uses_direct_io() {
        "sq-direct"
    } else {
        "sq-file"
    };
    points.sort_unstable();
    points.dedup();
    let initial_run = GpuSubtreeChildRun {
        extents: Vec::new(),
        len: points.len(),
        seed,
    };
    let mut queue = VecDeque::from([(points, initial_run, split_depth)]);
    let mut tasks = Vec::new();
    let split_limit = d0_capacity_config_from_params(params).split_recursion_limit;

    while let Some((points, child_run, depth)) = queue.pop_front() {
        if points.len() <= thresholds.c_high {
            tasks.push(GpuSubtreeD1ChildTask {
                child_idx,
                child_run,
                points,
                replay_wall: Duration::ZERO,
                split_depth: depth,
            });
            continue;
        }
        if depth >= split_limit || depth >= D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT {
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ SQ lazy admission split exceeded recursion limit: child={} rows={} depth={} limit={} c_high={}",
                child_idx,
                points.len(),
                depth,
                split_limit.min(D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT),
                thresholds.c_high
            )));
        }
        let split_count = split_leader_count(points.len(), thresholds);
        let split_runs = split_unique_points_once_by_sq_sidecar_with_points(
            sidecar,
            params,
            &points,
            split_count,
            child_run.seed,
            store,
        )?;
        let max_after = split_runs
            .iter()
            .map(|(_, child_points)| child_points.len())
            .max()
            .unwrap_or(0);
        if max_after >= points.len() {
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ SQ lazy admission split made no progress: child={} rows={} split_count={}",
                child_idx,
                points.len(),
                split_count
            )));
        }
        record_d1plus_preflight_split(telemetry, points.len(), max_after);
        telemetry.gpu_subtree_d1plus_prevented_cpu_fallback_count += 1;
        tracing::warn!(
            "gpu-subtree D1+ child {} SQ-only lazy split before admission: rows={} split_count={} produced_children={} max_after={} c_high={} c_target={} depth={}",
            child_idx,
            points.len(),
            split_count,
            split_runs.len(),
            max_after,
            thresholds.c_high,
            thresholds.c_target,
            depth,
        );
        for (run, child_points) in split_runs {
            queue.push_back((child_points, run, depth.saturating_add(1)));
        }
    }

    if tasks.len() <= 1 {
        return Err(AnnError::log_index_error(format!(
            "gpu-subtree D1+ SQ lazy admission split made no progress: child={} c_high={}",
            child_idx, thresholds.c_high
        )));
    }

    telemetry.gpu_subtree_d1plus_lazy_split_wall += split_wall_start.elapsed();
    Ok(tasks)
}

fn process_gpu_subtree_d1plus_materialized_child(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    task: GpuSubtreeD1ChildTask,
    child_dense: ChildMaterializedDense,
    diagnostics_enabled: bool,
    record_host_materialization_stats: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    let GpuSubtreeD1ChildTask {
        child_idx,
        child_run,
        points,
        replay_wall,
        split_depth,
    } = task;
    telemetry.d2_replay_wall += replay_wall;
    telemetry.gpu_subtree_d1plus_child_replay_wall += replay_wall;
    tracing::info!(
        "gpu-subtree D1+ child start: idx={}/{} run_len={} replayed_len={} unique_len={} extents={} split_depth={} backend={:?} assignment_backend={} leaf_topk_backend={} execution_mode={} mode=host-materialized",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        child_dense.global_ids.len(),
        child_run.extents.len(),
        split_depth,
        subtree_backend.kind(),
        params.gpu_subtree_assignment_backend.as_str(),
        params.gpu_subtree_leaf_topk_backend.as_str(),
        params.gpu_subtree_execution_mode.as_str(),
    );
    if diagnostics_enabled {
        let extent_chain = child_run
            .extents
            .iter()
            .map(|extent| format!("{}:{}", extent.byte_offset, extent.len))
            .collect::<Vec<_>>()
            .join(",");
        eprintln!(
            "PiPNN D1 child start: idx={} total={} run_len={} replayed_len={} unique_len={} extents={} seed={} extent_chain=[{}] backend={:?} assignment_backend={} leaf_topk_backend={} host_materialized=true",
            child_idx,
            d0_plan.child_runs.len(),
            child_run.len,
            points.len(),
            child_dense.global_ids.len(),
            child_run.extents.len(),
            child_run.seed,
            extent_chain,
            subtree_backend.kind(),
            params.gpu_subtree_assignment_backend.as_str(),
            params.gpu_subtree_leaf_topk_backend.as_str(),
        );
    }
    let root_leader_ids = prepare_d1_root_kmeans_local_leaders(
        subtree_backend,
        dataset,
        params,
        &child_dense.global_ids,
    )?;
    let request = GpuSubtreePartitionRequest {
        point_ids: &points,
        root_leader_ids: root_leader_ids.as_deref(),
        depth: gpu_subtree_d1plus_request_depth(
            split_depth,
            params.gpu_subtree_d1_root_partition_mode,
        ),
        parent_points: d0_plan.total_points,
        adaptive_c_max: d0_plan.adaptive_c_max,
        min_recurse_size: d0_plan.min_recurse_size,
        memory_budget_bytes: d1plus_transient_memory_budget_bytes(params, runtime_context),
    };
    let materialized = GpuSubtreeMaterializedInput {
        global_ids: &child_dense.global_ids,
        vectors_row_major: &child_dense.vectors_row_major,
        norms: &child_dense.norms,
        dim: dataset.dim(),
    };
    tracing::info!(
        "gpu-subtree D1+ child backend start: idx={}/{} rows={} unique_rows={} dim={} split_depth={} execution_mode={} mode=host-materialized",
        child_idx,
        d0_plan.child_runs.len(),
        points.len(),
        child_dense.global_ids.len(),
        dataset.dim(),
        split_depth,
        params.gpu_subtree_execution_mode.as_str(),
    );
    let backend_start = Instant::now();
    let result = match subtree_backend.process_materialized_subtree_l2_compact_topk(
        &request,
        materialized,
        params,
    ) {
        Ok(result) => result,
        Err(err) if is_gpu_subtree_capacity_error(&err) => {
            let backend_wall = backend_start.elapsed();
            telemetry.gpu_subtree_d1plus_backend_wall += backend_wall;
            if record_host_materialization_stats {
                telemetry.gpu_subtree_host_materialization_backend_wall += backend_wall;
            }
            if params.gpu_subtree_d1plus_lazy_split_mode == PiPNNGpuSubtreeD1PlusLazySplitMode::Off
            {
                return Err(AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {}/{} hit a persistent capacity error while Lazy Split is disabled: run_len={} replayed_len={} unique_len={} extents={} error={err}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    child_run.len,
                    points.len(),
                    child_dense.global_ids.len(),
                    child_run.extents.len(),
                )));
            }
            if params.gpu_subtree_rabitq_plus_mode == PiPNNGpuSubtreeRabitqPlusMode::Build {
                return Err(AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {}/{} dense-i8 RabitQ+ build mode failed without CPU fallback after materialized persistent capacity error: run_len={} replayed_len={} unique_len={} extents={} error={err}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    child_run.len,
                    points.len(),
                    child_dense.global_ids.len(),
                    child_run.extents.len(),
                )));
            }
            if points.len() > 1 && split_depth < D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT {
                let before_rows = points.len();
                let split_wall_start = Instant::now();
                let (left, right) = split_gpu_subtree_d1plus_task(GpuSubtreeD1ChildTask {
                    child_idx,
                    child_run: child_run.clone(),
                    points: points.clone(),
                    replay_wall: Duration::ZERO,
                    split_depth,
                })?;
                telemetry.gpu_subtree_d1plus_lazy_split_wall += split_wall_start.elapsed();
                let left_rows = left.points.len();
                let right_rows = right.points.len();
                record_d1plus_admission_split(telemetry, before_rows, left_rows, right_rows);
                telemetry.gpu_subtree_d1plus_prevented_cpu_fallback_count += 1;
                tracing::warn!(
                    "gpu-subtree D1+ materialized child {}/{} split after persistent capacity error: rows={} left={} right={} split_depth={} extents={} error={}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    before_rows,
                    left_rows,
                    right_rows,
                    split_depth,
                    child_run.extents.len(),
                    err
                );
                process_gpu_subtree_d1plus_child_with_context(
                    subtree_backend,
                    dataset,
                    params,
                    d0_plan,
                    telemetry,
                    left,
                    diagnostics_enabled,
                    runtime_context,
                    push_batch,
                )?;
                process_gpu_subtree_d1plus_child_with_context(
                    subtree_backend,
                    dataset,
                    params,
                    d0_plan,
                    telemetry,
                    right,
                    diagnostics_enabled,
                    runtime_context,
                    push_batch,
                )?;
                return Ok(());
            }
            let fallback_result = run_gpu_subtree_cpu_recursive_compact_topk_fallback(
                dataset,
                points.clone(),
                params,
                d0_plan,
                &child_run,
            )
            .map_err(|fallback_err| {
                AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {}/{} CPU fallback failed after materialized persistent capacity error: original_error={err}; fallback_error={fallback_err}",
                    child_idx,
                    d0_plan.child_runs.len(),
                ))
            })?;
            tracing::warn!(
                "gpu-subtree D1+ child {}/{} fell back to CPU recursive compact top-k after materialized persistent capacity error: run_len={} replayed_len={} extents={} error={}",
                child_idx,
                d0_plan.child_runs.len(),
                child_run.len,
                points.len(),
                child_run.extents.len(),
                err
            );
            fallback_result
        }
        Err(err) => {
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ child {}/{} failed: run_len={} replayed_len={} unique_len={} extents={} backend={:?} assignment_backend={} leaf_topk_backend={} host_materialized=true: {err}",
                child_idx,
                d0_plan.child_runs.len(),
                child_run.len,
                points.len(),
                child_dense.global_ids.len(),
                child_run.extents.len(),
                subtree_backend.kind(),
                params.gpu_subtree_assignment_backend.as_str(),
                params.gpu_subtree_leaf_topk_backend.as_str(),
            )));
        }
    };
    let backend_wall = backend_start.elapsed();
    telemetry.gpu_subtree_d1plus_backend_wall += backend_wall;
    if record_host_materialization_stats {
        telemetry.gpu_subtree_host_materialization_backend_wall += backend_wall;
    }
    let validate_start = Instant::now();
    let compact_rows = validate_compact_topk_child_output(&points, &result.compact_batches)?;
    telemetry.gpu_subtree_d1plus_validate_wall += validate_start.elapsed();
    tracing::info!(
        "gpu-subtree D1+ child done: idx={}/{} run_len={} replayed_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} backend_ms={} partition_kernel_ms={} topk_kernel_ms={} persistent_total_ms={} leaf_pushes={} topk_pops={} level_rounds={} overflow_flags={} mode=host-materialized",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        result.compact_batches.len(),
        compact_rows,
        result.leaf_count,
        result.assignment_passes,
        result.max_active_points,
        backend_wall.as_millis(),
        result.profile.partition_only_kernel_event_wall.as_millis(),
        result.profile.resident_topk_kernel_event_wall.as_millis(),
        result.profile.persistent_total_wall.as_millis(),
        result.profile.persistent_leaf_pushes,
        result.profile.persistent_topk_pops,
        result.profile.persistent_partition_level_rounds,
        result.profile.persistent_queue_overflow_flags,
    );
    if diagnostics_enabled {
        eprintln!(
            "PiPNN D1 child done: idx={} run_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} host_materialized=true",
            child_idx,
            child_run.len,
            result.compact_batches.len(),
            compact_rows,
            result.leaf_count,
            result.assignment_passes,
            result.max_active_points,
        );
    }
    if record_host_materialization_stats {
        telemetry.gpu_subtree_host_materialization_materialized_children += 1;
    }
    telemetry.gpu_subtree_compact_success_count += 1;
    telemetry.gpu_subtree_compact_success_points += points.len();
    telemetry.gpu_subtree_compact_leaf_count += result.leaf_count;
    telemetry.gpu_subtree_compact_assignment_passes += result.assignment_passes;
    telemetry.gpu_subtree_compact_max_points = telemetry
        .gpu_subtree_compact_max_points
        .max(result.max_active_points.max(points.len()));
    telemetry.gpu_subtree_compact_batches += result.compact_batches.len();
    telemetry.gpu_subtree_compact_rows += compact_rows;
    let merge_profile_start = Instant::now();
    merge_gpu_subtree_topk_profile(telemetry, &result.profile);
    telemetry.gpu_subtree_d1plus_merge_profile_wall += merge_profile_start.elapsed();
    let push_batch_start = Instant::now();
    for batch in result.compact_batches {
        push_batch(batch)?;
    }
    telemetry.gpu_subtree_d1plus_push_batch_wall += push_batch_start.elapsed();
    Ok(())
}

fn process_gpu_subtree_d1plus_quantized_sidecar_child(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    task: GpuSubtreeD1ChildTask,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    let GpuSubtreeD1ChildTask {
        child_idx,
        child_run,
        points,
        replay_wall,
        split_depth,
    } = task;
    telemetry.d2_replay_wall += replay_wall;
    telemetry.gpu_subtree_d1plus_child_replay_wall += replay_wall;
    if !gpu_subtree_rabitq_plus_sidecar_build_enabled(params) {
        return Err(AnnError::log_index_error(
            "dense-i8 RabitQ+ build mode requires a prebuilt sidecar; raw f32 resident materialization is disabled"
                .to_string(),
        ));
    }
    tracing::info!(
        "gpu-subtree D1+ child start: idx={}/{} run_len={} replayed_len={} extents={} split_depth={} backend={:?} execution_mode={} mode=rabitq-plus-sidecar",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        child_run.extents.len(),
        split_depth,
        subtree_backend.kind(),
        params.gpu_subtree_execution_mode.as_str(),
    );
    let mut unique_points = 0usize;
    if diagnostics_enabled {
        let mut sorted = points.clone();
        sorted.sort_unstable();
        sorted.dedup();
        unique_points = sorted.len();
        eprintln!(
            "PiPNN D1 child start: idx={} total={} run_len={} replayed_len={} unique_len={} extents={} backend={:?} rabitq_plus_sidecar=true",
            child_idx,
            d0_plan.child_runs.len(),
            child_run.len,
            points.len(),
            unique_points,
            child_run.extents.len(),
            subtree_backend.kind(),
        );
    }
    let admission_ratio = d1plus_admission_ratio(params);
    let preflight = d1_admission_preflight(points.len(), dataset.dim(), params, admission_ratio);
    if !preflight.supported {
        return Err(AnnError::log_index_error(format!(
            "gpu-subtree D1+ child {}/{} dense-i8 RabitQ+ sidecar build exceeds admission budget and will not be split because splitting a child changes the candidate universe: run_len={} replayed_len={} extents={} required_bytes={} budget_bytes={}",
            child_idx,
            d0_plan.child_runs.len(),
            child_run.len,
            points.len(),
            child_run.extents.len(),
            preflight.required_bytes,
            preflight.budget_bytes,
        )));
    }
    let normalize_start = Instant::now();
    let global_ids = sort_dedup_points(&points);
    let host_normalize_wall = normalize_start.elapsed();
    let file_sidecar;
    let sidecar = if let Some(sidecar) = runtime_context.rabitq_plus_resident_sidecar {
        sidecar
    } else {
        let prefix = params
            .gpu_subtree_rabitq_plus_sidecar_prefix
            .as_ref()
            .ok_or_else(|| {
                AnnError::log_index_error(
                    "dense-i8 RabitQ+ build mode requires a sidecar prefix".to_string(),
                )
            })?;
        file_sidecar = RabitqPlusSidecar::open_validated(
            prefix,
            d0_plan.total_points,
            dataset.dim(),
            params.gpu_subtree_rabitq_plus_bits,
            params.gpu_subtree_rabitq_plus_rotator,
            params.gpu_subtree_rabitq_plus_seed,
        )?;
        &file_sidecar
    };
    let gathered = sidecar.gather(&global_ids)?;
    tracing::info!(
        "gpu-subtree D1+ child backend start: idx={}/{} rows={} unique_rows={} dim={} padded_dim={} bits={} sidecar_gather_ms={} sidecar_resident={} normalize_ms={} admission_required_bytes={} admission_budget_bytes={} split_depth={} execution_mode={} mode=rabitq-plus-sidecar",
        child_idx,
        d0_plan.child_runs.len(),
        points.len(),
        gathered.global_ids.len(),
        gathered.dim,
        gathered.padded_dim,
        gathered.bits,
        gathered.gather_wall.as_millis(),
        gathered.resident_rows > 0,
        host_normalize_wall.as_millis(),
        preflight.required_bytes,
        preflight.budget_bytes,
        split_depth,
        params.gpu_subtree_execution_mode.as_str(),
    );
    if diagnostics_enabled {
        eprintln!(
            "PiPNN D1 child backend start: idx={} rows={} unique_rows={} dim={} padded_dim={} bits={} sidecar_gather_ms={} sidecar_resident={} normalize_ms={} admission_supported={} admission_required_bytes={} admission_budget_bytes={} split_depth={} rabitq_plus_sidecar=true",
            child_idx,
            points.len(),
            gathered.global_ids.len(),
            gathered.dim,
            gathered.padded_dim,
            gathered.bits,
            gathered.gather_wall.as_millis(),
            gathered.resident_rows > 0,
            host_normalize_wall.as_millis(),
            preflight.supported,
            preflight.required_bytes,
            preflight.budget_bytes,
            split_depth,
        );
    }
    let root_leader_ids = prepare_d1_root_kmeans_local_leaders(
        subtree_backend,
        dataset,
        params,
        &gathered.global_ids,
    )?;
    let request = GpuSubtreePartitionRequest {
        point_ids: &points,
        root_leader_ids: root_leader_ids.as_deref(),
        depth: gpu_subtree_d1plus_request_depth(
            split_depth,
            params.gpu_subtree_d1_root_partition_mode,
        ),
        parent_points: d0_plan.total_points,
        adaptive_c_max: d0_plan.adaptive_c_max,
        min_recurse_size: d0_plan.min_recurse_size,
        memory_budget_bytes: d1plus_transient_memory_budget_bytes(params, runtime_context),
    };
    let quantized = GpuSubtreeQuantizedInput {
        distance_kind: GpuSubtreeQuantizedDistanceKind::RabitqPlus,
        global_ids: &gathered.global_ids,
        codes: &gathered.codes,
        deltas: &gathered.deltas,
        code_sums: &gathered.code_sums,
        norms: &gathered.norms,
        dim: gathered.dim,
        padded_dim: gathered.padded_dim,
        code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
        code_row_bytes: gathered.padded_dim,
        bits: gathered.bits,
    };
    let backend_start = Instant::now();
    let mut result = match subtree_backend
        .process_quantized_subtree_l2_compact_topk(&request, quantized, params)
    {
        Ok(result) => result,
        Err(err) if is_gpu_subtree_capacity_error(&err) => {
            telemetry.gpu_subtree_d1plus_backend_wall += backend_start.elapsed();
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ child {}/{} dense-i8 RabitQ+ sidecar build failed without CPU fallback or child split after persistent capacity error: run_len={} replayed_len={} extents={} error={err}",
                child_idx,
                d0_plan.child_runs.len(),
                child_run.len,
                points.len(),
                child_run.extents.len(),
            )));
        }
        Err(err) => {
            let unique_len = if diagnostics_enabled {
                unique_points
            } else {
                global_ids.len()
            };
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ child {}/{} dense-i8 RabitQ+ sidecar build failed: run_len={} replayed_len={} unique_len={} extents={} backend={:?}: {err}",
                child_idx,
                d0_plan.child_runs.len(),
                child_run.len,
                points.len(),
                unique_len,
                child_run.extents.len(),
                subtree_backend.kind(),
            )));
        }
    };
    let backend_wall = backend_start.elapsed();
    telemetry.gpu_subtree_d1plus_backend_wall += backend_wall;
    result.profile.host_normalize_wall += host_normalize_wall;
    result.profile.rabitq_plus_read_wall += gathered.gather_wall;
    result.profile.rabitq_plus_sidecar_rows += gathered.global_ids.len();
    result.profile.rabitq_plus_sidecar_codes_bytes += gathered.codes.len();
    result.profile.rabitq_plus_sidecar_meta_bytes += gathered
        .global_ids
        .len()
        .saturating_mul(3)
        .saturating_mul(size_of::<f32>());
    result.profile.rabitq_plus_sidecar_gather_wall += gathered.gather_wall;
    result.profile.rabitq_plus_sidecar_resident |= gathered.resident_rows > 0;
    result.profile.rabitq_plus_sidecar_resident_rows += gathered.resident_rows;
    result.profile.rabitq_plus_sidecar_file_rows += gathered.file_rows;
    result.profile.rabitq_plus_sidecar_resident_gather_wall += gathered.resident_gather_wall;
    result.profile.rabitq_plus_sidecar_file_gather_wall += gathered.file_gather_wall;
    let validate_start = Instant::now();
    let compact_rows = validate_compact_topk_child_output(&points, &result.compact_batches)?;
    telemetry.gpu_subtree_d1plus_validate_wall += validate_start.elapsed();
    tracing::info!(
        "gpu-subtree D1+ child done: idx={}/{} run_len={} replayed_len={} unique_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} backend_ms={} partition_kernel_ms={} topk_kernel_ms={} persistent_total_ms={} leaf_pushes={} topk_pops={} level_rounds={} overflow_flags={} mode=rabitq-plus-sidecar",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        gathered.global_ids.len(),
        result.compact_batches.len(),
        compact_rows,
        result.leaf_count,
        result.assignment_passes,
        result.max_active_points,
        backend_wall.as_millis(),
        result.profile.partition_only_kernel_event_wall.as_millis(),
        result.profile.resident_topk_kernel_event_wall.as_millis(),
        result.profile.persistent_total_wall.as_millis(),
        result.profile.persistent_leaf_pushes,
        result.profile.persistent_topk_pops,
        result.profile.persistent_partition_level_rounds,
        result.profile.persistent_queue_overflow_flags,
    );
    if diagnostics_enabled {
        eprintln!(
            "PiPNN D1 child done: idx={} run_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} kernel_ms={} persistent_total_ms={} overflow_flags={} leaf_dco_tiles_started={} leaf_dco_tiles_done={} leaf_dco_prefilter_tiles={} leaf_dco_partial_tiles={} leaf_dco_full_exact_tiles={} leaf_dco_rows={} leaf_dco_prefilter_pairs={} leaf_dco_survivor_pairs={} leaf_dco_approx_output_pairs={} leaf_dco_exact_fallback_rows={} rabitq_plus_sidecar=true",
            child_idx,
            child_run.len,
            result.compact_batches.len(),
            compact_rows,
            result.leaf_count,
            result.assignment_passes,
            result.max_active_points,
            result.profile.persistent_kernel_event_wall.as_millis(),
            result.profile.persistent_total_wall.as_millis(),
            result.profile.persistent_queue_overflow_flags,
            result.profile.leaf_dco.tile_started,
            result.profile.leaf_dco.tile_done,
            result.profile.leaf_dco.tile_prefilter_tiles,
            result.profile.leaf_dco.tile_partial_tiles,
            result.profile.leaf_dco.tile_full_exact_tiles,
            result.profile.leaf_dco.rows,
            result.profile.leaf_dco.prefilter_pairs,
            result.profile.leaf_dco.survivor_pairs,
            result.profile.leaf_dco.approx_output_pairs,
            result.profile.leaf_dco.exact_fallback_rows,
        );
    }
    telemetry.gpu_subtree_compact_success_count += 1;
    telemetry.gpu_subtree_compact_success_points += points.len();
    telemetry.gpu_subtree_compact_leaf_count += result.leaf_count;
    telemetry.gpu_subtree_compact_assignment_passes += result.assignment_passes;
    telemetry.gpu_subtree_compact_max_points = telemetry
        .gpu_subtree_compact_max_points
        .max(result.max_active_points.max(points.len()));
    telemetry.gpu_subtree_compact_batches += result.compact_batches.len();
    telemetry.gpu_subtree_compact_rows += compact_rows;
    let merge_profile_start = Instant::now();
    merge_gpu_subtree_topk_profile(telemetry, &result.profile);
    telemetry.gpu_subtree_d1plus_merge_profile_wall += merge_profile_start.elapsed();
    let push_batch_start = Instant::now();
    for batch in result.compact_batches {
        push_batch(batch)?;
    }
    telemetry.gpu_subtree_d1plus_push_batch_wall += push_batch_start.elapsed();
    Ok(())
}

struct GpuSubtreeD1SqWmmaGatheredTask {
    task: GpuSubtreeD1ChildTask,
    global_ids: Vec<u32>,
    host_normalize_wall: Duration,
    gathered: SqWmmaGatheredInput,
}

struct GpuSubtreeD1SqWmmaPreloadedTask {
    gathered_task: GpuSubtreeD1SqWmmaGatheredTask,
    dedup_wall: Duration,
    queue_bytes: usize,
}

struct SqWmmaSidecarProfileDelta {
    host_normalize_wall: Duration,
    rows: usize,
    codes_bytes: usize,
    meta_bytes: usize,
    gather_wall: Duration,
    resident: bool,
    resident_rows: usize,
    file_rows: usize,
    resident_gather_wall: Duration,
    file_gather_wall: Duration,
}

struct PendingSqWmmaChild {
    child_idx: usize,
    child_count: usize,
    child_run: GpuSubtreeChildRun,
    points: Vec<u32>,
    unique_len: usize,
    diagnostics_enabled: bool,
    backend_wall: Duration,
    sidecar: SqWmmaSidecarProfileDelta,
}

impl PendingSqWmmaChild {
    fn estimated_host_bytes(&self) -> usize {
        self.points
            .capacity()
            .saturating_mul(size_of::<u32>())
            .saturating_add(
                self.child_run
                    .extents
                    .capacity()
                    .saturating_mul(size_of::<RunExtent>()),
            )
    }
}

struct SubmittedSqWmmaChild {
    pending: PendingSqWmmaChild,
    submission: GpuSubtreeTopKSubmission,
}

struct SequencedDeferredGpuSubtreeScatter {
    seq: usize,
    deferred: DeferredGpuSubtreeTopK,
}

struct SequencedGpuSubtreeScatterCompletion {
    seq: usize,
    result: AnnResult<GpuSubtreeTopKResult>,
    worker_wall: Duration,
}

struct PendingGpuSubtreeScatterContext<C> {
    seq: usize,
    context: C,
    context_bytes: usize,
    host_bytes: usize,
}

struct AsyncResultScatterRuntime<C> {
    work_tx: Option<mpsc::SyncSender<SequencedDeferredGpuSubtreeScatter>>,
    completion_rx: mpsc::Receiver<SequencedGpuSubtreeScatterCompletion>,
    worker: Option<std::thread::JoinHandle<()>>,
    pending: VecDeque<PendingGpuSubtreeScatterContext<C>>,
    next_seq: usize,
}

fn start_async_result_scatter_if_enabled<C>(
    config: &AsyncResultScatterConfig,
    preload_present: bool,
    telemetry: &mut RbcPartitionTelemetry,
) -> AnnResult<Option<AsyncResultScatterRuntime<C>>> {
    telemetry.gpu_subtree_async_result_scatter_requested = config.requested.clone();
    if !config.enabled || !preload_present {
        return Ok(None);
    }
    let runtime = AsyncResultScatterRuntime::<C>::start()?;
    telemetry.gpu_subtree_async_result_scatter_enabled = true;
    Ok(Some(runtime))
}

fn async_result_scatter_sequence_error(seq: usize, error: impl std::fmt::Display) -> AnnError {
    AnnError::log_index_error(format!(
        "gpu-subtree async result scatter sequence {seq}: {error}"
    ))
}

impl<C> AsyncResultScatterRuntime<C> {
    fn start() -> AnnResult<Self> {
        let (work_tx, work_rx) = mpsc::sync_channel::<SequencedDeferredGpuSubtreeScatter>(
            ASYNC_RESULT_SCATTER_MAX_INFLIGHT,
        );
        let (completion_tx, completion_rx) = mpsc::sync_channel::<
            SequencedGpuSubtreeScatterCompletion,
        >(ASYNC_RESULT_SCATTER_MAX_INFLIGHT);
        let worker = std::thread::Builder::new()
            .name("pipnn-result-scatter".to_string())
            .spawn(move || {
                while let Ok(work) = work_rx.recv() {
                    let worker_start = Instant::now();
                    let result = work.deferred.scatter.finish();
                    let failed = result.is_err();
                    if completion_tx
                        .send(SequencedGpuSubtreeScatterCompletion {
                            seq: work.seq,
                            result,
                            worker_wall: worker_start.elapsed(),
                        })
                        .is_err()
                    {
                        break;
                    }
                    if failed {
                        break;
                    }
                }
            })
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "failed to start gpu-subtree async result scatter worker: {err}"
                ))
            })?;
        Ok(Self {
            work_tx: Some(work_tx),
            completion_rx,
            worker: Some(worker),
            pending: VecDeque::with_capacity(ASYNC_RESULT_SCATTER_MAX_INFLIGHT),
            next_seq: 0,
        })
    }

    fn accept(
        &mut self,
        context: C,
        context_bytes: usize,
        submission: GpuSubtreeTopKSubmission,
        telemetry: &mut RbcPartitionTelemetry,
    ) -> AnnResult<Vec<(C, GpuSubtreeTopKResult)>> {
        let mut completed = Vec::with_capacity(ASYNC_RESULT_SCATTER_MAX_INFLIGHT + 1);
        match submission {
            GpuSubtreeTopKSubmission::Ready(result) => {
                while let Some(previous) = self.drain_oldest(telemetry)? {
                    completed.push(previous);
                }
                completed.push((context, result));
            }
            GpuSubtreeTopKSubmission::Deferred(deferred) => {
                while self.pending.len() >= ASYNC_RESULT_SCATTER_MAX_INFLIGHT {
                    if let Some(previous) = self.drain_oldest(telemetry)? {
                        completed.push(previous);
                    }
                }
                let seq = self.next_seq;
                self.next_seq = self.next_seq.saturating_add(1);
                let raw_bytes = deferred.estimated_host_bytes;
                let host_bytes = raw_bytes.saturating_add(context_bytes);
                let Some(work_tx) = self.work_tx.as_ref() else {
                    return Err(async_result_scatter_sequence_error(seq, "worker is closed"));
                };
                if work_tx
                    .send(SequencedDeferredGpuSubtreeScatter { seq, deferred })
                    .is_err()
                {
                    if !self.pending.is_empty() {
                        if let Err(error) = self.drain_oldest(telemetry) {
                            return Err(error);
                        }
                    }
                    telemetry.gpu_subtree_async_result_scatter_failures = telemetry
                        .gpu_subtree_async_result_scatter_failures
                        .saturating_add(1);
                    self.pending.clear();
                    let join_result = self.join_worker(telemetry);
                    return Err(async_result_scatter_sequence_error(
                        seq,
                        join_result
                            .err()
                            .map(|error| error.to_string())
                            .unwrap_or_else(|| "worker disconnected".to_string()),
                    ));
                }
                self.pending.push_back(PendingGpuSubtreeScatterContext {
                    seq,
                    context,
                    context_bytes,
                    host_bytes,
                });
                telemetry.gpu_subtree_async_result_scatter_submissions += 1;
                telemetry.gpu_subtree_async_result_scatter_peak_raw_bytes = telemetry
                    .gpu_subtree_async_result_scatter_peak_raw_bytes
                    .max(raw_bytes);
                telemetry.gpu_subtree_async_result_scatter_peak_context_bytes = telemetry
                    .gpu_subtree_async_result_scatter_peak_context_bytes
                    .max(context_bytes);
                let inflight_host_bytes = self.pending.iter().fold(0usize, |sum, pending| {
                    sum.saturating_add(pending.host_bytes)
                });
                telemetry.gpu_subtree_async_result_scatter_peak_host_bytes = telemetry
                    .gpu_subtree_async_result_scatter_peak_host_bytes
                    .max(inflight_host_bytes);
                telemetry.gpu_subtree_async_result_scatter_max_inflight = telemetry
                    .gpu_subtree_async_result_scatter_max_inflight
                    .max(self.pending.len());
            }
        }
        Ok(completed)
    }

    fn finish(
        &mut self,
        telemetry: &mut RbcPartitionTelemetry,
    ) -> AnnResult<Vec<(C, GpuSubtreeTopKResult)>> {
        let mut completed = Vec::with_capacity(self.pending.len());
        while let Some(previous) = self.drain_oldest(telemetry)? {
            completed.push(previous);
        }
        self.join_worker(telemetry)?;
        Ok(completed)
    }

    fn shutdown(&mut self, telemetry: &mut RbcPartitionTelemetry) -> AnnResult<()> {
        let pending_seq = self.pending.front().map(|pending| pending.seq);
        self.pending.clear();
        match self.join_worker(telemetry) {
            Ok(()) => Ok(()),
            Err(err) => {
                telemetry.gpu_subtree_async_result_scatter_failures += 1;
                Err(match pending_seq {
                    Some(seq) => async_result_scatter_sequence_error(seq, err),
                    None => err,
                })
            }
        }
    }

    fn shutdown_after_producer_error(
        &mut self,
        telemetry: &mut RbcPartitionTelemetry,
        producer_error: AnnError,
    ) -> AnnError {
        if let Err(shutdown_error) = self.shutdown(telemetry) {
            tracing::error!(
                error = %shutdown_error,
                "gpu-subtree async result scatter shutdown also failed after producer error"
            );
        }
        producer_error
    }

    fn drain_oldest(
        &mut self,
        telemetry: &mut RbcPartitionTelemetry,
    ) -> AnnResult<Option<(C, GpuSubtreeTopKResult)>> {
        let Some(pending) = self.pending.pop_front() else {
            return Ok(None);
        };
        let wait_start = Instant::now();
        let completion = self.completion_rx.recv();
        telemetry.gpu_subtree_async_result_scatter_wait_wall += wait_start.elapsed();
        let completion = match completion {
            Ok(completion) => completion,
            Err(_) => {
                telemetry.gpu_subtree_async_result_scatter_failures += 1;
                self.pending.clear();
                let join_result = self.join_worker(telemetry);
                return Err(async_result_scatter_sequence_error(
                    pending.seq,
                    join_result
                        .err()
                        .map(|error| error.to_string())
                        .unwrap_or_else(|| "worker disconnected".to_string()),
                ));
            }
        };
        telemetry.gpu_subtree_async_result_scatter_worker_wall += completion.worker_wall;
        telemetry.gpu_subtree_async_result_scatter_completions += 1;
        if completion.seq != pending.seq {
            telemetry.gpu_subtree_async_result_scatter_failures += 1;
            self.pending.clear();
            let cause = format!(
                "sequence mismatch: expected={} actual={}",
                pending.seq, completion.seq
            );
            let join_result = self.join_worker(telemetry);
            return Err(async_result_scatter_sequence_error(
                pending.seq,
                join_result
                    .err()
                    .map(|error| error.to_string())
                    .unwrap_or(cause),
            ));
        }
        let result = match completion.result {
            Ok(result) => result,
            Err(error) => {
                telemetry.gpu_subtree_async_result_scatter_failures += 1;
                self.pending.clear();
                let join_result = self.join_worker(telemetry);
                return Err(async_result_scatter_sequence_error(
                    pending.seq,
                    join_result.err().unwrap_or(error),
                ));
            }
        };
        let PendingGpuSubtreeScatterContext {
            context,
            context_bytes,
            ..
        } = pending;
        debug_assert!(
            context_bytes <= telemetry.gpu_subtree_async_result_scatter_peak_context_bytes
        );
        Ok(Some((context, result)))
    }

    fn join_worker(&mut self, telemetry: &mut RbcPartitionTelemetry) -> AnnResult<()> {
        self.work_tx.take();
        let Some(worker) = self.worker.take() else {
            return Ok(());
        };
        let join_start = Instant::now();
        let join_result = worker.join();
        telemetry.gpu_subtree_async_result_scatter_join_wait_wall += join_start.elapsed();
        if join_result.is_err() {
            return Err(AnnError::log_index_error(
                "gpu-subtree async result scatter worker panicked".to_string(),
            ));
        }
        Ok(())
    }
}

struct GpuSubtreeD1SqWmmaPreloadBatch {
    tasks: Vec<GpuSubtreeD1SqWmmaPreloadedTask>,
    split_telemetry: RbcPartitionTelemetry,
}

fn estimate_sq_wmma_gathered_bytes(gathered: &SqWmmaGatheredInput) -> usize {
    gathered
        .global_ids
        .len()
        .saturating_mul(size_of::<u32>())
        .saturating_add(gathered.codes.len().saturating_mul(size_of::<i8>()))
        .saturating_add(gathered.scales.len().saturating_mul(size_of::<f32>()))
        .saturating_add(gathered.norms.len().saturating_mul(size_of::<f32>()))
        .saturating_add(gathered.code_sums.len().saturating_mul(size_of::<f32>()))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct GpuSubtreeSqClusterRowRef {
    global_id: u32,
    payload_idx: usize,
    local_row: usize,
}

fn gather_gpu_subtree_d1plus_sq_shard_local_child(
    payload: &GpuSubtreeSqShardLocalPayload,
    child_rows: &[usize],
    child_idx: usize,
    child_run: GpuSubtreeChildRun,
) -> AnnResult<GpuSubtreeD1SqWmmaGatheredTask> {
    let normalize_start = Instant::now();
    let mut local_rows = child_rows.to_vec();
    local_rows.sort_unstable();
    local_rows.dedup();
    let mut global_ids = Vec::with_capacity(local_rows.len());
    for &local_row in &local_rows {
        let Some(&point_id) = payload.ids.get(local_row) else {
            return Err(AnnError::log_index_error(format!(
                "SQ GPU-D0 shard-local D1 payload row {} is outside shard starting at {} with rows {}",
                local_row,
                payload.row_start,
                payload.ids.len()
            )));
        };
        global_ids.push(point_id);
    }
    let host_normalize_wall = normalize_start.elapsed();

    let gather_start = Instant::now();
    let rows = local_rows.len();
    let code_row_bytes = payload.matrix.padded_dim;
    if payload.matrix.codes.len() != payload.matrix.rows.saturating_mul(code_row_bytes)
        || payload.matrix.scales.len() != payload.matrix.rows
        || payload.matrix.norms.len() != payload.matrix.rows
    {
        return Err(AnnError::log_index_error(format!(
            "SQ GPU-D0 shard-local D1 payload shape mismatch: shard_start={} matrix_rows={} codes={} scales={} norms={} code_row_bytes={}",
            payload.row_start,
            payload.matrix.rows,
            payload.matrix.codes.len(),
            payload.matrix.scales.len(),
            payload.matrix.norms.len(),
            code_row_bytes
        )));
    }
    let mut codes = Vec::with_capacity(rows.saturating_mul(code_row_bytes));
    let mut scales = Vec::with_capacity(rows);
    let mut norms = Vec::with_capacity(rows);
    for &local_row in &local_rows {
        if local_row >= payload.matrix.rows {
            return Err(AnnError::log_index_error(format!(
                "SQ GPU-D0 shard-local D1 local row {} is outside matrix rows {}",
                local_row, payload.matrix.rows
            )));
        }
        let code_start = local_row.saturating_mul(code_row_bytes);
        codes.extend_from_slice(&payload.matrix.codes[code_start..code_start + code_row_bytes]);
        scales.push(payload.matrix.scales[local_row]);
        norms.push(payload.matrix.norms[local_row]);
    }
    let gather_wall = gather_start.elapsed();
    let gathered = SqWmmaGatheredInput {
        global_ids: global_ids.clone(),
        codes,
        scales,
        norms,
        code_sums: vec![0.0_f32; rows],
        dim: payload.matrix.dim,
        padded_dim: payload.matrix.padded_dim,
        bits: SQ_INT8_DEFAULT_BITS,
        code_layout: SqWmmaCodeLayout::DenseI8,
        code_row_bytes,
        gather_wall,
        resident_source: true,
        resident_rows: 0,
        file_rows: 0,
        resident_gather_wall: Duration::ZERO,
        file_gather_wall: Duration::ZERO,
    };
    Ok(GpuSubtreeD1SqWmmaGatheredTask {
        task: GpuSubtreeD1ChildTask {
            child_idx,
            child_run,
            points: global_ids.clone(),
            replay_wall: Duration::ZERO,
            split_depth: 0,
        },
        global_ids,
        host_normalize_wall,
        gathered,
    })
}

fn gather_gpu_subtree_d1plus_sq_cluster_batch_child(
    payloads: &[GpuSubtreeSqShardLocalPayload],
    cluster_child_idx: usize,
    child_run_idx: usize,
    child_run: GpuSubtreeChildRun,
) -> AnnResult<GpuSubtreeD1SqWmmaGatheredTask> {
    let normalize_start = Instant::now();
    let mut row_refs = Vec::with_capacity(child_run.len);
    for (payload_idx, payload) in payloads.iter().enumerate() {
        let Some(child_rows) = payload.child_local_rows.get(cluster_child_idx) else {
            return Err(AnnError::log_index_error(format!(
                "SQ GPU-D0 cluster-batch child {} is outside payload {} child bucket count {}",
                cluster_child_idx,
                payload_idx,
                payload.child_local_rows.len()
            )));
        };
        for &local_row in child_rows {
            let Some(&global_id) = payload.ids.get(local_row) else {
                return Err(AnnError::log_index_error(format!(
                    "SQ GPU-D0 cluster-batch local row {} is outside payload {} rows {}",
                    local_row,
                    payload_idx,
                    payload.ids.len()
                )));
            };
            row_refs.push(GpuSubtreeSqClusterRowRef {
                global_id,
                payload_idx,
                local_row,
            });
        }
    }
    row_refs.sort_unstable_by_key(|row_ref| row_ref.global_id);
    row_refs.dedup_by_key(|row_ref| row_ref.global_id);
    let global_ids = row_refs
        .iter()
        .map(|row_ref| row_ref.global_id)
        .collect::<Vec<_>>();
    let host_normalize_wall = normalize_start.elapsed();

    let gather_start = Instant::now();
    let first_payload = payloads.first().ok_or_else(|| {
        AnnError::log_index_error(
            "SQ GPU-D0 cluster-batch D1 requires at least one SQ payload".to_string(),
        )
    })?;
    let code_row_bytes = first_payload.matrix.padded_dim;
    let dim = first_payload.matrix.dim;
    let padded_dim = first_payload.matrix.padded_dim;
    let mut codes = Vec::with_capacity(global_ids.len().saturating_mul(code_row_bytes));
    let mut scales = Vec::with_capacity(global_ids.len());
    let mut norms = Vec::with_capacity(global_ids.len());
    for row_ref in &row_refs {
        let payload = &payloads[row_ref.payload_idx];
        if payload.matrix.dim != dim
            || payload.matrix.padded_dim != padded_dim
            || payload.matrix.codes.len()
                != payload
                    .matrix
                    .rows
                    .saturating_mul(payload.matrix.padded_dim)
            || payload.matrix.scales.len() != payload.matrix.rows
            || payload.matrix.norms.len() != payload.matrix.rows
        {
            return Err(AnnError::log_index_error(format!(
                "SQ GPU-D0 cluster-batch payload {} shape mismatch: rows={} dim={} padded_dim={} codes={} scales={} norms={}",
                row_ref.payload_idx,
                payload.matrix.rows,
                payload.matrix.dim,
                payload.matrix.padded_dim,
                payload.matrix.codes.len(),
                payload.matrix.scales.len(),
                payload.matrix.norms.len()
            )));
        }
        if row_ref.local_row >= payload.matrix.rows {
            return Err(AnnError::log_index_error(format!(
                "SQ GPU-D0 cluster-batch local row {} is outside matrix rows {} for payload {}",
                row_ref.local_row, payload.matrix.rows, row_ref.payload_idx
            )));
        }
        let code_start = row_ref.local_row.saturating_mul(code_row_bytes);
        codes.extend_from_slice(&payload.matrix.codes[code_start..code_start + code_row_bytes]);
        scales.push(payload.matrix.scales[row_ref.local_row]);
        norms.push(payload.matrix.norms[row_ref.local_row]);
    }
    let gather_wall = gather_start.elapsed();
    let gathered = SqWmmaGatheredInput {
        global_ids: global_ids.clone(),
        codes,
        scales,
        norms,
        code_sums: vec![0.0_f32; global_ids.len()],
        dim,
        padded_dim,
        bits: SQ_INT8_DEFAULT_BITS,
        code_layout: SqWmmaCodeLayout::DenseI8,
        code_row_bytes,
        gather_wall,
        resident_source: true,
        resident_rows: 0,
        file_rows: 0,
        resident_gather_wall: Duration::ZERO,
        file_gather_wall: Duration::ZERO,
    };
    Ok(GpuSubtreeD1SqWmmaGatheredTask {
        task: GpuSubtreeD1ChildTask {
            child_idx: child_run_idx,
            child_run,
            points: global_ids.clone(),
            replay_wall: Duration::ZERO,
            split_depth: 0,
        },
        global_ids,
        host_normalize_wall,
        gathered,
    })
}

fn run_gpu_subtree_sq_shard_local_d1plus_producer(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    mut push_batch: impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    let diagnostics_enabled = std::env::var_os("SHEAR_PIPNN_D1_CHILD_DIAGNOSTICS").is_some();
    let mut child_idx = 0usize;
    for payload in &d0_plan.sq_shard_local_payloads {
        for child_rows in &payload.child_local_rows {
            if child_rows.is_empty() {
                continue;
            }
            let Some(child_run) = d0_plan.child_runs.get(child_idx).cloned() else {
                return Err(AnnError::log_index_error(format!(
                    "SQ GPU-D0 shard-local D1 payload produced more children than D0 plan: child_idx={} child_runs={}",
                    child_idx,
                    d0_plan.child_runs.len()
                )));
            };
            let gathered_task = gather_gpu_subtree_d1plus_sq_shard_local_child(
                payload, child_rows, child_idx, child_run,
            )?;
            process_gpu_subtree_d1plus_sq_wmma_gathered_sidecar_child(
                subtree_backend,
                dataset,
                params,
                d0_plan,
                telemetry,
                gathered_task,
                diagnostics_enabled,
                runtime_context,
                &mut push_batch,
            )?;
            child_idx += 1;
        }
    }
    if child_idx != d0_plan.child_runs.len() {
        return Err(AnnError::log_index_error(format!(
            "SQ GPU-D0 shard-local D1 payload produced {} non-empty children but D0 plan has {} child runs",
            child_idx,
            d0_plan.child_runs.len()
        )));
    }
    Ok(())
}

fn run_gpu_subtree_sq_cluster_batch_d1plus_producer(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    mut push_batch: impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    let diagnostics_enabled = std::env::var_os("SHEAR_PIPNN_D1_CHILD_DIAGNOSTICS").is_some();
    if d0_plan.sq_cluster_child_indices.len() != d0_plan.child_runs.len() {
        return Err(AnnError::log_index_error(format!(
            "SQ GPU-D0 cluster-batch D1 expected {} cluster child indices for {} child runs",
            d0_plan.child_runs.len(),
            d0_plan.sq_cluster_child_indices.len()
        )));
    }
    for (child_run_idx, &cluster_child_idx) in d0_plan.sq_cluster_child_indices.iter().enumerate() {
        let child_run = d0_plan.child_runs[child_run_idx].clone();
        let gathered_task = gather_gpu_subtree_d1plus_sq_cluster_batch_child(
            &d0_plan.sq_shard_local_payloads,
            cluster_child_idx,
            child_run_idx,
            child_run,
        )?;
        process_gpu_subtree_d1plus_sq_wmma_gathered_sidecar_child(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            gathered_task,
            diagnostics_enabled,
            runtime_context,
            &mut push_batch,
        )?;
    }
    Ok(())
}

fn gather_gpu_subtree_d1plus_sq_wmma_sidecar_child(
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    task: GpuSubtreeD1ChildTask,
) -> AnnResult<GpuSubtreeD1SqWmmaGatheredTask> {
    if !gpu_subtree_sq_wmma_sidecar_build_enabled(params) {
        return Err(AnnError::log_index_error(
            "SQ+WMMA build mode requires a prebuilt sidecar; raw f32 resident materialization is disabled"
                .to_string(),
        ));
    }
    let admission_ratio = d1plus_admission_ratio(params);
    let preflight =
        d1_admission_preflight(task.points.len(), dataset.dim(), params, admission_ratio);
    if !preflight.supported {
        return Err(AnnError::log_index_error(format!(
            "gpu-subtree D1+ child {}/{} SQ+WMMA sidecar build exceeds admission budget and will not be split because splitting a child changes the candidate universe: run_len={} replayed_len={} extents={} required_bytes={} budget_bytes={}",
            task.child_idx,
            d0_plan.child_runs.len(),
            task.child_run.len,
            task.points.len(),
            task.child_run.extents.len(),
            preflight.required_bytes,
            preflight.budget_bytes,
        )));
    }
    let normalize_start = Instant::now();
    let global_ids = sort_dedup_points(&task.points);
    let host_normalize_wall = normalize_start.elapsed();
    let file_sidecar;
    let sidecar = if let Some(sidecar) = runtime_context.sq_wmma_sidecar {
        sidecar
    } else {
        let prefix = params
            .gpu_subtree_sq_wmma_sidecar_prefix
            .as_ref()
            .ok_or_else(|| {
                AnnError::log_index_error(
                    "SQ+WMMA build mode requires a sidecar prefix".to_string(),
                )
            })?;
        file_sidecar = SqWmmaSidecar::open_validated_with_bits_and_io(
            prefix,
            d0_plan.total_points,
            dataset.dim(),
            params.gpu_subtree_sq_bits,
            if params.oom_enable {
                DirectIoConfig::enabled_with_alignment(4096)
            } else {
                DirectIoConfig::disabled()
            },
        )?;
        &file_sidecar
    };
    let gathered = sidecar.gather(&global_ids)?;
    Ok(GpuSubtreeD1SqWmmaGatheredTask {
        task,
        global_ids,
        host_normalize_wall,
        gathered,
    })
}

fn preload_gpu_subtree_d1plus_sq_wmma_sidecar_child(
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    mut task: GpuSubtreeD1ChildTask,
) -> AnnResult<GpuSubtreeD1SqWmmaPreloadedTask> {
    let before = task.points.len();
    let dedup_start = Instant::now();
    task.points.sort_unstable();
    task.points.dedup();
    let dedup_wall = dedup_start.elapsed();
    if before != task.points.len() {
        tracing::debug!(
            "gpu-subtree D1+ sidecar preload dedup: idx={} before={} after={} split_depth={}",
            task.child_idx,
            before,
            task.points.len(),
            task.split_depth,
        );
    }
    let gathered_task = gather_gpu_subtree_d1plus_sq_wmma_sidecar_child(
        dataset,
        params,
        d0_plan,
        runtime_context,
        task,
    )?;
    let queue_bytes = estimate_sq_wmma_gathered_bytes(&gathered_task.gathered);
    Ok(GpuSubtreeD1SqWmmaPreloadedTask {
        gathered_task,
        dedup_wall,
        queue_bytes,
    })
}

fn preload_gpu_subtree_d1plus_sq_wmma_sidecar_child_batch(
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    mut task: GpuSubtreeD1ChildTask,
) -> AnnResult<GpuSubtreeD1SqWmmaPreloadBatch> {
    let mut split_telemetry = RbcPartitionTelemetry::default();
    let before = task.points.len();
    let dedup_start = Instant::now();
    task.points.sort_unstable();
    task.points.dedup();
    split_telemetry.gpu_subtree_host_vector_dedup_wall += dedup_start.elapsed();
    if before != task.points.len() {
        tracing::debug!(
            "gpu-subtree D1+ sidecar preload pre-split dedup: idx={} before={} after={} split_depth={}",
            task.child_idx,
            before,
            task.points.len(),
            task.split_depth,
        );
    }

    let mut tasks = Vec::new();
    if let Some(thresholds) = d1plus_lazy_admission_thresholds(params, d0_plan) {
        let admission_ratio = d1plus_admission_ratio(params);
        let preflight =
            d1_admission_preflight(task.points.len(), dataset.dim(), params, admission_ratio);
        let should_split = task.points.len() > thresholds.c_high || !preflight.supported;
        if should_split && task.points.len() > 1 {
            if task.split_depth >= D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT {
                return Err(AnnError::log_index_error(format!(
                    "gpu-subtree D1+ sidecar preload child {} exceeded lazy admission split depth: rows={} depth={} c_high={} admission_supported={} required_bytes={} budget_bytes={}",
                    task.child_idx,
                    task.points.len(),
                    task.split_depth,
                    thresholds.c_high,
                    preflight.supported,
                    preflight.required_bytes,
                    preflight.budget_bytes,
                )));
            }
            let replay_wall = task.replay_wall;
            let mut split_store =
                ExternalRunStore::new(&d0_plan.external_child_dir, d0_plan.io_cfg);
            let file_sidecar;
            let sidecar = if let Some(sidecar) = runtime_context.sq_wmma_sidecar {
                sidecar
            } else {
                let prefix = params
                    .gpu_subtree_sq_wmma_sidecar_prefix
                    .as_ref()
                    .ok_or_else(|| {
                        AnnError::log_index_error(
                            "SQ+WMMA build mode requires a sidecar prefix".to_string(),
                        )
                    })?;
                file_sidecar = SqWmmaSidecar::open_validated_with_bits_and_io(
                    prefix,
                    d0_plan.total_points,
                    dataset.dim(),
                    params.gpu_subtree_sq_bits,
                    if params.oom_enable {
                        DirectIoConfig::enabled_with_alignment(4096)
                    } else {
                        DirectIoConfig::disabled()
                    },
                )?;
                &file_sidecar
            };
            let mut split_tasks =
                split_gpu_subtree_d1plus_sq_task_by_sampled_leaders_for_admission(
                    sidecar,
                    params,
                    task.child_idx,
                    task.child_run.seed,
                    task.points,
                    thresholds,
                    &mut split_store,
                    &mut split_telemetry,
                    task.split_depth,
                )?;
            split_store.finalize()?;
            if let Some(first_task) = split_tasks.first_mut() {
                first_task.replay_wall += replay_wall;
            }
            for split_task in split_tasks {
                tasks.push(preload_gpu_subtree_d1plus_sq_wmma_sidecar_child(
                    dataset,
                    params,
                    d0_plan,
                    runtime_context,
                    split_task,
                )?);
            }
            return Ok(GpuSubtreeD1SqWmmaPreloadBatch {
                tasks,
                split_telemetry,
            });
        }
    }

    tasks.push(preload_gpu_subtree_d1plus_sq_wmma_sidecar_child(
        dataset,
        params,
        d0_plan,
        runtime_context,
        task,
    )?);
    Ok(GpuSubtreeD1SqWmmaPreloadBatch {
        tasks,
        split_telemetry,
    })
}

fn preload_result_bytes(result: &SequencedSqWmmaPreloadResult) -> usize {
    result
        .result
        .as_ref()
        .map(|batch| {
            batch
                .tasks
                .iter()
                .map(|preloaded| preloaded.queue_bytes)
                .sum()
        })
        .unwrap_or(0)
}

fn process_sq_wmma_preload_result_in_order(
    sequenced: SequencedSqWmmaPreloadResult,
    wait_wall: Duration,
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
    record_repeat_profile: bool,
    repeat_estimator: &mut D1PlusRepeatEstimator,
    stop_replay: &AtomicBool,
    process_result: &mut AnnResult<()>,
    async_result_scatter: &mut Option<AsyncResultScatterRuntime<PendingSqWmmaChild>>,
) {
    match sequenced.result {
        Ok(batch) if process_result.is_ok() => {
            telemetry.gpu_subtree_gpu_wait_for_sidecar_wall += wait_wall;
            let gather_wall = batch.tasks.iter().fold(Duration::ZERO, |sum, preloaded| {
                sum + preloaded.gathered_task.gathered.gather_wall
            });
            telemetry.gpu_subtree_sidecar_gather_active_wall += gather_wall;
            telemetry.gpu_subtree_sidecar_gather_hidden_wall +=
                gather_wall.saturating_sub(wait_wall);
            let queue_bytes = batch
                .tasks
                .iter()
                .map(|preloaded| preloaded.queue_bytes)
                .sum();
            telemetry.merge(batch.split_telemetry);
            telemetry.gpu_subtree_sidecar_queue_max_bytes = telemetry
                .gpu_subtree_sidecar_queue_max_bytes
                .max(queue_bytes);
            telemetry.gpu_subtree_sidecar_queue_max_children = telemetry
                .gpu_subtree_sidecar_queue_max_children
                .max(batch.tasks.len());
            telemetry.gpu_subtree_sidecar_preload_children += batch.tasks.len();
            for preloaded in batch.tasks {
                if record_repeat_profile {
                    repeat_estimator.observe(
                        preloaded.gathered_task.task.child_idx,
                        &preloaded.gathered_task.task.points,
                    );
                }
                let child_result = if async_result_scatter.is_some() {
                    telemetry.gpu_subtree_host_vector_dedup_wall += preloaded.dedup_wall;
                    submit_gpu_subtree_d1plus_sq_wmma_gathered_sidecar_child(
                        subtree_backend,
                        dataset,
                        params,
                        d0_plan,
                        telemetry,
                        preloaded.gathered_task,
                        diagnostics_enabled,
                        runtime_context,
                        true,
                    )
                    .and_then(|submitted| {
                        let Some(submitted) = submitted else {
                            return Ok(Vec::new());
                        };
                        let context_bytes = submitted.pending.estimated_host_bytes();
                        async_result_scatter.as_mut().unwrap().accept(
                            submitted.pending,
                            context_bytes,
                            submitted.submission,
                            telemetry,
                        )
                    })
                    .and_then(|completed| {
                        for (pending, result) in completed {
                            finalize_gpu_subtree_d1plus_sq_wmma_child(
                                telemetry, pending, result, push_batch,
                            )?;
                        }
                        Ok(())
                    })
                } else {
                    process_gpu_subtree_d1plus_sq_wmma_preloaded_sidecar_child(
                        subtree_backend,
                        dataset,
                        params,
                        d0_plan,
                        telemetry,
                        preloaded,
                        diagnostics_enabled,
                        runtime_context,
                        push_batch,
                    )
                };
                if let Err(err) = child_result {
                    stop_replay.store(true, Ordering::Relaxed);
                    *process_result = Err(err);
                    break;
                }
            }
        }
        Ok(_) => {}
        Err(err) => {
            telemetry.gpu_subtree_gpu_wait_for_sidecar_wall += wait_wall;
            stop_replay.store(true, Ordering::Relaxed);
            if process_result.is_ok() {
                *process_result = Err(err);
            }
        }
    }
}

fn process_gpu_subtree_d1plus_sq_wmma_sidecar_child(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    task: GpuSubtreeD1ChildTask,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    let gathered_task = gather_gpu_subtree_d1plus_sq_wmma_sidecar_child(
        dataset,
        params,
        d0_plan,
        runtime_context,
        task,
    )?;
    process_gpu_subtree_d1plus_sq_wmma_gathered_sidecar_child(
        subtree_backend,
        dataset,
        params,
        d0_plan,
        telemetry,
        gathered_task,
        diagnostics_enabled,
        runtime_context,
        push_batch,
    )
}

fn process_gpu_subtree_d1plus_sq_wmma_preloaded_sidecar_child(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    preloaded: GpuSubtreeD1SqWmmaPreloadedTask,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    telemetry.gpu_subtree_host_vector_dedup_wall += preloaded.dedup_wall;
    process_gpu_subtree_d1plus_sq_wmma_gathered_sidecar_child(
        subtree_backend,
        dataset,
        params,
        d0_plan,
        telemetry,
        preloaded.gathered_task,
        diagnostics_enabled,
        runtime_context,
        push_batch,
    )
}

fn submit_gpu_subtree_d1plus_sq_wmma_gathered_sidecar_child(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    gathered_task: GpuSubtreeD1SqWmmaGatheredTask,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    deferred_enabled: bool,
) -> AnnResult<Option<SubmittedSqWmmaChild>> {
    let GpuSubtreeD1SqWmmaGatheredTask {
        task,
        global_ids,
        host_normalize_wall,
        gathered,
    } = gathered_task;
    let GpuSubtreeD1ChildTask {
        child_idx,
        child_run,
        points,
        replay_wall,
        split_depth,
    } = task;
    telemetry.d2_replay_wall += replay_wall;
    telemetry.gpu_subtree_d1plus_child_replay_wall += replay_wall;
    if points.len() <= 1 {
        tracing::debug!(
            "gpu-subtree D1+ child skipped: idx={}/{} rows={} split_depth={} reason=singleton mode=sq-wmma-sidecar",
            child_idx,
            d0_plan.child_runs.len(),
            points.len(),
            split_depth,
        );
        return Ok(None);
    }
    let sq_direct_d1 = matches!(
        params.gpu_subtree_sq_staging_mode,
        PiPNNGpuSubtreeSqStagingMode::GpuD0ShardLocalD1
            | PiPNNGpuSubtreeSqStagingMode::GpuD0ClusterBatchD1
    );
    if !gpu_subtree_sq_wmma_sidecar_build_enabled(params) && !sq_direct_d1 {
        return Err(AnnError::log_index_error(
            "SQ+WMMA build mode requires a prebuilt sidecar; raw f32 resident materialization is disabled"
                .to_string(),
        ));
    }
    tracing::info!(
        "gpu-subtree D1+ child start: idx={}/{} run_len={} replayed_len={} extents={} split_depth={} backend={:?} execution_mode={} mode=sq-wmma-sidecar",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        child_run.extents.len(),
        split_depth,
        subtree_backend.kind(),
        params.gpu_subtree_execution_mode.as_str(),
    );
    let mut unique_points = 0usize;
    if diagnostics_enabled {
        let mut sorted = points.clone();
        sorted.sort_unstable();
        sorted.dedup();
        unique_points = sorted.len();
        eprintln!(
            "PiPNN D1 child start: idx={} total={} run_len={} replayed_len={} unique_len={} extents={} backend={:?} sq_wmma_sidecar=true",
            child_idx,
            d0_plan.child_runs.len(),
            child_run.len,
            points.len(),
            unique_points,
            child_run.extents.len(),
            subtree_backend.kind(),
        );
    }
    let admission_ratio = d1plus_admission_ratio(params);
    let preflight = d1_admission_preflight(points.len(), dataset.dim(), params, admission_ratio);
    if !preflight.supported {
        return Err(AnnError::log_index_error(format!(
            "gpu-subtree D1+ child {}/{} SQ+WMMA sidecar build exceeds admission budget and will not be split because splitting a child changes the candidate universe: run_len={} replayed_len={} extents={} required_bytes={} budget_bytes={}",
            child_idx,
            d0_plan.child_runs.len(),
            child_run.len,
            points.len(),
            child_run.extents.len(),
            preflight.required_bytes,
            preflight.budget_bytes,
        )));
    }
    tracing::info!(
        "gpu-subtree D1+ child backend start: idx={}/{} rows={} unique_rows={} dim={} padded_dim={} bits={} code_layout={} code_row_bytes={} sidecar_gather_ms={} sidecar_resident={} normalize_ms={} admission_required_bytes={} admission_budget_bytes={} split_depth={} execution_mode={} mode=sq-wmma-sidecar",
        child_idx,
        d0_plan.child_runs.len(),
        points.len(),
        gathered.global_ids.len(),
        gathered.dim,
        gathered.padded_dim,
        gathered.bits,
        gathered.code_layout.as_str(),
        gathered.code_row_bytes,
        gathered.gather_wall.as_millis(),
        gathered.resident_rows > 0,
        host_normalize_wall.as_millis(),
        preflight.required_bytes,
        preflight.budget_bytes,
        split_depth,
        params.gpu_subtree_execution_mode.as_str(),
    );
    if diagnostics_enabled {
        eprintln!(
            "PiPNN D1 child backend start: idx={} rows={} unique_rows={} dim={} padded_dim={} bits={} code_layout={} code_row_bytes={} sidecar_gather_ms={} sidecar_resident={} normalize_ms={} admission_supported={} admission_required_bytes={} admission_budget_bytes={} split_depth={} sq_wmma_sidecar=true",
            child_idx,
            points.len(),
            gathered.global_ids.len(),
            gathered.dim,
            gathered.padded_dim,
            gathered.bits,
            gathered.code_layout.as_str(),
            gathered.code_row_bytes,
            gathered.gather_wall.as_millis(),
            gathered.resident_rows > 0,
            host_normalize_wall.as_millis(),
            preflight.supported,
            preflight.required_bytes,
            preflight.budget_bytes,
            split_depth,
        );
    }
    let root_leader_ids = prepare_d1_root_kmeans_local_leaders(
        subtree_backend,
        dataset,
        params,
        &gathered.global_ids,
    )?;
    let request = GpuSubtreePartitionRequest {
        point_ids: &points,
        root_leader_ids: root_leader_ids.as_deref(),
        depth: gpu_subtree_d1plus_request_depth(
            split_depth,
            params.gpu_subtree_d1_root_partition_mode,
        ),
        parent_points: d0_plan.total_points,
        adaptive_c_max: d0_plan.adaptive_c_max,
        min_recurse_size: d0_plan.min_recurse_size,
        memory_budget_bytes: d1plus_transient_memory_budget_bytes(params, runtime_context),
    };
    let unique_len = gathered.global_ids.len();
    let sidecar = SqWmmaSidecarProfileDelta {
        host_normalize_wall,
        rows: unique_len,
        codes_bytes: gathered.codes.len(),
        meta_bytes: unique_len
            .saturating_mul(2)
            .saturating_mul(size_of::<f32>()),
        gather_wall: gathered.gather_wall,
        resident: gathered.resident_rows > 0,
        resident_rows: gathered.resident_rows,
        file_rows: gathered.file_rows,
        resident_gather_wall: gathered.resident_gather_wall,
        file_gather_wall: gathered.file_gather_wall,
    };
    enum SqWmmaBackendInput<'a> {
        Borrowed(GpuSubtreeQuantizedInput<'a>),
        Owned(OwnedGpuSubtreeQuantizedInput),
    }
    let input = if deferred_enabled {
        SqWmmaBackendInput::Owned(OwnedGpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: Arc::new(gathered.global_ids),
            codes: Arc::new(gathered.codes),
            deltas: Arc::new(gathered.scales),
            code_sums: Arc::new(gathered.code_sums),
            norms: Arc::new(gathered.norms),
            dim: gathered.dim,
            padded_dim: gathered.padded_dim,
            code_layout: sq_wmma_compute_code_layout(gathered.code_layout),
            code_row_bytes: gathered.code_row_bytes,
            bits: gathered.bits,
        })
    } else {
        SqWmmaBackendInput::Borrowed(GpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: &gathered.global_ids,
            codes: &gathered.codes,
            deltas: &gathered.scales,
            code_sums: &gathered.code_sums,
            norms: &gathered.norms,
            dim: gathered.dim,
            padded_dim: gathered.padded_dim,
            code_layout: sq_wmma_compute_code_layout(gathered.code_layout),
            code_row_bytes: gathered.code_row_bytes,
            bits: gathered.bits,
        })
    };
    let backend_start = Instant::now();
    let mut retry_params = params.clone();
    if deferred_enabled {
        // Deferred overflow is observed only after submission, when replay is unsafe.
        retry_params.max_depth = retry_params
            .max_depth
            .max(GPU_SUBTREE_TERMINAL_DEPTH_RECOVERY_FLOOR);
    }
    let mut terminal_depth_retries = 0usize;
    let submission = loop {
        let attempt = match &input {
            SqWmmaBackendInput::Owned(owned) => subtree_backend
                .submit_owned_quantized_subtree_l2_compact_topk(
                    &request,
                    owned.clone(),
                    &retry_params,
                ),
            SqWmmaBackendInput::Borrowed(quantized) => subtree_backend
                .process_quantized_subtree_l2_compact_topk(&request, *quantized, &retry_params)
                .map(GpuSubtreeTopKSubmission::Ready),
        };
        match attempt {
            Ok(submission) => break submission,
            Err(err)
                if is_gpu_subtree_terminal_depth_only_error(&err)
                    && terminal_depth_retries < GPU_SUBTREE_TERMINAL_DEPTH_RETRY_LIMIT =>
            {
                let previous_max_depth = retry_params.max_depth;
                let next_max_depth = previous_max_depth
                    .saturating_add(1)
                    .max(GPU_SUBTREE_TERMINAL_DEPTH_RECOVERY_FLOOR)
                    .min(u32::MAX as usize);
                if next_max_depth == previous_max_depth {
                    telemetry.gpu_subtree_d1plus_backend_wall += backend_start.elapsed();
                    return Err(err);
                }
                terminal_depth_retries += 1;
                retry_params.max_depth = next_max_depth;
                tracing::warn!(
                    "gpu-subtree D1+ child {}/{} retrying identical SQ+WMMA candidate universe after terminal-depth overflow: rows={} previous_max_depth={} next_max_depth={} retry={}/{}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    points.len(),
                    previous_max_depth,
                    next_max_depth,
                    terminal_depth_retries,
                    GPU_SUBTREE_TERMINAL_DEPTH_RETRY_LIMIT,
                );
            }
            Err(err) if is_gpu_subtree_capacity_error(&err) => {
                telemetry.gpu_subtree_d1plus_backend_wall += backend_start.elapsed();
                return Err(AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {}/{} SQ+WMMA sidecar build failed without CPU fallback or child split after persistent capacity error: run_len={} replayed_len={} extents={} error={err}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    child_run.len,
                    points.len(),
                    child_run.extents.len(),
                )));
            }
            Err(err) => {
                let unique_len = if diagnostics_enabled {
                    unique_points
                } else {
                    global_ids.len()
                };
                return Err(AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {}/{} SQ+WMMA sidecar build failed: run_len={} replayed_len={} unique_len={} extents={} backend={:?}: {err}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    child_run.len,
                    points.len(),
                    unique_len,
                    child_run.extents.len(),
                    subtree_backend.kind(),
                )));
            }
        }
    };
    let backend_wall = backend_start.elapsed();
    telemetry.gpu_subtree_d1plus_backend_wall += backend_wall;
    Ok(Some(SubmittedSqWmmaChild {
        pending: PendingSqWmmaChild {
            child_idx,
            child_count: d0_plan.child_runs.len(),
            child_run,
            points,
            unique_len,
            diagnostics_enabled,
            backend_wall,
            sidecar,
        },
        submission,
    }))
}

fn finalize_gpu_subtree_d1plus_sq_wmma_child(
    telemetry: &mut RbcPartitionTelemetry,
    pending: PendingSqWmmaChild,
    mut result: GpuSubtreeTopKResult,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    result.profile.host_normalize_wall += pending.sidecar.host_normalize_wall;
    result.profile.sq_wmma_sidecar_rows += pending.sidecar.rows;
    result.profile.sq_wmma_sidecar_codes_bytes += pending.sidecar.codes_bytes;
    result.profile.sq_wmma_sidecar_meta_bytes += pending.sidecar.meta_bytes;
    result.profile.sq_wmma_sidecar_gather_wall += pending.sidecar.gather_wall;
    result.profile.sq_wmma_sidecar_resident |= pending.sidecar.resident;
    result.profile.sq_wmma_sidecar_resident_rows += pending.sidecar.resident_rows;
    result.profile.sq_wmma_sidecar_file_rows += pending.sidecar.file_rows;
    result.profile.sq_wmma_sidecar_resident_gather_wall += pending.sidecar.resident_gather_wall;
    result.profile.sq_wmma_sidecar_file_gather_wall += pending.sidecar.file_gather_wall;
    let validate_start = Instant::now();
    let compact_rows =
        validate_compact_topk_child_output(&pending.points, &result.compact_batches)?;
    telemetry.gpu_subtree_d1plus_validate_wall += validate_start.elapsed();
    tracing::info!(
        "gpu-subtree D1+ child done: idx={}/{} run_len={} replayed_len={} unique_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} backend_ms={} partition_kernel_ms={} topk_kernel_ms={} persistent_total_ms={} leaf_pushes={} topk_pops={} level_rounds={} split_retries={} balanced_fallbacks={} large_total_tiles={} large_count_next={} large_count_done={} large_scatter_next={} large_scatter_done={} overflow_flags={} mode=sq-wmma-sidecar",
        pending.child_idx,
        pending.child_count,
        pending.child_run.len,
        pending.points.len(),
        pending.unique_len,
        result.compact_batches.len(),
        compact_rows,
        result.leaf_count,
        result.assignment_passes,
        result.max_active_points,
        pending.backend_wall.as_millis(),
        result.profile.partition_only_kernel_event_wall.as_millis(),
        result.profile.resident_topk_kernel_event_wall.as_millis(),
        result.profile.persistent_total_wall.as_millis(),
        result.profile.persistent_leaf_pushes,
        result.profile.persistent_topk_pops,
        result.profile.persistent_partition_level_rounds,
        result.profile.persistent_large_split_retries,
        result.profile.persistent_large_balanced_fallbacks,
        result.profile.persistent_snapshot_large_total_tiles,
        result.profile.persistent_snapshot_large_count_next,
        result.profile.persistent_snapshot_large_count_done,
        result.profile.persistent_snapshot_large_scatter_next,
        result.profile.persistent_snapshot_large_scatter_done,
        result.profile.persistent_queue_overflow_flags,
    );
    if pending.diagnostics_enabled {
        eprintln!(
            "PiPNN D1 child done: idx={} run_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} kernel_ms={} persistent_total_ms={} split_retries={} balanced_fallbacks={} overflow_flags={} leaf_dco_tiles_started={} leaf_dco_tiles_done={} leaf_dco_prefilter_tiles={} leaf_dco_partial_tiles={} leaf_dco_full_exact_tiles={} leaf_dco_rows={} leaf_dco_prefilter_pairs={} leaf_dco_survivor_pairs={} leaf_dco_approx_output_pairs={} leaf_dco_exact_fallback_rows={} sq_wmma_sidecar=true",
            pending.child_idx,
            pending.child_run.len,
            result.compact_batches.len(),
            compact_rows,
            result.leaf_count,
            result.assignment_passes,
            result.max_active_points,
            result.profile.persistent_kernel_event_wall.as_millis(),
            result.profile.persistent_total_wall.as_millis(),
            result.profile.persistent_large_split_retries,
            result.profile.persistent_large_balanced_fallbacks,
            result.profile.persistent_queue_overflow_flags,
            result.profile.leaf_dco.tile_started,
            result.profile.leaf_dco.tile_done,
            result.profile.leaf_dco.tile_prefilter_tiles,
            result.profile.leaf_dco.tile_partial_tiles,
            result.profile.leaf_dco.tile_full_exact_tiles,
            result.profile.leaf_dco.rows,
            result.profile.leaf_dco.prefilter_pairs,
            result.profile.leaf_dco.survivor_pairs,
            result.profile.leaf_dco.approx_output_pairs,
            result.profile.leaf_dco.exact_fallback_rows,
        );
    }
    telemetry.gpu_subtree_compact_success_count += 1;
    telemetry.gpu_subtree_compact_success_points += pending.points.len();
    telemetry.gpu_subtree_compact_leaf_count += result.leaf_count;
    telemetry.gpu_subtree_compact_assignment_passes += result.assignment_passes;
    telemetry.gpu_subtree_compact_max_points = telemetry
        .gpu_subtree_compact_max_points
        .max(result.max_active_points.max(pending.points.len()));
    telemetry.gpu_subtree_compact_batches += result.compact_batches.len();
    telemetry.gpu_subtree_compact_rows += compact_rows;
    let merge_profile_start = Instant::now();
    merge_gpu_subtree_topk_profile(telemetry, &result.profile);
    telemetry.gpu_subtree_d1plus_merge_profile_wall += merge_profile_start.elapsed();
    let push_batch_start = Instant::now();
    for batch in result.compact_batches {
        push_batch(batch)?;
    }
    telemetry.gpu_subtree_d1plus_push_batch_wall += push_batch_start.elapsed();
    Ok(())
}

fn process_gpu_subtree_d1plus_sq_wmma_gathered_sidecar_child(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    gathered_task: GpuSubtreeD1SqWmmaGatheredTask,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    let Some(submitted) = submit_gpu_subtree_d1plus_sq_wmma_gathered_sidecar_child(
        subtree_backend,
        dataset,
        params,
        d0_plan,
        telemetry,
        gathered_task,
        diagnostics_enabled,
        runtime_context,
        false,
    )?
    else {
        return Ok(());
    };
    let result = match submitted.submission {
        GpuSubtreeTopKSubmission::Ready(result) => result,
        GpuSubtreeTopKSubmission::Deferred(deferred) => deferred.scatter.finish()?,
    };
    finalize_gpu_subtree_d1plus_sq_wmma_child(telemetry, submitted.pending, result, push_batch)
}

fn process_gpu_subtree_d1plus_turboquant_sidecar_child(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    task: GpuSubtreeD1ChildTask,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    let GpuSubtreeD1ChildTask {
        child_idx,
        child_run,
        points,
        replay_wall,
        split_depth,
    } = task;
    telemetry.d2_replay_wall += replay_wall;
    telemetry.gpu_subtree_d1plus_child_replay_wall += replay_wall;
    if !gpu_subtree_turboquant_sidecar_build_enabled(params) {
        return Err(AnnError::log_index_error(
            "TurboQuant-MSE4 build mode requires a prebuilt sidecar; raw f32 resident materialization is disabled"
                .to_string(),
        ));
    }
    tracing::info!(
        "gpu-subtree D1+ child start: idx={}/{} run_len={} replayed_len={} extents={} split_depth={} backend={:?} execution_mode={} mode=turboquant-mse4-sidecar",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        child_run.extents.len(),
        split_depth,
        subtree_backend.kind(),
        params.gpu_subtree_execution_mode.as_str(),
    );
    let mut unique_points = 0usize;
    if diagnostics_enabled {
        let mut sorted = points.clone();
        sorted.sort_unstable();
        sorted.dedup();
        unique_points = sorted.len();
        eprintln!(
            "PiPNN D1 child start: idx={} total={} run_len={} replayed_len={} unique_len={} extents={} backend={:?} turboquant_sidecar=true",
            child_idx,
            d0_plan.child_runs.len(),
            child_run.len,
            points.len(),
            unique_points,
            child_run.extents.len(),
            subtree_backend.kind(),
        );
    }
    let admission_ratio = d1plus_admission_ratio(params);
    let preflight = d1_admission_preflight(points.len(), dataset.dim(), params, admission_ratio);
    if !preflight.supported {
        return Err(AnnError::log_index_error(format!(
            "gpu-subtree D1+ child {}/{} TurboQuant-MSE4 sidecar build exceeds admission budget and will not be split because splitting a child changes the candidate universe: run_len={} replayed_len={} extents={} required_bytes={} budget_bytes={}",
            child_idx,
            d0_plan.child_runs.len(),
            child_run.len,
            points.len(),
            child_run.extents.len(),
            preflight.required_bytes,
            preflight.budget_bytes,
        )));
    }
    let normalize_start = Instant::now();
    let global_ids = sort_dedup_points(&points);
    let host_normalize_wall = normalize_start.elapsed();
    let file_sidecar;
    let sidecar = if let Some(sidecar) = runtime_context.turboquant_sidecar {
        sidecar
    } else {
        let prefix = params
            .gpu_subtree_turboquant_sidecar_prefix
            .as_ref()
            .ok_or_else(|| {
                AnnError::log_index_error(
                    "TurboQuant-MSE4 build mode requires a sidecar prefix".to_string(),
                )
            })?;
        file_sidecar = TurboQuantMse4Sidecar::open_validated(
            prefix,
            d0_plan.total_points,
            dataset.dim(),
            params.gpu_subtree_turboquant_bits,
            params.gpu_subtree_turboquant_seed,
        )?;
        &file_sidecar
    };
    let gathered = sidecar.gather(&global_ids)?;
    tracing::info!(
        "gpu-subtree D1+ child backend start: idx={}/{} rows={} unique_rows={} dim={} code_bytes_per_row={} bits=4 sidecar_gather_ms={} sidecar_resident={} normalize_ms={} admission_required_bytes={} admission_budget_bytes={} split_depth={} execution_mode={} mode=turboquant-mse4-sidecar",
        child_idx,
        d0_plan.child_runs.len(),
        points.len(),
        gathered.global_ids.len(),
        gathered.dim,
        gathered.code_bytes_per_row,
        gathered.gather_wall.as_millis(),
        gathered.resident_rows > 0,
        host_normalize_wall.as_millis(),
        preflight.required_bytes,
        preflight.budget_bytes,
        split_depth,
        params.gpu_subtree_execution_mode.as_str(),
    );
    if diagnostics_enabled {
        eprintln!(
            "PiPNN D1 child backend start: idx={} rows={} unique_rows={} dim={} code_bytes_per_row={} bits=4 sidecar_gather_ms={} sidecar_resident={} normalize_ms={} admission_supported={} admission_required_bytes={} admission_budget_bytes={} split_depth={} turboquant_sidecar=true",
            child_idx,
            points.len(),
            gathered.global_ids.len(),
            gathered.dim,
            gathered.code_bytes_per_row,
            gathered.gather_wall.as_millis(),
            gathered.resident_rows > 0,
            host_normalize_wall.as_millis(),
            preflight.supported,
            preflight.required_bytes,
            preflight.budget_bytes,
            split_depth,
        );
    }
    let root_leader_ids = prepare_d1_root_kmeans_local_leaders(
        subtree_backend,
        dataset,
        params,
        &gathered.global_ids,
    )?;
    let request = GpuSubtreePartitionRequest {
        point_ids: &points,
        root_leader_ids: root_leader_ids.as_deref(),
        depth: gpu_subtree_d1plus_request_depth(
            split_depth,
            params.gpu_subtree_d1_root_partition_mode,
        ),
        parent_points: d0_plan.total_points,
        adaptive_c_max: d0_plan.adaptive_c_max,
        min_recurse_size: d0_plan.min_recurse_size,
        memory_budget_bytes: d1plus_transient_memory_budget_bytes(params, runtime_context),
    };
    let zeros = vec![0.0_f32; gathered.global_ids.len()];
    let quantized = GpuSubtreeQuantizedInput {
        distance_kind: GpuSubtreeQuantizedDistanceKind::TurboQuantMse4,
        global_ids: &gathered.global_ids,
        codes: &gathered.codes,
        deltas: &zeros,
        code_sums: &zeros,
        norms: &gathered.norms,
        dim: gathered.dim,
        padded_dim: gathered.dim,
        code_layout: GpuSubtreeQuantizedCodeLayout::PackedS4,
        code_row_bytes: gathered.code_bytes_per_row,
        bits: 4,
    };
    let backend_start = Instant::now();
    let mut result = match subtree_backend
        .process_quantized_subtree_l2_compact_topk(&request, quantized, params)
    {
        Ok(result) => result,
        Err(err) if is_gpu_subtree_capacity_error(&err) => {
            telemetry.gpu_subtree_d1plus_backend_wall += backend_start.elapsed();
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ child {}/{} TurboQuant-MSE4 sidecar build failed without CPU fallback or child split after persistent capacity error: run_len={} replayed_len={} extents={} error={err}",
                child_idx,
                d0_plan.child_runs.len(),
                child_run.len,
                points.len(),
                child_run.extents.len(),
            )));
        }
        Err(err) => {
            let unique_len = if diagnostics_enabled {
                unique_points
            } else {
                global_ids.len()
            };
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ child {}/{} TurboQuant-MSE4 sidecar build failed: run_len={} replayed_len={} unique_len={} extents={} backend={:?}: {err}",
                child_idx,
                d0_plan.child_runs.len(),
                child_run.len,
                points.len(),
                unique_len,
                child_run.extents.len(),
                subtree_backend.kind(),
            )));
        }
    };
    let backend_wall = backend_start.elapsed();
    telemetry.gpu_subtree_d1plus_backend_wall += backend_wall;
    result.profile.host_normalize_wall += host_normalize_wall;
    result.profile.turboquant_sidecar_rows += gathered.global_ids.len();
    result.profile.turboquant_sidecar_codes_bytes += gathered.codes.len();
    result.profile.turboquant_sidecar_meta_bytes += gathered
        .global_ids
        .len()
        .saturating_mul(TURBOQUANT_MSE4_SIDECAR_META_ROW_BYTES);
    result.profile.turboquant_sidecar_gather_wall += gathered.gather_wall;
    result.profile.turboquant_sidecar_resident |= gathered.resident_rows > 0;
    result.profile.turboquant_sidecar_resident_rows += gathered.resident_rows;
    result.profile.turboquant_sidecar_file_rows += gathered.file_rows;
    result.profile.turboquant_sidecar_resident_gather_wall += gathered.resident_gather_wall;
    result.profile.turboquant_sidecar_file_gather_wall += gathered.file_gather_wall;
    result.profile.turboquant_read_wall += gathered.gather_wall;
    let validate_start = Instant::now();
    let compact_rows = validate_compact_topk_child_output(&points, &result.compact_batches)?;
    telemetry.gpu_subtree_d1plus_validate_wall += validate_start.elapsed();
    tracing::info!(
        "gpu-subtree D1+ child done: idx={}/{} run_len={} replayed_len={} unique_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} backend_ms={} partition_kernel_ms={} topk_kernel_ms={} persistent_total_ms={} leaf_pushes={} topk_pops={} level_rounds={} overflow_flags={} mode=turboquant-mse4-sidecar",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        gathered.global_ids.len(),
        result.compact_batches.len(),
        compact_rows,
        result.leaf_count,
        result.assignment_passes,
        result.max_active_points,
        backend_wall.as_millis(),
        result.profile.partition_only_kernel_event_wall.as_millis(),
        result.profile.resident_topk_kernel_event_wall.as_millis(),
        result.profile.persistent_total_wall.as_millis(),
        result.profile.persistent_leaf_pushes,
        result.profile.persistent_topk_pops,
        result.profile.persistent_partition_level_rounds,
        result.profile.persistent_queue_overflow_flags,
    );
    if diagnostics_enabled {
        eprintln!(
            "PiPNN D1 child done: idx={} run_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} kernel_ms={} persistent_total_ms={} overflow_flags={} leaf_dco_tiles_started={} leaf_dco_tiles_done={} leaf_dco_prefilter_tiles={} leaf_dco_partial_tiles={} leaf_dco_full_exact_tiles={} leaf_dco_rows={} leaf_dco_prefilter_pairs={} leaf_dco_survivor_pairs={} leaf_dco_approx_output_pairs={} leaf_dco_exact_fallback_rows={} turboquant_sidecar=true",
            child_idx,
            child_run.len,
            result.compact_batches.len(),
            compact_rows,
            result.leaf_count,
            result.assignment_passes,
            result.max_active_points,
            result.profile.persistent_kernel_event_wall.as_millis(),
            result.profile.persistent_total_wall.as_millis(),
            result.profile.persistent_queue_overflow_flags,
            result.profile.leaf_dco.tile_started,
            result.profile.leaf_dco.tile_done,
            result.profile.leaf_dco.tile_prefilter_tiles,
            result.profile.leaf_dco.tile_partial_tiles,
            result.profile.leaf_dco.tile_full_exact_tiles,
            result.profile.leaf_dco.rows,
            result.profile.leaf_dco.prefilter_pairs,
            result.profile.leaf_dco.survivor_pairs,
            result.profile.leaf_dco.approx_output_pairs,
            result.profile.leaf_dco.exact_fallback_rows,
        );
    }
    let merge_profile_start = Instant::now();
    merge_gpu_subtree_topk_profile(telemetry, &result.profile);
    telemetry.gpu_subtree_d1plus_merge_profile_wall += merge_profile_start.elapsed();
    let push_batch_start = Instant::now();
    for batch in result.compact_batches {
        push_batch(batch)?;
    }
    telemetry.gpu_subtree_d1plus_push_batch_wall += push_batch_start.elapsed();
    Ok(())
}

fn process_gpu_subtree_d1plus_child(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    task: GpuSubtreeD1ChildTask,
    diagnostics_enabled: bool,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    process_gpu_subtree_d1plus_child_with_context(
        subtree_backend,
        dataset,
        params,
        d0_plan,
        telemetry,
        task,
        diagnostics_enabled,
        GpuSubtreeRuntimeContext::default(),
        push_batch,
    )
}

fn process_gpu_subtree_d1plus_child_with_context(
    subtree_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    params: &PiPNNParams,
    d0_plan: &GpuSubtreeD0Plan,
    telemetry: &mut RbcPartitionTelemetry,
    mut task: GpuSubtreeD1ChildTask,
    diagnostics_enabled: bool,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    push_batch: &mut impl FnMut(CompactTopKBatch) -> AnnResult<()>,
) -> AnnResult<()> {
    dedup_gpu_subtree_d1plus_task_points(&mut task, telemetry);
    if task.points.len() <= 1 {
        telemetry.d2_replay_wall += task.replay_wall;
        telemetry.gpu_subtree_d1plus_child_replay_wall += task.replay_wall;
        tracing::debug!(
            "gpu-subtree D1+ child skipped: idx={}/{} rows={} split_depth={} reason=singleton",
            task.child_idx,
            d0_plan.child_runs.len(),
            task.points.len(),
            task.split_depth,
        );
        return Ok(());
    }
    if let Some(thresholds) = d1plus_lazy_admission_thresholds(params, d0_plan) {
        let admission_ratio = d1plus_admission_ratio(params);
        let preflight =
            d1_admission_preflight(task.points.len(), dataset.dim(), params, admission_ratio);
        let should_split = task.points.len() > thresholds.c_high || !preflight.supported;
        if should_split && task.points.len() > 1 {
            if task.split_depth >= D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT {
                return Err(AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {} exceeded lazy admission split depth: rows={} depth={} c_high={} admission_supported={} required_bytes={} budget_bytes={}",
                    task.child_idx,
                    task.points.len(),
                    task.split_depth,
                    thresholds.c_high,
                    preflight.supported,
                    preflight.required_bytes,
                    preflight.budget_bytes,
                )));
            }
            telemetry.d2_replay_wall += task.replay_wall;
            telemetry.gpu_subtree_d1plus_child_replay_wall += task.replay_wall;
            let mut split_store =
                ExternalRunStore::new(&d0_plan.external_child_dir, d0_plan.io_cfg);
            let split_tasks = split_gpu_subtree_d1plus_task_by_sampled_leaders_for_admission(
                dataset,
                params,
                task.child_idx,
                task.child_run.seed,
                task.points,
                thresholds,
                &mut split_store,
                telemetry,
                task.split_depth,
            )?;
            split_store.finalize()?;
            for split_task in split_tasks {
                process_gpu_subtree_d1plus_child_with_context(
                    subtree_backend,
                    dataset,
                    params,
                    d0_plan,
                    telemetry,
                    split_task,
                    diagnostics_enabled,
                    runtime_context,
                    push_batch,
                )?;
            }
            return Ok(());
        }
    }
    let GpuSubtreeD1ChildTask {
        child_idx,
        child_run,
        points,
        replay_wall,
        split_depth,
    } = task;
    if params.gpu_subtree_rabitq_plus_mode == PiPNNGpuSubtreeRabitqPlusMode::Build {
        return process_gpu_subtree_d1plus_quantized_sidecar_child(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            GpuSubtreeD1ChildTask {
                child_idx,
                child_run,
                points,
                replay_wall,
                split_depth,
            },
            diagnostics_enabled,
            runtime_context,
            push_batch,
        );
    }
    if params.gpu_subtree_sq_wmma_mode == PiPNNGpuSubtreeSqWmmaMode::Build {
        return process_gpu_subtree_d1plus_sq_wmma_sidecar_child(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            GpuSubtreeD1ChildTask {
                child_idx,
                child_run,
                points,
                replay_wall,
                split_depth,
            },
            diagnostics_enabled,
            runtime_context,
            push_batch,
        );
    }
    if params.gpu_subtree_turboquant_mode == PiPNNGpuSubtreeTurboQuantMode::Build {
        return process_gpu_subtree_d1plus_turboquant_sidecar_child(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            GpuSubtreeD1ChildTask {
                child_idx,
                child_run,
                points,
                replay_wall,
                split_depth,
            },
            diagnostics_enabled,
            runtime_context,
            push_batch,
        );
    }
    telemetry.d2_replay_wall += replay_wall;
    telemetry.gpu_subtree_d1plus_child_replay_wall += replay_wall;
    tracing::info!(
        "gpu-subtree D1+ child start: idx={}/{} run_len={} replayed_len={} extents={} split_depth={} backend={:?} assignment_backend={} leaf_topk_backend={} execution_mode={} mode=raw-resident",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        child_run.extents.len(),
        split_depth,
        subtree_backend.kind(),
        params.gpu_subtree_assignment_backend.as_str(),
        params.gpu_subtree_leaf_topk_backend.as_str(),
        params.gpu_subtree_execution_mode.as_str(),
    );
    let mut unique_points = 0usize;
    if diagnostics_enabled {
        let mut sorted = points.clone();
        sorted.sort_unstable();
        sorted.dedup();
        unique_points = sorted.len();
        let extent_chain = child_run
            .extents
            .iter()
            .map(|extent| format!("{}:{}", extent.byte_offset, extent.len))
            .collect::<Vec<_>>()
            .join(",");
        eprintln!(
            "PiPNN D1 child start: idx={} total={} run_len={} replayed_len={} unique_len={} extents={} seed={} extent_chain=[{}] backend={:?} assignment_backend={} leaf_topk_backend={}",
            child_idx,
            d0_plan.child_runs.len(),
            child_run.len,
            points.len(),
            unique_points,
            child_run.extents.len(),
            child_run.seed,
            extent_chain,
            subtree_backend.kind(),
            params.gpu_subtree_assignment_backend.as_str(),
            params.gpu_subtree_leaf_topk_backend.as_str(),
        );
    }
    let admission_ratio = d1plus_admission_ratio(params);
    let preflight = d1_admission_preflight(points.len(), dataset.dim(), params, admission_ratio);
    if params.gpu_subtree_d1plus_lazy_split_mode != PiPNNGpuSubtreeD1PlusLazySplitMode::Off
        && !preflight.supported
        && points.len() > 1
        && split_depth < D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT
    {
        let before_rows = points.len();
        let split_wall_start = Instant::now();
        let (left, right) = split_gpu_subtree_d1plus_task(GpuSubtreeD1ChildTask {
            child_idx,
            child_run,
            points,
            replay_wall: Duration::ZERO,
            split_depth,
        })?;
        telemetry.gpu_subtree_d1plus_lazy_split_wall += split_wall_start.elapsed();
        let left_rows = left.points.len();
        let right_rows = right.points.len();
        record_d1plus_admission_split(telemetry, before_rows, left_rows, right_rows);
        telemetry.gpu_subtree_d1plus_prevented_cpu_fallback_count += 1;
        tracing::warn!(
            "gpu-subtree D1+ child {}/{} split before persistent admission: rows={} left={} right={} split_depth={} admission_ratio={:.3} required_bytes={} budget_bytes={}",
            child_idx,
            d0_plan.child_runs.len(),
            before_rows,
            left_rows,
            right_rows,
            split_depth,
            admission_ratio,
            preflight.required_bytes,
            preflight.budget_bytes,
        );
        process_gpu_subtree_d1plus_child_with_context(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            left,
            diagnostics_enabled,
            runtime_context,
            push_batch,
        )?;
        process_gpu_subtree_d1plus_child_with_context(
            subtree_backend,
            dataset,
            params,
            d0_plan,
            telemetry,
            right,
            diagnostics_enabled,
            runtime_context,
            push_batch,
        )?;
        return Ok(());
    }
    let request = GpuSubtreePartitionRequest {
        point_ids: &points,
        root_leader_ids: None,
        depth: gpu_subtree_d1plus_request_depth(
            split_depth,
            params.gpu_subtree_d1_root_partition_mode,
        ),
        parent_points: d0_plan.total_points,
        adaptive_c_max: d0_plan.adaptive_c_max,
        min_recurse_size: d0_plan.min_recurse_size,
        memory_budget_bytes: d1plus_transient_memory_budget_bytes(params, runtime_context),
    };
    tracing::info!(
        "gpu-subtree D1+ child backend start: idx={}/{} rows={} dim={} split_depth={} execution_mode={} mode=raw-resident",
        child_idx,
        d0_plan.child_runs.len(),
        points.len(),
        dataset.dim(),
        split_depth,
        params.gpu_subtree_execution_mode.as_str(),
    );
    let backend_start = Instant::now();
    let result = match subtree_backend.process_subtree_l2_compact_topk(dataset, &request, params) {
        Ok(result) => result,
        Err(err) if is_gpu_subtree_capacity_error(&err) => {
            if params.gpu_subtree_d1plus_lazy_split_mode == PiPNNGpuSubtreeD1PlusLazySplitMode::Off
            {
                telemetry.gpu_subtree_d1plus_backend_wall += backend_start.elapsed();
                return Err(AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {}/{} hit a persistent capacity error while Lazy Split is disabled: run_len={} replayed_len={} extents={} error={err}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    child_run.len,
                    points.len(),
                    child_run.extents.len(),
                )));
            }
            if params.gpu_subtree_rabitq_plus_mode == PiPNNGpuSubtreeRabitqPlusMode::Build {
                telemetry.gpu_subtree_d1plus_backend_wall += backend_start.elapsed();
                return Err(AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {}/{} dense-i8 RabitQ+ build mode failed without CPU fallback after persistent capacity error: run_len={} replayed_len={} extents={} error={err}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    child_run.len,
                    points.len(),
                    child_run.extents.len(),
                )));
            }
            if points.len() > 1 && split_depth < D1PLUS_ADMISSION_SPLIT_DEPTH_LIMIT {
                telemetry.gpu_subtree_d1plus_backend_wall += backend_start.elapsed();
                let before_rows = points.len();
                let split_wall_start = Instant::now();
                let (left, right) = split_gpu_subtree_d1plus_task(GpuSubtreeD1ChildTask {
                    child_idx,
                    child_run: child_run.clone(),
                    points: points.clone(),
                    replay_wall: Duration::ZERO,
                    split_depth,
                })?;
                telemetry.gpu_subtree_d1plus_lazy_split_wall += split_wall_start.elapsed();
                let left_rows = left.points.len();
                let right_rows = right.points.len();
                record_d1plus_admission_split(telemetry, before_rows, left_rows, right_rows);
                telemetry.gpu_subtree_d1plus_prevented_cpu_fallback_count += 1;
                tracing::warn!(
                    "gpu-subtree D1+ child {}/{} split after persistent capacity error: rows={} left={} right={} split_depth={} extents={} error={}",
                    child_idx,
                    d0_plan.child_runs.len(),
                    before_rows,
                    left_rows,
                    right_rows,
                    split_depth,
                    child_run.extents.len(),
                    err
                );
                process_gpu_subtree_d1plus_child_with_context(
                    subtree_backend,
                    dataset,
                    params,
                    d0_plan,
                    telemetry,
                    left,
                    diagnostics_enabled,
                    runtime_context,
                    push_batch,
                )?;
                process_gpu_subtree_d1plus_child_with_context(
                    subtree_backend,
                    dataset,
                    params,
                    d0_plan,
                    telemetry,
                    right,
                    diagnostics_enabled,
                    runtime_context,
                    push_batch,
                )?;
                return Ok(());
            }
            let fallback_result = run_gpu_subtree_cpu_recursive_compact_topk_fallback(
                dataset,
                points.clone(),
                params,
                d0_plan,
                &child_run,
            )
            .map_err(|fallback_err| {
                AnnError::log_index_error(format!(
                    "gpu-subtree D1+ child {}/{} CPU fallback failed after persistent capacity error: original_error={err}; fallback_error={fallback_err}",
                    child_idx,
                    d0_plan.child_runs.len(),
                ))
            })?;
            tracing::warn!(
                "gpu-subtree D1+ child {}/{} fell back to CPU recursive compact top-k after persistent capacity error: run_len={} replayed_len={} extents={} error={}",
                child_idx,
                d0_plan.child_runs.len(),
                child_run.len,
                points.len(),
                child_run.extents.len(),
                err
            );
            fallback_result
        }
        Err(err) => {
            let unique_len = if diagnostics_enabled {
                unique_points
            } else {
                let mut sorted = points.clone();
                sorted.sort_unstable();
                sorted.dedup();
                sorted.len()
            };
            return Err(AnnError::log_index_error(format!(
                "gpu-subtree D1+ child {}/{} failed: run_len={} replayed_len={} unique_len={} extents={} backend={:?} assignment_backend={} leaf_topk_backend={}: {err}",
                child_idx,
                d0_plan.child_runs.len(),
                child_run.len,
                points.len(),
                unique_len,
                child_run.extents.len(),
                subtree_backend.kind(),
                params.gpu_subtree_assignment_backend.as_str(),
                params.gpu_subtree_leaf_topk_backend.as_str(),
            )));
        }
    };
    let backend_wall = backend_start.elapsed();
    telemetry.gpu_subtree_d1plus_backend_wall += backend_wall;
    let validate_start = Instant::now();
    let compact_rows = validate_compact_topk_child_output(&points, &result.compact_batches)?;
    telemetry.gpu_subtree_d1plus_validate_wall += validate_start.elapsed();
    tracing::info!(
        "gpu-subtree D1+ child done: idx={}/{} run_len={} replayed_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={} backend_ms={} partition_kernel_ms={} topk_kernel_ms={} persistent_total_ms={} leaf_pushes={} topk_pops={} level_rounds={} overflow_flags={} mode=raw-resident",
        child_idx,
        d0_plan.child_runs.len(),
        child_run.len,
        points.len(),
        result.compact_batches.len(),
        compact_rows,
        result.leaf_count,
        result.assignment_passes,
        result.max_active_points,
        backend_wall.as_millis(),
        result.profile.partition_only_kernel_event_wall.as_millis(),
        result.profile.resident_topk_kernel_event_wall.as_millis(),
        result.profile.persistent_total_wall.as_millis(),
        result.profile.persistent_leaf_pushes,
        result.profile.persistent_topk_pops,
        result.profile.persistent_partition_level_rounds,
        result.profile.persistent_queue_overflow_flags,
    );
    if diagnostics_enabled {
        eprintln!(
            "PiPNN D1 child done: idx={} run_len={} compact_batches={} compact_rows={} leaves={} assignment_passes={} max_active_points={}",
            child_idx,
            child_run.len,
            result.compact_batches.len(),
            compact_rows,
            result.leaf_count,
            result.assignment_passes,
            result.max_active_points,
        );
    }
    telemetry.gpu_subtree_compact_success_count += 1;
    telemetry.gpu_subtree_compact_success_points += points.len();
    telemetry.gpu_subtree_compact_leaf_count += result.leaf_count;
    telemetry.gpu_subtree_compact_assignment_passes += result.assignment_passes;
    telemetry.gpu_subtree_compact_max_points = telemetry
        .gpu_subtree_compact_max_points
        .max(result.max_active_points.max(points.len()));
    telemetry.gpu_subtree_compact_batches += result.compact_batches.len();
    telemetry.gpu_subtree_compact_rows += compact_rows;
    let merge_profile_start = Instant::now();
    merge_gpu_subtree_topk_profile(telemetry, &result.profile);
    telemetry.gpu_subtree_d1plus_merge_profile_wall += merge_profile_start.elapsed();
    let push_batch_start = Instant::now();
    for batch in result.compact_batches {
        push_batch(batch)?;
    }
    telemetry.gpu_subtree_d1plus_push_batch_wall += push_batch_start.elapsed();
    Ok(())
}

pub fn root_radius_dry_run_json(
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    rng: &mut (impl Rng + Send),
) -> AnnResult<String> {
    let total_size = indices.len();
    if total_size == 0 {
        let mut profile = RootFanoutProfile::fixed(params.fanout_top);
        if matches!(params.root_fanout_policy, RootFanoutPolicy::RiskBudgeted)
            || params.root_risk_dry_run
        {
            profile.policy = "risk-budgeted".to_string();
            profile.selection_semantics = "budgeted_utility_core_drop_v1".to_string();
            profile.dry_run = params.root_risk_dry_run;
            profile.target_avg_fanout = params.root_risk_target_avg_fanout;
            profile.sigma_lambda = params.root_risk_sigma_lambda;
            profile.sigma_mode = params.root_risk_sigma_mode.to_string();
        } else {
            profile.policy = "cell-radius-certified".to_string();
            profile.selection_semantics = "cell_radius_certified_root_assignment_v1".to_string();
            profile.dry_run = params.root_radius_dry_run;
        }
        profile.fallback_reason = Some("empty_dataset".to_string());
        return Ok(root_fanout_profile_json(&profile));
    }
    let root_leaders = select_root_leaders(indices, params, rng);
    let state = initialize_root_fanout_state(dataset, indices, &root_leaders, params, metric, rng)?;
    if state.radius_config().is_some() && metric == Metric::L2 {
        let _ = compute_root_radius_clusters_gemm_budgeted(
            dataset,
            indices,
            &root_leaders,
            &state,
            None,
        )?;
    } else if state.risk_config().is_some() && metric == Metric::L2 {
        let _ = compute_root_risk_clusters_gemm_budgeted(
            dataset,
            indices,
            &root_leaders,
            &state,
            None,
        )?;
    }
    Ok(root_fanout_profile_json(&state.profile()))
}

/// Per-worker scratch buffers for GEMM-based cluster assignment.
/// Reused across point-tile chunks to avoid repeated large heap allocations.
struct GemmScratch {
    x_data: Vec<f32>,
    x_norms: Vec<f32>,
    gram_data: Vec<f32>,
    topk_rows: Vec<StackTopK>,
    local_clusters: Vec<Vec<u32>>,
}

impl GemmScratch {
    fn new(point_tile: usize, leader_tile: usize, dim: usize, nl: usize, fanout: usize) -> Self {
        Self {
            x_data: Vec::with_capacity(point_tile * dim),
            x_norms: Vec::with_capacity(point_tile),
            gram_data: Vec::with_capacity(point_tile * leader_tile),
            topk_rows: (0..point_tile).map(|_| StackTopK::new(fanout)).collect(),
            local_clusters: (0..nl).map(|_| Vec::new()).collect(),
        }
    }
}

struct GemmFoldState {
    scratch: GemmScratch,
    clusters: Vec<Vec<u32>>,
    profile: GemmProfile,
}

fn default_rbc_windowed_options(
    dataset: &dyn PointStore,
    tile_rows: usize,
) -> WindowedGatherOptions {
    let row_bytes = dataset.dim().saturating_mul(size_of::<f32>());
    let max_window_bytes = row_bytes
        .saturating_mul(tile_rows.max(1))
        .min(4 * 1024 * 1024)
        .max(256 * 1024);
    let max_gap_rows = if row_bytes <= 4096 { 1 } else { 0 };
    WindowedGatherOptions {
        max_gap_rows,
        max_window_bytes,
        alignment_bytes: 4096,
        sort_ids: true,
    }
}

impl GemmFoldState {
    fn new(point_tile: usize, leader_tile: usize, dim: usize, nl: usize, fanout: usize) -> Self {
        Self {
            scratch: GemmScratch::new(point_tile, leader_tile, dim, nl, fanout),
            clusters: (0..nl).map(|_| Vec::new()).collect(),
            profile: GemmProfile::default(),
        }
    }
}

fn merge_cluster_buffers(dst: &mut [Vec<u32>], src: Vec<Vec<u32>>) {
    assert_eq!(dst.len(), src.len());
    for (dst_cluster, mut src_cluster) in dst.iter_mut().zip(src) {
        dst_cluster.append(&mut src_cluster);
    }
}

fn merge_cluster_buffers_in_place(dst: &mut [Vec<u32>], src: &mut [Vec<u32>]) {
    assert_eq!(dst.len(), src.len());
    for (dst_cluster, src_cluster) in dst.iter_mut().zip(src.iter_mut()) {
        dst_cluster.append(src_cluster);
    }
}

fn borrow_gram_tile(gram_data: &mut Vec<f32>, rows: usize, cols: usize) -> ArrayViewMut2<'_, f32> {
    let gram_len = rows * cols;
    gram_data.resize(gram_len, 0.0);
    gram_data[..gram_len].fill(0.0);
    ArrayViewMut2::from_shape((rows, cols), &mut gram_data[..gram_len]).unwrap()
}

/// GEMM-based cluster assignment for L2 metric when n >= 256.
///
/// Processes points in blocks to avoid OOM on large inputs (e.g. 35M × 10K leaders).
/// Each block is processed by a rayon thread: build local X matrix, GEMM against shared
/// leader matrix, top-k assignment, then merge into global clusters.
pub(super) fn compute_clusters_gemm(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
) -> AnnResult<(Vec<Vec<u32>>, GemmProfile)> {
    compute_clusters_gemm_budgeted(dataset, cur, leaders, local_fanout, None)
}

pub(super) fn compute_clusters_gemm_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
    memory_budget_bytes: Option<usize>,
) -> AnnResult<(Vec<Vec<u32>>, GemmProfile)> {
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let (point_tile_size, leader_tile_size) =
        choose_gemm_tile_sizes_with_override_and_budget(nl, dim, memory_budget_bytes);
    let leader_read_options =
        default_rbc_windowed_options(dataset, nl.min(leader_tile_size.max(1)));
    let point_read_options = default_rbc_windowed_options(dataset, point_tile_size);

    // Pre-compute leader matrix and norms (shared, read-only)
    let mut l_data = vec![0f32; nl * dim];
    let mut leader_io_stats = PointBatchStats::default();
    dataset.read_points_windowed_into_batch_stats(
        leaders,
        &mut l_data,
        &leader_read_options,
        &mut leader_io_stats,
    )?;
    let l_norms: Vec<f32> = l_data
        .chunks(dim)
        .map(|r| r.iter().map(|&v| v * v).sum())
        .collect();
    let l_mat = ArrayView2::from_shape((nl, dim), &l_data).unwrap();

    let num_workers = rayon::current_num_threads().max(1);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        num_workers,
        memory_budget_bytes,
    );
    let mut state = GemmFoldState::new(point_tile_size, leader_tile_size, dim, nl, local_fanout);
    let mut io_stats = leader_io_stats;

    // Stage batched point reads on the producer thread so worker hot loops focus on
    // GEMM/top-k/merge. This is the smallest execution-model change that starts hiding
    // point-store latency without changing clustering semantics or introducing a separate async
    // runtime.
    for_each_prefetched_point_batch(
        dataset,
        cur,
        batch_points,
        point_read_options,
        |prefetched| {
            io_stats.merge(&prefetched.io_stats);
            state.profile.build_x += prefetched.load;
            let compute_block_points =
                choose_compute_block_points_for_batch(point_tile_size, prefetched.len, num_workers);

            let batch_state = (0..prefetched.len)
                .into_par_iter()
                .step_by(compute_block_points)
                .map(|block_start_idx| {
                    let block_end_idx =
                        (block_start_idx + compute_block_points).min(prefetched.len);
                    let block = &prefetched.ids[block_start_idx..block_end_idx];
                    let x_slice = &prefetched.data[block_start_idx * dim..block_end_idx * dim];
                    let block_n = block.len();
                    let mut local_state = GemmFoldState::new(
                        compute_block_points,
                        leader_tile_size,
                        dim,
                        nl,
                        local_fanout,
                    );
                    let mut block_profile = GemmProfile {
                        blocks: 1,
                        ..GemmProfile::default()
                    };
                    let block_start = Instant::now();

                    let scratch = &mut local_state.scratch;
                    let build_x_start = Instant::now();
                    scratch.x_data.clear();
                    scratch.x_data.extend_from_slice(x_slice);
                    scratch.x_norms.resize(block_n, 0f32);
                    for (i, chunk) in scratch.x_data.chunks(dim).enumerate() {
                        scratch.x_norms[i] = chunk.iter().map(|&v| v * v).sum();
                    }
                    let x_mat =
                        ArrayView2::from_shape((block_n, dim), scratch.x_data.as_slice()).unwrap();
                    block_profile.build_x += build_x_start.elapsed();

                    if local_fanout == 1 {
                        let topk_start = Instant::now();
                        let mut best_distances = vec![f32::INFINITY; block_n];
                        let mut best_leaders = vec![0usize; block_n];
                        block_profile.topk += topk_start.elapsed();

                        for leader_offset in (0..nl).step_by(leader_tile_size) {
                            let leader_end = (leader_offset + leader_tile_size).min(nl);
                            let leader_view =
                                l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                            let tile_cols = leader_end - leader_offset;
                            let mut gram_tile =
                                borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                            let gemm_start = Instant::now();
                            ndarray::linalg::general_mat_mul(
                                1.0,
                                &x_mat,
                                &leader_view.t(),
                                0.0,
                                &mut gram_tile,
                            );
                            block_profile.gemm += gemm_start.elapsed();
                            let topk_update_start = Instant::now();
                            update_block_best_from_gram_tile(
                                &mut best_distances,
                                &mut best_leaders,
                                &scratch.x_norms[..block_n],
                                &l_norms,
                                gram_tile.view(),
                                leader_offset,
                            );
                            block_profile.topk += topk_update_start.elapsed();
                        }

                        let merge_start = Instant::now();
                        scratch.local_clusters.resize_with(nl, Vec::new);
                        for v in scratch.local_clusters[..nl].iter_mut() {
                            v.clear();
                        }
                        for (i, &best_lid) in best_leaders.iter().enumerate() {
                            scratch.local_clusters[best_lid].push(block[i]);
                        }

                        merge_cluster_buffers_in_place(
                            &mut local_state.clusters,
                            &mut scratch.local_clusters,
                        );
                        block_profile.merge += merge_start.elapsed();
                    } else {
                        let topk_start = Instant::now();
                        scratch
                            .topk_rows
                            .resize_with(block_n, || StackTopK::new(local_fanout));
                        for topk in scratch.topk_rows[..block_n].iter_mut() {
                            *topk = StackTopK::new(local_fanout);
                        }
                        block_profile.topk += topk_start.elapsed();

                        for leader_offset in (0..nl).step_by(leader_tile_size) {
                            let leader_end = (leader_offset + leader_tile_size).min(nl);
                            let leader_view =
                                l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                            let tile_cols = leader_end - leader_offset;
                            let mut gram_tile =
                                borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                            let gemm_start = Instant::now();
                            ndarray::linalg::general_mat_mul(
                                1.0,
                                &x_mat,
                                &leader_view.t(),
                                0.0,
                                &mut gram_tile,
                            );
                            block_profile.gemm += gemm_start.elapsed();
                            let topk_update_start = Instant::now();
                            update_block_topk_from_gram_tile(
                                &mut scratch.topk_rows[..block_n],
                                &scratch.x_norms[..block_n],
                                &l_norms,
                                gram_tile.view(),
                                leader_offset,
                            );
                            block_profile.topk += topk_update_start.elapsed();
                        }

                        let merge_start = Instant::now();
                        scratch.local_clusters.resize_with(nl, Vec::new);
                        for v in scratch.local_clusters[..nl].iter_mut() {
                            v.clear();
                        }
                        for (i, top_k) in scratch.topk_rows[..block_n].iter().enumerate() {
                            for &(_, lid) in top_k.iter() {
                                scratch.local_clusters[lid].push(block[i]);
                            }
                        }

                        merge_cluster_buffers_in_place(
                            &mut local_state.clusters,
                            &mut scratch.local_clusters,
                        );
                        block_profile.merge += merge_start.elapsed();
                    }
                    block_profile.total_wall = block_start.elapsed();
                    local_state.profile.merge(block_profile);
                    Ok::<GemmFoldState, crate::common::AnnError>(local_state)
                })
                .try_reduce(
                    || {
                        GemmFoldState::new(
                            compute_block_points,
                            leader_tile_size,
                            dim,
                            nl,
                            local_fanout,
                        )
                    },
                    |mut left, right| -> AnnResult<GemmFoldState> {
                        merge_cluster_buffers(&mut left.clusters, right.clusters);
                        left.profile.merge(right.profile);
                        Ok(left)
                    },
                )?;

            merge_cluster_buffers(&mut state.clusters, batch_state.clusters);
            state.profile.merge(batch_state.profile);
            Ok(())
        },
    )?;

    let mut profile = state.profile;
    profile.total_wall = total_start.elapsed();
    let io = &io_stats;
    tracing::info!(
        "[rbc/par] point_reads={} range_reads={} range_rows={} hit_ratio={:.2}",
        io.point_calls,
        io.range_calls,
        io.range_rows_read,
        io.range_hit_ratio(),
    );
    Ok((state.clusters, profile))
}

fn compute_clusters_gemm_to_spool_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
    memory_budget_bytes: Option<usize>,
    spool_writer: &mut BufWriter<File>,
    raw_counts: &mut [usize],
) -> AnnResult<GemmProfile> {
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let fanout = assign_record_fanout(local_fanout.min(nl.max(1)));
    let (point_tile_size, leader_tile_size) =
        choose_gemm_tile_sizes_with_override_and_budget(nl, dim, memory_budget_bytes);
    let leader_read_options =
        default_rbc_windowed_options(dataset, nl.min(leader_tile_size.max(1)));
    let point_read_options = default_rbc_windowed_options(dataset, point_tile_size);

    // Shared leader data is read once and reused across worker-local point tiles.
    let mut l_data = vec![0f32; nl * dim];
    let mut leader_io_stats = PointBatchStats::default();
    dataset.read_points_windowed_into_batch_stats(
        leaders,
        &mut l_data,
        &leader_read_options,
        &mut leader_io_stats,
    )?;
    let l_norms: Vec<f32> = l_data
        .chunks(dim)
        .map(|r| r.iter().map(|&v| v * v).sum())
        .collect();
    let l_mat = ArrayView2::from_shape((nl, dim), &l_data).unwrap();
    let num_workers = rayon::current_num_threads().max(1);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        choose_spool_prefetch_workers(num_workers, memory_budget_bytes),
        memory_budget_bytes,
    );

    struct BatchFold {
        scratch: GemmScratch,
        profile: GemmProfile,
        raw_counts: Vec<usize>,
        assign_chunks: Vec<Vec<u8>>,
    }

    let mut profile = GemmProfile::default();
    let mut io_stats = leader_io_stats;
    let mut merged_raw_counts = vec![0usize; nl];

    for_each_prefetched_point_batch(
        dataset,
        cur,
        batch_points,
        point_read_options,
        |prefetched| {
            io_stats.merge(&prefetched.io_stats);
            profile.build_x += prefetched.load;
            let compute_block_points =
                choose_compute_block_points_for_batch(point_tile_size, prefetched.len, num_workers);

            let folds: Vec<BatchFold> = (0..prefetched.len)
                .into_par_iter()
                .step_by(compute_block_points)
                .map(|block_start_idx| {
                    let block_end_idx =
                        (block_start_idx + compute_block_points).min(prefetched.len);
                    let block = &prefetched.ids[block_start_idx..block_end_idx];
                    let x_slice = &prefetched.data[block_start_idx * dim..block_end_idx * dim];
                    let mut fold = BatchFold {
                        scratch: GemmScratch::new(
                            compute_block_points,
                            leader_tile_size,
                            dim,
                            nl,
                            fanout,
                        ),
                        profile: GemmProfile::default(),
                        raw_counts: vec![0usize; nl],
                        assign_chunks: Vec::new(),
                    };
                    let block_n = block.len();
                    let scratch = &mut fold.scratch;
                    let mut block_profile = GemmProfile {
                        blocks: 1,
                        ..GemmProfile::default()
                    };
                    let block_start = Instant::now();

                    let build_x_start = Instant::now();
                    scratch.x_data.clear();
                    scratch.x_data.extend_from_slice(x_slice);
                    scratch.x_norms.resize(block_n, 0f32);
                    for (i, chunk) in scratch.x_data.chunks(dim).enumerate() {
                        scratch.x_norms[i] = chunk.iter().map(|&v| v * v).sum();
                    }
                    let x_mat =
                        ArrayView2::from_shape((block_n, dim), scratch.x_data.as_slice()).unwrap();
                    block_profile.build_x += build_x_start.elapsed();

                    let mut assign_buf = Vec::with_capacity(block_n * assign_record_width(fanout));

                    if fanout == 1 {
                        let mut best_distances = vec![f32::INFINITY; block_n];
                        let mut best_leaders = vec![0usize; block_n];

                        for leader_offset in (0..nl).step_by(leader_tile_size) {
                            let leader_end = (leader_offset + leader_tile_size).min(nl);
                            let leader_view =
                                l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                            let tile_cols = leader_end - leader_offset;
                            let mut gram_tile =
                                borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                            let gemm_start = Instant::now();
                            ndarray::linalg::general_mat_mul(
                                1.0,
                                &x_mat,
                                &leader_view.t(),
                                0.0,
                                &mut gram_tile,
                            );
                            block_profile.gemm += gemm_start.elapsed();
                            let topk_update_start = Instant::now();
                            update_block_best_from_gram_tile(
                                &mut best_distances,
                                &mut best_leaders,
                                &scratch.x_norms[..block_n],
                                &l_norms,
                                gram_tile.view(),
                                leader_offset,
                            );
                            block_profile.topk += topk_update_start.elapsed();
                        }

                        for &best_lid in &best_leaders {
                            fold.raw_counts[best_lid] += 1;
                            append_assign_record_bytes(
                                &mut assign_buf,
                                &[best_lid as u16],
                                fanout,
                            )?;
                        }
                    } else {
                        let topk_start = Instant::now();
                        scratch
                            .topk_rows
                            .resize_with(block_n, || StackTopK::new(fanout));
                        for topk in scratch.topk_rows[..block_n].iter_mut() {
                            *topk = StackTopK::new(fanout);
                        }
                        block_profile.topk += topk_start.elapsed();

                        for leader_offset in (0..nl).step_by(leader_tile_size) {
                            let leader_end = (leader_offset + leader_tile_size).min(nl);
                            let leader_view =
                                l_mat.slice(ndarray::s![leader_offset..leader_end, ..]);
                            let tile_cols = leader_end - leader_offset;
                            let mut gram_tile =
                                borrow_gram_tile(&mut scratch.gram_data, block_n, tile_cols);
                            let gemm_start = Instant::now();
                            ndarray::linalg::general_mat_mul(
                                1.0,
                                &x_mat,
                                &leader_view.t(),
                                0.0,
                                &mut gram_tile,
                            );
                            block_profile.gemm += gemm_start.elapsed();
                            let topk_update_start = Instant::now();
                            update_block_topk_from_gram_tile(
                                &mut scratch.topk_rows[..block_n],
                                &scratch.x_norms[..block_n],
                                &l_norms,
                                gram_tile.view(),
                                leader_offset,
                            );
                            block_profile.topk += topk_update_start.elapsed();
                        }

                        for top_k in &scratch.topk_rows[..block_n] {
                            let mut leaders_for_point = [0u16; 32];
                            let mut len = 0usize;
                            for &(_, lid) in top_k.iter() {
                                fold.raw_counts[lid] += 1;
                                leaders_for_point[len] = lid as u16;
                                len += 1;
                            }
                            append_assign_record_bytes(
                                &mut assign_buf,
                                &leaders_for_point[..len],
                                fanout,
                            )?;
                        }
                    }

                    block_profile.merge += Duration::ZERO;
                    block_profile.total_wall = block_start.elapsed();
                    fold.profile.merge(block_profile);
                    fold.assign_chunks.push(assign_buf);
                    Ok::<BatchFold, crate::common::AnnError>(fold)
                })
                .collect::<AnnResult<Vec<_>>>()?;

            for fold in folds {
                profile.merge(fold.profile);
                for (lid, count) in fold.raw_counts.into_iter().enumerate() {
                    merged_raw_counts[lid] += count;
                }
                for bytes in fold.assign_chunks {
                    let spool_write_start = Instant::now();
                    spool_writer.write_all(&bytes)?;
                    profile.spool_write += spool_write_start.elapsed();
                }
            }
            Ok(())
        },
    )?;

    raw_counts.copy_from_slice(&merged_raw_counts);

    let flush_start = Instant::now();
    spool_writer.flush()?;
    profile.flush += flush_start.elapsed();
    profile.total_wall = total_start.elapsed();
    tracing::info!(
        "[rbc/par-spool] point_reads={} range_reads={} range_rows={} hit_ratio={:.2} workers={} build_x_ms={} gemm_ms={} topk_ms={} merge_ms={} spool_write_ms={} flush_ms={} total_ms={}",
        io_stats.point_calls,
        io_stats.range_calls,
        io_stats.range_rows_read,
        io_stats.range_hit_ratio(),
        num_workers,
        profile.build_x.as_millis(),
        profile.gemm.as_millis(),
        profile.topk.as_millis(),
        profile.merge.as_millis(),
        profile.spool_write.as_millis(),
        profile.flush.as_millis(),
        profile.total_wall.as_millis(),
    );
    Ok(profile)
}

#[allow(clippy::too_many_arguments)]
fn compute_clusters_rabitq_sidecar_dco_to_spool_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
    memory_budget_bytes: Option<usize>,
    spool_writer: &mut BufWriter<File>,
    raw_counts: &mut [usize],
    sidecar: &RabitqPlusSidecar,
    params: &PiPNNParams,
) -> AnnResult<D0DcoSpoolProfile> {
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let fanout = assign_record_fanout(local_fanout.min(nl.max(1)));
    let survivor_count = params
        .gpu_subtree_d0_dco_survivors
        .max(fanout)
        .min(nl.max(1));
    let exact_rerank = params.gpu_subtree_d0_dco_rerank_mode == PiPNNGpuSubtreeDcoRerankMode::Exact;
    let (point_tile_size, leader_tile_size) =
        choose_gemm_tile_sizes_with_override_and_budget(nl, dim, memory_budget_bytes);
    let leader_read_options =
        default_rbc_windowed_options(dataset, nl.min(leader_tile_size.max(1)));
    let point_read_options = default_rbc_windowed_options(dataset, point_tile_size);

    let leader_gather = sidecar.gather(leaders)?;
    let mut sidecar_gather_wall = leader_gather.gather_wall;
    let mut profile = GemmProfile::default();
    let mut dco = GpuSubtreeAssignmentDcoTelemetry {
        nodes: 1,
        metadata_bytes: cur
            .len()
            .saturating_add(nl)
            .saturating_mul(leader_gather.padded_dim)
            .saturating_add(
                cur.len()
                    .saturating_add(nl)
                    .saturating_mul(size_of::<f32>() * 3),
            ),
        ..GpuSubtreeAssignmentDcoTelemetry::default()
    };
    let mut l_data = Vec::new();
    let mut l_norms = Vec::new();
    let mut io_stats = PointBatchStats::default();
    if exact_rerank || params.gpu_subtree_d0_dco_audit {
        let leader_read_start = Instant::now();
        l_data.resize(nl.saturating_mul(dim), 0.0);
        dataset.read_points_windowed_into_batch_stats(
            leaders,
            &mut l_data,
            &leader_read_options,
            &mut io_stats,
        )?;
        profile.build_x += leader_read_start.elapsed();
        l_norms = l_data
            .chunks(dim)
            .map(|row| row.iter().map(|&value| value * value).sum::<f32>())
            .collect();
    }
    let num_workers = rayon::current_num_threads().max(1);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        choose_spool_prefetch_workers(num_workers, memory_budget_bytes),
        memory_budget_bytes,
    );
    let mut merged_raw_counts = vec![0usize; nl];

    struct D0DcoFold {
        profile: GemmProfile,
        dco: GpuSubtreeAssignmentDcoTelemetry,
        raw_counts: Vec<usize>,
        assign_chunks: Vec<Vec<u8>>,
        approx_wall: Duration,
        exact_wall: Duration,
    }

    if exact_rerank || params.gpu_subtree_d0_dco_audit {
        for_each_prefetched_point_batch(
            dataset,
            cur,
            batch_points,
            point_read_options,
            |prefetched| {
                io_stats.merge(&prefetched.io_stats);
                profile.build_x += prefetched.load;
                let point_gather = sidecar.gather(&prefetched.ids)?;
                sidecar_gather_wall += point_gather.gather_wall;
                let compute_block_points = choose_compute_block_points_for_batch(
                    point_tile_size,
                    prefetched.len,
                    num_workers,
                );

                let folds: Vec<D0DcoFold> = (0..prefetched.len)
                    .into_par_iter()
                    .step_by(compute_block_points)
                    .map(|block_start_idx| {
                        let block_end_idx =
                            (block_start_idx + compute_block_points).min(prefetched.len);
                        let block_n = block_end_idx - block_start_idx;
                        let x_slice = &prefetched.data[block_start_idx * dim..block_end_idx * dim];
                        let x_norms = x_slice
                            .chunks(dim)
                            .map(|row| row.iter().map(|&value| value * value).sum::<f32>())
                            .collect::<Vec<_>>();
                        let mut fold = D0DcoFold {
                            profile: GemmProfile {
                                blocks: 1,
                                ..GemmProfile::default()
                            },
                            dco: GpuSubtreeAssignmentDcoTelemetry::default(),
                            raw_counts: vec![0usize; nl],
                            assign_chunks: Vec::new(),
                            approx_wall: Duration::ZERO,
                            exact_wall: Duration::ZERO,
                        };
                        let block_start = Instant::now();
                        let mut assign_buf =
                            Vec::with_capacity(block_n * assign_record_width(fanout));
                        for local_row in 0..block_n {
                            let gather_row = block_start_idx + local_row;
                            let exact_point = &x_slice[local_row * dim..(local_row + 1) * dim];
                            let (leaders_for_point, approx_wall, exact_wall, row_dco) =
                                d0_rabitq_sidecar_assign_row(
                                    &point_gather,
                                    gather_row,
                                    &leader_gather,
                                    leaders,
                                    exact_point,
                                    x_norms[local_row],
                                    &l_data,
                                    &l_norms,
                                    dim,
                                    fanout,
                                    survivor_count,
                                    params.gpu_subtree_d0_dco_rerank_mode,
                                    params.gpu_subtree_d0_dco_audit,
                                )?;
                            fold.approx_wall += approx_wall;
                            fold.exact_wall += exact_wall;
                            fold.dco.merge(row_dco);
                            for &lid in &leaders_for_point {
                                fold.raw_counts[lid as usize] += 1;
                            }
                            append_assign_record_bytes(
                                &mut assign_buf,
                                &leaders_for_point,
                                fanout,
                            )?;
                        }
                        fold.profile.gemm += fold.approx_wall;
                        fold.profile.topk += fold.exact_wall;
                        fold.profile.total_wall = block_start.elapsed();
                        fold.assign_chunks.push(assign_buf);
                        Ok::<D0DcoFold, crate::common::AnnError>(fold)
                    })
                    .collect::<AnnResult<Vec<_>>>()?;

                for fold in folds {
                    profile.merge(fold.profile);
                    dco.merge(fold.dco);
                    for (lid, count) in fold.raw_counts.into_iter().enumerate() {
                        merged_raw_counts[lid] += count;
                    }
                    for bytes in fold.assign_chunks {
                        let spool_write_start = Instant::now();
                        spool_writer.write_all(&bytes)?;
                        profile.spool_write += spool_write_start.elapsed();
                    }
                }
                Ok(())
            },
        )?;
    } else {
        for ids in cur.chunks(batch_points.max(1)) {
            let point_gather = sidecar.gather(ids)?;
            sidecar_gather_wall += point_gather.gather_wall;
            let compute_block_points =
                choose_compute_block_points_for_batch(point_tile_size, ids.len(), num_workers);
            let folds: Vec<D0DcoFold> = (0..ids.len())
                .into_par_iter()
                .step_by(compute_block_points)
                .map(|block_start_idx| {
                    let block_end_idx = (block_start_idx + compute_block_points).min(ids.len());
                    let block_n = block_end_idx - block_start_idx;
                    let mut fold = D0DcoFold {
                        profile: GemmProfile {
                            blocks: 1,
                            ..GemmProfile::default()
                        },
                        dco: GpuSubtreeAssignmentDcoTelemetry::default(),
                        raw_counts: vec![0usize; nl],
                        assign_chunks: Vec::new(),
                        approx_wall: Duration::ZERO,
                        exact_wall: Duration::ZERO,
                    };
                    let block_start = Instant::now();
                    let mut assign_buf = Vec::with_capacity(block_n * assign_record_width(fanout));
                    for gather_row in block_start_idx..block_end_idx {
                        let (leaders_for_point, approx_wall, exact_wall, row_dco) =
                            d0_rabitq_sidecar_assign_row(
                                &point_gather,
                                gather_row,
                                &leader_gather,
                                leaders,
                                &[],
                                0.0,
                                &[],
                                &[],
                                dim,
                                fanout,
                                survivor_count,
                                PiPNNGpuSubtreeDcoRerankMode::None,
                                false,
                            )?;
                        fold.approx_wall += approx_wall;
                        fold.exact_wall += exact_wall;
                        fold.dco.merge(row_dco);
                        for &lid in &leaders_for_point {
                            fold.raw_counts[lid as usize] += 1;
                        }
                        append_assign_record_bytes(&mut assign_buf, &leaders_for_point, fanout)?;
                    }
                    fold.profile.gemm += fold.approx_wall;
                    fold.profile.total_wall = block_start.elapsed();
                    fold.assign_chunks.push(assign_buf);
                    Ok::<D0DcoFold, crate::common::AnnError>(fold)
                })
                .collect::<AnnResult<Vec<_>>>()?;

            for fold in folds {
                profile.merge(fold.profile);
                dco.merge(fold.dco);
                for (lid, count) in fold.raw_counts.into_iter().enumerate() {
                    merged_raw_counts[lid] += count;
                }
                for bytes in fold.assign_chunks {
                    let spool_write_start = Instant::now();
                    spool_writer.write_all(&bytes)?;
                    profile.spool_write += spool_write_start.elapsed();
                }
            }
        }
    }

    raw_counts.copy_from_slice(&merged_raw_counts);
    let flush_start = Instant::now();
    spool_writer.flush()?;
    profile.flush += flush_start.elapsed();
    profile.total_wall = total_start.elapsed();
    tracing::info!(
        "[rbc/d0-rabitq-sidecar-spool] rows={} leaders={} fanout={} survivors={} rerank={} sidecar_resident={} sidecar_gather_ms={} approx_ms={} exact_ms={} point_reads={} range_reads={} range_rows={} hit_ratio={:.2} workers={} spool_write_ms={} flush_ms={} total_ms={}",
        cur.len(),
        nl,
        fanout,
        survivor_count,
        params.gpu_subtree_d0_dco_rerank_mode.as_str(),
        sidecar.is_resident(),
        sidecar_gather_wall.as_millis(),
        profile.gemm.as_millis(),
        profile.topk.as_millis(),
        io_stats.point_calls,
        io_stats.range_calls,
        io_stats.range_rows_read,
        io_stats.range_hit_ratio(),
        num_workers,
        profile.spool_write.as_millis(),
        profile.flush.as_millis(),
        profile.total_wall.as_millis(),
    );
    let approx_wall = profile.gemm;
    let exact_wall = profile.topk;
    Ok(D0DcoSpoolProfile {
        gemm: profile,
        dco,
        sidecar_gather_wall,
        approx_wall,
        exact_wall,
    })
}

#[allow(clippy::too_many_arguments)]
fn compute_clusters_sq_sidecar_dco_to_spool_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
    memory_budget_bytes: Option<usize>,
    spool_writer: &mut BufWriter<File>,
    raw_counts: &mut [usize],
    sidecar: &SqWmmaSidecar,
    params: &PiPNNParams,
) -> AnnResult<D0DcoSpoolProfile> {
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let fanout = assign_record_fanout(local_fanout.min(nl.max(1)));
    let survivor_count = params
        .gpu_subtree_d0_dco_survivors
        .max(fanout)
        .min(nl.max(1));
    if params.gpu_subtree_d0_dco_rerank_mode != PiPNNGpuSubtreeDcoRerankMode::None {
        return Err(AnnError::log_index_error(
            "D0 sq-int8-filter requires rerank mode none".to_string(),
        ));
    }
    if params.gpu_subtree_d0_dco_audit {
        return Err(AnnError::log_index_error(
            "D0 sq-int8-filter does not support raw audit".to_string(),
        ));
    }
    if sidecar.header().rows != dataset.len() || sidecar.header().dim != dim {
        return Err(AnnError::log_index_error(format!(
            "D0 SQ-int8 sidecar shape mismatch: sidecar rows={} dim={} dataset rows={} dim={}",
            sidecar.header().rows,
            sidecar.header().dim,
            dataset.len(),
            dim
        )));
    }
    if raw_counts.len() != nl {
        return Err(AnnError::log_index_error(format!(
            "D0 SQ-int8 raw_counts shape mismatch: raw_counts={} leaders={nl}",
            raw_counts.len()
        )));
    }

    let (point_tile_size, _) =
        choose_gemm_tile_sizes_with_override_and_budget(nl, dim, memory_budget_bytes);
    let leader_gather = d0_sq_gather_dense_i8_for_cpu_filter(sidecar.gather(leaders)?)?;
    let sq_cpu_kernel = resolve_sq_int8_cpu_kernel(params.gpu_subtree_d0_sq_cpu_kernel)?;
    let leader_code_sums = d0_sq_leader_code_sums_for_kernel(&leader_gather, sq_cpu_kernel);
    let mut sidecar_gather_wall = leader_gather.gather_wall;
    let mut profile = GemmProfile::default();
    let metadata_bytes = cur
        .len()
        .saturating_add(nl)
        .saturating_mul(sidecar.header().padded_dim)
        .saturating_mul(size_of::<i8>())
        .saturating_add(
            cur.len()
                .saturating_add(nl)
                .saturating_mul(size_of::<f32>() * 2),
        );
    let mut dco = GpuSubtreeAssignmentDcoTelemetry {
        nodes: 1,
        metadata_bytes,
        ..GpuSubtreeAssignmentDcoTelemetry::default()
    };
    let num_workers = rayon::current_num_threads().max(1);
    let batch_points = choose_prefetch_batch_points_for_budget(
        point_tile_size,
        dim,
        choose_spool_prefetch_workers(num_workers, memory_budget_bytes),
        memory_budget_bytes,
    );
    let mut merged_raw_counts = vec![0usize; nl];

    struct D0SqDcoFold {
        profile: GemmProfile,
        dco: GpuSubtreeAssignmentDcoTelemetry,
        raw_counts: Vec<usize>,
        assign_chunks: Vec<Vec<u8>>,
        approx_wall: Duration,
    }

    for ids in cur.chunks(batch_points.max(1)) {
        let point_gather = d0_sq_gather_dense_i8_for_cpu_filter(sidecar.gather(ids)?)?;
        sidecar_gather_wall += point_gather.gather_wall;
        let compute_block_points =
            choose_compute_block_points_for_batch(point_tile_size, ids.len(), num_workers);
        let folds: Vec<D0SqDcoFold> = (0..ids.len())
            .into_par_iter()
            .step_by(compute_block_points)
            .map(|block_start_idx| {
                let block_end_idx = (block_start_idx + compute_block_points).min(ids.len());
                let block_n = block_end_idx - block_start_idx;
                let mut fold = D0SqDcoFold {
                    profile: GemmProfile {
                        blocks: 1,
                        ..GemmProfile::default()
                    },
                    dco: GpuSubtreeAssignmentDcoTelemetry::default(),
                    raw_counts: vec![0usize; nl],
                    assign_chunks: Vec::new(),
                    approx_wall: Duration::ZERO,
                };
                let block_start = Instant::now();
                let mut assign_buf = Vec::with_capacity(block_n * assign_record_width(fanout));
                for gather_row in block_start_idx..block_end_idx {
                    let (leaders_for_point, approx_wall, row_dco) =
                        d0_sq_sidecar_assign_row_with_cpu_kernel(
                            &point_gather,
                            gather_row,
                            &leader_gather,
                            leaders,
                            fanout,
                            survivor_count,
                            sq_cpu_kernel,
                            leader_code_sums.as_deref(),
                        )?;
                    fold.approx_wall += approx_wall;
                    fold.dco.merge(row_dco);
                    for &lid in &leaders_for_point {
                        fold.raw_counts[lid as usize] += 1;
                    }
                    append_assign_record_bytes(&mut assign_buf, &leaders_for_point, fanout)?;
                }
                fold.profile.gemm += fold.approx_wall;
                fold.profile.total_wall = block_start.elapsed();
                fold.assign_chunks.push(assign_buf);
                Ok::<D0SqDcoFold, crate::common::AnnError>(fold)
            })
            .collect::<AnnResult<Vec<_>>>()?;

        for fold in folds {
            profile.merge(fold.profile);
            dco.merge(fold.dco);
            for (lid, count) in fold.raw_counts.into_iter().enumerate() {
                merged_raw_counts[lid] += count;
            }
            for bytes in fold.assign_chunks {
                let spool_write_start = Instant::now();
                spool_writer.write_all(&bytes)?;
                profile.spool_write += spool_write_start.elapsed();
            }
        }
    }

    raw_counts.copy_from_slice(&merged_raw_counts);
    let flush_start = Instant::now();
    spool_writer.flush()?;
    profile.flush += flush_start.elapsed();
    profile.total_wall = total_start.elapsed();
    tracing::info!(
        "[rbc/d0-sq-sidecar-spool] rows={} all_rows={} leaders={} dim={} padded_dim={} fanout={} survivors={} cpu_kernel={} sidecar_bytes={} sidecar_gather_ms={} approx_ms={} exact_ms=0 workers={} spool_write_ms={} flush_ms={} total_ms={}",
        cur.len(),
        sidecar.header().rows,
        nl,
        dim,
        sidecar.header().padded_dim,
        fanout,
        survivor_count,
        sq_cpu_kernel.as_str(),
        sidecar
            .header()
            .codes_bytes
            .saturating_add(sidecar.header().meta_rows_bytes),
        sidecar_gather_wall.as_millis(),
        profile.gemm.as_millis(),
        num_workers,
        profile.spool_write.as_millis(),
        profile.flush.as_millis(),
        profile.total_wall.as_millis(),
    );
    let approx_wall = profile.gemm;
    Ok(D0DcoSpoolProfile {
        gemm: profile,
        dco,
        sidecar_gather_wall,
        approx_wall,
        exact_wall: Duration::ZERO,
    })
}

fn d0_sq_gather_dense_i8_for_cpu_filter(
    gather: SqWmmaGatheredInput,
) -> AnnResult<SqWmmaGatheredInput> {
    let rows = gather.global_ids.len();
    match gather.code_layout {
        SqWmmaCodeLayout::DenseI8 => {
            let expected = rows.checked_mul(gather.padded_dim).ok_or_else(|| {
                AnnError::log_index_error(
                    "D0 SQ-int8 dense gathered code length overflows".to_string(),
                )
            })?;
            if gather.code_row_bytes != gather.padded_dim || gather.codes.len() != expected {
                return Err(AnnError::log_index_error(format!(
                    "D0 SQ-int8 dense gathered shape mismatch: codes={} rows={} padded_dim={} code_row_bytes={}",
                    gather.codes.len(),
                    rows,
                    gather.padded_dim,
                    gather.code_row_bytes
                )));
            }
            Ok(gather)
        }
        SqWmmaCodeLayout::PackedS4 => {
            let dense_codes = unpack_sq_s4_codes(&gather.codes, rows, gather.padded_dim)?;
            Ok(SqWmmaGatheredInput {
                codes: dense_codes,
                code_layout: SqWmmaCodeLayout::DenseI8,
                code_row_bytes: gather.padded_dim,
                ..gather
            })
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn compute_clusters_rabitq_split_sidecar_dco_to_spool_budgeted(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
    spool_writer: &mut BufWriter<File>,
    raw_counts: &mut [usize],
    sidecar: &RabitqSplitSidecar,
    params: &PiPNNParams,
) -> AnnResult<D0DcoSpoolProfile> {
    let total_start = Instant::now();
    let nl = leaders.len();
    let dim = dataset.dim();
    let fanout = assign_record_fanout(local_fanout.min(nl.max(1)));
    let survivor_count = params
        .gpu_subtree_d0_dco_survivors
        .max(fanout)
        .min(nl.max(1));
    if params.gpu_subtree_d0_dco_rerank_mode != PiPNNGpuSubtreeDcoRerankMode::None {
        return Err(AnnError::log_index_error(
            "D0 rabitq-split-filter requires rerank mode none".to_string(),
        ));
    }
    if params.gpu_subtree_d0_dco_audit {
        return Err(AnnError::log_index_error(
            "D0 rabitq-split-filter does not support raw audit".to_string(),
        ));
    }
    if sidecar.header().rows != dataset.len() || sidecar.header().dim != dim {
        return Err(AnnError::log_index_error(format!(
            "D0 RabitQ-Library split sidecar shape mismatch: sidecar rows={} dim={} dataset rows={} dim={}",
            sidecar.header().rows,
            sidecar.header().dim,
            dataset.len(),
            dim
        )));
    }
    if raw_counts.len() != nl {
        return Err(AnnError::log_index_error(format!(
            "D0 RabitQ-Library split raw_counts shape mismatch: raw_counts={} leaders={nl}",
            raw_counts.len()
        )));
    }
    for &pid in cur {
        if pid as usize >= sidecar.header().rows {
            return Err(AnnError::log_index_error(format!(
                "D0 RabitQ-Library split cur id {pid} out of bounds for {} rows",
                sidecar.header().rows
            )));
        }
    }

    let mut profile = GemmProfile {
        blocks: 1,
        ..GemmProfile::default()
    };
    let mut io_stats = PointBatchStats::default();
    let leader_read_options = default_rbc_windowed_options(dataset, nl.max(1));
    let leader_read_start = Instant::now();
    let mut leader_data = vec![0.0_f32; nl.saturating_mul(dim)];
    dataset.read_points_windowed_into_batch_stats(
        leaders,
        &mut leader_data,
        &leader_read_options,
        &mut io_stats,
    )?;
    profile.build_x += leader_read_start.elapsed();
    profile.build_x += sidecar.preload_wall();

    let assign = sidecar.assign_d0(&leader_data, nl, fanout, survivor_count)?;
    profile.gemm += assign.coarse_wall;
    profile.topk += assign.boost_wall;

    let mut assign_buf = Vec::with_capacity(cur.len().saturating_mul(assign_record_width(fanout)));
    let mut merged_raw_counts = vec![0usize; nl];
    for &pid in cur {
        let row_start = pid as usize * fanout;
        let row_end = row_start + fanout;
        let row_leaders = &assign.assignments[row_start..row_end];
        for &lid in row_leaders {
            if lid == u16::MAX || lid as usize >= nl {
                return Err(AnnError::log_index_error(format!(
                    "D0 RabitQ-Library split emitted invalid leader id {lid} for row {pid}, leaders={nl}"
                )));
            }
            merged_raw_counts[lid as usize] += 1;
        }
        append_assign_record_bytes(&mut assign_buf, row_leaders, fanout)?;
    }
    let spool_write_start = Instant::now();
    spool_writer.write_all(&assign_buf)?;
    profile.spool_write += spool_write_start.elapsed();
    raw_counts.copy_from_slice(&merged_raw_counts);

    let flush_start = Instant::now();
    spool_writer.flush()?;
    profile.flush += flush_start.elapsed();
    profile.total_wall = total_start.elapsed() + sidecar.preload_wall();

    let dco = GpuSubtreeAssignmentDcoTelemetry {
        nodes: 1,
        rows: cur.len(),
        leader_pairs: cur.len().saturating_mul(nl),
        prefilter_pairs: cur.len().saturating_mul(nl),
        pruned_pairs: cur.len().saturating_mul(nl.saturating_sub(survivor_count)),
        survivor_pairs: cur.len().saturating_mul(survivor_count),
        exact_pairs: 0,
        approx_output_pairs: cur.len().saturating_mul(fanout),
        metadata_bytes: sidecar
            .resident_bytes()
            .saturating_add(leader_data.len().saturating_mul(size_of::<f32>())),
        ..GpuSubtreeAssignmentDcoTelemetry::default()
    };
    tracing::info!(
        "[rbc/d0-rabitq-split-spool] rows={} all_rows={} leaders={} fanout={} survivors={} bits={} ex_bits={} sidecar_prefix={} sidecar_resident_bytes={} sidecar_preload_ms={} leader_point_reads={} leader_range_reads={} leader_range_rows={} leader_hit_ratio={:.2} coarse_ms={} boost_thread_ms={} boosted_pairs={} spool_write_ms={} flush_ms={} total_ms={}",
        cur.len(),
        sidecar.header().rows,
        nl,
        fanout,
        survivor_count,
        sidecar.header().bits,
        sidecar.header().ex_bits,
        sidecar.prefix().display(),
        sidecar.resident_bytes(),
        sidecar.preload_wall().as_millis(),
        io_stats.point_calls,
        io_stats.range_calls,
        io_stats.range_rows_read,
        io_stats.range_hit_ratio(),
        assign.coarse_wall.as_millis(),
        assign.boost_wall.as_millis(),
        assign.boosted_pairs,
        profile.spool_write.as_millis(),
        profile.flush.as_millis(),
        profile.total_wall.as_millis(),
    );

    Ok(D0DcoSpoolProfile {
        gemm: profile,
        dco,
        sidecar_gather_wall: sidecar.preload_wall(),
        approx_wall: assign.coarse_wall,
        exact_wall: assign.boost_wall,
    })
}

#[allow(clippy::too_many_arguments)]
fn d0_rabitq_sidecar_assign_row(
    point_gather: &RabitqPlusGatheredInput,
    point_row: usize,
    leader_gather: &RabitqPlusGatheredInput,
    leader_ids: &[u32],
    exact_point: &[f32],
    exact_point_norm: f32,
    leader_data: &[f32],
    leader_norms: &[f32],
    dim: usize,
    fanout: usize,
    survivor_count: usize,
    rerank_mode: PiPNNGpuSubtreeDcoRerankMode,
    audit: bool,
) -> AnnResult<(
    Vec<u16>,
    Duration,
    Duration,
    GpuSubtreeAssignmentDcoTelemetry,
)> {
    let leader_count = leader_ids.len();
    let approx_start = Instant::now();
    let mut approx_candidates = Vec::with_capacity(leader_count);
    for leader_idx in 0..leader_count {
        approx_candidates.push((
            leader_idx,
            rabitq_gathered_approx_l2(point_gather, point_row, leader_gather, leader_idx, dim),
        ));
    }
    sort_leader_candidates(&mut approx_candidates, leader_ids);
    approx_candidates.truncate(survivor_count);
    let approx_wall = approx_start.elapsed();

    let mut telemetry = GpuSubtreeAssignmentDcoTelemetry {
        rows: 1,
        leader_pairs: leader_count,
        prefilter_pairs: leader_count,
        pruned_pairs: leader_count.saturating_sub(survivor_count),
        survivor_pairs: survivor_count,
        ..GpuSubtreeAssignmentDcoTelemetry::default()
    };

    let exact_start = Instant::now();
    let selected = match rerank_mode {
        PiPNNGpuSubtreeDcoRerankMode::Exact => {
            let mut exact_candidates = Vec::with_capacity(approx_candidates.len());
            for &(leader_idx, _) in &approx_candidates {
                let leader = &leader_data[leader_idx * dim..(leader_idx + 1) * dim];
                exact_candidates.push((
                    leader_idx,
                    exact_l2_from_norms(
                        exact_point,
                        exact_point_norm,
                        leader,
                        leader_norms[leader_idx],
                    ),
                ));
            }
            telemetry.exact_pairs += approx_candidates.len();
            sort_leader_candidates(&mut exact_candidates, leader_ids);
            exact_candidates
        }
        PiPNNGpuSubtreeDcoRerankMode::None => {
            telemetry.approx_output_pairs += fanout.min(approx_candidates.len());
            approx_candidates
        }
        PiPNNGpuSubtreeDcoRerankMode::ExactStamp => {
            return Err(AnnError::log_index_error(
                "D0 dense-i8 RabitQ+ DCO does not support exact-stamp rerank".to_string(),
            ));
        }
    };
    let exact_wall = exact_start.elapsed();

    if audit {
        if exact_point.is_empty() || leader_data.is_empty() {
            return Err(AnnError::log_index_error(
                "D0 dense-i8 RabitQ+ DCO audit requires raw vectors".to_string(),
            ));
        }
        telemetry.false_prune_audit_pairs += leader_count;
        let mut exact_all = Vec::with_capacity(leader_count);
        for leader_idx in 0..leader_count {
            let leader = &leader_data[leader_idx * dim..(leader_idx + 1) * dim];
            exact_all.push((
                leader_idx,
                exact_l2_from_norms(
                    exact_point,
                    exact_point_norm,
                    leader,
                    leader_norms[leader_idx],
                ),
            ));
        }
        sort_leader_candidates(&mut exact_all, leader_ids);
        let selected_ids = selected
            .iter()
            .take(fanout.min(selected.len()))
            .map(|&(leader_idx, _)| leader_idx)
            .collect::<Vec<_>>();
        telemetry.false_prune_audit_misses += exact_all
            .iter()
            .take(fanout.min(exact_all.len()))
            .filter(|&&(leader_idx, _)| !selected_ids.contains(&leader_idx))
            .count();
    }

    let mut out = Vec::with_capacity(fanout.min(selected.len()));
    for &(leader_idx, _) in selected.iter().take(fanout.min(selected.len())) {
        out.push(u16::try_from(leader_idx).map_err(|_| {
            AnnError::log_index_error(format!(
                "D0 dense-i8 RabitQ+ DCO leader index {leader_idx} exceeds assignment record capacity"
            ))
        })?);
    }
    Ok((out, approx_wall, exact_wall, telemetry))
}

#[cfg_attr(not(test), allow(dead_code))]
fn d0_sq_sidecar_assign_row(
    point_gather: &SqWmmaGatheredInput,
    point_row: usize,
    leader_gather: &SqWmmaGatheredInput,
    leader_ids: &[u32],
    fanout: usize,
    survivor_count: usize,
) -> AnnResult<(Vec<u16>, Duration, GpuSubtreeAssignmentDcoTelemetry)> {
    let leader_count = leader_ids.len();
    let survivor_count = survivor_count.min(leader_count);
    let approx_start = Instant::now();
    let mut approx_candidates = Vec::with_capacity(leader_count);
    for leader_idx in 0..leader_count {
        approx_candidates.push((
            leader_idx,
            sq_gathered_approx_l2(point_gather, point_row, leader_gather, leader_idx),
        ));
    }
    sort_leader_candidates(&mut approx_candidates, leader_ids);
    approx_candidates.truncate(survivor_count);
    let approx_wall = approx_start.elapsed();

    let mut telemetry = GpuSubtreeAssignmentDcoTelemetry {
        rows: 1,
        leader_pairs: leader_count,
        prefilter_pairs: leader_count,
        pruned_pairs: leader_count.saturating_sub(survivor_count),
        survivor_pairs: survivor_count,
        ..GpuSubtreeAssignmentDcoTelemetry::default()
    };
    telemetry.approx_output_pairs += fanout.min(approx_candidates.len());

    let mut out = Vec::with_capacity(fanout.min(approx_candidates.len()));
    for &(leader_idx, _) in approx_candidates
        .iter()
        .take(fanout.min(approx_candidates.len()))
    {
        out.push(u16::try_from(leader_idx).map_err(|_| {
            AnnError::log_index_error(format!(
                "D0 SQ-int8 DCO leader index {leader_idx} exceeds assignment record capacity"
            ))
        })?);
    }
    Ok((out, approx_wall, telemetry))
}

fn d0_sq_sidecar_assign_row_with_cpu_kernel(
    point_gather: &SqWmmaGatheredInput,
    point_row: usize,
    leader_gather: &SqWmmaGatheredInput,
    leader_ids: &[u32],
    fanout: usize,
    survivor_count: usize,
    kernel: SqInt8CpuKernel,
    leader_code_sums: Option<&[i32]>,
) -> AnnResult<(Vec<u16>, Duration, GpuSubtreeAssignmentDcoTelemetry)> {
    let leader_count = leader_ids.len();
    let survivor_count = survivor_count.min(leader_count);
    if point_gather.padded_dim != leader_gather.padded_dim {
        return Err(AnnError::log_index_error(format!(
            "D0 SQ-int8 padded dim mismatch: point={} leader={}",
            point_gather.padded_dim, leader_gather.padded_dim
        )));
    }
    if point_gather.code_layout != SqWmmaCodeLayout::DenseI8
        || leader_gather.code_layout != SqWmmaCodeLayout::DenseI8
        || point_gather.code_row_bytes != point_gather.padded_dim
        || leader_gather.code_row_bytes != leader_gather.padded_dim
    {
        return Err(AnnError::log_index_error(format!(
            "D0 SQ-int8 CPU filter requires dense-i8 gathered codes: point_layout={} point_row_bytes={} leader_layout={} leader_row_bytes={} padded_dim={}",
            point_gather.code_layout.as_str(),
            point_gather.code_row_bytes,
            leader_gather.code_layout.as_str(),
            leader_gather.code_row_bytes,
            point_gather.padded_dim
        )));
    }
    if point_gather.codes.len()
        != point_gather
            .global_ids
            .len()
            .saturating_mul(point_gather.padded_dim)
        || leader_gather.codes.len()
            != leader_gather
                .global_ids
                .len()
                .saturating_mul(leader_gather.padded_dim)
    {
        return Err(AnnError::log_index_error(format!(
            "D0 SQ-int8 dense gathered code length mismatch: point_codes={} point_rows={} leader_codes={} leader_rows={} padded_dim={}",
            point_gather.codes.len(),
            point_gather.global_ids.len(),
            leader_gather.codes.len(),
            leader_gather.global_ids.len(),
            point_gather.padded_dim
        )));
    }
    if let Some(sums) = leader_code_sums
        && sums.len() != leader_count
    {
        return Err(AnnError::log_index_error(format!(
            "D0 SQ-int8 leader code sum mismatch: sums={} leaders={leader_count}",
            sums.len()
        )));
    }

    let approx_start = Instant::now();
    let point_start = point_row * point_gather.padded_dim;
    let point_code = &point_gather.codes[point_start..point_start + point_gather.padded_dim];
    let mut best = Vec::with_capacity(survivor_count);
    let mut leader_idx = 0usize;
    if kernel == SqInt8CpuKernel::Avx512Vnni
        && point_gather.padded_dim % 64 == 0
        && let Some(sums) = leader_code_sums
    {
        while leader_idx + 4 <= leader_count {
            let leader_start0 = leader_idx * leader_gather.padded_dim;
            let leader_start1 = leader_start0 + leader_gather.padded_dim;
            let leader_start2 = leader_start1 + leader_gather.padded_dim;
            let leader_start3 = leader_start2 + leader_gather.padded_dim;
            let leader_code0 =
                &leader_gather.codes[leader_start0..leader_start0 + leader_gather.padded_dim];
            let leader_code1 =
                &leader_gather.codes[leader_start1..leader_start1 + leader_gather.padded_dim];
            let leader_code2 =
                &leader_gather.codes[leader_start2..leader_start2 + leader_gather.padded_dim];
            let leader_code3 =
                &leader_gather.codes[leader_start3..leader_start3 + leader_gather.padded_dim];
            let dots = sq_int8_dot4_with_resolved_kernel_and_right_sums_unchecked(
                point_code,
                [leader_code0, leader_code1, leader_code2, leader_code3],
                kernel,
                Some([
                    sums[leader_idx],
                    sums[leader_idx + 1],
                    sums[leader_idx + 2],
                    sums[leader_idx + 3],
                ]),
            );
            for (offset, dot) in dots.into_iter().enumerate() {
                let current_leader_idx = leader_idx + offset;
                let dist = sq_int8_approx_l2_from_dot(
                    point_gather.scales[point_row],
                    point_gather.norms[point_row],
                    leader_gather.scales[current_leader_idx],
                    leader_gather.norms[current_leader_idx],
                    dot as f32,
                );
                d0_sq_keep_candidate(
                    &mut best,
                    (current_leader_idx, dist),
                    survivor_count,
                    leader_ids,
                );
            }
            leader_idx += 4;
        }
    }
    while leader_idx < leader_count {
        let leader_start = leader_idx * leader_gather.padded_dim;
        let leader_code =
            &leader_gather.codes[leader_start..leader_start + leader_gather.padded_dim];
        let dot = sq_int8_dot_with_resolved_kernel_and_right_sum_unchecked(
            point_code,
            leader_code,
            kernel,
            leader_code_sums.map(|sums| sums[leader_idx]),
        ) as f32;
        let dist = sq_int8_approx_l2_from_dot(
            point_gather.scales[point_row],
            point_gather.norms[point_row],
            leader_gather.scales[leader_idx],
            leader_gather.norms[leader_idx],
            dot,
        );
        d0_sq_keep_candidate(&mut best, (leader_idx, dist), survivor_count, leader_ids);
        leader_idx += 1;
    }
    sort_leader_candidates(&mut best, leader_ids);
    let approx_wall = approx_start.elapsed();

    let mut telemetry = GpuSubtreeAssignmentDcoTelemetry {
        rows: 1,
        leader_pairs: leader_count,
        prefilter_pairs: leader_count,
        pruned_pairs: leader_count.saturating_sub(survivor_count),
        survivor_pairs: survivor_count,
        ..GpuSubtreeAssignmentDcoTelemetry::default()
    };
    telemetry.approx_output_pairs += fanout.min(best.len());

    let mut out = Vec::with_capacity(fanout.min(best.len()));
    for &(leader_idx, _) in best.iter().take(fanout.min(best.len())) {
        out.push(u16::try_from(leader_idx).map_err(|_| {
            AnnError::log_index_error(format!(
                "D0 SQ-int8 DCO leader index {leader_idx} exceeds assignment record capacity"
            ))
        })?);
    }
    Ok((out, approx_wall, telemetry))
}

fn d0_sq_leader_code_sums_for_kernel(
    leader_gather: &SqWmmaGatheredInput,
    kernel: SqInt8CpuKernel,
) -> Option<Vec<i32>> {
    if kernel != SqInt8CpuKernel::Avx512Vnni
        || leader_gather.padded_dim % 64 != 0
        || leader_gather.code_layout != SqWmmaCodeLayout::DenseI8
        || leader_gather.code_row_bytes != leader_gather.padded_dim
    {
        return None;
    }
    Some(
        leader_gather
            .codes
            .chunks_exact(leader_gather.padded_dim)
            .map(|row| row.iter().map(|&value| i32::from(value)).sum())
            .collect(),
    )
}

fn sq_int8_approx_l2_from_dot(
    left_scale: f32,
    left_norm: f32,
    right_scale: f32,
    right_norm: f32,
    dot: f32,
) -> f32 {
    let dist = left_norm + right_norm - 2.0 * left_scale * right_scale * dot;
    if dist <= 0.0 { 0.0 } else { dist }
}

fn d0_sq_keep_candidate(
    best: &mut Vec<(usize, f32)>,
    candidate: (usize, f32),
    limit: usize,
    leader_ids: &[u32],
) {
    if limit == 0 {
        return;
    }
    if best.len() < limit {
        best.push(candidate);
        return;
    }
    let mut worst_idx = 0usize;
    for idx in 1..best.len() {
        if compare_leader_candidate(&best[idx], &best[worst_idx], leader_ids)
            == std::cmp::Ordering::Greater
        {
            worst_idx = idx;
        }
    }
    if compare_leader_candidate(&candidate, &best[worst_idx], leader_ids)
        == std::cmp::Ordering::Less
    {
        best[worst_idx] = candidate;
    }
}

fn rabitq_gathered_approx_l2(
    left: &RabitqPlusGatheredInput,
    left_row: usize,
    right: &RabitqPlusGatheredInput,
    right_row: usize,
    dim: usize,
) -> f32 {
    let left_start = left_row * left.padded_dim;
    let right_start = right_row * right.padded_dim;
    rabitq_approx_l2(
        &left.codes[left_start..left_start + left.padded_dim],
        left.deltas[left_row],
        left.code_sums[left_row],
        left.norms[left_row],
        &right.codes[right_start..right_start + right.padded_dim],
        right.deltas[right_row],
        right.code_sums[right_row],
        right.norms[right_row],
        dim,
    )
}

#[cfg_attr(not(test), allow(dead_code))]
fn sq_gathered_approx_l2(
    left: &SqWmmaGatheredInput,
    left_row: usize,
    right: &SqWmmaGatheredInput,
    right_row: usize,
) -> f32 {
    let left_start = left_row * left.padded_dim;
    let right_start = right_row * right.padded_dim;
    sq_int8_approx_l2(
        &left.codes[left_start..left_start + left.padded_dim],
        left.scales[left_row],
        left.norms[left_row],
        &right.codes[right_start..right_start + right.padded_dim],
        right.scales[right_row],
        right.norms[right_row],
    )
}

fn sort_leader_candidates(candidates: &mut [(usize, f32)], leader_ids: &[u32]) {
    candidates.sort_unstable_by(|left, right| compare_leader_candidate(left, right, leader_ids));
}

fn compare_leader_candidate(
    left: &(usize, f32),
    right: &(usize, f32),
    leader_ids: &[u32],
) -> std::cmp::Ordering {
    let left_finite = left.1.is_finite();
    let right_finite = right.1.is_finite();
    match (left_finite, right_finite) {
        (true, true) => left
            .1
            .total_cmp(&right.1)
            .then_with(|| leader_ids[left.0].cmp(&leader_ids[right.0])),
        (true, false) => std::cmp::Ordering::Less,
        (false, true) => std::cmp::Ordering::Greater,
        (false, false) => left
            .1
            .total_cmp(&right.1)
            .then_with(|| leader_ids[left.0].cmp(&leader_ids[right.0])),
    }
}

fn exact_l2_from_norms(point: &[f32], point_norm: f32, leader: &[f32], leader_norm: f32) -> f32 {
    let dot = point
        .iter()
        .zip(leader)
        .map(|(&lhs, &rhs)| lhs * rhs)
        .sum::<f32>();
    let dist = point_norm + leader_norm - 2.0 * dot;
    if dist <= 0.0 { 0.0 } else { dist }
}

fn compute_clusters_with_backend_to_spool_budgeted(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
    memory_budget_bytes: Option<usize>,
    spool_writer: &mut BufWriter<File>,
    raw_counts: &mut [usize],
) -> AnnResult<GemmProfile> {
    let total_start = Instant::now();
    let fanout = assign_record_fanout(local_fanout.min(leaders.len().max(1)));
    let (clusters, mut profile) =
        compute_backend.assign_clusters_l2(dataset, cur, leaders, fanout, memory_budget_bytes)?;
    let spool_start = Instant::now();
    for cluster in &clusters {
        for &point in cluster {
            let point_idx = point as usize;
            if point_idx >= cur.len() || cur[point_idx] != point {
                return Err(AnnError::log_index_error(
                    "backend-to-spool root assignment requires identity-ordered root point ids"
                        .to_string(),
                ));
            }
        }
    }
    let mut per_point_leaders: Vec<Vec<u16>> = vec![Vec::new(); cur.len()];
    for (leader_idx, cluster) in clusters.iter().enumerate() {
        if leader_idx >= raw_counts.len() {
            return Err(AnnError::log_index_error(format!(
                "backend returned cluster {leader_idx} beyond raw count length {}",
                raw_counts.len()
            )));
        }
        raw_counts[leader_idx] = cluster.len();
        let leader = u16::try_from(leader_idx).map_err(|_| {
            AnnError::log_index_error(format!(
                "backend returned leader index {leader_idx} beyond assignment record capacity"
            ))
        })?;
        for &point in cluster {
            per_point_leaders[point as usize].push(leader);
        }
    }
    for leaders_for_point in per_point_leaders {
        write_assign_record(spool_writer, &leaders_for_point, fanout)?;
    }
    profile.spool_write += spool_start.elapsed();
    let flush_start = Instant::now();
    spool_writer.flush()?;
    profile.flush += flush_start.elapsed();
    profile.total_wall = total_start.elapsed();
    Ok(profile)
}

pub(super) fn compute_clusters_gemm_cpu(
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
) -> AnnResult<(Vec<Vec<u32>>, GemmProfile)> {
    compute_clusters_gemm_budgeted(dataset, cur, leaders, local_fanout, None)
}

pub(super) fn compute_clusters_gemm_with_backend(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    cur: &[u32],
    leaders: &[u32],
    local_fanout: usize,
    memory_budget_bytes: Option<usize>,
) -> AnnResult<(Vec<Vec<u32>>, GemmProfile)> {
    compute_backend.assign_clusters_l2(dataset, cur, leaders, local_fanout, memory_budget_bytes)
}

#[inline]
fn should_dedup_cluster(_params: &PiPNNParams, depth: usize, local_fanout: usize) -> bool {
    depth <= 1 || local_fanout > 1
}

#[inline]
fn should_use_external_assign(
    params: &PiPNNParams,
    depth: usize,
    cluster_len: usize,
    has_external_run_store: bool,
) -> bool {
    params.oom_enable
        && has_external_run_store
        && depth <= EXTERNAL_ASSIGN_DEPTH_LIMIT
        && (depth == 0 || cluster_len >= MIN_EXTERNAL_ASSIGN_POINTS_NON_ROOT)
}

fn stop_root_d00_with_child_run(
    external_run_store: Option<&Arc<Mutex<ExternalRunStore>>>,
    depth: usize,
    points: &[u32],
    seed: u64,
    stats: &mut PartitionStats,
) -> AnnResult<()> {
    let run_store = external_run_store.ok_or_else(|| {
        AnnError::log_index_error(
            "root_stop_after_d00 fallback requires an external child run store".to_string(),
        )
    })?;
    let mut guard = run_store.lock();
    let extent = write_child_run(&mut guard, depth, points)?;
    guard.finalize()?;
    stats.root_stopped_child_runs = vec![ChildRun {
        extents: vec![extent],
        len: points.len(),
        seed,
    }];
    Ok(())
}

#[inline]
fn root_stop_child_seed(seed: u64, depth: usize) -> u64 {
    seed.wrapping_add(depth as u64 + 1)
        .wrapping_mul(0x9e3779b97f4a7c15)
}

/// Parallel recursive RBC partitioning.
/// When a cluster splits into multiple sub-clusters, they are processed in parallel
/// using rayon::join (binary tree of joins for arbitrary fan-out).
fn rbc_recurse_parallel(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    mut cur: Vec<u32>,
    depth: usize,
    parent_n: usize,
    metric: Metric,
    params: &PiPNNParams,
    adaptive_c_max: usize,
    min_recurse_size: usize,
    seed: u64,
    pb: &ProgressBar,
    external_run_store: Option<&Arc<Mutex<ExternalRunStore>>>,
    resident_options: Option<ResidentSubtreeOptions<'_>>,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    root_fanout_state: &RootFanoutState,
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<PartitionStats> {
    let expected_leaves = (cur.len() / adaptive_c_max.max(1)).max(4);
    let mut stats = PartitionStats::new(params.max_depth, expected_leaves);

    stats.max_depth_seen = stats.max_depth_seen.max(depth);
    stats.max_cluster_size_seen = stats.max_cluster_size_seen.max(cur.len());

    if cur.is_empty() {
        return Ok(stats);
    }

    let original_n = cur.len();
    let mut n = original_n;
    let stop_after_root_d00 = params.root_stop_after_d00 && depth == 0;

    if depth >= params.max_depth {
        if stop_after_root_d00 {
            stop_root_d00_with_child_run(
                external_run_store,
                depth,
                &cur,
                root_stop_child_seed(seed, depth),
                &mut stats,
            )?;
            return Ok(stats);
        }
        emit_leaf(
            dataset,
            metric,
            params,
            &mut cur,
            depth,
            LeafReason::MaxDepth,
            true,
            params.kernel_safe_leaf_size(),
            &mut stats,
            leaf_emitter,
        )?;
        return Ok(stats);
    }

    if depth >= 3 {
        let shrink_ratio = parent_n as f32 / n as f32;
        if shrink_ratio < params.min_shrink_ratio {
            emit_leaf(
                dataset,
                metric,
                params,
                &mut cur,
                depth,
                LeafReason::ShrinkRatio,
                true,
                params.kernel_safe_leaf_size(),
                &mut stats,
                leaf_emitter,
            )?;
            return Ok(stats);
        }
    }

    let use_root_radius = depth == 0 && root_fanout_state.is_variable_root();
    let local_fanout = root_fanout_state
        .variable_fixed_fanout()
        .filter(|_| use_root_radius)
        .unwrap_or_else(|| params.adaptive_fanout(n, depth));
    let dedup_cur = depth != 0 && should_dedup_cluster(params, depth, local_fanout);

    if depth != 0 {
        let before_dedup = cur.len();
        let dedup_start = Instant::now();
        if dedup_cur {
            cur.sort_unstable();
            cur.dedup();
        }
        stats.record_phase_time(RbcPhase::CurDedup, dedup_start.elapsed());
        stats.record_dedup(dedup_cur, before_dedup, cur.len());
        if cur.is_empty() {
            stats.record_assignments(original_n, 0);
            return Ok(stats);
        }
        stats.record_assignments(original_n, cur.len());
    } else {
        stats.record_assignments(n, n);
    }

    n = cur.len();

    if n <= adaptive_c_max {
        if stop_after_root_d00 {
            stop_root_d00_with_child_run(
                external_run_store,
                depth,
                &cur,
                root_stop_child_seed(seed, depth),
                &mut stats,
            )?;
            return Ok(stats);
        }
        emit_leaf(
            dataset,
            metric,
            params,
            &mut cur,
            depth,
            LeafReason::NaturalSize,
            false,
            params.kernel_safe_leaf_size(),
            &mut stats,
            leaf_emitter,
        )?;
        return Ok(stats);
    }

    if depth >= 3 && n <= min_recurse_size {
        emit_leaf(
            dataset,
            metric,
            params,
            &mut cur,
            depth,
            LeafReason::MinRecurse,
            false,
            params.kernel_safe_leaf_size(),
            &mut stats,
            leaf_emitter,
        )?;
        return Ok(stats);
    }

    if n < adaptive_c_max * 3 && depth >= 5 {
        emit_leaf(
            dataset,
            metric,
            params,
            &mut cur,
            depth,
            LeafReason::SmallDeep,
            false,
            params.kernel_safe_leaf_size(),
            &mut stats,
            leaf_emitter,
        )?;
        return Ok(stats);
    }

    let adaptive_psamp = params.adaptive_psamp_fraction(n, depth);
    let max_leaders = params.max_leaders.min(n);
    let mut num_leaders = ((adaptive_psamp * n as f64).round() as usize).max(2);
    num_leaders = num_leaders.min(max_leaders);

    let mut merged: Vec<Vec<u32>> = Vec::new();
    let mut external_attempt: Option<ExternalPartitionAttempt> = None;
    let mut attempts_for_current = 0usize;
    // Derive a deterministic RNG from seed + depth + cluster size to avoid needing &mut Rng
    let mut rng =
        StdRng::seed_from_u64(seed ^ (depth as u64).wrapping_mul(6364136223846793005) ^ (n as u64));

    for _ in 0..6 {
        attempts_for_current += 1;

        let leaders: Vec<u32> = if depth == 0 && attempts_for_current == 1 {
            root_fanout_state
                .forced_root_leaders
                .clone()
                .unwrap_or_else(|| {
                    let leader_pos = index::sample(&mut rng, n, num_leaders);
                    leader_pos.iter().map(|pos| cur[pos]).collect()
                })
        } else {
            let leader_pos = index::sample(&mut rng, n, num_leaders);
            leader_pos.iter().map(|pos| cur[pos]).collect()
        };
        num_leaders = leaders.len();

        let mut local_fanout = local_fanout;
        if num_leaders > 1 {
            local_fanout = local_fanout.min(num_leaders);
        } else {
            local_fanout = 1;
        }

        stats.record_partition_attempt(depth, n, num_leaders, local_fanout);

        let use_external_assign =
            should_use_external_assign(params, depth, n, external_run_store.is_some());
        if use_external_assign {
            let compute_task = resident_options.map(|options| options.memory.enter_compute_task());
            let attempt = partition_external_once(
                compute_backend,
                dataset,
                &cur,
                depth,
                metric,
                params,
                adaptive_c_max,
                &leaders,
                local_fanout,
                use_root_radius,
                root_fanout_state,
                compute_task.as_ref().map(RbcComputeTaskGuard::budget_bytes),
                external_run_store.expect("external run store must exist for external assign"),
                runtime_context,
                &mut stats,
            )?;
            if attempt.merge_groups.len() <= 1 && num_leaders < max_leaders {
                stats.record_retry_escalation();
                num_leaders = (num_leaders.saturating_mul(2)).min(max_leaders);
                continue;
            }
            external_attempt = Some(attempt);
            break;
        } else {
            let use_gemm = metric == Metric::L2 && n >= 256 && !use_root_radius;
            let use_radius_gemm = metric == Metric::L2
                && use_root_radius
                && root_fanout_state.radius_config().is_some();
            let use_risk_gemm = metric == Metric::L2
                && use_root_radius
                && root_fanout_state.risk_config().is_some();
            let assign_start = Instant::now();
            let clusters = if use_gemm {
                let compute_task =
                    resident_options.map(|options| options.memory.enter_compute_task());
                let (clusters, gemm_profile) = compute_clusters_gemm_with_backend(
                    compute_backend,
                    dataset,
                    &cur,
                    &leaders,
                    local_fanout,
                    compute_task
                        .as_ref()
                        .map(RbcComputeTaskGuard::budget_bytes)
                        .or_else(|| {
                            params
                                .oom_enable
                                .then(|| params.effective_oom_memory_budget_bytes())
                        }),
                )?;
                stats.record_gemm_profile(gemm_profile);
                clusters
            } else if use_radius_gemm {
                let compute_task =
                    resident_options.map(|options| options.memory.enter_compute_task());
                let (clusters, gemm_profile) = compute_root_radius_clusters_gemm_budgeted(
                    dataset,
                    &cur,
                    &leaders,
                    root_fanout_state,
                    compute_task
                        .as_ref()
                        .map(RbcComputeTaskGuard::budget_bytes)
                        .or_else(|| {
                            params
                                .oom_enable
                                .then(|| params.effective_oom_memory_budget_bytes())
                        }),
                )?;
                stats.record_gemm_profile(gemm_profile);
                clusters
            } else if use_risk_gemm {
                let compute_task =
                    resident_options.map(|options| options.memory.enter_compute_task());
                let (clusters, gemm_profile) = compute_root_risk_clusters_gemm_budgeted(
                    dataset,
                    &cur,
                    &leaders,
                    root_fanout_state,
                    compute_task
                        .as_ref()
                        .map(RbcComputeTaskGuard::budget_bytes)
                        .or_else(|| {
                            params
                                .oom_enable
                                .then(|| params.effective_oom_memory_budget_bytes())
                        }),
                )?;
                stats.record_gemm_profile(gemm_profile);
                clusters
            } else {
                let avg_cluster_size = (n / num_leaders).max(16);
                let mut clusters: Vec<Vec<u32>> = (0..num_leaders)
                    .map(|_| Vec::with_capacity(avg_cluster_size))
                    .collect();
                if local_fanout == 1 {
                    for &idx in &cur {
                        let mut best_lid = 0usize;
                        let mut best_dist = f32::INFINITY;
                        for (lid, &lid_global) in leaders.iter().enumerate() {
                            let d = dataset.get_distance(idx, lid_global, metric)?;
                            if d < best_dist {
                                best_dist = d;
                                best_lid = lid;
                            }
                        }
                        clusters[best_lid].push(idx);
                    }
                } else {
                    for &idx in &cur {
                        let mut top_k = StackTopK::new(local_fanout);
                        for (lid, &lid_global) in leaders.iter().enumerate() {
                            let d = dataset.get_distance(idx, lid_global, metric)?;
                            top_k.push(d, lid);
                        }
                        for &(_, lid) in top_k.iter() {
                            clusters[lid].push(idx);
                        }
                    }
                }
                clusters
            };
            stats.record_assignment_time(depth, assign_start.elapsed());

            let raw_cluster_count = clusters.len();
            let empty_clusters = clusters.iter().filter(|c| c.is_empty()).count();
            let pre_merge_clusters = raw_cluster_count.saturating_sub(empty_clusters);
            let assignments_before_merge = clusters.iter().map(Vec::len).sum::<usize>();

            let merge_start = Instant::now();
            merged = merge_clusters(clusters, params.c_min, adaptive_c_max);
            stats.record_phase_time(RbcPhase::MergeClusters, merge_start.elapsed());
            let post_merge_clusters = merged.len();
            stats.record_merge(pre_merge_clusters, post_merge_clusters, empty_clusters);
            stats.record_assignments(assignments_before_merge, assignments_before_merge);

            if merged.len() <= 1 && num_leaders < max_leaders {
                stats.record_retry_escalation();
                num_leaders = (num_leaders.saturating_mul(2)).min(max_leaders);
                continue;
            }
        }
        break;
    }

    let dedup_merged = should_dedup_cluster(params, depth, local_fanout);
    let mut to_recurse: Vec<SeededCluster> = Vec::new();
    let mut external_recurse_runs: Vec<ChildRun> = Vec::new();
    let child_seed_base = root_stop_child_seed(seed, depth);

    if let Some(attempt) = external_attempt {
        if attempt.merge_groups.is_empty() {
            stats.record_partition_result(PartitionResult::FailedEmpty);
            if stop_after_root_d00 {
                stop_root_d00_with_child_run(
                    external_run_store,
                    depth,
                    &cur,
                    child_seed_base,
                    &mut stats,
                )?;
                return Ok(stats);
            }
            emit_leaf(
                dataset,
                metric,
                params,
                &mut cur,
                depth,
                LeafReason::PartitionFallback,
                false,
                params.kernel_safe_leaf_size(),
                &mut stats,
                leaf_emitter,
            )?;
            return Ok(stats);
        }

        if attempt.merge_groups.len() == 1 {
            stats.record_partition_result(PartitionResult::FailedNoSplit);
            if stop_after_root_d00 {
                stop_root_d00_with_child_run(
                    external_run_store,
                    depth,
                    &cur,
                    child_seed_base,
                    &mut stats,
                )?;
                return Ok(stats);
            }
            emit_leaf(
                dataset,
                metric,
                params,
                &mut cur,
                depth,
                LeafReason::PartitionFallback,
                false,
                params.kernel_safe_leaf_size(),
                &mut stats,
                leaf_emitter,
            )?;
            return Ok(stats);
        }

        if attempts_for_current == 1 {
            stats.record_partition_result(PartitionResult::SuccessFirst);
        } else {
            stats.record_partition_result(PartitionResult::SuccessRetry);
        }

        let mut guard = external_run_store
            .expect("external run store must exist for external assign")
            .lock();
        let materialize_start = Instant::now();
        let materialized = materialize_merged_children_from_spool_with_inline_limit(
            &cur,
            depth,
            attempt.fanout,
            &attempt.merge_groups,
            &attempt.assign_spool,
            &mut guard,
            Some(adaptive_c_max),
        )?;
        stats.record_phase_time(RbcPhase::D1Materialize, materialize_start.elapsed());
        drop(guard);

        for (cluster_idx, child) in materialized.into_iter().enumerate() {
            let cluster_seed = child_seed_base
                ^ (cluster_idx as u64).wrapping_mul(0xbf58476d1ce4e5b9)
                ^ (child.extents.iter().map(|extent| extent.len).sum::<usize>() as u64)
                    .rotate_left(17);
            if stop_after_root_d00 {
                match child.points {
                    Some(points) => {
                        if !points.is_empty() {
                            let extent = {
                                let mut guard = external_run_store
                                    .expect("external run store must exist for root d00 stop")
                                    .lock();
                                write_child_run(&mut guard, depth, &points)?
                            };
                            external_recurse_runs.push(ChildRun {
                                extents: vec![extent],
                                len: points.len(),
                                seed: cluster_seed,
                            });
                        }
                    }
                    None => {
                        let len = child.extents.iter().map(|extent| extent.len).sum();
                        if len > 0 {
                            external_recurse_runs.push(ChildRun {
                                extents: child.extents,
                                len,
                                seed: cluster_seed,
                            });
                        }
                    }
                }
                continue;
            }
            let mut cluster = if let Some(points) = child.points {
                points
            } else {
                let guard = external_run_store
                    .expect("external run store must exist for external materialization")
                    .lock();
                let replay_start = Instant::now();
                let points = read_child_run_chain(&guard, depth, &child.extents)?;
                stats.record_phase_time(RbcPhase::D2Replay, replay_start.elapsed());
                points
            };
            if dedup_merged {
                let dedup_start = Instant::now();
                let before = cluster.len();
                cluster.sort_unstable();
                cluster.dedup();
                let after = cluster.len();
                stats.record_phase_time(RbcPhase::MergedDedup, dedup_start.elapsed());
                stats.record_dedup(true, before, after);
                stats.record_assignments(before, after);
            } else {
                stats.record_dedup(false, cluster.len(), cluster.len());
                stats.record_assignments(cluster.len(), cluster.len());
            }
            if cluster.is_empty() {
                continue;
            }
            if cluster.len() > adaptive_c_max {
                let cluster_seed = child_seed_base
                    ^ (cluster_idx as u64).wrapping_mul(0xbf58476d1ce4e5b9)
                    ^ (cluster.len() as u64).rotate_left(17);
                if depth <= EXTERNAL_CHILD_DEPTH_LIMIT {
                    let extent = {
                        let mut guard = external_run_store
                            .expect("external run store must exist for child run write")
                            .lock();
                        write_child_run(&mut guard, depth, &cluster)?
                    };
                    external_recurse_runs.push(ChildRun {
                        extents: vec![extent],
                        len: cluster.len(),
                        seed: cluster_seed,
                    });
                } else {
                    to_recurse.push(SeededCluster {
                        points: cluster,
                        seed: cluster_seed,
                    });
                }
            } else {
                emit_leaf(
                    dataset,
                    metric,
                    params,
                    &mut cluster,
                    depth + 1,
                    LeafReason::NaturalSize,
                    false,
                    params.kernel_safe_leaf_size(),
                    &mut stats,
                    leaf_emitter,
                )?;
            }
        }
    } else {
        if dedup_merged {
            // Parallelize sort+dedup across clusters (significant win at depth 0 with large
            // clusters)
            let dedup_start = Instant::now();
            let dedup_results: Vec<(usize, usize)> = merged
                .par_iter_mut()
                .map(|cluster| {
                    let before = cluster.len();
                    cluster.sort_unstable();
                    cluster.dedup();
                    (before, cluster.len())
                })
                .collect();
            let dedup_elapsed = dedup_start.elapsed();
            stats.record_phase_time(RbcPhase::MergedDedup, dedup_elapsed);
            for (before_dedup, after_dedup) in dedup_results {
                stats.record_dedup(true, before_dedup, after_dedup);
                stats.record_assignments(before_dedup, after_dedup);
            }
        } else {
            for cluster in &merged {
                stats.record_dedup(false, cluster.len(), cluster.len());
                stats.record_assignments(cluster.len(), cluster.len());
            }
        }
        merged.retain(|cluster| !cluster.is_empty());

        if merged.is_empty() {
            stats.record_partition_result(PartitionResult::FailedEmpty);
            if stop_after_root_d00 {
                stop_root_d00_with_child_run(
                    external_run_store,
                    depth,
                    &cur,
                    child_seed_base,
                    &mut stats,
                )?;
                return Ok(stats);
            }
            emit_leaf(
                dataset,
                metric,
                params,
                &mut cur,
                depth,
                LeafReason::PartitionFallback,
                false,
                params.kernel_safe_leaf_size(),
                &mut stats,
                leaf_emitter,
            )?;
            return Ok(stats);
        }

        if merged.len() == 1 {
            stats.record_partition_result(PartitionResult::FailedNoSplit);
            let mut leaf = merged.pop().unwrap();
            if stop_after_root_d00 {
                stop_root_d00_with_child_run(
                    external_run_store,
                    depth,
                    &leaf,
                    child_seed_base,
                    &mut stats,
                )?;
                return Ok(stats);
            }
            emit_leaf(
                dataset,
                metric,
                params,
                &mut leaf,
                depth,
                LeafReason::PartitionFallback,
                false,
                params.kernel_safe_leaf_size(),
                &mut stats,
                leaf_emitter,
            )?;
            return Ok(stats);
        }

        if attempts_for_current == 1 {
            stats.record_partition_result(PartitionResult::SuccessFirst);
        } else {
            stats.record_partition_result(PartitionResult::SuccessRetry);
        }

        // Separate small clusters (emit as leaves) from large ones (recurse)
        for (cluster_idx, cluster) in merged.into_iter().enumerate() {
            if cluster.len() > adaptive_c_max {
                let cluster_seed = child_seed_base
                    ^ (cluster_idx as u64).wrapping_mul(0xbf58476d1ce4e5b9)
                    ^ (cluster.len() as u64).rotate_left(17);
                if let Some(run_store) =
                    external_run_store.filter(|_| depth <= EXTERNAL_CHILD_DEPTH_LIMIT)
                {
                    let extent = {
                        let mut guard = run_store.lock();
                        write_child_run(&mut guard, depth, &cluster)?
                    };
                    external_recurse_runs.push(ChildRun {
                        extents: vec![extent],
                        len: cluster.len(),
                        seed: cluster_seed,
                    });
                } else {
                    to_recurse.push(SeededCluster {
                        points: cluster,
                        seed: cluster_seed,
                    });
                }
            } else {
                let mut leaf = cluster;
                emit_leaf(
                    dataset,
                    metric,
                    params,
                    &mut leaf,
                    depth + 1,
                    LeafReason::NaturalSize,
                    false,
                    params.kernel_safe_leaf_size(),
                    &mut stats,
                    leaf_emitter,
                )?;
            }
        }
    }

    if depth == 0 {
        log_root_fanout_summary(&root_fanout_state.profile());
    }

    if stop_after_root_d00 {
        if let Some(run_store) = external_run_store {
            run_store.lock().finalize()?;
        }
        stats.root_stopped_child_runs = external_recurse_runs;
        return Ok(stats);
    }

    if !external_recurse_runs.is_empty() {
        let child_stats = parallel_join_child_runs(
            compute_backend,
            dataset,
            external_recurse_runs,
            depth + 1,
            n,
            metric,
            params,
            adaptive_c_max,
            min_recurse_size,
            pb,
            external_run_store.expect("external run store must exist for external recurse runs"),
            resident_options,
            runtime_context,
            root_fanout_state,
            leaf_emitter,
        )?;
        stats.merge_from(child_stats);

        pb.inc(1);
        return Ok(stats);
    }

    // Process sub-clusters in parallel using rayon::join (binary tree)
    let child_stats = parallel_join_clusters(
        compute_backend,
        dataset,
        to_recurse,
        depth + 1,
        n,
        metric,
        params,
        adaptive_c_max,
        min_recurse_size,
        pb,
        external_run_store,
        resident_options,
        runtime_context,
        root_fanout_state,
        leaf_emitter,
    )?;
    stats.merge_from(child_stats);

    // Update progress bar
    pb.inc(1);

    Ok(stats)
}

/// Recursively process a list of clusters in parallel using rayon::join (binary tree
/// decomposition).
fn parallel_join_clusters(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    mut clusters: Vec<SeededCluster>,
    depth: usize,
    parent_n: usize,
    metric: Metric,
    params: &PiPNNParams,
    adaptive_c_max: usize,
    min_recurse_size: usize,
    pb: &ProgressBar,
    external_run_store: Option<&Arc<Mutex<ExternalRunStore>>>,
    resident_options: Option<ResidentSubtreeOptions<'_>>,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    root_fanout_state: &RootFanoutState,
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<PartitionStats> {
    let expected_leaves = (clusters
        .iter()
        .map(|cluster| cluster.points.len())
        .sum::<usize>()
        / adaptive_c_max.max(1))
    .max(4);
    let mut stats = PartitionStats::new(params.max_depth, expected_leaves);

    if clusters.is_empty() {
        return Ok(stats);
    }

    if clusters.len() == 1 {
        let cluster = clusters.pop().unwrap();
        let child_stats = rbc_recurse_parallel(
            compute_backend,
            dataset,
            cluster.points,
            depth,
            parent_n,
            metric,
            params,
            adaptive_c_max,
            min_recurse_size,
            cluster.seed,
            pb,
            external_run_store,
            resident_options,
            runtime_context,
            root_fanout_state,
            leaf_emitter,
        )?;
        stats.merge_from(child_stats);
        return Ok(stats);
    }

    // Split into two halves and process in parallel
    let (left, right) = split_seeded_clusters_balanced(clusters);

    let (left_result, right_result) = rayon::join(
        || {
            parallel_join_clusters(
                compute_backend,
                dataset,
                left,
                depth,
                parent_n,
                metric,
                params,
                adaptive_c_max,
                min_recurse_size,
                pb,
                external_run_store,
                resident_options,
                runtime_context,
                root_fanout_state,
                leaf_emitter,
            )
        },
        || {
            parallel_join_clusters(
                compute_backend,
                dataset,
                right,
                depth,
                parent_n,
                metric,
                params,
                adaptive_c_max,
                min_recurse_size,
                pb,
                external_run_store,
                resident_options,
                runtime_context,
                root_fanout_state,
                leaf_emitter,
            )
        },
    );

    stats.merge_from(left_result?);
    stats.merge_from(right_result?);
    Ok(stats)
}

fn parallel_join_child_runs(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    mut child_runs: Vec<ChildRun>,
    depth: usize,
    parent_n: usize,
    metric: Metric,
    params: &PiPNNParams,
    adaptive_c_max: usize,
    min_recurse_size: usize,
    pb: &ProgressBar,
    external_run_store: &Arc<Mutex<ExternalRunStore>>,
    resident_options: Option<ResidentSubtreeOptions<'_>>,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    root_fanout_state: &RootFanoutState,
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<PartitionStats> {
    let expected_leaves =
        (child_runs.iter().map(|run| run.len).sum::<usize>() / adaptive_c_max.max(1)).max(4);
    let mut stats = PartitionStats::new(params.max_depth, expected_leaves);

    if child_runs.is_empty() {
        return Ok(stats);
    }

    if child_runs.len() == 1 {
        let child_run = child_runs.pop().unwrap();
        let child_stats = recurse_child_run_maybe_resident(
            compute_backend,
            dataset,
            child_run,
            depth,
            parent_n,
            metric,
            params,
            adaptive_c_max,
            min_recurse_size,
            pb,
            external_run_store,
            resident_options,
            runtime_context,
            root_fanout_state,
            leaf_emitter,
        )?;
        stats.merge_from(child_stats);
        return Ok(stats);
    }

    child_runs.sort_unstable_by_key(|run| run.len);
    let split_at = child_runs.len() / 2;
    let right = child_runs.split_off(split_at);
    let left = child_runs;

    let (left_result, right_result) = rayon::join(
        || {
            parallel_join_child_runs(
                compute_backend,
                dataset,
                left,
                depth,
                parent_n,
                metric,
                params,
                adaptive_c_max,
                min_recurse_size,
                pb,
                external_run_store,
                resident_options,
                runtime_context,
                root_fanout_state,
                leaf_emitter,
            )
        },
        || {
            parallel_join_child_runs(
                compute_backend,
                dataset,
                right,
                depth,
                parent_n,
                metric,
                params,
                adaptive_c_max,
                min_recurse_size,
                pb,
                external_run_store,
                resident_options,
                runtime_context,
                root_fanout_state,
                leaf_emitter,
            )
        },
    );

    stats.merge_from(left_result?);
    stats.merge_from(right_result?);
    Ok(stats)
}

fn recurse_child_run_maybe_resident(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    child_run: ChildRun,
    depth: usize,
    parent_n: usize,
    metric: Metric,
    params: &PiPNNParams,
    adaptive_c_max: usize,
    min_recurse_size: usize,
    pb: &ProgressBar,
    external_run_store: &Arc<Mutex<ExternalRunStore>>,
    resident_options: Option<ResidentSubtreeOptions<'_>>,
    runtime_context: GpuSubtreeRuntimeContext<'_>,
    root_fanout_state: &RootFanoutState,
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<PartitionStats> {
    let expected_leaves = (child_run.len / adaptive_c_max.max(1)).max(4);
    let mut stats = PartitionStats::new(params.max_depth, expected_leaves);
    let (base_dir, io_cfg) = {
        let guard = external_run_store.lock();
        (guard.base_dir.clone(), guard.io_config())
    };
    let replay_start = Instant::now();
    let points = read_child_run_chain_from_path(&base_dir, io_cfg, depth - 1, &child_run.extents)?;
    stats.record_phase_time(RbcPhase::D2Replay, replay_start.elapsed());

    if let Some(options) = resident_options.filter(|options| options.materialize) {
        let estimated_bytes = estimate_resident_subtree_bytes(points.len(), dataset.dim());
        if estimated_bytes <= options.memory.single_subtree_cap_bytes() {
            let permit_start = Instant::now();
            if let Some(_permit) = options
                .memory
                .try_acquire_resident_subtree(points.len(), dataset.dim())
            {
                let permit_wait = permit_start.elapsed();
                let read_start = Instant::now();
                let mut resident_data = vec![0.0f32; points.len().saturating_mul(dataset.dim())];
                let mut batch_stats = PointBatchStats::default();
                let read_options = default_rbc_windowed_options(dataset, points.len().max(1));
                dataset.read_points_windowed_into_batch_stats(
                    &points,
                    &mut resident_data,
                    &read_options,
                    &mut batch_stats,
                )?;
                let read_wall = read_start.elapsed();
                let resident_store =
                    ResidentSubsetPointStore::new(points.clone(), dataset.dim(), resident_data)?;
                let resident_bytes = resident_store.resident_bytes().max(estimated_bytes);
                let resident_leaf_emitter = ResidentSubtreeLeafEmitter::new(leaf_emitter);
                let compute_start = Instant::now();
                let child_stats = rbc_recurse_parallel(
                    compute_backend,
                    &resident_store,
                    points,
                    depth,
                    parent_n,
                    metric,
                    params,
                    adaptive_c_max,
                    min_recurse_size,
                    child_run.seed,
                    pb,
                    Some(external_run_store),
                    Some(options.without_materialization()),
                    runtime_context,
                    root_fanout_state,
                    &resident_leaf_emitter,
                )?;
                let compute_wall = compute_start.elapsed();
                stats.record_resident_subtree_hit(
                    child_run.len,
                    resident_bytes,
                    read_wall,
                    compute_wall,
                );
                stats.telemetry.resident_subtree_leaf_count += resident_leaf_emitter.leaf_count();
                stats.telemetry.resident_subtree_emit_wall += resident_leaf_emitter.emit_wall();
                stats.telemetry.resident_subtree_permit_wait += permit_wait;
                stats.merge_from(child_stats);
                return Ok(stats);
            }
            stats.record_resident_subtree_fallback(points.len(), permit_start.elapsed());
        } else {
            stats.record_resident_subtree_fallback(points.len(), Duration::ZERO);
        }
    }

    let child_stats = rbc_recurse_parallel(
        compute_backend,
        dataset,
        points,
        depth,
        parent_n,
        metric,
        params,
        adaptive_c_max,
        min_recurse_size,
        child_run.seed,
        pb,
        Some(external_run_store),
        resident_options,
        runtime_context,
        root_fanout_state,
        leaf_emitter,
    )?;
    stats.merge_from(child_stats);
    Ok(stats)
}

fn rbc_partition_impl_streaming(
    compute_backend: &dyn PiPNNComputeBackend,
    dataset: &dyn PointStore,
    indices: &[u32],
    metric: Metric,
    params: &PiPNNParams,
    _num_threads: u32,
    rng: &mut (impl Rng + Send),
    external_run_store: Option<Arc<Mutex<ExternalRunStore>>>,
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<RbcPartitionTelemetry> {
    let total_size = indices.len();
    if total_size == 0 {
        return Ok(RbcPartitionTelemetry::default());
    }
    let adaptive_c_max = params.adaptive_c_max(total_size);
    let min_recurse_size = adaptive_c_max.saturating_mul(2);
    let root_leaders = select_root_leaders(indices, params, rng);
    let root_fanout_state = if root_leaders.is_empty() {
        RootFanoutState::fixed(params.fanout_top)
    } else {
        initialize_root_fanout_state(dataset, indices, &root_leaders, params, metric, rng)?
    };

    let pb = ProgressBar::new_spinner();
    pb.set_style(
        ProgressStyle::default_spinner()
            .template("{spinner:.green} [{elapsed_precise}] {msg}")
            .unwrap(),
    );

    let expected_leaves = (total_size / adaptive_c_max).max(1000);

    tracing::info!(
        "RBC partition starting: {} points, adaptive_c_max={}, min_recurse={}",
        format_count(total_size),
        format_count(adaptive_c_max),
        format_count(min_recurse_size),
    );

    pb.set_message(format!(
        "leaves=0 depth=0 c_max={} min_recurse={}",
        format_count(adaptive_c_max),
        format_count(min_recurse_size),
    ));

    // Derive a seed from the rng for the recursive parallel function
    let seed: u64 = rng.random();

    let resident_context =
        rbc_memory_context_for_params(params, dataset.dim(), rayon::current_num_threads().max(1));
    let resident_options = resident_context
        .as_ref()
        .map(|memory| ResidentSubtreeOptions {
            memory,
            materialize: true,
        });

    let mut stats = rbc_recurse_parallel(
        compute_backend,
        dataset,
        indices.to_vec(),
        0,
        total_size,
        metric,
        params,
        adaptive_c_max,
        min_recurse_size,
        seed,
        &pb,
        external_run_store.as_ref(),
        resident_options,
        GpuSubtreeRuntimeContext::default(),
        &root_fanout_state,
        leaf_emitter,
    )?;
    stats.max_cluster_size_seen = stats.max_cluster_size_seen.max(total_size);
    stats.telemetry.root_fanout = root_fanout_state.profile();
    // Ensure expected_leaves capacity is reflected
    stats
        .leaf_sizes
        .reserve(expected_leaves.saturating_sub(stats.leaf_sizes.len()));

    pb.finish_and_clear();
    log_final_summary(&stats, total_size, adaptive_c_max, min_recurse_size);

    Ok(stats.telemetry)
}

fn emit_leaf(
    dataset: &dyn PointStore,
    metric: Metric,
    params: &PiPNNParams,
    leaf: &mut Vec<u32>,
    depth: usize,
    reason: LeafReason,
    dedup: bool,
    max_leaf_size: usize,
    stats: &mut PartitionStats,
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<()> {
    let before_dedup = leaf.len();
    if dedup {
        leaf.sort_unstable();
        leaf.dedup();
    }
    stats.record_assignments(before_dedup, leaf.len());

    if leaf.is_empty() {
        return Ok(());
    }

    emit_leaf_with_safety(
        dataset,
        metric,
        params,
        leaf,
        depth,
        reason,
        max_leaf_size.max(1),
        stats,
        leaf_emitter,
    )
}

fn forced_leaf_split_seed(leaf: &[u32], depth: usize, reason: LeafReason) -> u64 {
    let reason_tag = match reason {
        LeafReason::NaturalSize => 0_u64,
        LeafReason::MaxDepth => 1_u64,
        LeafReason::ShrinkRatio => 2_u64,
        LeafReason::SmallDeep => 3_u64,
        LeafReason::MinRecurse => 4_u64,
        LeafReason::PartitionFallback => 5_u64,
    };
    let first = leaf.first().copied().unwrap_or_default() as u64;
    let last = leaf.last().copied().unwrap_or_default() as u64;
    (depth as u64).wrapping_mul(0x9e3779b97f4a7c15)
        ^ (leaf.len() as u64).wrapping_mul(0xbf58476d1ce4e5b9)
        ^ first.rotate_left(17)
        ^ last.rotate_left(41)
        ^ reason_tag
}

fn forced_split_oversized_leaf(
    dataset: &dyn PointStore,
    metric: Metric,
    params: &PiPNNParams,
    leaf: Vec<u32>,
    depth: usize,
    hard_cap: usize,
    seed: u64,
) -> AnnResult<Vec<Vec<u32>>> {
    let n = leaf.len();
    if n <= hard_cap {
        return Ok(vec![leaf]);
    }

    let max_leaders = params.max_leaders.max(2).min(n);
    let mut num_leaders = n.div_ceil(hard_cap).clamp(2, max_leaders);
    let local_fanout_base = params.adaptive_fanout(n, depth).max(1);
    let mut best_split: Option<Vec<Vec<u32>>> = None;
    let mut best_max_child = usize::MAX;
    let mut rng = StdRng::seed_from_u64(seed);

    for _ in 0..FORCED_LEAF_SPLIT_RETRY_LIMIT {
        let leader_pos = index::sample(&mut rng, n, num_leaders);
        let leaders: Vec<u32> = leader_pos.iter().map(|pos| leaf[pos]).collect();
        let local_fanout = local_fanout_base.min(num_leaders).max(1);

        let clusters = if metric == Metric::L2 && n >= 256 {
            compute_clusters_gemm(dataset, &leaf, &leaders, local_fanout)?.0
        } else {
            let avg_cluster_size = (n / num_leaders).max(16);
            let mut clusters: Vec<Vec<u32>> = (0..num_leaders)
                .map(|_| Vec::with_capacity(avg_cluster_size))
                .collect();
            for &idx in &leaf {
                let mut top_k = StackTopK::new(local_fanout);
                for (lid, &lid_global) in leaders.iter().enumerate() {
                    let d = dataset.get_distance(idx, lid_global, metric)?;
                    top_k.push(d, lid);
                }
                for &(_, lid) in top_k.iter() {
                    clusters[lid].push(idx);
                }
            }
            clusters
        };

        let mut merged = merge_clusters(clusters, params.c_min.min(hard_cap), hard_cap);
        if should_dedup_cluster(params, depth, local_fanout) {
            merged.par_iter_mut().for_each(|cluster| {
                cluster.sort_unstable();
                cluster.dedup();
            });
        }
        merged.retain(|cluster| !cluster.is_empty());

        let max_child = merged.iter().map(Vec::len).max().unwrap_or(0);
        if merged.len() > 1 && max_child < n {
            if max_child <= hard_cap {
                return Ok(merged);
            }
            if max_child < best_max_child {
                best_max_child = max_child;
                best_split = Some(merged);
            }
        }

        if num_leaders >= max_leaders {
            break;
        }

        let next_leaders = (num_leaders.saturating_mul(2))
            .min(max_leaders)
            .max(num_leaders + 1);
        if next_leaders == num_leaders {
            break;
        }
        num_leaders = next_leaders;
    }

    if let Some(split) = best_split {
        return Ok(split);
    }

    Ok(leaf.chunks(hard_cap).map(|chunk| chunk.to_vec()).collect())
}

fn emit_leaf_with_safety(
    dataset: &dyn PointStore,
    metric: Metric,
    params: &PiPNNParams,
    leaf: &mut Vec<u32>,
    depth: usize,
    reason: LeafReason,
    max_leaf_size: usize,
    stats: &mut PartitionStats,
    leaf_emitter: &dyn LeafEmitter,
) -> AnnResult<()> {
    if leaf.is_empty() {
        return Ok(());
    }

    if leaf.len() > FORCED_LEAF_HARD_CAP {
        stats.forced_leaf_splits += 1;
        let split_seed = forced_leaf_split_seed(leaf, depth, reason);
        let split_leaves = forced_split_oversized_leaf(
            dataset,
            metric,
            params,
            std::mem::take(leaf),
            depth,
            FORCED_LEAF_HARD_CAP,
            split_seed,
        )?;

        for mut split_leaf in split_leaves {
            emit_leaf_with_safety(
                dataset,
                metric,
                params,
                &mut split_leaf,
                depth,
                reason,
                max_leaf_size,
                stats,
                leaf_emitter,
            )?;
        }
        return Ok(());
    }

    if leaf.len() > max_leaf_size {
        stats.record_oversized_leaf(leaf.len());
    }

    stats.record_leaf(depth, leaf.len(), reason);
    leaf_emitter.emit_leaf(std::mem::take(leaf))?;
    Ok(())
}

fn log_via_progress_bar(pb: &ProgressBar, level: Level, message: impl Into<String>) {
    let enabled = match level {
        Level::ERROR => tracing::enabled!(Level::ERROR),
        Level::WARN => tracing::enabled!(Level::WARN),
        Level::INFO => tracing::enabled!(Level::INFO),
        Level::DEBUG => tracing::enabled!(Level::DEBUG),
        Level::TRACE => tracing::enabled!(Level::TRACE),
    };

    if enabled {
        pb.println(format!("{}: {}", level, message.into()));
    }
}

fn log_partition_warning(
    pb: &ProgressBar,
    depth: usize,
    size: usize,
    attempts: usize,
    leaders: usize,
    reason: &str,
) {
    log_via_progress_bar(
        pb,
        Level::WARN,
        format!(
            "Cluster at depth={} size={} failed after {} attempts (leaders={}): {}",
            depth,
            format_count(size),
            attempts,
            format_count(leaders),
            reason,
        ),
    );
}

fn log_debug_snapshot(
    pb: &ProgressBar,
    stats: &PartitionStats,
    stack: &[(Vec<u32>, usize, usize)],
    current_depth: usize,
) {
    let leaves_by_depth = stats
        .depth_stats
        .iter()
        .enumerate()
        .filter(|(_, depth_stats)| depth_stats.leaves_generated > 0)
        .map(|(depth, depth_stats)| {
            format!("d{}:{}", depth, format_count(depth_stats.leaves_generated))
        })
        .collect::<Vec<_>>()
        .join(", ");

    let failed = stats.partition_failed_empty + stats.partition_failed_nosplit;
    let merge_reduction = if stats.pre_merge_clusters_total > 0 {
        100.0
            - (stats.post_merge_clusters_total as f64 / stats.pre_merge_clusters_total as f64
                * 100.0)
    } else {
        0.0
    };

    log_via_progress_bar(
        pb,
        Level::DEBUG,
        format!(
            "RBC snapshot @ {} | Leaves: {} ({}) | Stack: {} pending | Depth: {} | Attempts: {} (success_first: {}, retry: {}, failed: {}) | Merge: {} -> {} ({:.1}% reduction) | Overlap: {:.1}% deduplicated",
            format_duration(stats.elapsed()),
            format_count(stats.total_leaves()),
            if leaves_by_depth.is_empty() {
                "none".to_string()
            } else {
                leaves_by_depth
            },
            format_count(stack.len()),
            format_depth_range(stack, current_depth),
            format_count(stats.partition_attempts),
            format_count(stats.partition_success_first),
            format_count(stats.partition_success_retry),
            format_count(failed),
            format_count(stats.pre_merge_clusters_total),
            format_count(stats.post_merge_clusters_total),
            merge_reduction,
            stats.overlap_ratio(),
        ),
    );
}

fn log_final_summary(
    stats: &PartitionStats,
    total_size: usize,
    adaptive_c_max: usize,
    min_recurse_size: usize,
) {
    let duration = format_duration(stats.elapsed());
    let total_leaves = stats.total_leaves();
    let total_points = stats.total_points_in_leaves();
    let min_leaf_size = stats.leaf_sizes.iter().min().copied().unwrap_or(0);
    let max_leaf_size = stats.leaf_sizes.iter().max().copied().unwrap_or(0);
    let avg_leaf_size = if total_leaves > 0 {
        total_points as f64 / total_leaves as f64
    } else {
        0.0
    };

    let merge_reduction = if stats.pre_merge_clusters_total > 0 {
        100.0
            - (stats.post_merge_clusters_total as f64 / stats.pre_merge_clusters_total as f64
                * 100.0)
    } else {
        0.0
    };
    let avg_leaders = if stats.partition_attempts > 0 {
        stats.leader_sum as f64 / stats.partition_attempts as f64
    } else {
        0.0
    };
    let avg_fanout = if stats.partition_attempts > 0 {
        stats.fanout_sum as f64 / stats.partition_attempts as f64
    } else {
        0.0
    };

    tracing::info!("========== RBC Partition Complete ==========");
    tracing::info!("Duration: {}", duration);
    tracing::info!("Points: {}", format_count(total_size));
    tracing::info!("Leaf points emitted: {}", format_count(total_points));
    tracing::info!("Leaves: {}", format_count(total_leaves));
    tracing::info!("Adaptive c_max: {}", format_count(adaptive_c_max));
    tracing::info!("Min recurse size: {}", format_count(min_recurse_size));
    tracing::info!("Max depth: {}", format_count(stats.max_depth_seen));
    tracing::info!("Max stack: {}", format_count(stats.max_stack_size));
    tracing::info!(
        "Max cluster size: {}",
        format_count(stats.max_cluster_size_seen)
    );
    tracing::info!(
        "Oversized leaf events: {} (forced_splits={}, total_points={}, largest={})",
        format_count(stats.oversized_leaf_events),
        format_count(stats.forced_leaf_splits),
        format_count(stats.oversized_leaf_points),
        format_count(stats.largest_oversized_leaf),
    );

    tracing::info!("Leaf Termination Reasons:");
    tracing::info!(
        "  Natural size (<=c_max): {} ({:.1}%)",
        format_count(stats.natural_leaf_size),
        percentage(stats.natural_leaf_size, total_leaves),
    );
    tracing::info!(
        "  Min recurse (<=2xc_max): {} ({:.1}%)",
        format_count(stats.early_stop_min_recurse),
        percentage(stats.early_stop_min_recurse, total_leaves),
    );
    tracing::info!(
        "  Shrink ratio insufficient: {} ({:.1}%)",
        format_count(stats.early_stop_shrink_ratio),
        percentage(stats.early_stop_shrink_ratio, total_leaves),
    );
    tracing::info!(
        "  Small deep cluster: {} ({:.1}%)",
        format_count(stats.early_stop_small_deep),
        percentage(stats.early_stop_small_deep, total_leaves),
    );
    tracing::info!(
        "  Max depth reached: {} ({:.1}%)",
        format_count(stats.early_stop_max_depth),
        percentage(stats.early_stop_max_depth, total_leaves),
    );
    tracing::info!(
        "  Partition fallback: {} ({:.1}%)",
        format_count(stats.partition_fallback_leaves),
        percentage(stats.partition_fallback_leaves, total_leaves),
    );

    tracing::info!("Partitioning Efficiency:");
    tracing::info!(
        "  Total attempts: {}",
        format_count(stats.partition_attempts)
    );
    tracing::info!(
        "  Success (first try): {} ({:.1}%)",
        format_count(stats.partition_success_first),
        percentage(stats.partition_success_first, stats.partition_attempts),
    );
    tracing::info!(
        "  Success (after retry): {} ({:.1}%)",
        format_count(stats.partition_success_retry),
        percentage(stats.partition_success_retry, stats.partition_attempts),
    );
    tracing::info!(
        "  Failed (empty merge): {} ({:.1}%)",
        format_count(stats.partition_failed_empty),
        percentage(stats.partition_failed_empty, stats.partition_attempts),
    );
    tracing::info!(
        "  Failed (no split): {} ({:.1}%)",
        format_count(stats.partition_failed_nosplit),
        percentage(stats.partition_failed_nosplit, stats.partition_attempts),
    );
    tracing::info!(
        "  Retry escalations: {}",
        format_count(stats.retry_escalations)
    );

    tracing::info!("Merge Effectiveness:");
    tracing::info!(
        "  Pre-merge clusters: {}",
        format_count(stats.pre_merge_clusters_total)
    );
    tracing::info!(
        "  Post-merge clusters: {} ({:.1}% reduction)",
        format_count(stats.post_merge_clusters_total),
        merge_reduction,
    );
    tracing::info!(
        "  Empty clusters dropped: {}",
        format_count(stats.empty_clusters_dropped)
    );
    tracing::info!(
        "  No-op merges: {} ({:.1}%)",
        format_count(stats.no_op_merges),
        percentage(stats.no_op_merges, stats.partition_attempts),
    );

    tracing::info!("Adaptive Parameters:");
    tracing::info!("  Leaders per attempt (avg): {:.1}", avg_leaders);
    tracing::info!("  Max leaders used: {}", format_count(stats.leader_max));
    tracing::info!("  Fanout per attempt (avg): {:.1}", avg_fanout);
    tracing::info!("  Max fanout used: {}", format_count(stats.fanout_max));

    tracing::info!("Overlap Analysis:");
    tracing::info!(
        "  Assignments before dedup: {}",
        format_count(stats.assignments_before_dedup),
    );
    tracing::info!(
        "  Assignments after dedup: {}",
        format_count(stats.assignments_after_dedup),
    );
    tracing::info!("  Overlap ratio: {:.1}%", stats.overlap_ratio());
    tracing::info!("Dedup Activity:");
    tracing::info!(
        "  Runs: {} | Skipped: {}",
        format_count(stats.dedup_runs),
        format_count(stats.dedup_skipped),
    );
    tracing::info!(
        "  Assignments before/after: {} -> {} (removed={} / {:.3}%)",
        format_count(stats.dedup_assignments_before),
        format_count(stats.dedup_assignments_after),
        format_count(stats.dedup_assignments_removed),
        percentage(
            stats.dedup_assignments_removed,
            stats.dedup_assignments_before
        ),
    );
    tracing::info!("Phase Timing:");
    tracing::info!("  Cur dedup: {}", format_duration(stats.cur_dedup_time));
    tracing::info!(
        "  Cluster assign: {}",
        format_duration(stats.cluster_assign_time)
    );
    tracing::info!("  Merge clusters: {}", format_duration(stats.merge_time));
    tracing::info!(
        "  Merged dedup: {}",
        format_duration(stats.merged_dedup_time)
    );
    tracing::info!(
        "  GEMM profile: total={} build_x={} gemm={} topk={} merge={} blocks={}",
        format_duration(stats.gemm_profile.total_wall),
        format_duration(stats.gemm_profile.build_x),
        format_duration(stats.gemm_profile.gemm),
        format_duration(stats.gemm_profile.topk),
        format_duration(stats.gemm_profile.merge),
        format_count(stats.gemm_profile.blocks),
    );
    tracing::info!(
        "                spool_write={} flush={}",
        format_duration(stats.gemm_profile.spool_write),
        format_duration(stats.gemm_profile.flush),
    );
    tracing::info!(
        "  Resident subtrees: hits={} points={} bytes={} read={} compute={} fallbacks={} permit_wait={}",
        format_count(stats.telemetry.resident_subtree_count),
        format_count(stats.telemetry.resident_subtree_points),
        format_count(stats.telemetry.resident_subtree_bytes),
        format_duration(stats.telemetry.resident_subtree_read_wall),
        format_duration(stats.telemetry.resident_subtree_compute_wall),
        format_count(stats.telemetry.resident_subtree_fallback_count),
        format_duration(stats.telemetry.resident_subtree_permit_wait),
    );

    tracing::info!("Leaf Size Distribution:");
    for (label, count) in leaf_size_buckets(&stats.leaf_sizes) {
        tracing::info!(
            "  {}: {} ({:.1}%)",
            label,
            format_count(count),
            percentage(count, total_leaves),
        );
    }
    tracing::info!(
        "  Min/Avg/Max leaf size: {}/{:.1}/{}",
        format_count(min_leaf_size),
        avg_leaf_size,
        format_count(max_leaf_size),
    );

    tracing::info!("==============================================");

    if tracing::enabled!(Level::DEBUG) {
        tracing::debug!("Depth Distribution:");
        for (depth, depth_stats) in stats.depth_stats.iter().enumerate() {
            if depth_stats.leaves_generated == 0 && depth_stats.clusters_processed == 0 {
                continue;
            }
            let avg_points = if depth_stats.leaves_generated > 0 {
                depth_stats.total_points as f64 / depth_stats.leaves_generated as f64
            } else {
                0.0
            };
            tracing::debug!(
                "  Depth {}: leaves={} processed={} points={} avg_leaf_size={:.1} min={} max={}",
                depth,
                format_count(depth_stats.leaves_generated),
                format_count(depth_stats.clusters_processed),
                format_count(depth_stats.total_points),
                avg_points,
                format_count(depth_stats.min_cluster_size()),
                format_count(depth_stats.max_cluster_size),
            );
        }
    }
}

pub(crate) fn root_fanout_profile_json(profile: &RootFanoutProfile) -> String {
    format!(
        concat!(
            "{{\n",
            "  \"root_fanout\": {{\n",
            "    \"policy\": \"{}\",\n",
            "    \"selection_semantics\": \"{}\",\n",
            "    \"enabled\": {},\n",
            "    \"dry_run\": {},\n",
            "    \"fallback_reason\": {},\n",
            "    \"k\": {},\n",
            "    \"fixed_fanout\": {},\n",
            "    \"candidate_rs\": {},\n",
            "    \"warmup_points\": {},\n",
            "    \"total_points\": {},\n",
            "    \"warmup_points_seen\": {},\n",
            "    \"certified_points\": {},\n",
            "    \"fallback_points\": {},\n",
            "    \"insufficient_radius_points\": {},\n",
            "    \"insufficient_stats_points\": {},\n",
            "    \"avg_fanout\": {:.12},\n",
            "    \"target_avg_fanout\": {:.6},\n",
            "    \"calibrated_budget_lambda\": {},\n",
            "    \"sigma_lambda\": {:.6},\n",
            "    \"sigma_mode\": \"{}\",\n",
            "    \"calibration_points\": {},\n",
            "    \"calibration_avg_fanout\": {:.12},\n",
            "    \"actual_avg_fanout\": {:.12},\n",
            "    \"retained_utility_sum\": {:.12},\n",
            "    \"omitted_utility_sum\": {:.12},\n",
            "    \"omitted_utility_avg\": {:.12},\n",
            "    \"sum_child_size_squared_ratio\": {:.12},\n",
            "    \"largest_child_ratio\": {:.12},\n",
            "    \"child_size_cv\": {:.12},\n",
            "    \"predicted_work_score\": {:.12},\n",
            "    \"kept_hist\": {},\n",
            "    \"ready_cells\": {},\n",
            "    \"selector_ms\": {},\n",
            "    \"radius_update_ms\": {},\n",
            "    \"risk_update_ms\": {},\n",
            "    \"projected_assignment_bytes\": {},\n",
            "    \"projected_partition_d00_bytes_pre_dedup\": {},\n",
            "    \"root_leader_hash\": {}\n",
            "  }}\n",
            "}}\n"
        ),
        escape_json(&profile.policy),
        escape_json(&profile.selection_semantics),
        profile.enabled,
        profile.dry_run,
        optional_json_string(profile.fallback_reason.as_deref()),
        profile.k,
        profile.fixed_fanout,
        usize_slice_json(&profile.candidate_rs),
        profile.warmup_points,
        profile.total_points,
        profile.warmup_points_seen,
        profile.certified_points,
        profile.fallback_points,
        profile.insufficient_radius_points,
        profile.insufficient_stats_points,
        profile.avg_fanout,
        profile.target_avg_fanout,
        optional_f32_json(profile.calibrated_budget_lambda),
        profile.sigma_lambda,
        escape_json(&profile.sigma_mode),
        profile.calibration_points,
        profile.calibration_avg_fanout,
        profile.actual_avg_fanout,
        profile.retained_utility_sum,
        profile.omitted_utility_sum,
        profile.omitted_utility_avg,
        profile.sum_child_size_squared_ratio,
        profile.largest_child_ratio,
        profile.child_size_cv,
        profile.predicted_work_score,
        usize_slice_json(&profile.kept_hist),
        profile.ready_cells,
        profile.selector_ms,
        profile.radius_update_ms,
        profile.risk_update_ms,
        profile.projected_assignment_bytes,
        profile.projected_partition_d00_bytes_pre_dedup,
        profile.root_leader_hash,
    )
}

fn log_root_fanout_summary(profile: &RootFanoutProfile) {
    if !profile.observed() {
        return;
    }
    tracing::info!(
        "[rbc/root-fanout] policy={} semantics={} enabled={} dry_run={} k={} fixed_fanout={} candidate_rs={:?} ready_cells={} certified_points={} fallback_points={} insufficient_radius_points={} avg_fanout={:.3} selector_ms={} radius_update_ms={} projected_assignment_bytes={} projected_partition_d00_bytes_pre_dedup={} root_leader_hash={}",
        profile.policy,
        profile.selection_semantics,
        profile.enabled,
        profile.dry_run,
        profile.k,
        profile.fixed_fanout,
        profile.candidate_rs,
        profile.ready_cells,
        profile.certified_points,
        profile.fallback_points,
        profile.insufficient_radius_points,
        profile.avg_fanout,
        profile.selector_ms,
        profile.radius_update_ms,
        profile.projected_assignment_bytes,
        profile.projected_partition_d00_bytes_pre_dedup,
        profile.root_leader_hash,
    );
}

fn usize_slice_json(values: &[usize]) -> String {
    let body = values
        .iter()
        .map(|value| value.to_string())
        .collect::<Vec<_>>()
        .join(", ");
    format!("[{body}]")
}

fn optional_json_string(value: Option<&str>) -> String {
    value
        .map(|value| format!("\"{}\"", escape_json(value)))
        .unwrap_or_else(|| "null".to_string())
}

fn optional_f32_json(value: Option<f32>) -> String {
    value
        .filter(|value| value.is_finite())
        .map(|value| format!("{:.12}", value))
        .unwrap_or_else(|| "null".to_string())
}

fn escape_json(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            ch if ch.is_control() => {
                use std::fmt::Write as _;
                let _ = write!(&mut out, "\\u{:04x}", ch as u32);
            }
            ch => out.push(ch),
        }
    }
    out
}

fn format_progress_line(
    stats: &PartitionStats,
    stack: &[(Vec<u32>, usize, usize)],
    current_depth: usize,
) -> String {
    format!(
        "leaves={} | stack={} | depth={} | {} elapsed",
        format_count(stats.total_leaves()),
        format_count(stack.len()),
        format_depth_range(stack, current_depth),
        format_duration(stats.elapsed()),
    )
}

fn format_depth_range(stack: &[(Vec<u32>, usize, usize)], current_depth: usize) -> String {
    let mut min_depth = current_depth;
    let mut max_depth = current_depth;
    for (_, depth, _) in stack {
        min_depth = min_depth.min(*depth);
        max_depth = max_depth.max(*depth);
    }

    if min_depth == max_depth {
        format_count(min_depth)
    } else {
        format!("{}-{}", format_count(min_depth), format_count(max_depth))
    }
}

fn leaf_size_buckets(leaf_sizes: &[usize]) -> [(&'static str, usize); 6] {
    let mut counts = [0usize; 6];
    for &size in leaf_sizes {
        let idx = if size <= 1_000 {
            0
        } else if size <= 5_000 {
            1
        } else if size <= 10_000 {
            2
        } else if size <= 20_000 {
            3
        } else if size <= 30_000 {
            4
        } else {
            5
        };
        counts[idx] += 1;
    }

    [
        ("[1-1K]", counts[0]),
        ("[1K-5K]", counts[1]),
        ("[5K-10K]", counts[2]),
        ("[10K-20K]", counts[3]),
        ("[20K-30K]", counts[4]),
        ("[30K+]", counts[5]),
    ]
}

fn percentage(part: usize, total: usize) -> f64 {
    if total == 0 {
        0.0
    } else {
        part as f64 * 100.0 / total as f64
    }
}

fn format_duration(duration: Duration) -> String {
    let total_secs = duration.as_secs();
    let hours = total_secs / 3600;
    let minutes = (total_secs % 3600) / 60;
    let seconds = total_secs % 60;

    if hours > 0 {
        format!("{hours}h{minutes:02}m{seconds:02}s")
    } else if minutes > 0 {
        format!("{minutes}m{seconds:02}s")
    } else {
        format!("{seconds}s")
    }
}

fn format_count(value: usize) -> String {
    let digits = value.to_string();
    let mut out = String::with_capacity(digits.len() + digits.len() / 3);

    for (idx, ch) in digits.chars().rev().enumerate() {
        if idx != 0 && idx % 3 == 0 {
            out.push(',');
        }
        out.push(ch);
    }

    out.chars().rev().collect()
}

fn merge_clusters(mut clusters: Vec<Vec<u32>>, c_min: usize, c_max: usize) -> Vec<Vec<u32>> {
    clusters.retain(|cluster| !cluster.is_empty());
    if clusters.is_empty() {
        return clusters;
    }

    clusters.sort_by_key(Vec::len);

    let mut result: Vec<Vec<u32>> = Vec::new();
    let mut current_small: Option<Vec<u32>> = None;

    for cluster in clusters {
        let size = cluster.len();
        if size >= c_min {
            if let Some(mut small) = current_small.take() {
                if small.len() + size <= c_max {
                    let mut merged = cluster;
                    merged.append(&mut small);
                    result.push(merged);
                } else {
                    result.push(small);
                    result.push(cluster);
                }
            } else {
                result.push(cluster);
            }
        } else {
            match current_small {
                Some(small) => {
                    if small.len() + size <= c_max {
                        let mut merged = small;
                        merged.extend_from_slice(&cluster);
                        current_small = Some(merged);
                    } else {
                        result.push(small);
                        current_small = Some(cluster);
                    }
                }
                None => {
                    current_small = Some(cluster);
                }
            }
        }
    }

    if let Some(small) = current_small {
        if let Some(last) = result.last_mut() {
            if last.len() + small.len() <= c_max {
                last.extend_from_slice(&small);
            } else {
                result.push(small);
            }
        } else {
            result.push(small);
        }
    }

    result
}

