    #[test]
    fn gpu_subtree_d0_hash_contract_is_stable_and_storage_layout_independent() {
        let baseline = vec![
            (0, 3, 11, vec![vec![3, 1], vec![2]]),
            (1, 2, 22, vec![vec![7, 6]]),
            (2, 1, 33, vec![vec![9]]),
        ];
        let different_layout = vec![
            (0, 3, 11, vec![vec![2], vec![1], vec![3]]),
            (1, 2, 22, vec![vec![6], vec![7]]),
            (2, 1, 33, vec![vec![], vec![9]]),
        ];

        let baseline_hashes = super::canonical_gpu_subtree_d0_hashes(&baseline);
        assert_eq!(
            baseline_hashes,
            super::canonical_gpu_subtree_d0_hashes(&different_layout)
        );

        let mut changed_point = baseline.clone();
        changed_point[1].3[0][0] = 8;
        let changed_point_hashes = super::canonical_gpu_subtree_d0_hashes(&changed_point);
        assert_ne!(baseline_hashes.0, changed_point_hashes.0);

        let changed_child = vec![
            (0, 3, 11, vec![vec![3, 1, 7]]),
            (1, 2, 22, vec![vec![2, 6]]),
            (2, 1, 33, vec![vec![9]]),
        ];
        let changed_child_hashes = super::canonical_gpu_subtree_d0_hashes(&changed_child);
        assert_ne!(baseline_hashes.0, changed_child_hashes.0);

        let mut changed_seed = baseline;
        changed_seed[2].2 = 34;
        let changed_seed_hashes = super::canonical_gpu_subtree_d0_hashes(&changed_seed);
        assert_eq!(baseline_hashes.0, changed_seed_hashes.0);
        assert_ne!(baseline_hashes.1, changed_seed_hashes.1);
    }

