    struct ControlledDeferredScatter {
        result: GpuSubtreeTopKResult,
        events: Arc<Mutex<Vec<&'static str>>>,
        started: Option<mpsc::Sender<()>>,
        release: Option<mpsc::Receiver<()>>,
        panic_in_finish: bool,
    }

    impl DeferredGpuSubtreeScatter for ControlledDeferredScatter {
        fn finish(self: Box<Self>) -> AnnResult<GpuSubtreeTopKResult> {
            self.events.lock().push("scatter_start");
            if let Some(started) = self.started.as_ref() {
                started.send(()).unwrap();
            }
            if let Some(release) = self.release.as_ref() {
                release.recv().unwrap();
            }
            if self.panic_in_finish {
                panic!("controlled scatter panic");
            }
            self.events.lock().push("scatter_done");
            Ok(self.result.clone())
        }
    }

    struct ErrorDeferredScatter;

    impl DeferredGpuSubtreeScatter for ErrorDeferredScatter {
        fn finish(self: Box<Self>) -> AnnResult<GpuSubtreeTopKResult> {
            Err(AnnError::log_index_error(
                "controlled scatter error".to_string(),
            ))
        }
    }

    fn deferred_scatter_submission(
        scatter: impl DeferredGpuSubtreeScatter + Send + 'static,
    ) -> GpuSubtreeTopKSubmission {
        GpuSubtreeTopKSubmission::Deferred(DeferredGpuSubtreeTopK {
            estimated_host_bytes: 64,
            scatter: Box::new(scatter),
        })
    }

