    #[test]
    fn async_result_scatter_gate_defaults_on_only_with_preload() {
        use std::ffi::OsStr;

        for (value, preload_present, expected_enabled) in [
            (None, true, true),
            (None, false, false),
            (Some(OsStr::new("0")), true, false),
            (Some(OsStr::new("true")), true, false),
            (Some(OsStr::new("1")), false, false),
            (Some(OsStr::new("1")), true, true),
        ] {
            let config = super::parse_async_result_scatter_env(value);
            let mut telemetry = super::RbcPartitionTelemetry::default();
            let mut runtime = super::start_async_result_scatter_if_enabled::<usize>(
                &config,
                preload_present,
                &mut telemetry,
            )
            .unwrap();
            assert_eq!(runtime.is_some(), expected_enabled);
            assert_eq!(
                telemetry.gpu_subtree_async_result_scatter_enabled,
                expected_enabled
            );
            assert_eq!(
                telemetry.gpu_subtree_async_result_scatter_requested,
                config.requested
            );
            if let Some(runtime) = runtime.as_mut() {
                assert!(runtime.finish(&mut telemetry).unwrap().is_empty());
                assert!(runtime.worker.is_none());
            }
        }
    }

