    #[test]
    fn async_result_scatter_buffers_two_gpu_steps_and_preserves_order() {
        let events = Arc::new(Mutex::new(Vec::new()));
        let (started_tx, started_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let first = deferred_scatter_submission(ControlledDeferredScatter {
            result: scatter_test_result(10),
            events: Arc::clone(&events),
            started: Some(started_tx),
            release: Some(release_rx),
            panic_in_finish: false,
        });
        let second = deferred_scatter_submission(ControlledDeferredScatter {
            result: scatter_test_result(20),
            events: Arc::clone(&events),
            started: None,
            release: None,
            panic_in_finish: false,
        });
        let mut telemetry = super::RbcPartitionTelemetry::default();
        let mut runtime = super::AsyncResultScatterRuntime::<usize>::start().unwrap();
        let mut completed = runtime.accept(0, 32, first, &mut telemetry).unwrap();
        assert!(completed.is_empty());

        started_rx.recv().unwrap();
        events.lock().push("gpu_1");
        release_tx.send(()).unwrap();
        completed.extend(runtime.accept(1, 32, second, &mut telemetry).unwrap());
        completed.extend(runtime.finish(&mut telemetry).unwrap());

        let finalized: Vec<_> = completed
            .into_iter()
            .map(|(context, result)| (context, result.max_active_points))
            .collect();
        assert_eq!(finalized, vec![(0, 10), (1, 20)]);
        assert_eq!(
            events.lock().as_slice(),
            &[
                "scatter_start",
                "gpu_1",
                "scatter_done",
                "scatter_start",
                "scatter_done"
            ]
        );
        assert_eq!(telemetry.gpu_subtree_async_result_scatter_max_inflight, 2);
        assert_eq!(
            telemetry.gpu_subtree_async_result_scatter_peak_host_bytes,
            2 * (64 + 32)
        );
    }

    #[test]
    fn async_result_scatter_backpressures_only_the_third_deferred_result() {
        let events = Arc::new(Mutex::new(Vec::new()));
        let (started_tx, started_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let first = deferred_scatter_submission(ControlledDeferredScatter {
            result: scatter_test_result(10),
            events: Arc::clone(&events),
            started: Some(started_tx),
            release: Some(release_rx),
            panic_in_finish: false,
        });
        let second = deferred_scatter_submission(ControlledDeferredScatter {
            result: scatter_test_result(20),
            events: Arc::clone(&events),
            started: None,
            release: None,
            panic_in_finish: false,
        });
        let third = deferred_scatter_submission(ControlledDeferredScatter {
            result: scatter_test_result(30),
            events,
            started: None,
            release: None,
            panic_in_finish: false,
        });
        let mut telemetry = super::RbcPartitionTelemetry::default();
        let mut runtime = super::AsyncResultScatterRuntime::<usize>::start().unwrap();
        assert!(
            runtime
                .accept(0, 32, first, &mut telemetry)
                .unwrap()
                .is_empty()
        );
        started_rx.recv().unwrap();

        let (second_accepted_tx, second_accepted_rx) = mpsc::channel();
        let second_accept = std::thread::spawn(move || {
            let completed = runtime.accept(1, 32, second, &mut telemetry);
            second_accepted_tx.send(()).unwrap();
            (runtime, telemetry, completed)
        });
        second_accepted_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("the second deferred result should occupy the free slot");
        let (runtime, telemetry, second_completed) = second_accept.join().unwrap();
        assert!(second_completed.unwrap().is_empty());
        assert_eq!(runtime.pending.len(), 2);

        let (third_accepted_tx, third_accepted_rx) = mpsc::channel();
        let third_accept = std::thread::spawn(move || {
            let mut runtime = runtime;
            let mut telemetry = telemetry;
            let completed = runtime.accept(2, 32, third, &mut telemetry);
            third_accepted_tx.send(()).unwrap();
            (runtime, telemetry, completed)
        });
        assert!(
            third_accepted_rx
                .recv_timeout(Duration::from_millis(100))
                .is_err(),
            "the third deferred result must wait for the oldest slot"
        );
        release_tx.send(()).unwrap();
        third_accepted_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("the third deferred result should proceed after the oldest slot drains");
        let (mut runtime, mut telemetry, third_completed) = third_accept.join().unwrap();
        let mut completed = third_completed.unwrap();
        completed.extend(runtime.finish(&mut telemetry).unwrap());

        let finalized: Vec<_> = completed
            .into_iter()
            .map(|(context, result)| (context, result.max_active_points))
            .collect();
        assert_eq!(finalized, vec![(0, 10), (1, 20), (2, 30)]);
        assert_eq!(telemetry.gpu_subtree_async_result_scatter_max_inflight, 2);
    }

