    fn complete_rabitq_payload_for_test(rows: usize, dim: usize) -> RabitqResidualPayloadStore {
        let mut store = RabitqResidualPayloadStore::new(RabitqResidualPayloadHeader {
            rows,
            dim,
            padded_dim: dim,
            centroid_count: 1,
            code_row_bytes: dim,
        })
        .unwrap();
        let mut codes = Vec::with_capacity(rows.saturating_mul(dim));
        for row in 0..rows {
            for axis in 0..dim {
                codes.push((row as i32 + axis as i32).clamp(-127, 127) as i8);
            }
        }
        store
            .write_shard(&RabitqResidualShardPayload {
                global_ids: (0..rows as u32).collect(),
                centroid_ids: vec![0; rows],
                codes,
                residual_norms: vec![1.0; rows],
                scales: vec![1.0; rows],
                code_sums: vec![0.0; rows],
                original_norms: vec![1.0; rows],
                code_row_bytes: dim,
            })
            .unwrap();
        assert!(store.is_complete());
        store
    }

    struct RecordingCompactTopKSink {
        flushed: Mutex<Vec<u64>>,
        fail_leaf_id: Option<u64>,
        sleep_on_flush: Duration,
        active_flushes: AtomicUsize,
        max_active_flushes: AtomicUsize,
        bulk_flushes: AtomicUsize,
    }

    impl RecordingCompactTopKSink {
        fn new() -> Self {
            Self {
                flushed: Mutex::new(Vec::new()),
                fail_leaf_id: None,
                sleep_on_flush: Duration::ZERO,
                active_flushes: AtomicUsize::new(0),
                max_active_flushes: AtomicUsize::new(0),
                bulk_flushes: AtomicUsize::new(0),
            }
        }

        fn failing(fail_leaf_id: u64) -> Self {
            Self {
                fail_leaf_id: Some(fail_leaf_id),
                ..Self::new()
            }
        }

        fn sleepy(sleep_on_flush: Duration) -> Self {
            Self {
                sleep_on_flush,
                ..Self::new()
            }
        }

        fn flushed_ids(&self) -> Vec<u64> {
            self.flushed.lock().clone()
        }

        fn max_active_flushes(&self) -> usize {
            self.max_active_flushes.load(Ordering::Relaxed)
        }

        fn bulk_flushes(&self) -> usize {
            self.bulk_flushes.load(Ordering::Relaxed)
        }
    }

    impl CompactTopKSink for RecordingCompactTopKSink {
        fn flush_compact_topk(&self, batch: CompactTopKBatch) -> AnnResult<LeafProfile> {
            let active = self.active_flushes.fetch_add(1, Ordering::SeqCst) + 1;
            let mut current_max = self.max_active_flushes.load(Ordering::Relaxed);
            while active > current_max {
                match self.max_active_flushes.compare_exchange_weak(
                    current_max,
                    active,
                    Ordering::Relaxed,
                    Ordering::Relaxed,
                ) {
                    Ok(_) => break,
                    Err(observed) => current_max = observed,
                }
            }
            if self.sleep_on_flush > Duration::ZERO {
                std::thread::sleep(self.sleep_on_flush);
            }
            if self.fail_leaf_id == Some(batch.leaf_id) {
                self.active_flushes.fetch_sub(1, Ordering::SeqCst);
                return Err(AnnError::log_index_error(format!(
                    "injected compact flush failure for leaf {}",
                    batch.leaf_id
                )));
            }
            self.flushed.lock().push(batch.leaf_id);
            self.active_flushes.fetch_sub(1, Ordering::SeqCst);
            Ok(LeafProfile {
                leaves: 1,
                points: batch.rows,
                ..LeafProfile::default()
            })
        }

        fn flush_compact_topk_batches(
            &self,
            batches: Vec<CompactTopKBatch>,
        ) -> AnnResult<LeafProfile> {
            self.bulk_flushes.fetch_add(1, Ordering::Relaxed);
            let mut profile = LeafProfile::default();
            for batch in batches {
                profile.merge(self.flush_compact_topk(batch)?);
            }
            Ok(profile)
        }
    }

    struct PanickingCompactTopKSink;

    impl CompactTopKSink for PanickingCompactTopKSink {
        fn flush_compact_topk(&self, _batch: CompactTopKBatch) -> AnnResult<LeafProfile> {
            panic!("injected compact flush panic");
        }
    }

