    fn adaptive_async_flush_lazily_spawns_requested_workers() {
        const CHUNK_BYTES: usize = 8 * 1024 * 1024;
        let sink = RecordingCompactTopKSink::sleepy(Duration::from_millis(10));
        let runtime = super::AsyncCompactFlushRuntime::new(
            &sink,
            1024 * 1024 * 1024,
            super::AsyncCompactFlushWorkerPolicy::Adaptive {
                initial_workers: 2,
                max_workers: 4,
                invalid_override: false,
            },
        );

        let result = runtime
            .run(|producer| {
                for leaf_id in 0..64 {
                    producer.enqueue(compact_batch_with_estimated_bytes_for_test(
                        leaf_id,
                        CHUNK_BYTES,
                    ))?;
                }
                Ok(())
            })
            .unwrap();

        assert!(result.telemetry.peak_workers > 2);
        assert!(result.telemetry.peak_workers <= 4);
        assert!(result.telemetry.scale_up_events > 0);
        assert!(sink.max_active_flushes() > 2);
        assert!(sink.max_active_flushes() <= result.telemetry.peak_workers);
    }

