    #[test]
    fn gpu_subtree_async_flush_consumes_batches_concurrently_with_multiple_workers() {
        let sink = RecordingCompactTopKSink::sleepy(Duration::from_millis(1));
        let runtime = super::AsyncCompactFlushRuntime::new(
            &sink,
            1 << 20,
            super::AsyncCompactFlushWorkerPolicy::Fixed { workers: 3 },
        );
        let total_batches = 192usize;
        let result = runtime
            .run(|producer| {
                for leaf_id in 0..total_batches as u64 {
                    producer.enqueue(compact_batch_for_test(leaf_id, 2, 2))?;
                }
                Ok(())
            })
            .unwrap();

        let mut flushed = sink.flushed_ids();
        flushed.sort_unstable();
        assert_eq!(flushed, (0..total_batches as u64).collect::<Vec<_>>());
        assert!(
            sink.max_active_flushes() > 1,
            "expected multiple compact flush workers to be active"
        );
        assert_eq!(result.telemetry.worker_count, 3);
        assert!(result.telemetry.chunks >= 3);
        assert_eq!(result.telemetry.batches, total_batches);
        assert_eq!(result.telemetry.rows, total_batches * 2);
        assert_eq!(result.telemetry.errors, 0);
    }

    #[test]
    fn gpu_subtree_async_flush_small_budget_records_backpressure() {
        let sink = RecordingCompactTopKSink::sleepy(Duration::from_millis(20));
        let budget = super::estimate_compact_topk_batch_bytes(&compact_batch_for_test(1, 8, 2));
        let runtime = super::AsyncCompactFlushRuntime::new(
            &sink,
            budget,
            super::AsyncCompactFlushWorkerPolicy::Fixed { workers: 1 },
        );
        let result = runtime
            .run(|producer| {
                producer.enqueue(compact_batch_for_test(1, 8, 2))?;
                producer.enqueue(compact_batch_for_test(2, 8, 2))?;
                producer.enqueue(compact_batch_for_test(3, 8, 2))?;
                Ok(())
            })
            .unwrap();

        assert_eq!(sink.flushed_ids(), vec![1, 2, 3]);
        assert!(result.telemetry.push_wait_wall > Duration::ZERO);
        assert!(result.telemetry.queue_max_bytes >= budget);
        assert_eq!(result.telemetry.queue_max_batches, 1);
    }

