    struct CountingPointStore {
        data: Vec<f32>,
        rows: usize,
        dim: usize,
        point_reads: AtomicUsize,
        batch_reads: AtomicUsize,
    }

    impl CountingPointStore {
        fn new(rows: usize, dim: usize) -> Self {
            let data = (0..rows)
                .flat_map(|row| (0..dim).map(move |col| row as f32 + col as f32 * 0.01))
                .collect();
            Self {
                data,
                rows,
                dim,
                point_reads: AtomicUsize::new(0),
                batch_reads: AtomicUsize::new(0),
            }
        }

        fn point_read_count(&self) -> usize {
            self.point_reads.load(Ordering::Relaxed)
        }

        fn batch_read_count(&self) -> usize {
            self.batch_reads.load(Ordering::Relaxed)
        }
    }

    impl PointStore for CountingPointStore {
        fn len(&self) -> usize {
            self.rows
        }

        fn dim(&self) -> usize {
            self.dim
        }

        fn read_point_into(&self, pid: u32, out: &mut [f32]) -> AnnResult<()> {
            self.point_reads.fetch_add(1, Ordering::Relaxed);
            let start = pid as usize * self.dim;
            out.copy_from_slice(&self.data[start..start + self.dim]);
            Ok(())
        }

        fn read_range_into(&self, start_pid: u32, count: usize, out: &mut [f32]) -> AnnResult<()> {
            for row in 0..count {
                let pid = start_pid as usize + row;
                let src_start = pid * self.dim;
                let dst_start = row * self.dim;
                out[dst_start..dst_start + self.dim]
                    .copy_from_slice(&self.data[src_start..src_start + self.dim]);
            }
            Ok(())
        }

        fn read_points_into(&self, ids: &[u32], out: &mut [f32]) -> AnnResult<()> {
            for (row, &pid) in ids.iter().enumerate() {
                let src_start = pid as usize * self.dim;
                let dst_start = row * self.dim;
                out[dst_start..dst_start + self.dim]
                    .copy_from_slice(&self.data[src_start..src_start + self.dim]);
            }
            Ok(())
        }

        fn read_points_windowed_into_batch_stats(
            &self,
            ids: &[u32],
            out: &mut [f32],
            _options: &super::WindowedGatherOptions,
            _stats: &mut super::PointBatchStats,
        ) -> AnnResult<()> {
            self.batch_reads.fetch_add(1, Ordering::Relaxed);
            self.read_points_into(ids, out)
        }
    }

    #[test]
    fn gpu_subtree_rolling_vector_reuse_serves_recent_child_rows() {
        let store = CountingPointStore::new(6, 4);
        let reuse_store = super::RollingVectorReusePointStore::new(&store, 1 << 20, 1);
        let options = super::WindowedGatherOptions::default();

        let first_ids = vec![0, 1, 2, 3];
        let mut first = vec![0.0f32; first_ids.len() * store.dim()];
        let mut first_stats = super::PointBatchStats::default();
        reuse_store
            .read_points_windowed_into_batch_stats(
                &first_ids,
                &mut first,
                &options,
                &mut first_stats,
            )
            .unwrap();
        assert_eq!(first_stats.vector_reuse_hits, 0);
        assert_eq!(first_stats.vector_reuse_misses, 4);
        assert_eq!(first_stats.vector_reuse_inserts, 4);

        let second_ids = vec![2, 3, 4, 5];
        let mut second = vec![0.0f32; second_ids.len() * store.dim()];
        let mut second_stats = super::PointBatchStats::default();
        reuse_store
            .read_points_windowed_into_batch_stats(
                &second_ids,
                &mut second,
                &options,
                &mut second_stats,
            )
            .unwrap();

        let mut expected = vec![0.0f32; second_ids.len() * store.dim()];
        store.read_points_into(&second_ids, &mut expected).unwrap();
        assert_eq!(second, expected);
        assert_eq!(store.batch_read_count(), 2);
        assert_eq!(second_stats.vector_reuse_hits, 2);
        assert_eq!(second_stats.vector_reuse_misses, 2);
        assert_eq!(
            second_stats.vector_reuse_hit_bytes,
            2 * store.dim() as u64 * std::mem::size_of::<f32>() as u64
        );
        assert_eq!(second_stats.vector_reuse_inserts, 4);
        assert_eq!(second_stats.vector_reuse_evictions, 4);
    }

    struct CountingAssignBackend {
        total_points: usize,
        root_sized_calls: AtomicUsize,
        subtree_calls: AtomicUsize,
    }

    impl CountingAssignBackend {
        fn new(total_points: usize) -> Self {
            Self {
                total_points,
                root_sized_calls: AtomicUsize::new(0),
                subtree_calls: AtomicUsize::new(0),
            }
        }

        fn root_sized_calls(&self) -> usize {
            self.root_sized_calls.load(Ordering::Relaxed)
        }

        fn subtree_calls(&self) -> usize {
            self.subtree_calls.load(Ordering::Relaxed)
        }
    }

    impl PiPNNComputeBackend for CountingAssignBackend {
        fn kind(&self) -> PiPNNComputeBackendKind {
            PiPNNComputeBackendKind::Cuda
        }

        fn assign_clusters_l2(
            &self,
            dataset: &dyn PointStore,
            cur: &[u32],
            leaders: &[u32],
            local_fanout: usize,
            memory_budget_bytes: Option<usize>,
        ) -> AnnResult<(Vec<Vec<u32>>, super::GemmProfile)> {
            if cur.len() == self.total_points {
                self.root_sized_calls.fetch_add(1, Ordering::Relaxed);
            } else {
                self.subtree_calls.fetch_add(1, Ordering::Relaxed);
            }
            cpu_backend().assign_clusters_l2(
                dataset,
                cur,
                leaders,
                local_fanout,
                memory_budget_bytes,
            )
        }

        fn process_leaf_parallel_large_l2(
            &self,
            _dataset: &dyn PointStore,
            _sketches: &dyn SketchAccessor,
            _leaf: &[u32],
            _params: &PiPNNParams,
            _edge_sink: &dyn PendingEdgeSink,
            _block_rows: usize,
        ) -> AnnResult<LeafProfile> {
            Err(AnnError::log_index_error(
                "test assignment backend should not process leaves".to_string(),
            ))
        }
    }

