    struct SubmissionCountingQuantizedBackend {
        sync_quantized_calls: AtomicUsize,
        owned_submission_calls: AtomicUsize,
        max_depths: Mutex<Vec<usize>>,
    }

    impl SubmissionCountingQuantizedBackend {
        fn new() -> Self {
            Self {
                sync_quantized_calls: AtomicUsize::new(0),
                owned_submission_calls: AtomicUsize::new(0),
                max_depths: Mutex::new(Vec::new()),
            }
        }

        fn max_depths(&self) -> Vec<usize> {
            self.max_depths.lock().clone()
        }

        fn result(
            request: &GpuSubtreePartitionRequest<'_>,
            params: &PiPNNParams,
        ) -> GpuSubtreeTopKResult {
            let rows = request.point_ids.len();
            let k = params.leaf_knn.max(1);
            let mut topk_ids = Vec::with_capacity(rows.saturating_mul(k));
            let mut topk_dists = Vec::with_capacity(rows.saturating_mul(k));
            for &point_id in request.point_ids {
                for _ in 0..k {
                    topk_ids.push(point_id);
                    topk_dists.push(0.0);
                }
            }
            GpuSubtreeTopKResult {
                compact_batches: vec![CompactTopKBatch {
                    leaf_id: 0,
                    point_ids: request.point_ids.to_vec(),
                    rows,
                    k,
                    topk_ids,
                    topk_dists,
                    ..CompactTopKBatch::default()
                }],
                assignment_passes: 1,
                leaf_count: 1,
                max_active_points: rows,
                profile: GpuSubtreeTopKProfile {
                    child_points: rows,
                    persistent_attempt_count: 1,
                    persistent_success_count: 1,
                    persistent_topk_rows: rows,
                    persistent_leaf_count: 1,
                    ..GpuSubtreeTopKProfile::default()
                },
            }
        }
    }

    impl PiPNNComputeBackend for SubmissionCountingQuantizedBackend {
        fn kind(&self) -> PiPNNComputeBackendKind {
            PiPNNComputeBackendKind::Cuda
        }

        fn assign_clusters_l2(
            &self,
            _dataset: &dyn PointStore,
            _cur: &[u32],
            _leaders: &[u32],
            _local_fanout: usize,
            _memory_budget_bytes: Option<usize>,
        ) -> AnnResult<(Vec<Vec<u32>>, super::GemmProfile)> {
            unreachable!("submission counting backend does not assign clusters")
        }

        fn process_leaf_parallel_large_l2(
            &self,
            _dataset: &dyn PointStore,
            _sketches: &dyn SketchAccessor,
            _leaf: &[u32],
            _params: &PiPNNParams,
            _edge_sink: &dyn PendingEdgeSink,
            _block_rows: usize,
        ) -> AnnResult<LeafProfile> {
            unreachable!("submission counting backend does not process leaves")
        }

        fn supports_quantized_subtree_l2_compact_topk(&self) -> bool {
            true
        }

        fn process_quantized_subtree_l2_compact_topk(
            &self,
            request: &GpuSubtreePartitionRequest<'_>,
            _quantized: GpuSubtreeQuantizedInput<'_>,
            params: &PiPNNParams,
        ) -> AnnResult<GpuSubtreeTopKResult> {
            self.sync_quantized_calls.fetch_add(1, Ordering::Relaxed);
            self.max_depths.lock().push(params.max_depth);
            Ok(Self::result(request, params))
        }

        fn submit_owned_quantized_subtree_l2_compact_topk(
            &self,
            request: &GpuSubtreePartitionRequest<'_>,
            _quantized: OwnedGpuSubtreeQuantizedInput,
            params: &PiPNNParams,
        ) -> AnnResult<GpuSubtreeTopKSubmission> {
            self.owned_submission_calls.fetch_add(1, Ordering::Relaxed);
            self.max_depths.lock().push(params.max_depth);
            Ok(GpuSubtreeTopKSubmission::Ready(Self::result(
                request, params,
            )))
        }
    }

