    #[test]
    fn gpu_subtree_root_stop_after_d00_returns_after_d0_preflight() {
        let num_points = 256;
        let dim = 8;
        let dataset = build_test_dataset(num_points, dim);
        let store = InmemDatasetPointStore::new(&dataset, num_points);
        let indices: Vec<u32> = (0..num_points as u32).collect();
        let mut params = PiPNNParams::default();
        params.partitioner = PiPNNPartitionerKind::GpuSubtree;
        params.oom_enable = true;
        params.oom_memory_budget_bytes = 512 * 1024 * 1024;
        params.root_stop_after_d00 = true;
        params.c_min = 8;
        params.c_max = 16;
        params.max_depth = 4;
        params.max_leaders = 16;
        params.psamp_fraction = 0.05;
        params.fanout_top = 2;
        params.fanout_second = 2;
        params.root_fanout_policy = RootFanoutPolicy::Fixed;
        let dir = tempdir().unwrap();
        let sink = RecordingCompactTopKSink::new();
        let mut rng = StdRng::seed_from_u64(42);

        let profile = super::rbc_partition_gpu_subtree_streaming(
            &FailingSubtreeBackend,
            &store,
            &indices,
            Metric::L2,
            &params,
            1,
            &mut rng,
            Some(dir.path()),
            None,
            Some(&sink),
        )
        .unwrap();

        assert!(profile.rbc.gpu_subtree_d0_wall > Duration::ZERO);
        assert!(profile.rbc.gpu_subtree_d0_child_run_count > 0);
        assert_eq!(profile.rbc.gpu_subtree_compact_attempt_count, 0);
        assert!(sink.flushed_ids().is_empty());

        let split_dir = tempdir().unwrap();
        let mut split_rng = StdRng::seed_from_u64(42);
        let d0_plan = super::run_gpu_subtree_d0_preflight(
            cpu_backend(),
            &store,
            &indices,
            Metric::L2,
            &params,
            1,
            &mut split_rng,
            Some(split_dir.path()),
        )
        .unwrap();
        let split_sink = RecordingCompactTopKSink::new();

        let split_profile = super::run_gpu_subtree_from_d0_plan(
            &FailingSubtreeBackend,
            &store,
            Metric::L2,
            &params,
            d0_plan,
            &split_sink,
            super::CompactFlushMode::Sync,
        )
        .unwrap();

        assert!(split_profile.rbc.gpu_subtree_d0_wall > Duration::ZERO);
        assert!(split_profile.rbc.gpu_subtree_d0_child_run_count > 0);
        assert_eq!(split_profile.rbc.gpu_subtree_compact_attempt_count, 0);
        assert!(split_sink.flushed_ids().is_empty());
    }

