    #[test]
    fn tagore_d0_parallel_topk_clusters_match_dense_assignment() {
        let num_points = 96;
        let dim = 8;
        let dataset = build_test_dataset(num_points, dim);
        let store = InmemDatasetPointStore::new(&dataset, num_points);
        let indices: Vec<u32> = (0..num_points as u32).collect();
        let center_ids = vec![0, 8, 16, 32, 48, 64];
        let centers = super::read_point_ids_dense(&store, &center_ids).unwrap();
        let topk = 4;

        let clusters =
            super::build_tagore_d0_topk_clusters_parallel(&store, &indices, &centers, topk)
                .unwrap();

        let dense = super::read_point_ids_dense(&store, &indices).unwrap();
        let assignments =
            super::assign_dense_rows_to_centers(&dense, num_points, dim, &centers, topk);
        let mut expected = vec![Vec::new(); center_ids.len()];
        for (row, &point_id) in indices.iter().enumerate() {
            for &cluster_idx in assignments.row(row) {
                expected[cluster_idx].push(point_id);
            }
        }

        assert_eq!(clusters, expected);
    }

