    #[test]
    fn lazy_admission_split_uses_sampled_leaders_and_preserves_unique_points() {
        let dir = tempdir().unwrap();
        let dataset = build_test_dataset(96, 4);
        let store = InmemDatasetPointStore::new(&dataset, 96);
        let points = (0..96_u32).collect::<Vec<_>>();
        let mut run_store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let thresholds = crate::algorithm::pipnn::d0_capacity::D0CapacityThresholds {
            c_gpu: 24,
            c_high: 20,
            c_target: 18,
            c_low: 4,
        };
        let mut params = PiPNNParams::default();
        params.gpu_subtree_d0_capacity_split_recursion_limit = 4;
        let mut telemetry = super::RbcPartitionTelemetry::default();

        let tasks = super::split_gpu_subtree_d1plus_task_by_sampled_leaders_for_admission(
            &store,
            &params,
            7,
            99,
            points.clone(),
            thresholds,
            &mut run_store,
            &mut telemetry,
            0,
        )
        .unwrap();
        run_store.finalize().unwrap();

        assert!(tasks.len() >= 2);
        assert!(
            tasks
                .iter()
                .all(|task| task.points.len() <= thresholds.c_high)
        );
        assert!(telemetry.gpu_subtree_d1plus_admission_split_count >= 1);
        assert!(telemetry.gpu_subtree_d1plus_preflight_split_count >= 1);
        assert!(telemetry.gpu_subtree_d1plus_preflight_split_rows >= points.len());
        assert_eq!(
            telemetry.gpu_subtree_d1plus_preflight_split_max_before,
            points.len()
        );

        let mut merged = tasks
            .iter()
            .flat_map(|task| task.points.iter().copied())
            .collect::<Vec<_>>();
        merged.sort_unstable();
        assert_eq!(merged, points);
        assert!(tasks.iter().all(|task| !task.child_run.extents.is_empty()));
    }

    #[test]
    fn lazy_admission_split_uses_batched_point_reads_instead_of_pairwise_distance_reads() {
        let dir = tempdir().unwrap();
        let store = CountingPointStore::new(96, 4);
        let points = (0..96_u32).collect::<Vec<_>>();
        let mut run_store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let thresholds = crate::algorithm::pipnn::d0_capacity::D0CapacityThresholds {
            c_gpu: 24,
            c_high: 20,
            c_target: 18,
            c_low: 4,
        };
        let mut params = PiPNNParams::default();
        params.gpu_subtree_d0_capacity_split_recursion_limit = 4;
        let mut telemetry = super::RbcPartitionTelemetry::default();

        let tasks = super::split_gpu_subtree_d1plus_task_by_sampled_leaders_for_admission(
            &store,
            &params,
            7,
            99,
            points,
            thresholds,
            &mut run_store,
            &mut telemetry,
            0,
        )
        .unwrap();

        assert!(tasks.len() >= 2);
        assert_eq!(
            store.point_read_count(),
            0,
            "lazy split should reuse D0-style batched point reads instead of pairwise get_distance"
        );
        assert!(
            store.batch_read_count() >= 2,
            "lazy split should batch-read sampled leaders and point chunks"
        );
    }

    fn d0_plan_with_single_child_and_capacity(
        dir: &tempfile::TempDir,
        point_ids: &[u32],
        c_high: usize,
        c_target: usize,
    ) -> super::GpuSubtreeD0Plan {
        let mut run_store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let extent = run_store.append_points(0, point_ids).unwrap();
        run_store.finalize().unwrap();
        let child_runs = vec![super::GpuSubtreeChildRun {
            extents: vec![extent],
            len: point_ids.len(),
            seed: 11,
        }];
        let child_stats = super::compute_gpu_subtree_child_run_stats(&child_runs);
        super::GpuSubtreeD0Plan {
            total_points: point_ids.len(),
            adaptive_c_max: 16,
            min_recurse_size: 32,
            external_child_dir: dir.path().to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: super::RootFanoutProfile::fixed(4),
            child_runs,
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats,
            rbc_telemetry: super::RbcPartitionTelemetry::default(),
            d0_capacity: super::D0CapacityTelemetry {
                enabled: true,
                c_gpu: c_high,
                c_high,
                c_target,
                c_low: 1,
                ..super::D0CapacityTelemetry::default()
            },
        }
    }

