    #[test]
    fn gpu_subtree_d1plus_capacity_lazy_splits_oversized_child_before_backend() {
        let dir = tempdir().unwrap();
        let point_ids = (0..96_u32).collect::<Vec<_>>();
        let d0_plan = d0_plan_with_single_child_and_capacity(&dir, &point_ids, 20, 18);
        let dataset = build_test_dataset(point_ids.len(), 4);
        let store = InmemDatasetPointStore::new(&dataset, point_ids.len());
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.oom_memory_budget_bytes = 512 * 1024 * 1024;
        params.gpu_workspace_budget_bytes = 512 * 1024 * 1024;
        params.gpu_subtree_d0_capacity_enable = true;
        params.gpu_subtree_d0_capacity_split_recursion_limit = 6;
        params.c_min = 4;
        params.c_max = 16;
        params.max_depth = 8;
        params.max_leaders = 8;
        params.psamp_fraction = 0.2;
        params.fanout_top = 4;
        params.fanout_second = 2;
        params.leaf_knn = 2;
        let sink = RecordingCompactTopKSink::new();
        let backend = SuccessfulCompactSubtreeBackend::sleepy(Duration::ZERO);

        let profile = super::run_gpu_subtree_from_d0_plan(
            &backend,
            &store,
            Metric::L2,
            &params,
            d0_plan,
            &sink,
            super::CompactFlushMode::Sync,
        )
        .unwrap();

        let rows = backend.rows();
        assert!(!rows.contains(&point_ids.len()), "{rows:?}");
        assert!(rows.iter().all(|&rows| rows <= 20), "{rows:?}");
        assert!(profile.rbc.gpu_subtree_d1plus_preflight_split_count >= 1);
        assert_eq!(
            profile.rbc.gpu_subtree_d1plus_admission_split_count,
            profile.rbc.gpu_subtree_d1plus_preflight_split_count
        );
        assert_eq!(
            profile.rbc.gpu_subtree_compact_success_points,
            point_ids.len()
        );
        assert_eq!(profile.rbc.gpu_subtree_cpu_fallbacks, 0);
    }

    #[test]
    fn gpu_subtree_d0_throughput_report_does_not_change_capacity_rows() {
        let mut params = PiPNNParams::default();
        params.partitioner = PiPNNPartitionerKind::GpuSubtree;
        params.oom_enable = true;
        params.c_max = 16;
        params.gpu_subtree_d0_capacity_enable = true;
        params.gpu_subtree_d0_throughput_model =
            crate::algorithm::pipnn::PiPNNGpuSubtreeD0ThroughputModelMode::Report;
        let cfg = super::d0_capacity_config_from_params(&params);
        let workspace = params.effective_gpu_workspace_budget_bytes();

        let baseline = find_max_admissible_rows(
            16,
            params.leaf_knn,
            gpu_persistent_subtree_max_leaders_for_params(&params),
            params.fanout_second,
            Some(workspace),
            Some(workspace),
            &params,
        );
        let (selected, decision) =
            super::plan_d0_capacity_with_throughput_model(100_000, 16, &params, cfg, workspace, 16)
                .unwrap();

        assert_eq!(selected, baseline);
        let decision = decision.unwrap();
        assert_eq!(
            decision.mode,
            crate::algorithm::pipnn::PiPNNGpuSubtreeD0ThroughputModelMode::Report
        );
        assert_eq!(decision.selected_rows, baseline);
        assert_eq!(
            decision.memory_safe_root_leaders,
            decision.selected_root_leaders
        );
        assert!(decision.score_preferred_root_leaders >= decision.selected_root_leaders);
    }

