    #[test]
    fn gpu_subtree_d1plus_error_reports_child_context() {
        let dir = tempdir().unwrap();
        let mut store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let extent = store.append_points(0, &[0, 1, 2, 3, 4, 5]).unwrap();
        store.finalize().unwrap();
        let child_runs = vec![super::GpuSubtreeChildRun {
            extents: vec![extent],
            len: 6,
            seed: 11,
        }];
        let child_stats = super::compute_gpu_subtree_child_run_stats(&child_runs);
        let d0_plan = super::GpuSubtreeD0Plan {
            total_points: 6,
            adaptive_c_max: 4,
            min_recurse_size: 8,
            external_child_dir: dir.path().to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: super::RootFanoutProfile::fixed(4),
            child_runs,
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats,
            rbc_telemetry: super::RbcPartitionTelemetry::default(),
            d0_capacity: super::D0CapacityTelemetry {
                enabled: true,
                c_gpu: 16,
                c_high: 8,
                c_target: 8,
                c_low: 2,
                ..super::D0CapacityTelemetry::default()
            },
        };
        let dataset = build_test_dataset(6, 4);
        let store = InmemDatasetPointStore::new(&dataset, 6);
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        let sink = RecordingCompactTopKSink::new();

        let err = super::run_gpu_subtree_from_d0_plan(
            &FailingSubtreeBackend,
            &store,
            Metric::L2,
            &params,
            d0_plan,
            &sink,
            super::CompactFlushMode::Sync,
        )
        .unwrap_err();
        let msg = err.to_string();

        assert!(msg.contains("gpu-subtree D1+ child 0/1 failed"));
        assert!(msg.contains("run_len=6"));
        assert!(msg.contains("replayed_len=6"));
        assert!(msg.contains("unique_len=6"));
        assert!(msg.contains("extents=1"));
        assert!(msg.contains("backend=Cuda"));
        assert!(msg.contains("assignment_backend=persistent-wmma-tf32"));
        assert!(msg.contains("leaf_topk_backend=persistent-wmma-tf32"));
        assert!(msg.contains("injected persistent subtree failure"));
    }

    #[test]
    fn gpu_subtree_capacity_error_recognizes_persistent_no_progress_overflow() {
        let err = AnnError::log_index_error(
            "CUDA persistent subtree overflow: resident_rows=15873 overflow_flags=0x480 overflow_labels=NO_PROGRESS_SPLIT,OVERSIZED_TERMINAL_NODE leaf_rows=0".to_string(),
        );
        assert!(super::is_gpu_subtree_capacity_error(&err));
    }

    #[test]
    fn gpu_subtree_terminal_depth_retry_requires_exact_overflow_flag() {
        let terminal_only = AnnError::log_index_error(
            "CUDA persistent subtree overflow: resident_rows=1370 overflow_flags=0x400 overflow_labels=OVERSIZED_TERMINAL_NODE leaf_rows=0".to_string(),
        );
        let mixed = AnnError::log_index_error(
            "CUDA persistent subtree overflow: resident_rows=15873 overflow_flags=0x480 overflow_labels=NO_PROGRESS_SPLIT,OVERSIZED_TERMINAL_NODE leaf_rows=0".to_string(),
        );

        assert!(super::is_gpu_subtree_terminal_depth_only_error(
            &terminal_only
        ));
        assert!(!super::is_gpu_subtree_terminal_depth_only_error(&mixed));
    }

    #[test]
    fn gpu_subtree_capacity_error_does_not_hide_invalid_row_overflow() {
        let err = AnnError::log_index_error(
            "CUDA persistent subtree overflow: resident_rows=10 overflow_flags=0x2000 overflow_labels=INVALID_TOPK_ROW_ID leaf_rows=0".to_string(),
        );
        assert!(!super::is_gpu_subtree_capacity_error(&err));
    }

    struct DimOnlyPointStore {
        rows: usize,
        dim: usize,
    }

    impl PointStore for DimOnlyPointStore {
        fn len(&self) -> usize {
            self.rows
        }

        fn dim(&self) -> usize {
            self.dim
        }

        fn read_point_into(&self, _pid: u32, _out: &mut [f32]) -> AnnResult<()> {
            Err(AnnError::log_index_error(
                "DimOnlyPointStore should not be read by dense-i8 RabitQ+ sidecar build"
                    .to_string(),
            ))
        }

        fn read_range_into(
            &self,
            _start_pid: u32,
            _count: usize,
            _out: &mut [f32],
        ) -> AnnResult<()> {
            Err(AnnError::log_index_error(
                "DimOnlyPointStore should not be range-read by dense-i8 RabitQ+ sidecar build"
                    .to_string(),
            ))
        }

        fn read_points_into(&self, _ids: &[u32], _out: &mut [f32]) -> AnnResult<()> {
            Err(AnnError::log_index_error(
                "DimOnlyPointStore should not be batch-read by dense-i8 RabitQ+ sidecar build"
                    .to_string(),
            ))
        }
    }

    #[test]
    fn rabitq_plus_sidecar_large_task_is_not_host_split_before_backend() {
        let point_ids = (0..15_873_u32).collect::<Vec<_>>();
        let child_run = super::GpuSubtreeChildRun {
            extents: Vec::new(),
            len: point_ids.len(),
            seed: 42,
        };
        let mut child_runs = vec![
            super::GpuSubtreeChildRun {
                extents: Vec::new(),
                len: 0,
                seed: 0,
            };
            1500
        ];
        child_runs[49] = child_run.clone();
        let child_stats = super::compute_gpu_subtree_child_run_stats(&child_runs);
        let output_dir = tempdir().expect("temp output dir");
        let d0_plan = super::GpuSubtreeD0Plan {
            total_points: 10_000_000,
            adaptive_c_max: 2560,
            min_recurse_size: 5120,
            external_child_dir: output_dir.path().to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: super::RootFanoutProfile::default(),
            child_runs,
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats,
            rbc_telemetry: super::RbcPartitionTelemetry::default(),
            d0_capacity: super::D0CapacityTelemetry::default(),
        };
        let dataset = DimOnlyPointStore {
            rows: 10_000_000,
            dim: 1024,
        };
        let mut params = PiPNNParams::default();
        params.random_seed = 42;
        params.leaf_knn = 2;
        params.c_min = 256;
        params.c_max = 1280;
        params.max_depth = 12;
        params.max_leaders = 1500;
        params.fanout_top = 6;
        params.fanout_second = 3;
        params.psamp_fraction = 0.05;
        params.gpu_workspace_budget_bytes = 16 * 1024 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_rabitq_plus_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusMode::Build;
        params.gpu_subtree_rabitq_plus_bits = 8;
        params.gpu_subtree_rabitq_plus_rotator =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusRotator::FhtKac;
        params.gpu_subtree_rabitq_plus_sidecar_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusSidecarMode::Require;
        params.gpu_subtree_rabitq_plus_sidecar_prefix = Some(std::path::PathBuf::from(
            "/tmp/nonexistent-rabitq-plus-sidecar",
        ));
        let backend = SuccessfulCompactSubtreeBackend::sleepy(Duration::ZERO);
        let mut telemetry = super::RbcPartitionTelemetry::default();
        let mut batches = Vec::new();
        let task = super::GpuSubtreeD1ChildTask {
            child_idx: 49,
            child_run,
            points: point_ids,
            replay_wall: Duration::ZERO,
            split_depth: 0,
        };

        let err = super::process_gpu_subtree_d1plus_quantized_sidecar_child(
            &backend,
            &dataset,
            &params,
            &d0_plan,
            &mut telemetry,
            task,
            true,
            super::GpuSubtreeRuntimeContext::default(),
            &mut |batch| {
                batches.push(batch);
                Ok(())
            },
        )
        .unwrap_err();
        let msg = err.to_string();

        assert!(msg.contains("sidecar"));
        assert!(!msg.contains("large-task work guard"));
        assert_eq!(telemetry.gpu_subtree_d1plus_admission_split_count, 0);
        assert_eq!(telemetry.gpu_subtree_compact_success_count, 0);
        assert!(batches.is_empty());
    }

    #[test]
    fn gpu_subtree_d1plus_oom_splits_child_instead_of_cpu_fallback() {
        let dir = tempdir().unwrap();
        let mut store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let point_ids = (0..96_u32).collect::<Vec<_>>();
        let extent = store.append_points(0, &point_ids).unwrap();
        store.finalize().unwrap();
        let child_runs = vec![super::GpuSubtreeChildRun {
            extents: vec![extent],
            len: point_ids.len(),
            seed: 11,
        }];
        let child_stats = super::compute_gpu_subtree_child_run_stats(&child_runs);
        let d0_plan = super::GpuSubtreeD0Plan {
            total_points: point_ids.len(),
            adaptive_c_max: 16,
            min_recurse_size: 32,
            external_child_dir: dir.path().to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: super::RootFanoutProfile::fixed(4),
            child_runs,
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats,
            rbc_telemetry: super::RbcPartitionTelemetry::default(),
            d0_capacity: super::D0CapacityTelemetry {
                enabled: true,
                c_gpu: 16,
                c_high: 8,
                c_target: 8,
                c_low: 2,
                ..super::D0CapacityTelemetry::default()
            },
        };
        let dataset = build_test_dataset(point_ids.len(), 4);
        let store = InmemDatasetPointStore::new(&dataset, point_ids.len());
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.oom_memory_budget_bytes = 512 * 1024 * 1024;
        params.gpu_subtree_d0_capacity_enable = false;
        params.c_min = 4;
        params.c_max = 16;
        params.max_depth = 8;
        params.max_leaders = 8;
        params.psamp_fraction = 0.2;
        params.fanout_top = 4;
        params.fanout_second = 2;
        params.leaf_knn = 2;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        let sink = RecordingCompactTopKSink::new();
        let backend = OomUntilSmallSubtreeBackend::new(point_ids.len() / 2);

        let profile = super::run_gpu_subtree_from_d0_plan(
            &backend,
            &store,
            Metric::L2,
            &params,
            d0_plan,
            &sink,
            super::CompactFlushMode::Sync,
        )
        .unwrap();

        let rows = backend.rows();
        assert!(rows.contains(&point_ids.len()));
        assert!(rows.iter().any(|&rows| rows <= point_ids.len() / 2));
        assert_eq!(profile.rbc.gpu_subtree_compact_success_count, 2);
        assert_eq!(
            profile.rbc.gpu_subtree_compact_success_points,
            point_ids.len()
        );
        assert_eq!(profile.rbc.gpu_subtree_cpu_fallbacks, 0);
        assert_eq!(profile.rbc.gpu_subtree_persistent_fallback_count, 0);
        assert_eq!(profile.rbc.gpu_subtree_d1plus_admission_split_count, 1);
        assert_eq!(
            profile.rbc.gpu_subtree_d1plus_admission_split_rows,
            point_ids.len()
        );
        assert_eq!(
            profile.rbc.gpu_subtree_d1plus_prevented_cpu_fallback_count,
            1
        );
        assert_eq!(
            profile.rbc.gpu_subtree_d1plus_admission_split_max_after,
            point_ids.len() / 2
        );
        assert_eq!(profile.rbc.gpu_subtree_compact_leaf_count, 2);
        assert!(profile.rbc.gpu_subtree_compact_rows >= point_ids.len());
        assert_eq!(
            sink.flushed_ids().len(),
            profile.rbc.gpu_subtree_compact_batches
        );
    }

