    #[test]
    fn gpu_subtree_sq_staging_preflight_shard_local_d1_keeps_payloads_without_sidecar() {
        let dir = tempdir().unwrap();
        let child_dir = dir.path().join("children");
        std::fs::create_dir_all(&child_dir).unwrap();
        let rows = 10;
        let dim = 5;
        let dataset = build_test_dataset(rows, dim);
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let indices = (0..rows as u32).collect::<Vec<_>>();
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.oom_io_mode = PiPNNOomIoMode::Direct;
        params.fanout_top = 2;
        params.max_leaders = 4;
        params.gpu_subtree_sq_staging_mode = PiPNNGpuSubtreeSqStagingMode::GpuD0ShardLocalD1;
        params.gpu_subtree_sq_staging_upload_shard_rows = 3;
        params.gpu_subtree_sq_wmma_mode = PiPNNGpuSubtreeSqWmmaMode::Build;
        params.gpu_subtree_sq_wmma_sidecar_mode = PiPNNGpuSubtreeSqWmmaSidecarMode::Off;
        let mut rng = StdRng::seed_from_u64(7);

        let d0_plan = super::run_gpu_subtree_sq_staging_preflight(
            cpu_backend(),
            &store,
            &indices,
            Metric::L2,
            &params,
            1,
            &mut rng,
            Some(&child_dir),
        )
        .unwrap();

        assert_eq!(d0_plan.total_points, rows);
        assert_eq!(d0_plan.child_stats.total_points, rows * params.fanout_top);
        assert_eq!(d0_plan.sq_shard_local_payloads.len(), 4);
        assert_eq!(
            d0_plan
                .sq_shard_local_payloads
                .iter()
                .map(|payload| payload.ids.len())
                .collect::<Vec<_>>(),
            vec![3, 3, 3, 1]
        );
        assert!(d0_plan.child_runs.iter().all(|run| run.extents.is_empty()));
        assert_eq!(
            d0_plan.rbc_telemetry.gpu_subtree_sq_staging_mode,
            PiPNNGpuSubtreeSqStagingMode::GpuD0ShardLocalD1.as_str()
        );
        assert_eq!(
            d0_plan.rbc_telemetry.gpu_subtree_sq_staging_pipeline_mode,
            "read-compute-direct-d1"
        );
        assert!(
            !d0_plan
                .rbc_telemetry
                .gpu_subtree_sq_staging_sidecar_compatible
        );
        assert_eq!(
            d0_plan.rbc_telemetry.gpu_subtree_sq_staging_sidecar_source,
            "gpu-d0-shard-local-d1"
        );
        assert_eq!(
            d0_plan
                .sq_shard_local_payloads
                .iter()
                .map(|payload| payload.child_local_rows.iter().map(Vec::len).sum::<usize>())
                .sum::<usize>(),
            rows * params.fanout_top
        );
        for payload in &d0_plan.sq_shard_local_payloads {
            assert_eq!(payload.matrix.rows, payload.ids.len());
            assert_eq!(payload.matrix.dim, dim);
            assert_eq!(
                payload.child_local_rows.len(),
                d0_plan.root_fanout_profile.k
            );
            assert!(
                payload
                    .child_local_rows
                    .iter()
                    .flatten()
                    .all(|&row| row < payload.ids.len())
            );
        }
    }

