    #[test]
    fn gpu_coarse_kmeans_backend_reference_trains_sample_centers() {
        let rows = 12;
        let dim = 4;
        let partitions = 4;
        let dataset = build_test_dataset(rows, dim);
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let sample_ids = (0..rows as u32).collect::<Vec<_>>();
        let sample_vectors = super::read_point_ids_dense(&store, &sample_ids).unwrap();
        let params = PiPNNParams::default();

        let result = cpu_backend()
            .train_coarse_kmeans_l2(
                GpuCoarseKMeansTrainRequest {
                    sample_vectors_row_major: &sample_vectors,
                    sample_ids: &sample_ids,
                    partitions,
                    dim,
                    iterations: 2,
                },
                &params,
            )
            .unwrap();

        assert_eq!(result.centers.len(), partitions * dim);
        assert_eq!(result.sample_points, rows);
        assert_eq!(result.profile.partitions, partitions);
        assert_eq!(result.profile.sample_points, rows);
        assert_eq!(result.profile.iterations, 2);
        assert_eq!(result.profile.assignment_backend, "cpu-reference");
        assert_eq!(result.profile.assignment_rows, rows * 2);
    }

    #[test]
    fn gpu_subtree_qcode_split_short_ex_uses_child_local_split_payload() {
        let dir = tempdir().unwrap();
        let rows = 12;
        let dim = 4;
        let mut run_store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let point_ids = (0..rows as u32).collect::<Vec<_>>();
        let extent = run_store.append_points(0, &point_ids).unwrap();
        run_store.finalize().unwrap();
        let child_runs = vec![super::GpuSubtreeChildRun {
            extents: vec![extent],
            len: point_ids.len(),
            seed: 11,
        }];
        let child_stats = super::compute_gpu_subtree_child_run_stats(&child_runs);
        let d0_plan = super::GpuSubtreeD0Plan {
            total_points: rows,
            adaptive_c_max: 8,
            min_recurse_size: 16,
            external_child_dir: dir.path().to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: super::RootFanoutProfile::fixed(4),
            child_runs,
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats,
            rbc_telemetry: super::RbcPartitionTelemetry::default(),
            d0_capacity: super::D0CapacityTelemetry {
                enabled: true,
                c_gpu: 16,
                c_high: 8,
                c_target: 8,
                c_low: 2,
                ..super::D0CapacityTelemetry::default()
            },
        };
        let dataset = build_test_dataset(rows, dim);
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let qcode_dir = tempdir().unwrap();
        let header = RabitqResidualPayloadHeader {
            rows,
            dim,
            padded_dim: dim,
            centroid_count: 1,
            code_row_bytes: dim,
        };
        let centroids = vec![0.0_f32; dim];
        let mut qcode_store =
            RabitqResidualQcodeShardStore::create_split_only(qcode_dir.path(), header, &centroids)
                .unwrap();
        qcode_store
            .write_shard(&RabitqResidualShardPayload {
                global_ids: point_ids.clone(),
                centroid_ids: vec![0; rows],
                codes: (0..rows)
                    .flat_map(|row| {
                        (0..dim).map(move |axis| (row as i8).saturating_add(axis as i8))
                    })
                    .collect(),
                residual_norms: vec![1.0; rows],
                scales: vec![1.0; rows],
                code_sums: vec![0.0; rows],
                original_norms: vec![1.0; rows],
                code_row_bytes: dim,
            })
            .unwrap();
        assert!(qcode_store.is_complete());
        assert!(!qcode_dir.path().join("shard_000000.codes").exists());

        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.leaf_knn = 2;
        params.gpu_subtree_qcode_staging_mode = PiPNNGpuSubtreeQcodeStagingMode::RabitqResidual;
        params.gpu_subtree_qcode_d1_payload_mode = PiPNNGpuSubtreeQcodeD1PayloadMode::ChildLocal;
        params.gpu_subtree_rabitq_d1_distance_mode =
            PiPNNGpuSubtreeRabitqD1DistanceMode::SplitShortEx;
        params.gpu_subtree_rabitq_residual_centroids = 1;
        params.gpu_subtree_qcode_staging_upload_shard_rows = 8;
        params.gpu_subtree_qcode_global_d0_leaders = 4;
        let backend = SuccessfulCompactSubtreeBackend::sleepy(Duration::ZERO);
        let sink = RecordingCompactTopKSink::new();

        let profile = super::run_gpu_subtree_from_d0_plan_with_context(
            &backend,
            &store,
            Metric::L2,
            &params,
            d0_plan,
            &sink,
            super::CompactFlushMode::Sync,
            super::GpuSubtreeRuntimeContext {
                rabitq_residual_qcode_store: Some(&qcode_store),
                ..super::GpuSubtreeRuntimeContext::default()
            },
        )
        .unwrap();

        assert_eq!(backend.calls(), 0);
        assert_eq!(backend.materialized_calls(), 0);
        assert_eq!(backend.resident_rabitq_calls(), 1);
        assert_eq!(backend.resident_rabitq_rows(), vec![rows]);
        assert_eq!(
            backend.resident_rabitq_payload_kinds(),
            vec!["child-local-split"]
        );
        assert_eq!(profile.rbc.gpu_subtree_compact_success_count, 1);
        assert_eq!(profile.rbc.gpu_subtree_qcode_d1_payload_mode, "child-local");
        assert_eq!(
            profile
                .rbc
                .gpu_subtree_rabitq_residual_host_lazy_split_count,
            0
        );
    }

    #[test]
    fn gpu_subtree_sq_wmma_pipeline_uses_resident_sidecar_from_context() {
        let dir = tempdir().unwrap();
        let rows = 6;
        let dim = 4;
        let dataset = build_test_dataset(rows, dim);
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let sidecar_prefix = dir.path().join("tiny.sq8");
        let source_bytes = 8 + rows * dim * std::mem::size_of::<f32>();
        create_sq_wmma_sidecar_from_point_store(&store, &sidecar_prefix, source_bytes as u64)
            .unwrap();
        let resident_sidecar =
            SqWmmaSidecar::preload_validated(&sidecar_prefix, rows, dim).unwrap();

        let mut run_store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let child_a = vec![0, 1, 2, 3];
        let child_b = vec![2, 3, 4, 5];
        let extent_a = run_store.append_points(0, &child_a).unwrap();
        let extent_b = run_store.append_points(0, &child_b).unwrap();
        run_store.finalize().unwrap();
        let child_runs = vec![
            super::GpuSubtreeChildRun {
                extents: vec![extent_a],
                len: child_a.len(),
                seed: 11,
            },
            super::GpuSubtreeChildRun {
                extents: vec![extent_b],
                len: child_b.len(),
                seed: 12,
            },
        ];
        let child_stats = super::compute_gpu_subtree_child_run_stats(&child_runs);
        let d0_plan = super::GpuSubtreeD0Plan {
            total_points: rows,
            adaptive_c_max: 8,
            min_recurse_size: 16,
            external_child_dir: dir.path().to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: super::RootFanoutProfile::fixed(4),
            child_runs,
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats,
            rbc_telemetry: super::RbcPartitionTelemetry::default(),
            d0_capacity: super::D0CapacityTelemetry {
                enabled: true,
                c_gpu: 16,
                c_high: 8,
                c_target: 8,
                c_low: 2,
                ..super::D0CapacityTelemetry::default()
            },
        };
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.leaf_knn = 2;
        params.gpu_subtree_d0_capacity_enable = true;
        params.gpu_subtree_sq_wmma_mode = PiPNNGpuSubtreeSqWmmaMode::Build;
        params.gpu_subtree_sq_wmma_sidecar_mode = PiPNNGpuSubtreeSqWmmaSidecarMode::Require;
        params.gpu_subtree_sq_wmma_sidecar_prefix = Some(sidecar_prefix);
        let backend = SuccessfulCompactSubtreeBackend::sleepy(Duration::ZERO);
        let sink = RecordingCompactTopKSink::new();

        let profile = super::run_gpu_subtree_from_d0_plan_with_context(
            &backend,
            &store,
            Metric::L2,
            &params,
            d0_plan,
            &sink,
            super::CompactFlushMode::AsyncOrdered {
                queue_budget_bytes: 1 << 20,
                worker_policy: super::AsyncCompactFlushWorkerPolicy::Fixed { workers: 1 },
            },
            super::GpuSubtreeRuntimeContext {
                rabitq_plus_resident_sidecar: None,
                sq_wmma_sidecar: Some(&resident_sidecar),
                transient_pipeline_budget_bytes: Some(1 << 20),
                ..super::GpuSubtreeRuntimeContext::default()
            },
        )
        .unwrap();

        assert_eq!(backend.calls(), 2);
        assert_eq!(profile.rbc.gpu_subtree_sq_wmma_sidecar_rows, 8);
        assert!(profile.rbc.gpu_subtree_sq_wmma_sidecar_resident);
        assert_eq!(
            profile.rbc.gpu_subtree_sq_wmma_sidecar_resident_bytes,
            resident_sidecar.resident_bytes()
        );
        assert!(profile.rbc.gpu_subtree_sq_wmma_sidecar_resident_gather_wall > Duration::ZERO);
        assert_eq!(
            profile.rbc.gpu_subtree_sq_wmma_sidecar_file_gather_wall,
            Duration::ZERO
        );
        assert_eq!(profile.rbc.gpu_subtree_sidecar_preload_children, 2);
        assert_eq!(profile.rbc.gpu_subtree_sidecar_preload_workers, 1);
        assert!(profile.rbc.gpu_subtree_sidecar_gather_active_wall > Duration::ZERO);
        assert!(profile.rbc.gpu_subtree_gpu_wait_for_sidecar_wall > Duration::ZERO);
        assert!(
            profile.rbc.gpu_subtree_sidecar_gather_hidden_wall
                <= profile.rbc.gpu_subtree_sidecar_gather_active_wall
        );
        assert!(profile.rbc.gpu_subtree_sidecar_queue_max_bytes > 0);
    }

