    #[test]
    fn sq_wmma_preload_uses_admissible_split_rows_when_c_high_is_too_large() {
        let dir = tempdir().unwrap();
        let dim = 1024;
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.oom_memory_budget_bytes = 96 * 1024;
        params.gpu_workspace_budget_bytes = 96 * 1024;
        params.gpu_subtree_d0_capacity_enable = true;
        params.gpu_subtree_d0_capacity_split_recursion_limit = 6;
        params.gpu_subtree_sq_wmma_mode = PiPNNGpuSubtreeSqWmmaMode::Build;
        params.gpu_subtree_sq_wmma_sidecar_mode = PiPNNGpuSubtreeSqWmmaSidecarMode::Require;
        params.gpu_subtree_sq_wmma_sidecar_prefix = Some(dir.path().join("preload_clamped.sq8"));
        params.c_min = 4;
        params.c_max = 16;
        params.max_depth = 8;
        params.max_leaders = 8;
        params.psamp_fraction = 0.2;
        params.fanout_top = 4;
        params.fanout_second = 2;
        params.leaf_knn = 2;

        let ratio = super::d1plus_admission_ratio(&params);
        let workspace_budget = params.effective_gpu_workspace_budget_bytes();
        let device_budget = ((workspace_budget as f64) * ratio).floor().max(1.0) as usize;
        let max_admissible = find_max_admissible_rows(
            dim,
            params.leaf_knn,
            gpu_persistent_subtree_max_leaders_for_params(&params),
            params.fanout_second.max(1),
            Some(workspace_budget),
            Some(device_budget),
            &params,
        );
        assert!(max_admissible > 1);

        let c_high = max_admissible + 1;
        let point_ids = (0..(c_high + 8) as u32).collect::<Vec<_>>();
        let d0_plan =
            d0_plan_with_single_child_and_capacity(&dir, &point_ids, c_high, max_admissible);

        assert!(!d1_admission_preflight(c_high, dim, &params, ratio).supported);
        assert!(d1_admission_preflight(max_admissible, dim, &params, ratio).supported);
        assert!(super::gpu_subtree_sq_wmma_sidecar_preload_enabled(
            &params, &d0_plan, dim
        ));
    }

    #[test]
    fn sq_wmma_preload_splits_oversized_child_before_gather() {
        let dir = tempdir().unwrap();
        let rows = 96;
        let dim = 4;
        let dataset = build_test_dataset(rows, dim);
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let sidecar_prefix = dir.path().join("split_preload.sq8");
        let source_bytes = 8 + rows * dim * std::mem::size_of::<f32>();
        create_sq_wmma_sidecar_from_point_store(&store, &sidecar_prefix, source_bytes as u64)
            .unwrap();
        let resident_sidecar =
            SqWmmaSidecar::preload_validated(&sidecar_prefix, rows, dim).unwrap();

        let point_ids = (0..rows as u32).collect::<Vec<_>>();
        let d0_plan = d0_plan_with_single_child_and_capacity(&dir, &point_ids, 20, 18);
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.oom_memory_budget_bytes = 512 * 1024 * 1024;
        params.gpu_workspace_budget_bytes = 512 * 1024 * 1024;
        params.gpu_subtree_d0_capacity_enable = true;
        params.gpu_subtree_d0_capacity_split_recursion_limit = 6;
        params.gpu_subtree_sq_wmma_mode = PiPNNGpuSubtreeSqWmmaMode::Build;
        params.gpu_subtree_sq_wmma_sidecar_mode = PiPNNGpuSubtreeSqWmmaSidecarMode::Require;
        params.gpu_subtree_sq_wmma_sidecar_prefix = Some(sidecar_prefix);
        params.c_min = 4;
        params.c_max = 16;
        params.max_depth = 8;
        params.max_leaders = 8;
        params.psamp_fraction = 0.2;
        params.fanout_top = 4;
        params.fanout_second = 2;
        params.leaf_knn = 2;
        let sink = RecordingCompactTopKSink::new();
        let backend = SuccessfulCompactSubtreeBackend::sleepy(Duration::ZERO);
        let raw_store = CountingPointStore::new(rows, dim);

        let profile = super::run_gpu_subtree_from_d0_plan_with_context(
            &backend,
            &raw_store,
            Metric::L2,
            &params,
            d0_plan,
            &sink,
            super::CompactFlushMode::AsyncOrdered {
                queue_budget_bytes: 1 << 20,
                worker_policy: super::AsyncCompactFlushWorkerPolicy::Fixed { workers: 1 },
            },
            super::GpuSubtreeRuntimeContext {
                rabitq_plus_resident_sidecar: None,
                sq_wmma_sidecar: Some(&resident_sidecar),
                transient_pipeline_budget_bytes: Some(1 << 20),
                ..super::GpuSubtreeRuntimeContext::default()
            },
        )
        .unwrap();

        let backend_rows = backend.rows();
        assert!(!backend_rows.contains(&rows), "{backend_rows:?}");
        assert!(
            backend_rows.iter().all(|&rows| rows <= 20),
            "{backend_rows:?}"
        );
        assert!(profile.rbc.gpu_subtree_sidecar_preload_children >= 2);
        assert!(profile.rbc.gpu_subtree_d1plus_preflight_split_count >= 1);
        assert_eq!(
            profile.rbc.gpu_subtree_d1plus_lazy_split_source,
            "sq-resident"
        );
        assert_eq!(profile.rbc.gpu_subtree_cpu_fallbacks, 0);
        assert_eq!(raw_store.point_read_count(), 0);
        assert_eq!(
            raw_store.batch_read_count(),
            0,
            "SQ lazy split must not revisit raw vectors"
        );
    }

    #[test]
    fn gpu_subtree_d1plus_materialization_reuse_loads_union_once_for_overlapping_children() {
        let dir = tempdir().unwrap();
        let mut run_store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let child_a = vec![0, 1, 2, 3];
        let child_b = vec![2, 3, 4, 5];
        let extent_a = run_store.append_points(0, &child_a).unwrap();
        let extent_b = run_store.append_points(0, &child_b).unwrap();
        run_store.finalize().unwrap();
        let child_runs = vec![
            super::GpuSubtreeChildRun {
                extents: vec![extent_a],
                len: child_a.len(),
                seed: 11,
            },
            super::GpuSubtreeChildRun {
                extents: vec![extent_b],
                len: child_b.len(),
                seed: 12,
            },
        ];
        let child_stats = super::compute_gpu_subtree_child_run_stats(&child_runs);
        let d0_plan = super::GpuSubtreeD0Plan {
            total_points: 6,
            adaptive_c_max: 8,
            min_recurse_size: 16,
            external_child_dir: dir.path().to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: super::RootFanoutProfile::fixed(4),
            child_runs,
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats,
            rbc_telemetry: super::RbcPartitionTelemetry::default(),
            d0_capacity: super::D0CapacityTelemetry::default(),
        };
        let store = CountingPointStore::new(6, 4);
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.oom_memory_budget_bytes = 512 * 1024 * 1024;
        params.leaf_knn = 2;
        let backend = SuccessfulCompactSubtreeBackend::sleepy(Duration::ZERO);
        let sink = RecordingCompactTopKSink::new();

        let mut telemetry = d0_plan.rbc_telemetry.clone();
        let mut leaf_profile = LeafProfile::default();
        super::run_gpu_subtree_d1plus_materialization_reuse(
            &backend,
            &store,
            &params,
            &d0_plan,
            &mut telemetry,
            super::GpuSubtreeRuntimeContext::default(),
            |batch| {
                let profile = sink.flush_compact_topk(batch)?;
                leaf_profile.merge(profile);
                Ok(())
            },
        )
        .unwrap();
        let profile = super::GpuSubtreeStreamingProfile {
            rbc: telemetry,
            leaf: leaf_profile,
            entry_point: Some(0),
        };

        let mut flushed = sink.flushed_ids();
        flushed.sort_unstable();
        let mut materialized_rows = backend.materialized_rows();
        materialized_rows.sort_unstable();
        assert_eq!(store.batch_read_count(), 1);
        assert_eq!(store.point_read_count(), 0);
        assert_eq!(backend.calls(), 0);
        assert_eq!(backend.materialized_calls(), 2);
        assert_eq!(materialized_rows, vec![4, 4]);
        assert_eq!(flushed, vec![0, 1]);
        assert!(profile.rbc.gpu_subtree_host_materialization_reuse_enabled);
        assert_eq!(profile.rbc.gpu_subtree_host_materialization_groups, 1);
        assert_eq!(
            profile
                .rbc
                .gpu_subtree_host_materialization_materialized_children,
            2
        );
        assert_eq!(
            profile.rbc.gpu_subtree_host_materialization_duplicate_rows,
            2
        );
        assert_eq!(
            profile
                .rbc
                .gpu_subtree_host_materialization_saved_read_rows_estimate,
            2
        );
        assert_eq!(profile.rbc.gpu_subtree_compact_success_count, 2);
        assert_eq!(
            profile.rbc.gpu_subtree_compact_success_points,
            child_a.len() + child_b.len()
        );
    }

