    #[test]
    fn gpu_subtree_vector_staging_groups_nonconsecutive_overlaps() {
        let dir = tempdir().unwrap();
        let mut run_store = ExternalRunStore::new(dir.path(), DirectIoConfig::disabled());
        let rows = 131_072_u32;
        let child_a = (0..rows).collect::<Vec<_>>();
        let child_b = (200_000..200_000 + rows).collect::<Vec<_>>();
        let child_c = (400_000..400_000 + rows).collect::<Vec<_>>();
        let child_d = (600_000..600_000 + rows).collect::<Vec<_>>();
        let children = [
            child_a.clone(),
            child_b.clone(),
            child_c.clone(),
            child_d.clone(),
            child_a.clone(),
            child_b.clone(),
        ];
        let mut child_runs = Vec::with_capacity(children.len());
        for (idx, child) in children.iter().enumerate() {
            let extent = run_store.append_points(0, child).unwrap();
            child_runs.push(super::GpuSubtreeChildRun {
                extents: vec![extent],
                len: child.len(),
                seed: 100 + idx as u64,
            });
        }
        run_store.finalize().unwrap();

        let child_stats = super::compute_gpu_subtree_child_run_stats(&child_runs);
        let d0_plan = super::GpuSubtreeD0Plan {
            total_points: 800_000,
            adaptive_c_max: 8,
            min_recurse_size: 16,
            external_child_dir: dir.path().to_path_buf(),
            io_cfg: DirectIoConfig::disabled(),
            root_fanout_profile: super::RootFanoutProfile::fixed(6),
            child_runs,
            sq_shard_local_payloads: Vec::new(),
            sq_cluster_child_indices: Vec::new(),
            child_stats,
            rbc_telemetry: super::RbcPartitionTelemetry::default(),
            d0_capacity: super::D0CapacityTelemetry::default(),
        };
        let store = CountingPointStore::new(800_000, 2);
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.oom_memory_budget_bytes = 512 * 1024 * 1024;
        params.gpu_subtree_vector_staging_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeVectorStagingMode::FanoutSlab;
        params.leaf_knn = 2;
        let backend = SuccessfulCompactSubtreeBackend::sleepy(Duration::ZERO);
        let sink = RecordingCompactTopKSink::new();

        let profile = super::run_gpu_subtree_from_d0_plan(
            &backend,
            &store,
            Metric::L2,
            &params,
            d0_plan,
            &sink,
            super::CompactFlushMode::AsyncOrdered {
                queue_budget_bytes: 1 << 20,
                worker_policy: super::AsyncCompactFlushWorkerPolicy::Fixed { workers: 1 },
            },
        )
        .unwrap();

        assert_eq!(backend.materialized_calls(), 4);
        assert_eq!(backend.calls(), 2);
        assert_eq!(store.batch_read_count(), 2);
        assert_eq!(profile.rbc.gpu_subtree_vector_staging_groups, 2);
        assert_eq!(
            profile.rbc.gpu_subtree_vector_staging_materialized_children,
            4
        );
        assert_eq!(
            profile
                .rbc
                .gpu_subtree_vector_staging_saved_read_rows_estimate,
            (rows as usize) * 2
        );
        assert_eq!(
            profile.rbc.gpu_subtree_d1plus_child_rows_total,
            rows as usize * children.len()
        );
        assert_eq!(
            profile.rbc.gpu_subtree_d1plus_unique_rows_estimate,
            rows as usize * 4
        );
    }

    #[test]
    fn gpu_subtree_child_schedule_overlap_greedy_clusters_repeated_children() {
        fn staging_task(child_idx: usize, points: &[u32]) -> super::GpuSubtreeD1StagingTask {
            let mut unique_ids = points.to_vec();
            unique_ids.sort_unstable();
            unique_ids.dedup();
            super::GpuSubtreeD1StagingTask {
                task: super::GpuSubtreeD1ChildTask {
                    child_idx,
                    child_run: super::GpuSubtreeChildRun {
                        extents: Vec::new(),
                        len: points.len(),
                        seed: child_idx as u64,
                    },
                    points: points.to_vec(),
                    replay_wall: Duration::ZERO,
                    split_depth: 0,
                },
                unique_ids,
            }
        }

        let tasks = vec![
            staging_task(0, &[0, 1, 2]),
            staging_task(1, &[10, 11, 12]),
            staging_task(2, &[0, 1, 2]),
            staging_task(3, &[10, 11, 12]),
        ];
        let natural = super::identity_child_order(tasks.len());
        let natural_profile =
            super::estimate_d1plus_repeat_profile_for_task_order(&tasks, &natural, 16);
        assert_eq!(natural_profile.rolling_prev1_hits, 0);

        let mut params = PiPNNParams::default();
        params.gpu_subtree_child_schedule_mode = PiPNNGpuSubtreeChildScheduleMode::OverlapGreedy;
        params.gpu_subtree_vector_staging_window_children = 1;
        params.gpu_subtree_vector_staging_budget_bytes = 1 << 20;
        let mut telemetry = super::RbcPartitionTelemetry::default();
        let order = super::plan_gpu_subtree_d1plus_child_schedule_order(
            &tasks,
            16,
            &params,
            &mut telemetry,
        );
        assert_eq!(order, vec![0, 2, 1, 3]);

        let scheduled_profile =
            super::estimate_d1plus_repeat_profile_for_task_order(&tasks, &order, 16);
        assert_eq!(scheduled_profile.rolling_prev1_hits, 6);
        assert_eq!(telemetry.gpu_subtree_child_schedule_mode, "overlap-greedy");
        assert_eq!(telemetry.gpu_subtree_child_schedule_reordered_children, 4);
        assert_eq!(telemetry.gpu_subtree_child_schedule_overlap_edges, 2);
    }

