    fn collect_sorted_leaves(receiver: crossbeam::channel::Receiver<Vec<u32>>) -> Vec<Vec<u32>> {
        let mut leaves: Vec<Vec<u32>> = receiver
            .iter()
            .map(|mut leaf| {
                leaf.sort_unstable();
                leaf
            })
            .collect();
        leaves.sort_unstable();
        leaves
    }

    #[test]
    fn external_run_store_strict_io_round_trips_child_runs() {
        let dir = tempdir().unwrap();
        let mut store =
            ExternalRunStore::new(dir.path(), DirectIoConfig::enabled_with_alignment(4096));

        let extent_a = store.append_points(1, &[1, 2, 3, 4]).unwrap();
        let extent_b = store.append_points(1, &[10, 11]).unwrap();
        let extent_c = store.append_points(2, &[7, 8, 9]).unwrap();

        assert_eq!(store.read_points(1, extent_a).unwrap(), vec![1, 2, 3, 4]);
        assert_eq!(store.read_points(1, extent_b).unwrap(), vec![10, 11]);
        assert_eq!(store.read_points(2, extent_c).unwrap(), vec![7, 8, 9]);
    }

    #[test]
    fn external_run_store_strict_io_does_not_sync_every_append() {
        use crate::algorithm::pipnn::direct_io::{
            direct_io_test_sync_calls, reset_direct_io_test_counters,
        };

        let dir = tempdir().unwrap();
        let mut store =
            ExternalRunStore::new(dir.path(), DirectIoConfig::enabled_with_alignment(4096));
        reset_direct_io_test_counters();

        for i in 0..16_u32 {
            store.append_points(1, &[i, i + 1, i + 2]).unwrap();
        }

        assert_eq!(
            direct_io_test_sync_calls(),
            0,
            "strict partition run appends should defer sync instead of syncing every extent"
        );
    }

