    #[test]
    fn resident_child_recursion_matches_external_child_recursion() {
        let num_points = 96;
        let dim = 6;
        let dataset = build_test_dataset(num_points, dim);
        let point_store = InmemDatasetPointStore::new(&dataset, num_points);
        let child_points: Vec<u32> = (0..num_points as u32)
            .filter(|point| point % 3 != 1)
            .collect();
        let mut params = PiPNNParams::default();
        params.oom_enable = true;
        params.oom_memory_budget_bytes = 512 * 1024 * 1024;
        params.c_min = 8;
        params.c_max = 12;
        params.max_depth = 4;
        params.max_leaders = 16;
        params.fanout_top = 4;
        params.fanout_second = 2;
        let adaptive_c_max = params.adaptive_c_max(child_points.len());
        let min_recurse_size = adaptive_c_max.saturating_mul(2);
        let pb = ProgressBar::hidden();

        let external_dir = tempdir().unwrap();
        let external_store = Arc::new(Mutex::new(ExternalRunStore::new(
            external_dir.path(),
            DirectIoConfig::disabled(),
        )));
        let child_run = {
            let mut guard = external_store.lock();
            let extent = super::write_child_run(&mut guard, 0, &child_points).unwrap();
            super::ChildRun {
                extents: vec![extent],
                len: child_points.len(),
                seed: 0x5eed,
            }
        };

        let (external_tx, external_rx) = unbounded();
        let external_stats = super::recurse_child_run_maybe_resident(
            cpu_backend(),
            &point_store,
            child_run.clone(),
            1,
            child_points.len(),
            Metric::L2,
            &params,
            adaptive_c_max,
            min_recurse_size,
            &pb,
            &external_store,
            None,
            super::GpuSubtreeRuntimeContext::default(),
            &super::RootFanoutState::fixed(params.fanout_top),
            &external_tx,
        )
        .unwrap();
        drop(external_tx);

        let memory = super::RbcMemoryContext::for_oom_budget(96 * 1024 * 1024, dim)
            .expect("test memory context should be available");
        let resident_options = super::ResidentSubtreeOptions {
            memory: &memory,
            materialize: true,
        };
        let (resident_tx, resident_rx) = unbounded();
        let resident_stats = super::recurse_child_run_maybe_resident(
            cpu_backend(),
            &point_store,
            child_run,
            1,
            child_points.len(),
            Metric::L2,
            &params,
            adaptive_c_max,
            min_recurse_size,
            &pb,
            &external_store,
            Some(resident_options),
            super::GpuSubtreeRuntimeContext::default(),
            &super::RootFanoutState::fixed(params.fanout_top),
            &resident_tx,
        )
        .unwrap();
        drop(resident_tx);

        let resident_leaves = collect_sorted_leaves(resident_rx);
        let external_leaves = collect_sorted_leaves(external_rx);
        assert_eq!(resident_leaves, external_leaves);
        assert_eq!(external_stats.telemetry.resident_subtree_count, 0);
        assert!(resident_stats.telemetry.resident_subtree_count >= 1);
        assert!(resident_stats.telemetry.resident_subtree_points >= child_points.len());
        assert_eq!(
            resident_stats.telemetry.resident_subtree_leaf_count,
            resident_leaves.len()
        );
        assert!(resident_stats.telemetry.resident_subtree_emit_wall > Duration::ZERO);
        assert!(resident_stats.telemetry.resident_subtree_max_points >= child_points.len());
    }

    #[cfg(any())]
    #[test]
    fn partition_preserves_point_coverage_even_with_large_emitted_leaves() {
        let num_points = 23;
        let dataset = build_test_dataset(num_points, 4);
        let store = InmemDatasetPointStore::new(&dataset, num_points);
        let indices: Vec<u32> = (0..num_points as u32).collect();
        let (tx, rx) = unbounded();

        let mut params = PiPNNParams::default();
        params.c_min = 1;
        params.c_max = 64;
        params.max_depth = 0;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.max_full_matrix_leaf_size = 5;

        let mut rng = StdRng::seed_from_u64(params.random_seed);
        rbc_partition_streaming(&store, &indices, Metric::L2, &params, 1, &mut rng, &tx).unwrap();
        drop(tx);

        let leaves: Vec<Vec<u32>> = rx.into_iter().collect();
        assert!(!leaves.is_empty());
        assert_eq!(leaves.iter().map(Vec::len).sum::<usize>(), num_points);

        let mut emitted_points: Vec<u32> = leaves.into_iter().flatten().collect();
        emitted_points.sort_unstable();
        emitted_points.dedup();
        assert_eq!(emitted_points.len(), num_points);
    }

    #[test]
    fn partition_forces_oversized_leaves_below_hard_cap() {
        let num_points = 16_023;
        let dataset = build_test_dataset(num_points, 4);
        let store = InmemDatasetPointStore::new(&dataset, num_points);
        let indices: Vec<u32> = (0..num_points as u32).collect();
        let (tx, rx) = unbounded();

        let mut params = PiPNNParams::default();
        params.c_min = 1;
        params.c_max = 64;
        params.max_depth = 0;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.max_full_matrix_leaf_size = 5;

        let mut rng = StdRng::seed_from_u64(params.random_seed);
        rbc_partition_streaming(&store, &indices, Metric::L2, &params, 1, &mut rng, &tx).unwrap();
        drop(tx);

        let leaves: Vec<Vec<u32>> = rx.into_iter().collect();
        assert!(!leaves.is_empty());
        assert!(
            leaves
                .iter()
                .all(|leaf| leaf.len() <= super::FORCED_LEAF_HARD_CAP),
            "all emitted leaves should respect the forced hard cap"
        );

        let mut emitted_points: Vec<u32> = leaves.into_iter().flatten().collect();
        emitted_points.sort_unstable();
        emitted_points.dedup();
        assert_eq!(emitted_points.len(), num_points);
    }

    #[test]
    fn emit_leaf_with_safety_records_forced_split_for_oversized_leaf() {
        let dataset = build_test_dataset(16_023, 4);
        let store = InmemDatasetPointStore::new(&dataset, 16_023);
        let (tx, rx) = unbounded();
        let mut params = PiPNNParams::default();
        params.c_min = 1;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.max_full_matrix_leaf_size = 5;

        let mut stats = PartitionStats::new(params.max_depth, 4);
        let mut leaf: Vec<u32> = (0..16_023_u32).collect();
        super::emit_leaf_with_safety(
            &store,
            Metric::L2,
            &params,
            &mut leaf,
            0,
            super::LeafReason::MaxDepth,
            params.max_full_matrix_leaf_size,
            &mut stats,
            &tx,
        )
        .unwrap();
        drop(tx);

        let leaves: Vec<Vec<u32>> = rx.into_iter().collect();
        assert!(stats.forced_leaf_splits > 0);
        assert!(
            leaves
                .iter()
                .all(|leaf| leaf.len() <= super::FORCED_LEAF_HARD_CAP)
        );
    }

    #[test]
    fn adaptive_fanout_uses_depth_aware_overlap_schedule() {
        let mut params = PiPNNParams::default();
        params.fanout_top = 10;
        params.fanout_second = 3;

        assert_eq!(params.adaptive_fanout(10_000, 0), 10);
        assert_eq!(params.adaptive_fanout(2_000_000, 0), 10);
        assert_eq!(params.adaptive_fanout(20_000_000, 0), 10);
        assert_eq!(params.adaptive_fanout(10_000, 1), 3);
        assert_eq!(params.adaptive_fanout(2_000_000, 1), 3);
        assert_eq!(params.adaptive_fanout(10_000, 3), 1);

        let mut local_fanout = params.adaptive_fanout(10_000, 3);
        let num_leaders = 2;
        if num_leaders > 1 {
            local_fanout = local_fanout.min(num_leaders);
        } else {
            local_fanout = 1;
        }

        assert_eq!(local_fanout, 1);
    }

    #[test]
    fn stats_track_dedup_work_and_removed_assignments() {
        let mut stats = PartitionStats::new(4, 8);

        stats.record_dedup(true, 8, 6);
        stats.record_dedup(false, 10, 10);

        assert_eq!(stats.dedup_runs, 1);
        assert_eq!(stats.dedup_skipped, 1);
        assert_eq!(stats.dedup_assignments_before, 8);
        assert_eq!(stats.dedup_assignments_after, 6);
        assert_eq!(stats.dedup_assignments_removed, 2);
    }

    #[test]
    fn fanout_one_dedup_policy_skips_non_root_clusters() {
        let params = PiPNNParams::default();

        assert!(super::should_dedup_cluster(&params, 0, 1));
        assert!(super::should_dedup_cluster(&params, 1, 3));
        assert!(!super::should_dedup_cluster(&params, 2, 1));
        assert!(!super::should_dedup_cluster(&params, 5, 1));
    }

    #[test]
    fn stats_accumulate_phase_timing() {
        let mut stats = PartitionStats::new(4, 8);

        stats.record_phase_time(super::RbcPhase::CurDedup, Duration::from_millis(12));
        stats.record_assignment_time(0, Duration::from_millis(20));
        stats.record_assignment_time(1, Duration::from_millis(30));
        stats.record_phase_time(super::RbcPhase::CurDedup, Duration::from_millis(8));
        stats.record_phase_time(super::RbcPhase::D1Materialize, Duration::from_millis(40));
        stats.record_phase_time(super::RbcPhase::D2Replay, Duration::from_millis(50));

        assert_eq!(stats.cur_dedup_time, Duration::from_millis(20));
        assert_eq!(stats.cluster_assign_time, Duration::from_millis(50));
        assert_eq!(
            stats.telemetry.d0_ads_assignment_wall,
            Duration::from_millis(20)
        );
        assert_eq!(
            stats.telemetry.d1_ads_assignment_wall,
            Duration::from_millis(30)
        );
        assert_eq!(
            stats.telemetry.d1_materialize_wall,
            Duration::from_millis(40)
        );
        assert_eq!(stats.telemetry.d2_replay_wall, Duration::from_millis(50));
        assert_eq!(stats.merge_time, Duration::ZERO);
    }

    #[test]
    fn stats_merge_combines_phase_timing() {
        let mut left = PartitionStats::new(4, 8);
        let mut right = PartitionStats::new(4, 8);

        left.record_phase_time(super::RbcPhase::MergedDedup, Duration::from_millis(7));
        right.record_phase_time(super::RbcPhase::MergedDedup, Duration::from_millis(5));
        right.record_phase_time(super::RbcPhase::MergeClusters, Duration::from_millis(11));
        left.record_assignment_time(0, Duration::from_millis(13));
        right.record_assignment_time(1, Duration::from_millis(17));
        right.record_phase_time(super::RbcPhase::D1Materialize, Duration::from_millis(19));
        right.record_phase_time(super::RbcPhase::D2Replay, Duration::from_millis(23));
        left.record_resident_subtree_hit(
            10,
            1024,
            Duration::from_millis(2),
            Duration::from_millis(3),
        );
        left.telemetry.resident_subtree_emit_wall = Duration::from_millis(7);
        left.telemetry.resident_subtree_leaf_count = 1;
        left.telemetry.resident_subtree_max_points = 10;
        right.record_resident_subtree_hit(
            20,
            2048,
            Duration::from_millis(4),
            Duration::from_millis(5),
        );
        right.telemetry.resident_subtree_emit_wall = Duration::from_millis(11);
        right.telemetry.resident_subtree_leaf_count = 2;
        right.telemetry.resident_subtree_max_points = 20;
        right.record_resident_subtree_fallback(20, Duration::from_millis(6));

        left.merge_from(right);

        assert_eq!(left.merged_dedup_time, Duration::from_millis(12));
        assert_eq!(left.merge_time, Duration::from_millis(11));
        assert_eq!(left.cluster_assign_time, Duration::from_millis(30));
        assert_eq!(
            left.telemetry.d0_ads_assignment_wall,
            Duration::from_millis(13)
        );
        assert_eq!(
            left.telemetry.d1_ads_assignment_wall,
            Duration::from_millis(17)
        );
        assert_eq!(
            left.telemetry.d1_materialize_wall,
            Duration::from_millis(19)
        );
        assert_eq!(left.telemetry.d2_replay_wall, Duration::from_millis(23));
        assert_eq!(left.telemetry.resident_subtree_count, 2);
        assert_eq!(left.telemetry.resident_subtree_points, 30);
        assert_eq!(left.telemetry.resident_subtree_bytes, 3072);
        assert_eq!(
            left.telemetry.resident_subtree_read_wall,
            Duration::from_millis(6)
        );
        assert_eq!(
            left.telemetry.resident_subtree_compute_wall,
            Duration::from_millis(8)
        );
        assert_eq!(
            left.telemetry.resident_subtree_emit_wall,
            Duration::from_millis(18)
        );
        assert_eq!(left.telemetry.resident_subtree_leaf_count, 3);
        assert_eq!(left.telemetry.resident_subtree_fallback_count, 1);
        assert_eq!(left.telemetry.resident_subtree_fallback_points, 20);
        assert_eq!(left.telemetry.resident_subtree_max_points, 20);
        assert_eq!(
            left.telemetry.resident_subtree_permit_wait,
            Duration::from_millis(6)
        );
    }

    #[test]
    fn post_last_gpu_cpu_tail_finalizes_after_all_flush_mode_branches() {
        let source = include_str!("rbc_partition.rs");
        let production = source.split("\n#[cfg(test)]\nmod tests {").next().unwrap();

        assert_eq!(
            production
                .matches("telemetry.finish_post_last_gpu_cpu_tail(Instant::now());")
                .count(),
            3
        );
    }

    #[test]
    fn post_last_gpu_cpu_tail_uses_explicit_completion_and_flush_boundaries() {
        let last_gpu_completion_at = Instant::now();
        let flush_completed_at = last_gpu_completion_at + Duration::from_millis(42);
        let mut telemetry = super::RbcPartitionTelemetry::default();

        telemetry.observe_last_gpu_completion(Some(last_gpu_completion_at));
        telemetry.finish_post_last_gpu_cpu_tail(flush_completed_at);

        assert!(telemetry.gpu_subtree_post_last_gpu_cpu_tail_observed);
        assert_eq!(
            telemetry.gpu_subtree_post_last_gpu_cpu_tail_wall,
            Duration::from_millis(42)
        );
    }

    #[test]
    fn post_last_gpu_cpu_tail_is_unobserved_without_gpu_marker() {
        let mut telemetry = super::RbcPartitionTelemetry::default();

        telemetry.finish_post_last_gpu_cpu_tail(Instant::now());

        assert!(!telemetry.gpu_subtree_post_last_gpu_cpu_tail_observed);
        assert_eq!(
            telemetry.gpu_subtree_post_last_gpu_cpu_tail_wall,
            Duration::ZERO
        );
    }

    #[test]
    fn post_last_gpu_cpu_tail_keeps_latest_child_marker() {
        let older = Instant::now();
        let newer = older + Duration::from_millis(5);
        let mut telemetry = super::RbcPartitionTelemetry::default();
        let older_profile = GpuSubtreeTopKProfile {
            last_gpu_completion_at: Some(older),
            ..GpuSubtreeTopKProfile::default()
        };
        let newer_profile = GpuSubtreeTopKProfile {
            last_gpu_completion_at: Some(newer),
            ..GpuSubtreeTopKProfile::default()
        };

        super::merge_gpu_subtree_topk_profile(&mut telemetry, &newer_profile);
        super::merge_gpu_subtree_topk_profile(&mut telemetry, &older_profile);

        assert_eq!(telemetry.gpu_subtree_last_gpu_completion_at, Some(newer));
    }

