    #[test]
    fn merge_cluster_buffers_appends_all_assignments() {
        let mut dst = vec![vec![1_u32, 2], vec![], vec![9]];
        let src = vec![vec![3_u32], vec![4, 5], vec![]];

        super::merge_cluster_buffers(&mut dst, src);

        assert_eq!(dst, vec![vec![1, 2, 3], vec![4, 5], vec![9]]);
    }

    #[test]
    fn merge_cluster_plan_matches_legacy_merge_grouping() {
        let raw_clusters = vec![
            vec![10_u32, 11],
            vec![],
            vec![30_u32],
            vec![40_u32, 41, 42, 43],
            vec![50_u32],
            vec![60_u32, 61, 62],
            vec![],
        ];
        let raw_counts: Vec<usize> = raw_clusters.iter().map(Vec::len).collect();
        let plan = super::merge_cluster_plan(&raw_counts, 3, 6);

        let planned_groups: Vec<BTreeSet<u32>> = plan
            .iter()
            .map(|group| {
                group
                    .raw_children
                    .iter()
                    .flat_map(|&raw_child| raw_clusters[raw_child as usize].iter().copied())
                    .collect()
            })
            .collect();

        let legacy_groups: Vec<BTreeSet<u32>> = super::merge_clusters(raw_clusters.clone(), 3, 6)
            .into_iter()
            .map(|cluster| cluster.into_iter().collect())
            .collect();

        assert_eq!(planned_groups, legacy_groups);
    }

    #[test]
    fn materialize_from_spool_matches_legacy_merge_membership() {
        let temp = tempdir().unwrap();
        let mut store = super::ExternalRunStore::new(temp.path(), DirectIoConfig::disabled());
        let cur = vec![7_u32, 1, 4, 9, 3, 8, 5, 2, 6];
        let raw_assignments: Vec<Vec<u16>> = vec![
            vec![2, 0],
            vec![1, 0],
            vec![2, 3],
            vec![0, 3],
            vec![1, 3],
            vec![2, 0],
            vec![1, 0],
            vec![3, 2],
            vec![0, 1],
        ];
        let raw_child_count = 4usize;
        let fanout = 2usize;
        let mut raw_counts = vec![0usize; raw_child_count];
        let spool = tempfile::NamedTempFile::new_in(temp.path()).unwrap();
        {
            let mut writer = std::io::BufWriter::new(spool.reopen().unwrap());
            for assignment in &raw_assignments {
                for &raw_child in assignment {
                    raw_counts[raw_child as usize] += 1;
                }
                super::write_assign_record(&mut writer, assignment, fanout).unwrap();
            }
            writer.flush().unwrap();
        }

        let merge_groups = super::merge_cluster_plan(&raw_counts, 3, 6);
        let materialized = super::materialize_merged_children_from_spool(
            &cur,
            0,
            fanout,
            &merge_groups,
            &spool,
            &mut store,
        )
        .unwrap();

        let actual: Vec<BTreeSet<u32>> = materialized
            .into_iter()
            .map(|child| {
                super::read_child_run_chain(&store, 0, &child.extents)
                    .unwrap()
                    .into_iter()
                    .collect()
            })
            .collect();

        let mut legacy_raw = vec![Vec::new(); raw_child_count];
        for (&point, assignment) in cur.iter().zip(raw_assignments.iter()) {
            for &raw_child in assignment {
                legacy_raw[raw_child as usize].push(point);
            }
        }
        let expected: Vec<BTreeSet<u32>> = super::merge_clusters(legacy_raw, 3, 6)
            .into_iter()
            .map(|cluster| cluster.into_iter().collect())
            .collect();

        assert_eq!(actual, expected);
    }

