    #[test]
    fn materialize_from_spool_keeps_leaf_ready_children_in_memory_without_run_file() {
        let temp = tempdir().unwrap();
        let mut store = super::ExternalRunStore::new(temp.path(), DirectIoConfig::disabled());
        let cur = vec![10_u32, 11, 12, 13, 14, 15, 16];
        let raw_assignments: Vec<Vec<u16>> = vec![
            vec![0],
            vec![0],
            vec![1],
            vec![1],
            vec![1],
            vec![1],
            vec![1],
        ];
        let fanout = 1usize;
        let spool = tempfile::NamedTempFile::new_in(temp.path()).unwrap();
        {
            let mut writer = std::io::BufWriter::new(spool.reopen().unwrap());
            for assignment in &raw_assignments {
                super::write_assign_record(&mut writer, assignment, fanout).unwrap();
            }
            writer.flush().unwrap();
        }
        let merge_groups = vec![
            super::MergedRawGroup {
                raw_children: vec![0],
                raw_len: 2,
            },
            super::MergedRawGroup {
                raw_children: vec![1],
                raw_len: 5,
            },
        ];

        let materialized = super::materialize_merged_children_from_spool_with_inline_limit(
            &cur,
            0,
            fanout,
            &merge_groups,
            &spool,
            &mut store,
            Some(3),
        )
        .unwrap();

        assert_eq!(materialized[0].points.as_deref(), Some(&[10_u32, 11][..]));
        assert!(materialized[0].extents.is_empty());
        assert!(materialized[1].points.is_none());
        assert_eq!(
            super::read_child_run_chain(&store, 0, &materialized[1].extents).unwrap(),
            vec![12_u32, 13, 14, 15, 16]
        );

        store.finalize().unwrap();
        let run_path = store.path_for_depth(0);
        let run_bytes = std::fs::metadata(run_path).unwrap().len();
        assert_eq!(run_bytes, 8 + 5 * 4);
    }

    #[test]
    fn gemm_tile_sizes_cap_large_leader_tiles_and_shrink_point_tiles_for_wide_vectors() {
        let (small_point_tile, small_leader_tile) = super::choose_gemm_tile_sizes(64, 128);
        assert_eq!(small_leader_tile, 64);
        assert_eq!(small_point_tile, 8192);

        let (wiki_point_tile, wiki_leader_tile) = super::choose_gemm_tile_sizes(10_000, 768);
        assert_eq!(wiki_leader_tile, 512);
        assert_eq!(wiki_point_tile, 8192);

        let (large_point_tile, large_leader_tile) = super::choose_gemm_tile_sizes(10_000, 16_384);
        assert!(large_leader_tile < 10_000);
        assert!(large_leader_tile <= 512);
        assert!(large_point_tile < wiki_point_tile);
        assert!(large_point_tile >= 256);
    }

    #[test]
    fn compute_clusters_gemm_matches_scalar_assignments() {
        let dataset = build_test_dataset(32, 8);
        let store = InmemDatasetPointStore::new(&dataset, 32);
        let cur: Vec<u32> = (0..32_u32).collect();
        let leaders = vec![1_u32, 7, 11, 19, 27];
        let fanout = 2;

        let mut expected = vec![Vec::new(); leaders.len()];
        for &idx in &cur {
            let mut top_k = super::StackTopK::new(fanout);
            let mut point = vec![0.0f32; 8];
            store.read_point_into(idx, &mut point).unwrap();
            for (lid, &leader_idx) in leaders.iter().enumerate() {
                let mut leader = vec![0.0f32; 8];
                store.read_point_into(leader_idx, &mut leader).unwrap();
                let distance = point
                    .iter()
                    .zip(leader.iter())
                    .map(|(&x, &y)| {
                        let diff = x - y;
                        diff * diff
                    })
                    .sum();
                top_k.push(distance, lid);
            }
            for &(_, lid) in top_k.iter() {
                expected[lid].push(idx);
            }
        }

        let (mut actual, _profile) =
            super::compute_clusters_gemm(&store, &cur, &leaders, fanout).unwrap();
        for cluster in &mut actual {
            cluster.sort_unstable();
        }
        for cluster in &mut expected {
            cluster.sort_unstable();
        }

        assert_eq!(actual, expected);
    }

    #[test]
    fn compute_clusters_gemm_matches_scalar_assignments_for_fanout_one() {
        let dataset = build_test_dataset(32, 8);
        let store = InmemDatasetPointStore::new(&dataset, 32);
        let cur: Vec<u32> = (0..32_u32).collect();
        let leaders = vec![1_u32, 7, 11, 19, 27];
        let fanout = 1;

        let mut expected = vec![Vec::new(); leaders.len()];
        for &idx in &cur {
            let mut point = vec![0.0f32; 8];
            store.read_point_into(idx, &mut point).unwrap();
            let mut best_lid = 0usize;
            let mut best_dist = f32::INFINITY;
            for (lid, &leader_idx) in leaders.iter().enumerate() {
                let mut leader = vec![0.0f32; 8];
                store.read_point_into(leader_idx, &mut leader).unwrap();
                let distance = point
                    .iter()
                    .zip(leader.iter())
                    .map(|(&x, &y)| {
                        let diff = x - y;
                        diff * diff
                    })
                    .sum();
                if distance < best_dist {
                    best_dist = distance;
                    best_lid = lid;
                }
            }
            expected[best_lid].push(idx);
        }

        let (mut actual, _profile) =
            super::compute_clusters_gemm(&store, &cur, &leaders, fanout).unwrap();
        for cluster in &mut actual {
            cluster.sort_unstable();
        }
        for cluster in &mut expected {
            cluster.sort_unstable();
        }

        assert_eq!(actual, expected);
    }

